        ${r?`<span class="axe-retro">℞</span>`:""}
        <span class="axe-pos">M${nd.house} · ${T(nd.sign)}</span>
        <span class="axe-dig" style="color:${digColor(nd.force)};background:${digBg(nd.force)}">${nd.sym||""} ${nd.dignite}</span>
    </span>` : "";

    const warnings = [];
    if (ax.nd1.force===L.faible) warnings.push(`⚠ ${T(ax.m1)} ${ax.nd1.sym} ${ax.nd1.dignite} : ${L.signalFrag}`);
    if (ax.nd1.force===L.fort)   warnings.push(`✦ ${T(ax.m1)} ${ax.nd1.sym} ${ax.nd1.dignite} : ${L.signalPuiss}`);
    if (ax.nd1.dignite===L.peregrin && ax.nd1.isRetro) warnings.push(`⚠ ${T(ax.m1)} ${L.doubleAffaib}`);
    if (ax.nd3?.force===L.faible) warnings.push(`⚠ ${L.boutChaine} ${T(ax.m3)} ${ax.nd3.sym} ${ax.nd3.dignite} → ${L.energieDistordue}`);

    return `<div class="section-title axe-title">🔗 ${L.axeMaitrise} — M${maisNum} (${T(ax.signe0)})</div>
    <div class="axe-chain">
        <span class="axe-label">${L.cuspide} ${T(ax.signe0)}</span>
        <span class="axe-arrow">→</span>
        ${node(ax.m1, ax.nd1, ax.nd1.isRetro)}
        ${ax.m2 ? `<span class="axe-arrow">→</span>${node(ax.m2, ax.nd2, ax.nd2?.isRetro)}` : ""}
        ${ax.m3 ? `<span class="axe-arrow">→</span>${node(ax.m3, ax.nd3, ax.nd3?.isRetro)}` : ""}
    </div>
    ${warnings.length ? `<div class="axe-warnings">${warnings.map(w=>`<div class="axe-warn">${w}</div>`).join("")}</div>` : ""}`;
};

