    if (!planH.length) return "";
    const touched = new Set();
    aspectsList.forEach(a => { if (a.maison === maisNum || (a.isAngle && maisNum===a.maison)) touched.add(a.pNatal); });
    planH.forEach(p => touched.add(p));

    const lines = [];
    touched.forEach(pN => {
        const links = (natalAspR[pN]||[]).filter(l => l.type==="Conjonction"||l.type==="Opposition" ? l.orbe<=6 : l.orbe<=5);
        if (!links.length) return;
        const linesP = links.map(l => {
            const q   = l.orbe<=1?"★ ":"";
            const dig = natalDictR[l.planete];
            return `<div class="fn-link">
