const _SKIP_PROG_D = new Set(["Nœud Moyen","Nœud moyen","Noeud Moyen","Noeud moyen","Noeud_Moyen","Noeud_moyen","Mean Node"]);
const _RENAME_PROG_D = {"Nœud Vrai":"Nœud Nord","Nœud vrai":"Nœud Nord","Noeud Vrai":"Nœud Nord","Noeud vrai":"Nœud Nord","Noeud_Vrai":"Nœud Nord","Noeud_vrai":"Nœud Nord","True Node":"Nœud Nord","MC":"Milieu du Ciel","IC":"Imum Coeli"};

if (progressionsRaw?.planetes) {
    const cleanedPlanetes = {};
    let _trueNodeDeg = null;
    Object.entries(progressionsRaw.planetes).forEach(([pName, pd]) => {
        if (_SKIP_PROG_D.has(pName)) return;
        const dName = _RENAME_PROG_D[pName] || pName;
        if (dName === "Nœud Nord" && pName !== "Nœud Nord") _trueNodeDeg = pd.fullDegree;
        cleanedPlanetes[dName] = { ...pd };
    });
    if (_trueNodeDeg !== null && !cleanedPlanetes["Nœud Sud"]) {
        const _sDeg = (_trueNodeDeg + 180) % 360;
        const _sSignIdx = Math.floor(_sDeg / 30) % 12;
        const _signsD = ["Bélier","Taureau","Gémeaux","Cancer","Lion","Vierge","Balance","Scorpion","Sagittaire","Capricorne","Verseau","Poissons"];
        const _sSign = _signsD[_sSignIdx];
        const nordData = cleanedPlanetes["Nœud Nord"];
        const nordHouse = nordData ? parseInt(nordData.house, 10) : 0;
        const _sHouse = nordHouse > 0 ? ((nordHouse + 5) % 12) + 1 : "?";
        cleanedPlanetes["Nœud Sud"] = { sign: _sSign, house: _sHouse, deg: `${((_sDeg??0) % 30).toFixed(2)}° ${_sSign}`, retro: "", fullDegree: _sDeg };
    }
    progressionsRaw.planetes = cleanedPlanetes;
}

const progByHouse = {};
items.forEach(it => {
    if (it.progressions_planetes?.length && it.maison >= 1 && it.maison <= 12) {
        const cleaned = it.progressions_planetes
            .filter(p => !_SKIP_PROG_D.has(p.name))
            .map(p => ({ ...p, name: _RENAME_PROG_D[p.name] || p.name }));
        if (cleaned.length) progByHouse[it.maison] = cleaned;
    }
});
if (!Object.keys(progByHouse).length && progressionsRaw?.planetes) {
    Object.entries(progressionsRaw.planetes).forEach(([pName, pd]) => {
        const h = parseInt(pd.house, 10);
        if (h >= 1 && h <= 12) {
            if (!progByHouse[h]) progByHouse[h] = [];
            progByHouse[h].push({ name: pName, deg: (pd.deg || '?').replace(/°.*/, ''), sign: pd.sign || '?', retro: pd.retro });
        }
    });
}

/** Lignes ☀ ARC SOLAIRE du flux progressionsRaw → tableau dédié (évite doublon dans « Aspects progressés »). */
const _solarArcRows = [];
if (progressionsRaw?.aspects?.length) {
    const _saRe = /^☀ ARC SOLAIRE :\s*(.+?)\s+dirigé\s+\(([^,]+),\s*M(\d+)\)\s+en\s+(.+?)\s+avec\s+(.+?)\s+natal\s+\(M(\d+)\)\s+—\s+orbe\s+([\d.]+)°\s*([\s\S]*)$/;
    progressionsRaw.aspects.forEach(a => {
        if (typeof a !== 'string' || a.indexOf('ARC SOLAIRE') === -1) return;
        const m = a.match(_saRe);
        if (m) {
            let note = (m[8] || '').trim()
                .replace(/^\([^)]*\)\s*/, '')
                .replace(/\[poids\s+[\d.]+\]\.?\s*/i, '')
                .replace(/\s*Direction lente et structurante[^.]*\.?\s*/gi, '')
                .replace(/^[\s.…—\-]+/, '')
                .trim();
            _solarArcRows.push({
                directed: m[1].trim(),
                dirSign: m[2].trim(),
                dirHouse: m[3],
                aspect: m[4].trim(),
                target: m[5].trim(),
                targetHouse: m[6],
                orbRaw: m[7],
                note
            });
        } else {
            _solarArcRows.push({ fallback: a });
        }
    });
}

/** N8N Prev Repport : pas de chaînes « ☀ ARC SOLAIRE » dans progressionsRaw.aspects — données dans chaque item .arcs_solaires { pSA, pNat, aspect, orbe, saSign, saHouse }. */
if (_solarArcRows.length === 0 && maisons?.length) {
    const _saSeen = new Set();
    maisons.forEach(it => {
        (it.arcs_solaires || []).forEach(a => {
            const orbN = typeof a.orbe === 'number' ? a.orbe : parseFloat(a.orbe);
            const orbKey = Number.isFinite(orbN) ? orbN.toFixed(3) : String(a.orbe ?? '');
            const key = `${a.pSA}|${a.pNat}|${a.aspect}|${orbKey}`;
            if (_saSeen.has(key)) return;
            _saSeen.add(key);
            const orb = Number.isFinite(orbN) ? orbN : 0;
            let note = '';
            if (orb < 0.15) note = isEN ? 'Near-exact arc' : 'Arc quasi-exact';
            else if (orb < 0.4) note = isEN ? 'Tight arc' : 'Arc serré';
            _solarArcRows.push({
                directed: a.pSA,
                dirSign: a.saSign || '—',
                dirHouse: String(a.saHouse ?? '?'),
                aspect: a.aspect,
                target: a.pNat,
                targetHouse: String(it.maison),
                orbRaw: orb.toFixed(2),
                note
            });
        });
    });
}

