const renderDeclinaisons = (list) => {
    if (!list?.length) return "";
    const filtered = list.filter(txt => {
        const isOOB = txt.includes("OOB") || txt.includes("HORS LIMITES");
        if (isOOB) return true;
        const orbMatch = txt.match(/orbe\s*[:=]?\s*([\d.]+)/i) || txt.match(/([\d.]+)°?\s*(?:d['']orbe|orbe)/i);
        if (orbMatch && parseFloat(orbMatch[1]) <= 0.5) return true;
        if (txt.includes("exact") || txt.includes("EXACT")) return true;
        return false;
    });
    if (!filtered.length) return "";
    const html = filtered.map(txt => {
        const isOOB = txt.includes("OOB") || txt.includes("HORS LIMITES");
        const isPara = txt.includes("PARALLÈLE") || txt.includes("parallèle");
        const isContra = txt.includes("CONTRA") || txt.includes("contre-parallèle");
        const col = isOOB ? "#831843" : isContra ? "#1F3864" : isPara ? "#2E5FA3" : "#1F3864";
        const bg  = isOOB ? "#fdf2f8" : isContra ? "#e8f0fe" : isPara ? "#eef2fb" : "#f0f4ff";
