const _ecaToISO = (s) => { let m = String(s || "").match(/(\d{4})-(\d{2})-(\d{2})/); if (m) return m[1] + "-" + m[2] + "-" + m[3]; m = String(s || "").match(/(\d{2})[\/-](\d{2})[\/-](\d{4})/); if (m) return m[3] + "-" + m[2] + "-" + m[1]; return ""; };
const _ecaStart = _ecaToISO(perso.date_entree) || (annee ? annee + "-01-01" : "");
const _ecaEnd   = _ecaToISO(perso.date_sortie) || (annee ? annee + "-12-31" : "");
const _ecaIn    = (iso) => iso && (!_ecaStart || iso >= _ecaStart) && (!_ecaEnd || iso <= _ecaEnd);
const _ecaSaros = {};
try { $("Saros Enrichment").all().forEach((it) => { const arr = (it.json && (it.json.data || [it.json])) || []; (Array.isArray(arr) ? arr : [arr]).forEach((e) => { const iso = _ecaToISO(e.date_maximum || e.date); if (iso && e.saros_number) _ecaSaros[iso] = { n: e.saros_number, theme: e.saros_theme || "", themeEN: e.saros_themeEN || "", heure: (String(e.date_maximum || "").match(/\d{2}:\d{2}/) || [""])[0] }; }); }); } catch (e) {}
try { ($("Analyseur Technique v").first()?.json?.eclipses || []).forEach((e) => { const iso = _ecaToISO(e.date); if (iso && !_ecaSaros[iso]) _ecaSaros[iso] = { n: e.saros_number, theme: e.saros_theme || "", themeEN: e.saros_themeEN || "", heure: e.heure || "" }; }); } catch (e) {}
let _ecaAll = []; try { _ecaAll = $("Download Eclipses 2").all().map((i) => i.json); } catch (e) {}
if (!_ecaAll.length) { try { _ecaAll = $("Analyseur Technique v").first()?.json?.eclipses || []; } catch (e) {} }
const _ecaList = _ecaAll.map((e) => { const iso = _ecaToISO(e.date_maximum || e.date); const sa = _ecaSaros[iso] || {}; const hm = (String(e.date_maximum || "").match(/\d{2}:\d{2}/) || [""])[0]; return { date: iso, heure: hm || e.heure || sa.heure || "", astre: e.astre, type: e.type, signe: e.signe, saros_number: e.saros_number || sa.n || null, saros_theme: e.saros_theme || sa.theme || "", saros_themeEN: e.saros_themeEN || sa.themeEN || "" }; }).filter((e) => _ecaIn(e.date)).sort((a, b) => (a.date || "").localeCompare(b.date || ""));
let eclipsesAnneeHTML = "";
if (_ecaList.length) {
    eclipsesAnneeHTML = `<div id="prev-eclipses-annee" class="house-block" style="margin-bottom:45px">
