    </div>
__PREV_TOC_PLACEHOLDER__
    ${(() => {
        const helioLines = [];
        if (helioConditions) {
            Object.entries(helioConditions).forEach(([name, v]) => {
                if (v.condition) {
                    const orient = v.orientation ? ` · ${_frToEn(v.orientation)}` : '';
                    const isCazimi = v.condition.includes('CAZIMI');
                    const isCombuste = v.condition.includes('COMBUSTE');
                    const color = isCazimi ? '#1F3864' : isCombuste ? '#dc2626' : '#6b7280';
                    const icon = isCazimi ? '☀️' : isCombuste ? '🔥' : '🌤️';
                    helioLines.push(`<div style="display:flex;align-items:center;gap:8px;padding:4px 0"><span>${icon}</span><span style="font-weight:700">${glyphs[name]||''} ${T(name)}</span> <span style="color:${color};font-size:0.9em">${_frToEn(v.condition)}${orient}</span></div>`);
                }
            });
        }
        if (helioLines.length === 0 && !chartRulerTrad) return '';
        let html = '<div id="prev-helio" style="background:#eef2fb;border:1px solid #2E5FA3;border-radius:10px;padding:14px 18px;margin:0 0 20px">';
        if (chartRulerTrad) {
            html += `<div style="font-weight:700;color:#1F3864;margin-bottom:8px;font-size:1em">👑 ${L.coMaitre} <strong>${_frToEn(chartRulerTrad)}</strong></div>`;
        }
        if (helioLines.length > 0) {
            html += `<div style="font-weight:700;color:#1F3864;margin-bottom:6px;font-size:0.95em">☀ ${L.condHelio}</div>`;
            html += helioLines.join('');
        }
        html += '</div>';
        return html;
    })()}
    ${eclipseNatalH ? `<div id="prev-eclipse" style="background:linear-gradient(135deg,#fff0e6,#fff8f5);border:2px solid #7c2d12;border-radius:10px;padding:14px 18px;margin:0 0 20px;"><div style="color:#7c2d12;font-weight:700;font-size:1.05em;margin-bottom:6px">⚡ ${L.neeSousEcl}</div><div>${L.eclipse} <strong>${T(eclipseNatalH.type)}</strong> ${L.de} <strong>${T(eclipseNatalH.astre)}</strong> ${L.en} <strong>${T(eclipseNatalH.sign)}</strong> — ${L.maison} <strong>${eclipseNatalH.house}</strong> (${((eclipseNatalH.degree??0)%30).toFixed(1)}°). ${L.eclNatDesc}${eclipseNatalH.house} ${L.eclNatDesc2}</div></div>` : ""}
    ${(etoileMatchesNatH.length || etoileCuspNatH.length) ? `<div id="prev-stellar" style="background:#fff8e1;border:1px solid #ffb300;border-radius:8px;padding:10px 16px;margin:0 0 16px;color:#5d4037">★ ${L.themeStellair} ${[...new Set([...etoileMatchesNatH.map(e=>e.etoile),...etoileCuspNatH.map(e=>e.etoile)])].join(' · ')} ${L.voirSection}</div>` : ""}
    ${"" /* Parans Brady — SUPPRIMÉ du rapport Prévisions (déjà présent dans le DHN) */}
    ${_primaryDirections && _primaryDirections.length > 0 ? (() => {
        const aspGlyph = {"Conjonction":"☌","Opposition":"☍","Carré":"□","Trigone":"△","Sextile":"⚹"};
        // [DP MUNDANE 2026-07-06] Présentation 2 tiers : structurantes (= les 6 du narratif/heatmap)
        // puis autres directions. Miroirs d'axes repliés, géométrie d'angles regroupée, M? -> cuspide.
        // Aucune nouveauté graphique : styles/couleurs/glyphes strictement identiques à l'existant.
        const _angH = {"ASC":1,"Ascendant":1,"DSC":7,"Descendant":7,"MC":10,"Milieu du Ciel":10,"IC":4,"Imum Coeli":4};
        const _hDisp = (name, h) => (h && h >= 1 && h <= 12) ? ('M' + h) : (_angH[name] ? ('M' + _angH[name]) : 'M?');
        const _PRIO = new Set(["Soleil","Lune","ASC","DSC","MC","IC"]);
        const _ANG = new Set(["Ascendant","Descendant","Milieu du Ciel","Imum Coeli","ASC","DSC","MC","IC"]);
        const _PB = {"Descendant":"Ascendant","Imum Coeli":"Milieu du Ciel","Nœud Sud":"Nœud Nord"};
        const _SB = {"DSC":"ASC","IC":"MC","Nœud Sud":"Nœud Nord"};
        const _sel = (() => {
            const cand = _primaryDirections.filter(d => d && (_PRIO.has(d.significator) || (typeof d.orbYears === "number" && d.orbYears <= 0.5)) && !(_ANG.has(d.promissor) && _ANG.has(d.significator)));
            cand.sort((a, b) => (a.orbYears || 0) - (b.orbYears || 0));
            const seen = new Set(), out = [];
            for (const d of cand) { const k = (_PB[d.promissor] || d.promissor) + "|" + (_SB[d.significator] || d.significator) + "|" + (Math.round((d.exactAge || 0) * 10) / 10); if (!seen.has(k)) { seen.add(k); out.push(d); } }
            return out.slice(0, 6);
        })();
        const _cls = (n) => _ANG.has(n) ? "AXE:ANGLES" : (n === "Nœud Nord" || n === "Nœud Sud") ? "AXE:NODES" : n;
        const _grp = new Map();
        _primaryDirections.forEach(d => { const k = _cls(d.promissor) + "|" + _cls(d.significator) + "|" + (Math.round((d.exactAge || 0) * 10) / 10); if (!_grp.has(k)) _grp.set(k, []); _grp.get(k).push(d); });
        const _events = [..._grp.values()].map(mem => {
            mem.sort((a, b) => (a.orbYears || 0) - (b.orbYears || 0));
            const canon = mem.find(d => _sel.includes(d)) || mem[0];
            return { canon, mirrors: mem.filter(x => x !== canon), isAngleGeom: _ANG.has(canon.promissor) && _ANG.has(canon.significator), struct: mem.some(d => _sel.includes(d)), orb: canon.orbYears || 0 };
        });
        const _structE = _events.filter(e => e.struct).sort((a, b) => a.orb - b.orb);
        const _otherE = _events.filter(e => !e.struct).sort((a, b) => a.orb - b.orb);
        const _mir = (e) => { if (!e.mirrors.length) return ''; const _p = e.mirrors.map(m => (m.promissor !== e.canon.promissor ? (glyphs[m.promissor] || '') + T(m.promissor) + ' ' : '') + (aspGlyph[m.aspect] || T(m.aspect)) + ' ' + (glyphs[m.significator] || '') + T(m.significator)); const _s = _p.slice(0, 3).join(' · ') + (_p.length > 3 ? ' · +' + (_p.length - 3) + ' ' + L.dpMirrorMore : ''); return `<div style="font-size:0.8em;color:#6b7280;margin-top:2px">${L.dpMirror} : ${_s}</div>`; };
        const _MOISDP = isEN ? ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'] : ['janv.','févr.','mars','avr.','mai','juin','juil.','août','sept.','oct.','nov.','déc.'];
        const _dpDateLbl = (iso) => { if (!iso) return ''; const d = new Date(iso); return isNaN(d) ? '' : ` · ${_MOISDP[d.getMonth()]} ${d.getFullYear()}`; };
        const _rowOf = (e, i) => {
            const dp = e.canon; const bg = i % 2 === 0 ? '#faf5ff' : '#ffffff';
            const orbCol = dp.orbYears <= 0.3 ? '#991b1b' : dp.orbYears <= 0.7 ? '#b45309' : '#4b5563';
            const orbBold = dp.orbYears <= 0.5 ? 'font-weight:700' : '';
            if (e.isAngleGeom) {
                return `<tr style="background:${bg}"><td colspan="3" style="padding:7px 12px;font-weight:600">${L.dpAxisGeom}</td><td style="padding:7px 12px;text-align:center;font-size:0.85em;color:#6b7280">${dp.direction}</td><td style="padding:7px 12px;text-align:center">${dp.exactAge.toFixed(1)} ${isEN ? 'yrs' : 'ans'}<span style="font-size:0.82em;color:#6b7280">${_dpDateLbl(dp.exactDate)}</span></td><td style="padding:7px 12px;text-align:center;color:${orbCol};${orbBold}">${dp.orbYears.toFixed(2)} ${isEN ? 'yr' : 'an'}${dp.orbYears >= 2 ? 's' : ''}</td><td style="padding:7px 12px;text-align:center;font-size:0.85em">—</td></tr>`;
            }
            return `<tr style="background:${bg}"><td style="padding:7px 12px;font-weight:600">${glyphs[dp.promissor]||''}  ${T(dp.promissor)}</td><td style="padding:7px 12px;text-align:center;font-size:1.1em">${aspGlyph[dp.aspect]||T(dp.aspect)}</td><td style="padding:7px 12px;font-weight:600">${glyphs[dp.significator]||''} ${T(dp.significator)}${_mir(e)}</td><td style="padding:7px 12px;text-align:center;font-size:0.85em;color:#6b7280">${dp.direction}</td><td style="padding:7px 12px;text-align:center">${dp.exactAge.toFixed(1)} ${isEN ? 'yrs' : 'ans'}<span style="font-size:0.82em;color:#6b7280">${_dpDateLbl(dp.exactDate)}</span></td><td style="padding:7px 12px;text-align:center;color:${orbCol};${orbBold}">${dp.orbYears.toFixed(2)} ${isEN ? 'yr' : 'an'}${dp.orbYears >= 2 ? 's' : ''}</td><td style="padding:7px 12px;text-align:center;font-size:0.85em">${_hDisp(dp.promissor, dp.promHouse)} → ${_hDisp(dp.significator, dp.sigHouse)}</td></tr>`;
        };
        const _sep = (txt) => `<tr><td colspan="7" style="padding:8px 12px;background:linear-gradient(135deg,#4a1d96,#7c3aed);color:white;font-weight:700;font-size:0.9em">${txt}</td></tr>`;
        let _ri = 0;
        const dpRows = _sep(L.dpStructTitle) + _structE.map(e => _rowOf(e, _ri++)).join('') + (_otherE.length ? _sep(L.dpOtherTitle) + _otherE.map(e => _rowOf(e, _ri++)).join('') : '');
        return `<div id="prev-dirs-primaires" class="house-block" style="page-break-before:always;margin-bottom:30px">
            <div class="house-banner" style="background:linear-gradient(135deg,#4a1d96,#7c3aed)">
                <div class="house-title" style="color:white">🔱 ${L.dirPrimaires}</div>
                <div class="house-meta"><span class="type-badge" style="background:#fbbf24;color:#1a1a2e;font-weight:700">${_structE.length} ${L.dpStructLbl} · ${_primaryDirections.length} ${_primaryDirections.length>1?L.dirsActives:L.dirActive}</span><span class="type-badge" style="background:rgba(255,255,255,0.2);color:white;margin-left:6px">${L.methodeDP}</span></div>
            </div>
            <div class="house-content">
                <div style="background:#faf5ff;border:2px solid #7c3aed;border-radius:8px;padding:12px 16px;margin-bottom:14px;color:#4a1d96;font-size:0.9em">
                    ${L.dpWarning}
                    <div style="margin-top:8px;font-weight:400">${L.dpMundaneNote}</div>
                </div>
                <table style="width:100%;border-collapse:collapse;font-size:0.9rem">
                    <thead><tr style="background:linear-gradient(135deg,#4a1d96,#7c3aed);color:white"><th style="padding:8px 12px;text-align:left">${L.promisseur}</th><th style="padding:8px 12px;text-align:center">${L.aspect}</th><th style="padding:8px 12px;text-align:left">${L.significateur}</th><th style="padding:8px 12px;text-align:center">${L.type}</th><th style="padding:8px 12px;text-align:center">${L.ageExact}</th><th style="padding:8px 12px;text-align:center">${L.dpOrbHeader}</th><th style="padding:8px 12px;text-align:center">${L.maisons_pl}</th></tr></thead><tbody>
                    ${dpRows}
                </tbody></table>
                <div style="margin-top:8px;font-size:0.8em;color:#6b7280;line-height:1.45">${L.dpOrbLegend}</div>
                ${firdariaActive ? `<div style="margin-top:16px;padding:12px 16px;background:#faf5ff;border:1px solid #c4b5fd;border-radius:8px;font-size:0.88rem;line-height:1.55;color:#5b21b6;text-align:left;hyphens:none">${L.dpFirdBridge}</div>` : ''}
            </div>
        </div>`;
    })() : ''}
    ${_solarArcRows.length > 0 ? (() => {
        const aspGlyphSA = {"Conjonction":"☌","Opposition":"☍","Carré":"□","Trigone":"△","Sextile":"⚹","Quinconce":"⚻"};
        const escSA = (t) => String(t).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
        const saRows = _solarArcRows.map((row, i) => {
            if (row.fallback) {
                return `<tr style="background:${i % 2 ? '#ffffff' : '#fff7ed'}"><td colspan="6" style="padding:8px 12px;font-size:0.85rem">${escSA(row.fallback)}</td></tr>`;
            }
            const bg = i % 2 === 0 ? '#fff7ed' : '#ffffff';
