            return `<tr style="background:${bg}"><td style="padding:7px 10px;font-weight:600">${gDir} ${escSA(T(row.directed))}<div style="font-size:0.72rem;color:#9a3412;font-weight:500">${escSA(T(row.dirSign))} · M${row.dirHouse}</div></td><td style="padding:7px 10px;text-align:center;font-size:1.05em">${aspGlyphSA[row.aspect] || T(row.aspect)}</td><td style="padding:7px 10px;font-weight:600">${gTgt} ${escSA(T(row.target))}</td><td style="padding:7px 10px;text-align:center;font-weight:600">M${row.targetHouse}</td><td style="padding:7px 10px;text-align:center;font-weight:600">${orbDisp}</td><td style="padding:7px 10px;font-size:0.82rem;color:#57534e">${noteCell}</td></tr>`;
        }).join('');
        return `<div id="prev-arcs-solaires" class="house-block" style="page-break-before:always;break-before:page;margin-bottom:30px">
