    })() : ''}
    ${firdariaActive ? `<div id="prev-firdaria" class="house-block" style="${((_primaryDirections && _primaryDirections.length > 0) || _solarArcRows.length > 0) ? 'page-break-before:always;break-before:page;' : ''}margin-bottom:30px">
        <div class="house-banner" style="background:${tc.bg}">
            <div class="house-title">⏳ ${L.firdariaTitle}</div>
