                    <strong>${L.sousPeriode}</strong> ${T(firdariaActive.sub)}<br>
                    <span style="color:#64748b;font-size:0.9em;margin-top:6px;display:block">${L.firdariaDesc} <strong>${T(firdariaActive.major)}</strong> ${isEN?'and':'et'} <strong>${T(firdariaActive.sub)}</strong> ${L.firdariaDesc2}</span>
                </div>
            </div>
        </div>
    </div>` : ''}
    ${progressionsRaw ? (() => {
        const progAge = typeof progressionsRaw.age === 'number' ? progressionsRaw.age.toFixed(1) : '?';
        const progPlanetsHTML = Object.entries(progressionsRaw.planetes || {}).map(([pName, pd], i) => {
            const bg = i % 2 === 0 ? '#fafafa' : '#ffffff';
            return `<tr style="background:${bg}"><td style="padding:7px 14px;font-weight:700">${glyphs[pName]||''} ${T(pName)}</td><td style="padding:7px 14px">${isEN && pd.sign ? String(pd.deg||'?').split(pd.sign).join(T(pd.sign)) : (pd.deg||'?')}</td><td style="padding:7px 14px;text-align:center">${signGlyphs[pd.sign]||''} ${T(pd.sign||'?')}</td><td style="padding:7px 14px;text-align:center">M${pd.house||'?'}</td><td style="padding:7px 14px;text-align:center">${pd.retro ? '℞' : '—'}</td></tr>`;
        }).join('');
        const _progAspNoSA = (progressionsRaw.aspects || []).filter(a => typeof a !== 'string' || a.indexOf('ARC SOLAIRE') === -1);
        const progAspectsHTML = _progAspNoSA.length > 0
            ? `<div class="section-title" style="color:#2E5FA3;margin-top:18px;page-break-before:always">🔮 ${L.aspEvtProg}</div>` +
