const _MDSE_FAST_ORB_A = {"Mars":3.0,"Vénus":2.5,"Soleil":2.5};
const _mdseFastScanA = {};
const _needFastScanA = _MDSE_FAST_PLANETS_A.some(p => !slowPlanets.includes(p));
if (_needFastScanA && days.length > 0) {
    const _natalTgtsA = Object.entries(natalDictLoc).filter(([n]) =>
        ["Soleil","Lune","Mercure","Vénus","Mars","Jupiter","Saturne","Uranus","Neptune","Pluton","Chiron","Nœud Nord","Nœud Sud","Ascendant","Milieu du Ciel","Descendant","Imum Coeli"].includes(n)
    );
    const _lastDateFSA = days[days.length - 1]?.date || "";
    for (const pFast of _MDSE_FAST_PLANETS_A) {
        if (slowPlanets.includes(pFast)) continue;
        const maxOrb = _MDSE_FAST_ORB_A[pFast] || 2.5;
        for (const [pNatal, nData] of _natalTgtsA) {
            if (pFast === pNatal) continue;
            for (const [aspName, aspDeg] of Object.entries(_MDSE_FAST_ASPECTS_A)) {
                let inOrb = false, wStart = null, wBestOrb = 999, wBestDate = null;
                const waves = [];
                for (const day of days) {
                    const pd = day?.planetes?.[pFast]; if (!pd?.fullDegree) continue;
                    const diff = _getOrbMDSE(pd.fullDegree, nData.deg);
                    const ex = Math.abs(diff - aspDeg);
                    if (ex <= maxOrb) {
                        if (!inOrb) { inOrb = true; wStart = day.date; wBestOrb = 999; }
                        if (ex < wBestOrb) { wBestOrb = ex; wBestDate = day.date; }
                    } else if (inOrb) {
                        waves.push({ start:wStart, end:day.date, peakDate:wBestDate, peakOrb:wBestOrb });
                        inOrb = false;
                    }
                }
                if (inOrb) waves.push({ start:wStart, end:_lastDateFSA, peakDate:wBestDate, peakOrb:wBestOrb });
                if (waves.length > 0) {
                    const globalBest = Math.min(...waves.map(w => w.peakOrb));
                    const bestWave = waves.reduce((a, b) => a.peakOrb < b.peakOrb ? a : b);
                    _mdseFastScanA[`${pFast}|||${aspName}|||${pNatal}`] = {
                        pTransit:pFast, pNatal, aspName,
                        bestOrb:globalBest, bestDate:bestWave.peakDate,
                        waves, natalHouse:nData.house
                    };
                }
            }
        }
    }
}

