// --- MDSE : Évaluation d'une condition unitaire (adapté aux structures locales) ---
const _mdseEvalCondA = (cond) => {
  const result = { hit:false, strength:0, detail:"", involvedHouses:[], involvedPlanets:[] };
  switch (cond.type) {
    case "transit_in_house": {
      const mKeys = Object.keys(_allSlowAspA).filter(key => {
        const a = _allSlowAspA[key];
        return a.pTransit === cond.planet && cond.houses.includes(a.natalHouse) && cond.aspects.includes(a.aspect) && a.waves && a.waves.length > 0;
      });
      if (mKeys.length > 0) {
        let bestTightness = 0;
        const houses = new Set();
        const _exp = _MDSE_TIGHT_EXP_A[cond.planet] ?? 1.5;
        mKeys.forEach(key => {
          const a = _allSlowAspA[key];
          const maxOrb = _getOrbSlowA(cond.planet, a.aspect);
          houses.add(a.natalHouse);
          a.waves.forEach(w => { const mo = w._minOrb; if (mo != null) { const t = Math.pow(Math.max(0, 1 - mo / maxOrb), _exp); if (t > bestTightness) bestTightness = t; } });
        });
        const tightness = bestTightness > 0 ? bestTightness : 0.5;
        result.hit = true; result.strength = tightness;
        result.involvedHouses = [...houses]; result.involvedPlanets = [cond.planet];
        result.detail = `${cond.planet} transit dur M${[...houses].join("/")}`;
      } else {
        const fbM = Object.values(_mdseFastScanA).filter(fb => fb.pTransit === cond.planet && cond.houses.includes(fb.natalHouse) && cond.aspects.includes(fb.aspName));
        if (fbM.length > 0) {
          const bestFb = fbM.reduce((a, b) => a.bestOrb < b.bestOrb ? a : b);
          const hasWaves = bestFb.waves && bestFb.waves.length > 0;
          const _fbMaxOrb = _getOrbFastA(bestFb.pTransit, bestFb.aspName);
          const _fbExp = _MDSE_TIGHT_EXP_A[bestFb.pTransit] ?? 1.5;
          const tightness = Math.pow(Math.max(0, 1 - bestFb.bestOrb / _fbMaxOrb), _fbExp);
          const multiWave = hasWaves && bestFb.waves.length >= 3 ? 1.3 : hasWaves && bestFb.waves.length >= 2 ? 1.15 : 1.0;
          result.hit = true; result.strength = Math.min(tightness * multiWave, 1.0);
          result.involvedHouses = [...new Set(fbM.map(fb => fb.natalHouse))]; result.involvedPlanets = [cond.planet];
          result.detail = `${cond.planet} transit M${result.involvedHouses.join("/")}`;
        }
      }
      break;
    }
    case "transit_aspect": {
      const mKey = Object.keys(_allSlowAspA).find(key => {
        const a = _allSlowAspA[key];
        return a.pTransit === cond.pTransit && a.pNatal === cond.pNatal && cond.aspects.includes(a.aspect) && a.waves && a.waves.length > 0;
      });
      if (mKey) {
        const a = _allSlowAspA[mKey];
        const maxOrb = _getOrbSlowA(cond.pTransit, a.aspect);
        const _exp = _MDSE_TIGHT_EXP_A[cond.pTransit] ?? 1.5;
        let bestTightness = 0;
        a.waves.forEach(w => { const mo = w._minOrb; if (mo != null) { const t = Math.pow(Math.max(0, 1 - mo / maxOrb), _exp); if (t > bestTightness) bestTightness = t; } });
        const tightness = bestTightness > 0 ? bestTightness : 0.5;
        const multiWave = a.waves.length >= 3 ? 1.3 : a.waves.length >= 2 ? 1.15 : 1.0;
        result.hit = true; result.strength = Math.min(tightness * multiWave, 1.0);
        result.involvedHouses = a.natalHouse ? [a.natalHouse] : []; result.involvedPlanets = [cond.pTransit, cond.pNatal];
        result.detail = `${cond.pTransit} ${a.aspect} ${cond.pNatal} natal (M${a.natalHouse})`;
      } else {
        const fbKey = Object.keys(_mdseFastScanA).find(key => {
          const fb = _mdseFastScanA[key];
          return fb.pTransit === cond.pTransit && fb.pNatal === cond.pNatal && cond.aspects.includes(fb.aspName);
        });
        if (fbKey) {
          const fb = _mdseFastScanA[fbKey];
          const hasWaves = fb.waves && fb.waves.length > 0;
          const _fbMaxOrb = _getOrbFastA(fb.pTransit, fb.aspName);
          const _fbExp = _MDSE_TIGHT_EXP_A[fb.pTransit] ?? 1.5;
          const tightness = Math.pow(Math.max(0, 1 - fb.bestOrb / _fbMaxOrb), _fbExp);
          const multiWave = hasWaves && fb.waves.length >= 3 ? 1.3 : hasWaves && fb.waves.length >= 2 ? 1.15 : 1.0;
          result.hit = true; result.strength = Math.min(tightness * multiWave, 1.0);
          result.involvedHouses = fb.natalHouse ? [fb.natalHouse] : []; result.involvedPlanets = [cond.pTransit, cond.pNatal];
          result.detail = `${fb.pTransit} ${fb.aspName} ${fb.pNatal} natal (M${fb.natalHouse})`;
        }
      }
      break;
    }
    case "progression": {
      const pM = [];
      Object.entries(_progActsA).forEach(([pNatal, acts]) => {
        acts.forEach(a => {
          if (a.pProg?.startsWith("Arc ") || a.pProg?.startsWith("Éclipse") || a.pProg?.startsWith("T→P")) return;
          if (a.pProg === cond.pProg && cond.aspects.includes(a.aspName)) {
            const nH = natalDictLoc[pNatal]?.house;
            if (nH && cond.houseTargets.includes(nH)) pM.push({ pNatal, aspect:a.aspName, house:nH, weight:a.weight||0.5 });
          }
        });
      });
      if (pM.length > 0) {
        result.hit = true; result.strength = Math.min(Math.max(...pM.map(m => m.weight)), 1.0);
        result.involvedHouses = [...new Set(pM.map(m => m.house))]; result.involvedPlanets = [cond.pProg, ...pM.map(m => m.pNatal)];
        result.detail = `Prog. ${cond.pProg} → ${pM.map(m => `${m.pNatal}(M${m.house})`).join("+")}`;
      }
      break;
    }
    case "solar_arc": {
      const aM = [];
      Object.entries(_progActsA).forEach(([pNatal, acts]) => {
        acts.forEach(a => {
          if (!a.pProg?.startsWith("Arc ")) return;
          const arcP = a.pProg.replace("Arc ", "");
          if (arcP === cond.pArc && cond.targets.includes(pNatal)) aM.push({ pNatal, house:a.house, weight:a.weight||0.5 });
        });
      });
      if (aM.length > 0) {
        result.hit = true; result.strength = Math.min(Math.max(...aM.map(m => m.weight)), 1.0);
        result.involvedHouses = [...new Set(aM.map(m => m.house))]; result.involvedPlanets = [cond.pArc, ...aM.map(m => m.pNatal)];
        result.detail = `Arc ${cond.pArc} → ${aM.map(m => `${m.pNatal}(M${m.house})`).join("+")}`;
      }
      break;
    }
    case "transit_on_angle": {
      const angleName = cond.angle;
      for (let h = 0; h < 12; h++) {
        const angPas = rapportMaisons[h].passages_angles || [];
        const match = angPas.find(a => cond.planets.includes(a.planete));
        if (match) {
          const angleHouse = natalDictLoc[angleName]?.house;
          if (angleHouse && angleHouse === h + 1) {
            result.hit = true; result.strength = 0.8;
            result.involvedHouses = [h + 1]; result.involvedPlanets = [match.planete];
            result.detail = `${match.planete} sur ${angleName} (M${h+1})`;
            break;
          }
        }
      }
      break;
    }
    case "eclipse_in_house": {
      const eH = [];
      const _ORBE_ECL_MDSE = 3.0;
      cond.houses.forEach(h => {
        if (h < 1 || h > 12) return;
        let found = false;
        rapportMaisons.forEach(m => {
          (m.eclipses || []).forEach(e => {
            if (found || e.fullDegree == null) return;
            const isConjAny = Object.values(natalDictLoc).some(n => {
              let d = Math.abs(e.fullDegree - n.deg); if (d > 180) d = 360 - d;
              return d <= _ORBE_ECL_MDSE;
            });
            if (!isConjAny) return;
            if (e.maison === h) { found = true; return; }
            Object.values(natalDictLoc).forEach(n => {
              if (found) return;
              let d = Math.abs(e.fullDegree - n.deg); if (d > 180) d = 360 - d;
              if (d <= _ORBE_ECL_MDSE && n.house === h) found = true;
            });
          });
        });
        if (found) eH.push(h);
      });
      if (eH.length > 0) { result.hit = true; result.strength = Math.min(0.5 + eH.length * 0.25, 1.0); result.involvedHouses = eH; result.detail = `Éclipse conjoncte M${eH.join("/")}`; }
      break;
    }
    case "eclipse_conjunct_natal": {
      const eclHits = _mdseEclipseNatalHitsA.filter(h => cond.planets.includes(h.planet) && h.orb <= (cond.orb || 3.0));
      if (eclHits.length > 0) {
        const best = eclHits.reduce((a, b) => a.orb < b.orb ? a : b);
        const tightness = Math.pow(Math.max(0, 1 - best.orb / (cond.orb || 3.0)), 1.5);
        result.hit = true;
        result.strength = Math.min(tightness + 0.3, 1.0);
        result.involvedHouses = [...new Set(eclHits.map(h => h.house))];
        result.involvedPlanets = eclHits.map(h => h.planet);
        result.detail = `Éclipse conjoncte ${eclHits.map(h => `${h.planet}(${h.orb.toFixed(1)}°)`).join("+")}`;
      }
      break;
    }
    case "transit_minor_aspect": {
      const mKey = Object.keys(_mdseMinorAspectsA).find(key => {
        const m = _mdseMinorAspectsA[key];
        return m.pTransit === cond.pTransit && m.pNatal === cond.pNatal;
      });
      if (mKey) {
        const m = _mdseMinorAspectsA[mKey];
        const _exp = _MDSE_TIGHT_EXP_A[m.pTransit] ?? 1.5;
        const tightness = Math.pow(Math.max(0, 1 - m.bestOrb / 1.0), _exp);
        result.hit = true;
        result.strength = Math.min(tightness * 0.7, 1.0);
        result.involvedHouses = m.natalHouse ? [m.natalHouse] : [];
        result.involvedPlanets = [cond.pTransit, cond.pNatal];
        result.detail = `${cond.pTransit} ${m.aspName} ${cond.pNatal} natal (M${m.natalHouse})`;
      }
      break;
    }
    case "double_activation": {
      const daMatches = [];
      Object.entries(_allSlowAspA).forEach(([key, a]) => {
        if (!cond.planets.includes(a.pTransit)) return;
