};
let chartRulerTradName = ascSign ? MAITRES_TRAD_THEME[ascSign] : null;
let chartRulerTrad = (chartRulerTradName && chartRulerTradName !== chartRulerName) ? planetes.find(p => p.planet.fr === chartRulerTradName) : null;
stats.chart_ruler_trad = (chartRulerTradName && chartRulerTradName !== chartRulerName) ? chartRulerTradName : null;

let pSynth = `Tu es un astrologue expert. Fais la synthèse globale de ce thème natal en utilisant les maîtrises modernes.\n\n`;

pSynth += `=== IDENTITÉ DU THÈME ===\n`;
pSynth += `Type : ${sectStr}.\n`;
pSynth += `Éléments : Feu(${stats.elements.Feu}) Terre(${stats.elements.Terre}) Air(${stats.elements.Air}) Eau(${stats.elements.Eau}).\n`;
pSynth += `Modes : Cardinal(${stats.modes.Cardinal}) Fixe(${stats.modes.Fixe}) Mutable(${stats.modes.Mutable}).\n`;
pSynth += `Secte : Luminaire = ${stats.sectLight}, Bénéfique de secte = ${stats.sectBenefic}, Maléfique tempéré = ${stats.sectMalefic}, Maléfique aggravé (contra-secte) = ${stats.contraSectMalefic}.\n`;
pSynth += `→ INSTRUCTION : Le ${stats.sectLight} est le luminaire directeur (${sectStr}). ${stats.sectBenefic} agit en pleine puissance bénéfique, ${stats.sectMalefic} est le maléfique tempéré (IN-secte). ${stats.contraSectMalefic} est le maléfique HORS-secte (contra-secte) = le plus nuisible.\n`;
pSynth += `⛔ TERMINOLOGIE OBLIGATOIRE : ${stats.sectMalefic} = "maléfique tempéré" ou "maléfique de secte". ${stats.contraSectMalefic} = "maléfique hors-secte" ou "maléfique aggravé (contra-secte)". Ne JAMAIS dire "${stats.contraSectMalefic} est le maléfique de ta secte" — c'est FAUX, ${stats.contraSectMalefic} est HORS de la secte ${sectStr.split(" ")[0].toLowerCase()}.\n`;

if (sensitivityProfileTheme) pSynth += sensitivityProfileTheme;

if (configurations.length > 0) {
    pSynth += `\n=== CONFIGURATIONS NATALES MAJEURES (triées par Score de Puissance décroissant) ===\n`;
    pSynth += `Légende scores : PRIORITÉ ABSOLUE ≥120 | Majeure ≥80 | Significative ≥50 | Mineure <50\n`;
    const hasSubs = configurations.some(c => c.subConfigOf);
    const hasVariants = configurations.some(c => c.subConfigType === "variant");
    if (hasSubs) pSynth += `INSTRUCTION : Les configurations marquées [composante de X] sont géométriquement contenues dans la figure parente — interpréter comme facettes, NON comme événements distincts.\n`;
    if (hasVariants) pSynth += `INSTRUCTION : Les configurations marquées [variante de X] partagent la majorité de leurs planètes avec une figure de même type déjà listée — ne pas doubler l'interprétation.\n`;
    configurations.forEach(c => {
        const scoreLabel = c.puissanceScore !== undefined ? ` [Score: ${c.puissanceScore} — ${c.prioriteLabel}]` : "";
