// ── C2 : ARBRE DES DISPOSITIONS & DISPOSITEUR FINAL ──
const SIGN_RULER_MAP = {
    "Bélier":"Mars","Taureau":"Vénus","Gémeaux":"Mercure","Cancer":"Lune",
    "Lion":"Soleil","Vierge":"Mercure","Balance":"Vénus","Scorpion":"Pluton",
    "Sagittaire":"Jupiter","Capricorne":"Saturne","Verseau":"Uranus","Poissons":"Neptune"
};
const DISPOSITOR_PLANETS = ["Soleil","Lune","Mercure","Vénus","Mars","Jupiter","Saturne","Uranus","Neptune","Pluton"];
const dispositorTree = {};
DISPOSITOR_PLANETS.forEach(name => {
    const chain = [];
    let current = name;
    const visited = new Set();
    while (current && !visited.has(current)) {
        visited.add(current);
        const p = planetes.find(x => x.planet.fr === current);
        if (!p) break;
        const sign = p.zodiac_sign?.name?.fr;
        if (!sign) break;
        const ruler = SIGN_RULER_MAP[sign];
        const isInDomicile = getDignity(current, sign) === "Domicile";
        chain.push({ planet: current, sign, ruler, inDomicile: isInDomicile });
        if (isInDomicile) break;
        current = ruler;
    }
    dispositorTree[name] = {
        chain,
        finalDispositor: chain.find(c => c.inDomicile)?.planet || null,
        isLoop: !chain.some(c => c.inDomicile)
    };
});
const finalDispositors = [...new Set(
    Object.values(dispositorTree).map(d => d.finalDispositor).filter(Boolean)
)];
const dispositorStr = finalDispositors.length > 0
    ? `Dispositeur(s) final(aux) : ${finalDispositors.join(", ")} — planète(s) en domicile concentrant le pouvoir de la chaîne de maîtrise. Toute la carte est ultimement « commandée » par ${finalDispositors.length === 1 ? 'cette planète' : 'ces planètes'}.`
    : `Aucun dispositeur final unique — chaîne(s) de disposition en boucle (réceptions mutuelles ou orbite fermée), indiquant un réseau de pouvoir distribué plutôt qu'une seule planète directrice.`;

// ── C3 : DIGNITÉ ACCIDENTELLE (Table de Lilly simplifiée) ──
const ANGULAR_HOUSES_SET = new Set([1, 10]);
const STRONG_HOUSES_SET  = new Set([7, 4]);
const SUCCEDENT_HOUSES   = new Set([2, 5, 8, 11]);
const CADENT_WEAK_HOUSES = new Set([6, 12]);
const MASCULINE_SIGNS    = new Set(["Bélier","Gémeaux","Lion","Balance","Sagittaire","Verseau"]);
const FEMININE_SIGNS     = new Set(["Taureau","Cancer","Vierge","Scorpion","Capricorne","Poissons"]);
const DIURNAL_PLANETS    = new Set(["Soleil","Jupiter","Saturne"]);
const NOCTURNAL_PLANETS  = new Set(["Lune","Vénus","Mars"]);
const MALEFICS_TRAD      = new Set(["Mars","Saturne"]);
const BENEFICS_TRAD      = new Set(["Jupiter","Vénus"]);

const accidentalDignityScores = {};
DISPOSITOR_PLANETS.forEach(name => {
    const p = planetes.find(x => x.planet.fr === name);
    if (!p) return;
    const house = getHouseNumber(p.fullDegree);
    const isRetro = p.isRetro?.toLowerCase?.() === 'true' || p.isRetro === true;
    const sign = p.zodiac_sign?.name?.fr;
    let score = 0;
    const details = [];

    if (ANGULAR_HOUSES_SET.has(house))  { score += 5; details.push(`M${house} angulaire +5`); }
    else if (STRONG_HOUSES_SET.has(house)) { score += 4; details.push(`M${house} angulaire +4`); }
    else if (SUCCEDENT_HOUSES.has(house))  { score += 3; details.push(`M${house} succédente +3`); }
    else if (CADENT_WEAK_HOUSES.has(house)){ score -= 5; details.push(`M${house} cadente faible -5`); }
    else { score += 2; details.push(`M${house} cadente +2`); }

    if (isRetro) { score -= 5; details.push("Rétrograde -5"); }
    else         { score += 4; details.push("Direct +4"); }

    const helio = helioConditions[name];
    if (helio?.condition?.includes("CAZIMI"))    { score += 5; details.push("Cazimi +5"); }
    else if (helio?.condition?.includes("COMBUSTE")) { score -= 5; details.push("Combuste -5"); }
    else if (helio?.condition?.includes("SOUS LES RAYONS")) { score -= 4; details.push("Sous les rayons -4"); }
    else if (name !== "Soleil" && name !== "Lune") { score += 5; details.push("Libre du Soleil +5"); }

    const inMutualReception = mutualReceptions.some(mr =>
        (mr.p1 === name || mr.p2 === name) && mr.type === "domicile"
    );
    if (inMutualReception) { score += 5; details.push("Réception mutuelle domicile +5"); }

    const essentialDig = getDignity(name, sign);
    const essentialScore = essentialDig === "Domicile" ? 5 : essentialDig === "Exaltation" ? 4
        : essentialDig === "Exil" ? -5 : essentialDig === "Chute" ? -4 : 0;
    if (essentialScore !== 0) details.push(`${essentialDig} ${essentialScore > 0 ? '+' : ''}${essentialScore}`);
    score += essentialScore;

    // Bonus/malus aspects reçus de bénéfiques/maléfiques (Lilly)
    const BENEFICS = new Set(["Jupiter","Vénus"]);
    const MALEFICS = new Set(["Saturne","Mars"]);
    const aspFromBen = aspects.filter(a => a.isMajor && ((a.p1 === name && BENEFICS.has(a.p2)) || (a.p2 === name && BENEFICS.has(a.p1))));
    const aspFromMal = aspects.filter(a => a.isMajor && ((a.p1 === name && MALEFICS.has(a.p2)) || (a.p2 === name && MALEFICS.has(a.p1))));
    if (aspFromBen.length > 0) { const b = Math.min(aspFromBen.length, 2) * 2; score += b; details.push(`Aspect(s) bénéfique(s) reçu(s) +${b}`); }
    if (aspFromMal.length > 0) { const m = Math.min(aspFromMal.length, 2) * -2; score += m; details.push(`Aspect(s) maléfique(s) reçu(s) ${m}`); }

    // Bonus station
    if (stationaryPlanets.some(sp => sp.planet === name)) { score += 3; details.push("Stationnaire +3"); }

    accidentalDignityScores[name] = { score, details, house, sign, isRetro, essentialDig };
});
