    } else if (!isDayChart && NOCTURNAL_PLANETS.has(name) && !aboveHorizon && !isMasculine) {
        inHayz = true; desc = `${name} nocturne, sous l'horizon, en signe féminin (${sign}) de nuit — condition de HAYZ parfaite : la planète opère dans son élément naturel avec une efficacité maximale.`;
    }
