    const majorAspDegs = [0, 60, 90, 120, 180];
    let hasApplyingAspect = false;
    DISPOSITOR_PLANETS.filter(n => n !== "Lune").forEach(name => {
        const p = planetes.find(x => x.planet.fr === name); if (!p) return;
        majorAspDegs.forEach(aspDeg => {
