    { name: "Procyon", lon: 115.78 }, { name: "Régulus", lon: 149.83 },
    { name: "Vindemiatrix", lon: 189.95 }, { name: "Spica", lon: 203.836 },
    { name: "Arcturus", lon: 204.23 }, { name: "Alphecca", lon: 222.30 },
    { name: "Zubenelgenubi", lon: 225.08 }, { name: "Zubeneschamali", lon: 229.37 },
    { name: "Toliman", lon: 239.85 }, { name: "Antarès", lon: 249.77 },
    { name: "Lesath", lon: 264.22 },
    { name: "Polis", lon: 273.23 },
    { name: "Facies", lon: 278.30 },
    { name: "Ascella", lon: 283.67 },
