    { name: "Sadalmelik", lon: 333.48 }, { name: "Fomalhaut", lon: 333.87 },
    { name: "Deneb", lon: 335.33 }
  ];

  // 3) Précession depuis J2000.0 (IAU 2006, identique à 3c. Étoiles Fixes)
  let _s64Prec = 0;
  if (dateNaiss && !isNaN(dateNaiss)) {
    const y = dateNaiss.getFullYear(), m = dateNaiss.getMonth() + 1, d = dateNaiss.getDate();
    let yy = y, mm = m;
    if (mm <= 2) { yy -= 1; mm += 12; }
    const A = Math.floor(yy / 100);
    const B = 2 - A + Math.floor(A / 4);
    const JD = Math.floor(365.25 * (yy + 4716)) + Math.floor(30.6001 * (mm + 1)) + d + 0.5 + B - 1524.5;
    const T = (JD - 2451545.0) / 365.25;
    _s64Prec = (50.2909 * T + 0.000022 * T * T) / 3600.0;
  }

  // 4) Scan : Part de Fortune + Vertex contre 33 étoiles (orbe ≤ 1.5°)
  const _s64ExtraPoints = [];
  if (natalDict["Part de Fortune"]) _s64ExtraPoints.push({ name: "Part de Fortune", deg: natalDict["Part de Fortune"].deg });
  if (natalDict["Vertex"])           _s64ExtraPoints.push({ name: "Vertex",           deg: natalDict["Vertex"].deg });
  let _s64NewMatches = 0;
  for (const pt of _s64ExtraPoints) {
    for (const star of _S64_STARS_J2000) {
      const starLon = ((star.lon + _s64Prec) % 360 + 360) % 360;
      let diff = Math.abs(pt.deg - starLon);
      if (diff > 180) diff = 360 - diff;
      if (diff <= 1.5) {
        const orbRounded = parseFloat(diff.toFixed(2));
        const precQual = orbRounded <= 0.5 ? "très précis" : (orbRounded <= 1.0 ? "précis" : "actif");
        etoileMatchesNatal.push({
          planete: pt.name,
          etoile: star.name,
          orb: orbRounded,
          etoile_degree: starLon,
          maison: findNatalHouse(pt.deg),
          isAngle: false,
          precision: precQual,
          _s64Source: "Q107-E2"
        });
        _s64NewMatches++;
      }
    }
  }
  if (_s64NewMatches > 0) {
    console.log(`[S6.4 Q107-E2] +${_s64NewMatches} matches étoiles via Part de Fortune/Vertex (Vertex=${natalDict["Vertex"]?.deg?.toFixed(2) ?? "absent"}°)`);
  }
} catch(eS64Q107E) {
  console.log("[WARN] S6.4 Q107-E2 Vertex/Fortune scan:", eS64Q107E.message, eS64Q107E.stack?.split("\n")[1]?.trim());
}

