const NATAL_ORBES = {
    luminaire   : { "Conjonction":12, "Opposition":12, "Carré":10, "Trigone":10, "Sextile":8, "Quinconce":3, "Semi-Sextile":2, "Semi-Carré":2, "Quintile":2, "Biquintile":2, "Sesqui-Carré":2 },
