    lente       : { "Conjonction":8,  "Opposition":8,  "Carré":6,  "Trigone":6,  "Sextile":5, "Quinconce":2, "Semi-Sextile":1, "Semi-Carré":1, "Quintile":1, "Biquintile":1, "Sesqui-Carré":1 }
