        if(!_SIGNIF.has(pN)) continue;
        const nD=natalD[pN]; if(!nD||typeof nD.deg!=="number") continue;
        const fam=_fam(_sep(refDeg,nD.deg)); if(!fam) continue;
        const orb=_sep(refDeg,nD.deg);
        const soft=(fam==="trigone"||fam==="sextile"||(fam==="conj"&&_BEN.has(pN)));
        const hard=(fam==="carré"||fam==="opp"||(fam==="conj"&&_MAL.has(pN)));
        const dig=_dig(pN,nD.sign);
        let val="nuance", sc=0;
        if(_BEN.has(pN)&&soft){ val="porteur"; sc=(fam==="conj"?2:1); }
        else if(_MAL.has(pN)&&hard){ val="exigeant"; sc=(fam==="conj"||fam==="opp"?-2:-1); }
        // corps neutres (Mercure/Uranus/Neptune/Chiron/nœuds/angles) ou bénéf-tendu / maléf-adouci ⇒ nuance (sc 0)
        if(dig==="détriment"||dig==="chute"){ if(val==="porteur"){val="nuance"; sc=0;} else if(val==="exigeant"){sc=Math.min(sc,-2);} }
        if((dig==="domicile"||dig==="exaltation")&&val==="porteur"){ val="porteur+"; sc=Math.max(sc,2); }
        score+=sc;
        const digFR=(dig!=="—"&&dig!=="pérégrin")?dig:"";
        const digEN=_DIGEN[dig]||"";
        const toneFR=val.startsWith("porteur")?"soutien":(val==="exigeant"?"défi":"nuance");
        const toneEN=val.startsWith("porteur")?"support":(val==="exigeant"?"challenge":"nuance");
        const parFR=[digFR,toneFR].filter(Boolean).join(", "), parEN=[digEN,toneEN].filter(Boolean).join(", ");
        const _pH=(typeof nD.house==="number")?nD.house:null;   // maison natale du point activé (cross-lecture Étape 1)
        const drv={ p:pN, fam, sc, val, orb, personal:_PERSO.has(pN), house:_pH, fr:_aFR[fam]+" ta "+pN+" natale"+(parFR?" ("+parFR+")":""), en:_aEN[fam]+" your natal "+pN+(parEN?" ("+parEN+")":"") };
        drivers.push(drv);
        const clear=(val==="porteur"||val==="porteur+"||val==="exigeant");
        if(clear){ const key=Math.abs(sc)*100+(drv.personal?10:0)-orb; if(!best||key>best.key) best={ p:pN, valence:val, sc, orb, personal:drv.personal, house:_pH, fr:drv.fr, en:drv.en, key }; }
      }
    }
    if (!drivers.length) return { nature, valence:"mixte", score:0, drivers:[], netPersonal:null };
    drivers.sort((a,b)=>Math.abs(b.sc)-Math.abs(a.sc)||a.orb-b.orb);
    const valence = score>=2?"porteur":(score<=-2?"exigeant":"mixte");
    const netPersonal = best?{ valence:best.valence, sc:best.sc, personal:best.personal, house:best.house, p:best.p, fr:best.fr, en:best.en }:null;
    return { nature, valence, score, drivers:drivers.slice(0,3), netPersonal };
  } catch(e){ return null; }
}

