    for (let i = 0; i < 12; i++) {
        const a = cusps[order[i]];
        const b = cusps[order[(i + 1) % 12]];
        if (a <= b) { if (d >= a && d < b) return order[i]; }
        else        { if (d >= a || d < b) return order[i]; }
    }
    return 1;
}
