                      keyPlanets:["Saturne","Mars","Pluton","Jupiter","Neptune"], houses:[7,9,12], aspects:"hard" },
    JURIDIQUE_UP:   { pairs:[["Jupiter","Jupiter"],["Jupiter","Descendant"],["Jupiter","Soleil"],["Jupiter","Ascendant"],["Vénus","Jupiter"]],
                      keyPlanets:["Jupiter","Vénus","Soleil"], houses:[7,9], aspects:"soft" },
    VOYAGE:         { pairs:[["Jupiter","Jupiter"],["Uranus","Jupiter"],["Jupiter","Ascendant"],["Mercure","Jupiter"],["Soleil","Jupiter"]],
                      keyPlanets:["Jupiter","Uranus","Mercure"], houses:[3,9], aspects:"soft" },
    // SPRINT 6.20 retour 81 (2026-05-11) — Q179-C SCANDALE.
    // Promesse natale = visibilité publique (Soleil/Lune/MC) ☌/dur Lilith
    // ou Pluton ☌/dur MC. La logique fine de cumul Public Personnae (A) +
    // Lilith native active (B) est calculée séparément en post-processing
    // (Piste E de _natalPromises) avec seuil ≥ 14 (S6.22.3 Q-γ). Cette définition générique
    // alimente seulement le score `_mdseNatalPromise.SCANDALE` consommé par
    // EVENT_SIGNATURES.SCANDALE.conditions.natal_promise pour donner du grain.
    SCANDALE:       { pairs:[["Lilith","Lune"],["Lilith","Soleil"],["Lilith","Milieu du Ciel"],
