// SPRINT 6.21.1 (2026-05-12, retour 82-bis astrologue D5+D8) — PATCH -bis :
// Connecter la Piste F HÉRITAGE (étoile bénéfique en M8 natale) au scoring
// _mdseNatalPromise consommé par EVENT_SIGNATURES.HÉRITAGE.
// ═══════════════════════════════════════════════════════════════════════════
// Bug détecté audit fa1d849 : la Piste F (lignes 1558-1623) écrit dans
// _natalPromises.heritagePisteFDiag mais le matcher EVENT_SIGNATURES consomme
// _mdseNatalPromise[code] (autre boucle ligne 4500-4615), sans pont entre les
// deux. Conséquence : sur 63 cas critiques, _q137HeritageDiag.appliedCount=0
// → la Piste F est inerte en S6.21.
//
// Patch : après calcul _mdseNatalPromise, on injecte un bonus selon le nombre
// de hits Piste F. Formule : 8 + 2 × hits, capé à 15. Cela garantit que tout
// sujet ayant Spica/Régulus/Sirius/Mirach/Véga/Zubeneschamali en M8 (ou
// Jupiter natal en M8) obtient un score de promesse HÉRITAGE ≥ 10, ce qui :
//   • Active la condition {type:"natal_promise",sigCode:"HÉRITAGE"} dans
//     EVENT_SIGNATURES.HÉRITAGE.
//   • Skippe le cap Q137-A @ 60 (HÉRITAGE peut monter > 60 légitimement).
try {
  const _heritagePisteF = (typeof _natalPromises !== "undefined")
    ? _natalPromises.heritagePisteFDiag
    : null;
  if (_heritagePisteF && _heritagePisteF.active && Array.isArray(_heritagePisteF.hits)) {
    const _f1Score = Math.min(15, 8 + (_heritagePisteF.hits.length * 2));
    const _previousScore = _mdseNatalPromise["HÉRITAGE"] || 0;
    if (_f1Score > _previousScore) {
      _mdseNatalPromise["HÉRITAGE"] = _f1Score;
      _mdseNatalPromiseDetails["HÉRITAGE"] = {
        ..._mdseNatalPromiseDetails["HÉRITAGE"],
        S621bisPisteFConnect: {
          previousScore: _previousScore,
          newScore: _f1Score,
          hits: _heritagePisteF.hits
        }
      };
    }
  }
} catch(e) {
  console.log("[WARN] S6.21.1 Piste F connect:", e.message);
}

