    const _ZR_YEARS = { "Bélier":15,"Taureau":8,"Gémeaux":20,"Cancer":25,"Lion":19,"Vierge":20,"Balance":8,"Scorpion":15,"Sagittaire":12,"Capricorne":27,"Verseau":30,"Poissons":12 };
