        const orbFactor = best.orb <= 0.3 ? 1.0 : best.orb <= 0.7 ? 0.9 : best.orb <= 1.0 ? 0.8 : 0.7;
        result.strength = Math.min(orbFactor + (pdHits.length - 1) * 0.1, 1.0);
        result.involvedPlanets = [...new Set(pdHits.flatMap(h => [h.planet, h.significator]))];
