          result.involvedHouses = _mdsePrenatalSyzygy ? [_mdsePrenatalSyzygy.house] : [];
          result.detail = `Syzygie prénatale (${_mdsePrenatalSyzygy?.type || "?"}) transitée par ${result.involvedPlanets.join("+")}`;
