  return result;
};

// --- MDSE : Évaluation globale de toutes les signatures ---
let _mdseResults = [];
const _mdseDebugAll = [];
let _mdsePreFilterSnapshot = []; // v19.12-instr : snapshot pré-filtre convergence/cap pour audit

// [INSTR-4.3-PREP] Sentinelle d'instrumentation sigJourney
// Capture l'état de _mdseResults aux ~10 points charnières du moteur.
// Lecture pure (zéro mutation), conditionnée par INSTR_PREV_4_3.
const _instrSnapshots = [];
const _recordSnapshot = (label) => {
  if (!INSTR_PREV_4_3) return;
  if (!Array.isArray(_mdseResults)) return;
  const snap = {};
  for (const sig of _mdseResults) {
    const entry = {
      confidence: sig.confidence,
      level: sig.level,
    };
    if (typeof sig._rawRatio === "number") entry._rawRatio = sig._rawRatio;
    if (typeof sig._heavyCount === "number") entry._heavyCount = sig._heavyCount;
    if (sig._pnaTier) entry._pnaTier = sig._pnaTier;
    if (typeof sig._pnaWeight === "number") entry._pnaWeight = sig._pnaWeight;
    if (sig._carriereDemoted) entry._carriereDemoted = { ...sig._carriereDemoted };
    if (sig._engagementContractCap) entry._engagementContractCap = { ...sig._engagementContractCap };
    snap[sig.code] = entry;
  }
  _instrSnapshots.push({ label, snapshot: snap });
};

try {
