// Détecte les déclencheurs précis : étoile fixe natale (em ∈ etoileMatchesNatal)
// touchant une planète natale, ET un transit lourd (Saturne/Jupiter/Uranus/Neptune/Pluton)
// partile (orb ≤ 0.5°) sur cette même planète pendant la peakWindow.
// Stocke dans sig.peakTriggerDates[] (option β étendue, validée astrologue retour 38).
// Mécanique : tableau pour capter la "triple frappe" classique des planètes lourdes
// rétrogradant 3 fois sur le même point. Précision peak date pour métrique recall@3d.
const _Q6C_HEAVY_TRANSITS = new Set(["Saturne","Jupiter","Uranus","Neptune","Pluton"]);
const _Q6C_PARTILE_ORB = 0.5;
const _Q6C_HIGH_ORB = 0.25;
try {
_mdseResults.forEach(sig => {
  const pStart = sig.peakWindow?.start || "";
  const pEnd = sig.peakWindow?.end || "9999-12-31";
  if (!pStart) return;
  const triggers = [];
  const starHits = _mdseFixedStarHits[sig.code] || [];
  for (const hit of starHits) {
    if (hit.isAngle) continue; // V1 : seulement planètes natales (les angles n'ont pas d'aspectsSuiviLent direct)
    const natalPlanet = hit.planet;
    // Scanner aspectsSuiviLent pour transits lourds → cette planète natale
    Object.keys(aspectsSuiviLent || {}).forEach(key => {
      const parts = key.replace("slow_", "").split("|||");
      if (parts.length !== 3) return;
      const pTransit = parts[0];
      const aspect = parts[1];
      const pNatal = parts[2];
      if (!_Q6C_HEAVY_TRANSITS.has(pTransit) || pNatal !== natalPlanet) return;
      const a = aspectsSuiviLent[key];
      for (const wave of (a.waves || [])) {
        const peakDate = wave.peakDate || wave.start;
        if (!peakDate || peakDate < pStart || peakDate > pEnd) continue;
        const orb = parseFloat(wave.minOrb);
        if (!Number.isFinite(orb) || orb > _Q6C_PARTILE_ORB) continue;
        triggers.push({
          date: peakDate,
          starName: hit.star,
          transitPlanet: pTransit,
          natalTarget: natalPlanet,
          transitAspect: aspect,
          orbAtPartile: Math.round(orb * 100) / 100,
          starOrb: hit.orb,
          boostedCodes: [sig.code],
          intensity: orb <= _Q6C_HIGH_ORB ? "high" : "medium"
        });
      }
    });
  }
  if (triggers.length > 0) {
    triggers.sort((a, b) => a.date.localeCompare(b.date));
    const seen = new Set();
    const dedup = [];
    for (const t of triggers) {
      const k = t.date + "|" + t.starName + "|" + t.transitPlanet + "|" + t.transitAspect;
      if (seen.has(k)) continue;
      seen.add(k);
      dedup.push(t);
    }
    sig.peakTriggerDates = dedup;
  }
});
} catch(e) { console.log("[WARN] Q6C peakTriggerDates:", e.message); }

