    //   Q3A : forfaitaire (+8 quel que soit le nombre de triggers high — doctrine
    //         "1 seule étincelle partile suffit à allumer la poudre").
    //   Q4A : aucun boost medium (0.25° < orb ≤ 0.5°). L'astrologie des étoiles fixes
    //         ne tolère pas l'à-peu-près : les étoiles projettent une lumière ponctuelle,
    //         au-delà de 0.25° l'éclair perd sa létalité.
    // Cap95 : autorise jusqu'à 95 même si la sig était cappée plus bas (ex. cap85).
    // Garde anti-régression : on ne baisse JAMAIS la confidence existante.
    const _Q6D_BOOST_HIGH = 8;
    const _Q6D_CAP = 95;
    let _q6dPromotionsCount = 0;
    try {
    _mdseResults.forEach(sig => {
      const triggers = Array.isArray(sig.peakTriggerDates) ? sig.peakTriggerDates : [];
      if (triggers.length === 0) return;
      const hasHigh = triggers.some(t => t && t.intensity === "high");
      if (!hasHigh) return;
      const before = sig.confidence || 0;
      const boosted = Math.min(_Q6D_CAP, before + _Q6D_BOOST_HIGH);
      if (boosted <= before) return;
      sig.confidence = boosted;
      sig.level = sig.confidence >= 55 ? "high" : sig.confidence >= 35 ? "medium" : "low";
      const sample = triggers.find(t => t.intensity === "high");
      sig._q6dPromoter = {
        boost: boosted - before,
        confidenceBefore: before,
        confidenceAfter: boosted,
        cap: _Q6D_CAP,
        highTriggerCount: triggers.filter(t => t && t.intensity === "high").length,
        sampleStar: sample?.starName || null,
        sampleTransit: sample ? `${sample.transitPlanet} ${sample.transitAspect} ${sample.natalTarget}` : null,
        sampleDate: sample?.date || null,
        sampleOrb: sample?.orbAtPartile ?? null
      };
      _q6dPromotionsCount++;
      if (INSTR_PREV_4_3) {
        console.log(`[Q6D] PROMOTEUR ${sig.code}: ${before}→${boosted} (+${boosted-before}) via ${sample?.starName}/${sample?.transitPlanet} ${sample?.transitAspect} ${sample?.natalTarget} orb=${sample?.orbAtPartile}° date=${sample?.date}`);
      }
    });
    if (INSTR_PREV_4_3 && _q6dPromotionsCount > 0) console.log(`[Q6D] Total promotions :`, _q6dPromotionsCount);
    } catch(eQ6D) { console.log("[WARN] Q6D promoteur:", eQ6D.message); }
    // === FIN [PROMOTEUR-Q6D-43d] ===

    // === [Q6D-FILTER-43e] Sprint 4.3e — Filtre natal Algol/Antarès (Q-OPS-6 OR libéral) ===
    // Validation astrologue retour 42 bonus + retour 43 §6 :
    //   "Algol ne détruit que si la structure natale est déjà fissurée. Conditionnez le boost
    //    avec un OR : (Maléfique natal sur un angle) OU (Maître de la 8 affligé) OU
    //    (Algol conjointe à un Luminaire natal ≤ 2°). Si aucune condition n'est remplie,
    //    l'étincelle d'Algol est étouffée."
    // MVP (retour 43 §6.3) — uniquement C1 et C3 (C2 désactivé : calcul maître M8 dynamique trop
    // coûteux pour rendement statistique quasi nul) :
    //   C1 : Mars OU Saturne natal ≤ 5° d'un des 4 angles AS/MC/DS/IC natal
    //   C3 : Algol OU Antarès natale ≤ 2° d'un luminaire natal (Soleil/Lune)
    // Scope : étendu narratif (retour 43 §6.2) — purge aussi les rangs 2+ pour éviter
    //   star-washing anxiogène dans le rapport LLM client (ex. "Vous avez frôlé la mort
    //   cette année..." sans support doctrinal réel).
    // Dry-run n=100 validé (PREV-DRY-RUN-Q6D-ALGOL-FILTER.md) :
    //   - 1 cas top-1 purgé : obama-1961 (Algol Jupiter Trigone Vesta orb 0.04°)
    //   - M4 : 81 → 82 (+1, ratchet dual M1=62 ✅ M4=82 ✅)
    //   - Préserve les 3 gains Q6-D légitimes (Elizabeth II / Zidane / Rowling — sur Régulus
    //     et Sirius, pas Algol/Antarès)
    const _Q6D_FILTER_STARS = new Set(["Algol", "Antarès", "Caput Algol", "Algol Caput"]);
    const _Q6D_FILTER_CODES = new Set(["ACCIDENT", "DEUIL", "CARRIERE_DOWN", "JURIDIQUE_DOWN"]);
    const _Q6D_FILTER_C1_ORB = 5.0;
    const _Q6D_FILTER_C3_ORB = 2.0;
    let _q6dFilterAnnulesCount = 0;
    try {
      const _ANGLE_NAMES_43e = ["Ascendant", "Milieu du Ciel", "Descendant", "Imum Coeli", "Fond du Ciel"];
      const _angleSep43e = (a, b) => {
        let d = Math.abs((Number(a)||0) - (Number(b)||0)) % 360;
        return d > 180 ? 360 - d : d;
      };
      const _c1MalefiquesAngulaires = (() => {
        for (const p of ["Mars", "Saturne"]) {
          const pDeg = (natalDict && natalDict[p] && natalDict[p].deg) ?? (natalPlanets.find(np => (np.planet?.fr === p || np.planet?.en === p))?.fullDegree);
          if (pDeg == null) continue;
          for (const aName of _ANGLE_NAMES_43e) {
            const aDeg = natalAngles[aName];
            if (aDeg == null) continue;
            if (_angleSep43e(pDeg, aDeg) <= _Q6D_FILTER_C1_ORB) return true;
          }
        }
        return false;
      })();
      const _c3StarLuminaire = (etoileMatchesNatal || []).some(em =>
        em && _Q6D_FILTER_STARS.has(em.etoile) &&
        ["Soleil", "Lune"].includes(em.planete) &&
        Number.isFinite(Number(em.orb)) && Number(em.orb) <= _Q6D_FILTER_C3_ORB
      );
      const _natalSupportOK = _c1MalefiquesAngulaires || _c3StarLuminaire;
      if (!_natalSupportOK) {
        _mdseResults.forEach(sig => {
          if (!sig._q6dPromoter) return;
          if (!_Q6D_FILTER_CODES.has(sig.code)) return;
          const star = sig._q6dPromoter.sampleStar;
          if (!_Q6D_FILTER_STARS.has(star)) return;
          const before = sig._q6dPromoter.confidenceBefore;
          const after  = sig._q6dPromoter.confidenceAfter;
          sig.confidence = before;
          sig.level = sig.confidence >= 55 ? "high" : sig.confidence >= 35 ? "medium" : "low";
          sig._q6dPromoter.filtered = true;
          sig._q6dPromoter.filteredReason = "Q-OPS-6 OR libéral : ni C1 (maléfique angulaire) ni C3 (étoile↔luminaire) → boost annulé";
          sig._q6dPromoter.confidenceAfter = before;
          _q6dFilterAnnulesCount++;
          if (INSTR_PREV_4_3) console.log(`[Q6D-FILTER-43e] ${sig.code}: ${after}→${before} (boost -${after-before} annulé) — étoile=${star} sans support natal`);
        });
      }
      if (INSTR_PREV_4_3) console.log(`[Q6D-FILTER-43e] Support natal C1=${_c1MalefiquesAngulaires} C3=${_c3StarLuminaire} → filtre actif=${!_natalSupportOK} | annulations=${_q6dFilterAnnulesCount}`);
    } catch(eFilter) { console.log("[WARN] Q6D filter:", eFilter.message); }
    // === FIN [Q6D-FILTER-43e] ===

    // === [ANGLES-44-BOOST] Sprint 4.4 Phase B — Boost angulaire (Lilly stricte + option C) ===
    // Doctrine validée retour 44 §1-§2 + retour 45 (arbitrages doctrinaux Q1-Q3) :
    //   • Q-OPS-1 (multiplicateurs) : AS=MC=1.0 ; DS=IC=0.6
    //   • Q-OPS-2 (planètes/aspects) : Saturne, Uranus, Neptune, Pluton + Jupiter (×0.8)
    //                                  Conjonction, Carré, Opposition (orbe ≤ 1.5°)
    //   • Q-OPS-3 (boost de base)   : médian +7
    //   • Q-OPS-5 (cap)             : 95 strict + flag isStellarApex
    //   • Méta-Q3 (discount)        : AA/A=1.0 | B=0.75 | C/UNKNOWN=0.5
    //   • Q1 retour 45 (tie-break)  : isStellarApex prioritaire (sortKey composite)
    //   • Q2 retour 45 (POLARITÉ)   : Lilly stricte par planète/aspect — Saturne/Pluton →
    //                                  signatures destructrices ; Jupiter → constructives ;
    //                                  Uranus Conjonction → libération ; Uranus Carré/Opp,
    //                                  Neptune Carré/Opp → maléfique-rupture/dissolutif.
    //   • Q3 retour 45 (axe)        : option C STRICTE — boost dominant unique sur l'angle
    //                                  physiquement le plus proche, axisActivated:true en
    //                                  flag narratif uniquement (pas de double boost).
    let _angles44BoostsCount = 0;
    try {
        const _A44_PLANETS  = new Set(["Saturne", "Uranus", "Neptune", "Pluton", "Jupiter"]);
        const _A44_ASPECTS  = new Set(["Conjonction", "Carré", "Opposition"]);
        const _A44_ANGLES   = ["Ascendant", "Milieu du Ciel", "Descendant", "Imum Coeli", "Fond du Ciel"];
        const _A44_ANGLE_SET = new Set(_A44_ANGLES);
        const _A44_ORB_MAX  = 1.5;
        const _A44_BOOST_BASE = 7;
        const _A44_CAP      = 95;
        // SPRINT 5.0 (2026-05-08) — P2 : multiplicateurs DSC/IC : 0.6 → 0.8.
        // Compromis Lilly stricte vs équité multi-axes (retour 5.0 P2) : un effondrement
        // de foyer (IC) ou de couple (DSC) a un impact événementiel comparable à une
        // promotion (MC). Subtile prime aux angles proactifs (1.0) conservée.
        const _A44_ANGLE_MULT = { "Ascendant": 1.0, "Milieu du Ciel": 1.0, "Descendant": 0.8, "Imum Coeli": 0.8, "Fond du Ciel": 0.8 };
        const _A44_PLANET_W   = { "Saturne":1.0, "Uranus":1.0, "Neptune":1.0, "Pluton":1.0, "Jupiter":0.8 };
        const _A44_DISCOUNT_TIME = { "AA":1.0, "A":1.0, "B":0.75, "C":0.5, "DD":0.5, "UNKNOWN":0.5, "X":0.5 };
        const _A44_RATING = (typeof birthDataRating !== "undefined" && birthDataRating) ? String(birthDataRating).toUpperCase() : "UNKNOWN";
        const _A44_DISCOUNT = _A44_DISCOUNT_TIME[_A44_RATING] ?? 0.5;

        // Q2 — Polarité Lilly stricte par (planète, aspect) → famille de signatures
        // - "malefic"          : Saturne/Pluton tous aspects → destructeur
        // - "benefic"          : Jupiter Conjonction → expansif
        // - "benefic_modere"   : Jupiter Carré/Opp → expansif tempéré (×0.8 supplémentaire)
        // - "benefic_rupture"  : Uranus Conjonction → libération constructive
        // - "malefic_rupture"  : Uranus Carré/Opp → crise/rupture
        // - "neutral_dissolve" : Neptune Conjonction → dissolution spirituelle (ambivalent)
        // - "malefic_dissolve" : Neptune Carré/Opp → dissolution destructrice
        const _A44_POLARITY = (planet, aspect) => {
            if (planet === "Saturne" || planet === "Pluton") return "malefic";
            if (planet === "Jupiter") return aspect === "Conjonction" ? "benefic" : "benefic_modere";
            if (planet === "Uranus")  return aspect === "Conjonction" ? "benefic_rupture" : "malefic_rupture";
            if (planet === "Neptune") return aspect === "Conjonction" ? "neutral_dissolve" : "malefic_dissolve";
            return "neutral_dissolve";
        };
        // Mapping signature par polarité × angle (Lilly/Morin tradition)
        const _A44_SIGS_BENEFIC = {
            "Ascendant"      : ["CARRIERE_UP", "SANTE_UP"],
            "Milieu du Ciel" : ["CARRIERE_UP", "JURIDIQUE_UP", "FINANCE_UP"],
            "Descendant"     : ["MARIAGE", "JURIDIQUE_UP"],
            "Imum Coeli"     : ["ENFANT", "IMMOBILIER"],
            "Fond du Ciel"   : ["ENFANT", "IMMOBILIER"],
        };
        const _A44_SIGS_MALEFIC = {
            "Ascendant"      : ["ACCIDENT", "SANTE_DOWN", "CARRIERE_DOWN"],
            "Milieu du Ciel" : ["CARRIERE_DOWN", "JURIDIQUE_DOWN", "FINANCE_DOWN"],
            "Descendant"     : ["SEPARATION", "JURIDIQUE_DOWN"],
            "Imum Coeli"     : ["DEUIL", "RELOCATION", "FINANCE_DOWN"],
            "Fond du Ciel"   : ["DEUIL", "RELOCATION", "FINANCE_DOWN"],
        };
        const _A44_SIGS_BENEFIC_RUPTURE = {  // Uranus Conjonction
            "Ascendant"      : ["RELOCATION", "CARRIERE_UP"],
            "Milieu du Ciel" : ["CARRIERE_UP", "RELOCATION"],
            "Descendant"     : ["MARIAGE", "SEPARATION"],
            "Imum Coeli"     : ["RELOCATION", "IMMOBILIER"],
            "Fond du Ciel"   : ["RELOCATION", "IMMOBILIER"],
        };
        const _A44_SIGS_MALEFIC_RUPTURE = {  // Uranus Carré/Opp
            "Ascendant"      : ["ACCIDENT", "RELOCATION"],
            "Milieu du Ciel" : ["CARRIERE_DOWN", "RELOCATION"],
            "Descendant"     : ["SEPARATION"],
            "Imum Coeli"     : ["RELOCATION", "DEUIL"],
            "Fond du Ciel"   : ["RELOCATION", "DEUIL"],
        };
        const _A44_SIGS_NEUTRAL_DISSOLVE = {  // Neptune Conjonction
            "Ascendant"      : ["SPIRITUEL", "SANTE_DOWN"],
            "Milieu du Ciel" : ["SPIRITUEL", "CARRIERE_DOWN"],
            "Descendant"     : ["SPIRITUEL", "SEPARATION"],
            "Imum Coeli"     : ["SPIRITUEL", "RELOCATION"],
            "Fond du Ciel"   : ["SPIRITUEL", "RELOCATION"],
        };
        const _A44_SIGS_MALEFIC_DISSOLVE = {  // Neptune Carré/Opp
            "Ascendant"      : ["SANTE_DOWN", "ACCIDENT"],
            "Milieu du Ciel" : ["CARRIERE_DOWN", "FINANCE_DOWN"],
            "Descendant"     : ["SEPARATION", "JURIDIQUE_DOWN"],
            "Imum Coeli"     : ["DEUIL", "FINANCE_DOWN"],
            "Fond du Ciel"   : ["DEUIL", "FINANCE_DOWN"],
        };
        const _A44_SIGS_BY_POLARITY = {
            "malefic"          : _A44_SIGS_MALEFIC,
            "benefic"          : _A44_SIGS_BENEFIC,
            "benefic_modere"   : _A44_SIGS_BENEFIC,
            "benefic_rupture"  : _A44_SIGS_BENEFIC_RUPTURE,
            "malefic_rupture"  : _A44_SIGS_MALEFIC_RUPTURE,
            "neutral_dissolve" : _A44_SIGS_NEUTRAL_DISSOLVE,
            "malefic_dissolve" : _A44_SIGS_MALEFIC_DISSOLVE,
        };
        // Multiplicateur supplémentaire pour Jupiter Carré/Opp (benefic modéré)
        const _A44_POLARITY_MULT = (pol) => pol === "benefic_modere" ? 0.8 : 1.0;

        // 1. Collecte des hits bruts depuis aspectsSuiviLent
        const _a44Hits = [];
        Object.keys(aspectsSuiviLent || {}).forEach(key => {
            const parts = key.replace("slow_", "").split("|||");
            if (parts.length < 3) return;
            const [pT, aspName, pN] = parts;
            if (!_A44_PLANETS.has(pT)) return;
            if (!_A44_ASPECTS.has(aspName)) return;
            if (!_A44_ANGLE_SET.has(pN)) return;
            const a = aspectsSuiviLent[key];
            const waves = a.waves || [];
            for (const w of waves) {
                const orb = parseFloat(w.minOrb);
                if (!Number.isFinite(orb) || orb > _A44_ORB_MAX) continue;
                _a44Hits.push({
                    transitPlanet : pT,
                    aspect        : aspName,
                    angleNatal    : pN,
                    orbAtPeak     : orb,
                    dateAtPeak    : w.peakDate || w.start || null,
                    multiplier    : _A44_ANGLE_MULT[pN] ?? 0.6,
                });
            }
        });

        // 2. Dedupe primaire : un même (planet, aspect, angle) sur plusieurs peaks (rétro
        //    triple-passage) → un seul hit à l'orbe minimal.
        const _a44Dedup1 = new Map();
        for (const h of _a44Hits) {
            const k = `${h.transitPlanet}|${h.aspect}|${h.angleNatal}`;
            const ex = _a44Dedup1.get(k);
            if (!ex || h.orbAtPeak < ex.orbAtPeak) _a44Dedup1.set(k, h);
        }
        const _a44HitsP = Array.from(_a44Dedup1.values());

        // 3. Dedupe axiale option C STRICTE (Q3 retour 45) : si une même planète/aspect
        //    touche un angle ET son angle conjugué dans la fenêtre, on garde UN SEUL hit
        //    (l'angle physiquement le plus proche = orbe minimal). L'angle conjugué reçoit
        //    seulement un flag axisActivated:true (narratif), aucun boost mathématique.
        const _A44_CONJUGATE = { "Ascendant":"Descendant", "Descendant":"Ascendant",
                                 "Milieu du Ciel":"Imum Coeli", "Imum Coeli":"Milieu du Ciel",
                                 "Fond du Ciel":"Milieu du Ciel" };
        const _a44Buckets = new Map(); // key = `${planet}|${aspect}|${axis}` (axis = paire normalisée)
        const _axisOf = (a) => {
            if (a === "Ascendant" || a === "Descendant") return "AS↔DS";
            if (a === "Milieu du Ciel" || a === "Imum Coeli" || a === "Fond du Ciel") return "MC↔IC";
            return a;
        };
        for (const h of _a44HitsP) {
            const k = `${h.transitPlanet}|${h.aspect}|${_axisOf(h.angleNatal)}`;
            const ex = _a44Buckets.get(k);
            if (!ex) {
                _a44Buckets.set(k, { ...h, axisActivated: false });
            } else {
                const isConj = _A44_CONJUGATE[ex.angleNatal] === h.angleNatal;
                if (isConj) {
                    // Garde le plus serré, flag axe activé sur le winner
                    const winner = h.orbAtPeak < ex.orbAtPeak ? h : ex;
                    _a44Buckets.set(k, { ...winner, axisActivated: true });
                } else {
                    // Cas rare : même axe label mais angles distincts non conjugués (ne devrait pas arriver)
                    if (h.orbAtPeak < ex.orbAtPeak) _a44Buckets.set(k, { ...h, axisActivated: ex.axisActivated });
                }
            }
        }
        const _a44Final = Array.from(_a44Buckets.values());

        // 3-bis. Enrichissement axisActivated par axe-planète (Q2 retour 45) :
        //   un hit (planète, angle) reçoit axisActivated=true si la même planète touche
        //   AUSSI le conjugué de l'angle, MEME via un aspect différent. Capture le cas
        //   Musk 2008 : Jupiter Opp AS (= Jupiter Conj DS géométriquement) → 2 hits avec
        //   aspects différents non-fusionnés par la dedupe axiale aspect-stricte. La
        //   croix axiale AS↔DS est physiquement activée même si le moteur a généré 2
        //   buckets distincts. Ce drapeau secondaire est déclencheur APEX (cf. §6).
        const _planetAxisAngles = new Map();
        for (const h of _a44Final) {
            const k = `${h.transitPlanet}|${_axisOf(h.angleNatal)}`;
            if (!_planetAxisAngles.has(k)) _planetAxisAngles.set(k, new Set());
            _planetAxisAngles.get(k).add(h.angleNatal);
        }
        for (const h of _a44Final) {
            if (h.axisActivated) continue;
            const k = `${h.transitPlanet}|${_axisOf(h.angleNatal)}`;
            const angles = _planetAxisAngles.get(k);
            const conj = _A44_CONJUGATE[h.angleNatal];
            if (angles && conj && angles.has(conj)) h.axisActivated = true;
        }

        // 4. Index sigs par code pour O(1) lookup
        const _a44SigByCode = new Map();
        for (const sig of _mdseResults) _a44SigByCode.set(sig.code, sig);

        // 5. Snapshot pré-boost : pour ratchet anti-régression M1 + tie-break stable.
        //    On capture (a) le top-1 confiance avant boost, (b) son code, (c) le rang
        //    initial de chaque signature (utilisé comme tie-break stable en cas d'égalité
        //    composite après tri).
        _mdseResults.sort((a, b) => (b.confidence || 0) - (a.confidence || 0));
        _mdseResults.forEach((s, i) => { s._preBoostRank = i; });
        const _a44Top1Before = _mdseResults[0] ? { code: _mdseResults[0].code, confidence: _mdseResults[0].confidence } : null;
        const _A44_BENEFIC_FAMILY = new Set([
            "CARRIERE_UP","JURIDIQUE_UP","FINANCE_UP","SANTE_UP","MARIAGE","ENFANT","IMMOBILIER","RELOCATION","SPIRITUEL","VOYAGE"
        ]);
        const _A44_TOP1_IS_BENEFIC = _a44Top1Before && _A44_BENEFIC_FAMILY.has(_a44Top1Before.code);

        // 6. Application du boost selon polarité (Q2 retour 45 — Lilly stricte) +
        //    cap cumulatif +6 par signature (garde-fou non-régression M1) +
        //    plafond anti-régression : un boost maléfique ne peut pas dépasser le top-1
        //    constructif pré-boost (sinon ratchet déclencherait, cf. cas Rowling 1997).
        const _A44_CUMUL_CAP = 6;
        for (const h of _a44Final) {
            const pol = _A44_POLARITY(h.transitPlanet, h.aspect);
            const sigsCandidates = (_A44_SIGS_BY_POLARITY[pol] || {})[h.angleNatal] || [];
            // Premier candidat présent dans _mdseResults avec confidence > 0
            let target = null;
            for (const code of sigsCandidates) {
                const sig = _a44SigByCode.get(code);
                if (sig && (sig.confidence ?? 0) > 0) { target = sig; break; }
            }
            if (!target) continue;
            // Garde-fou : signature déjà au cap → hit consommé sans bénéfice → skip
            // (évite de déclencher APEX abusif sur sig qui ne gagne rien, cf. Hitler/Tesla
            // où ACCIDENT=95 pré-boost recevait des hits angulaires gratuits).
            if ((target.confidence ?? 0) >= _A44_CAP) {
                if (INSTR_PREV_4_3) console.log(`[ANGLES-44-BOOST] SKIP ${target.code} (déjà cap=${_A44_CAP}) ← ${h.transitPlanet} ${h.aspect} ${h.angleNatal}`);
                continue;
            }
            const angleMult  = h.multiplier;
            const planetMult = _A44_PLANET_W[h.transitPlanet] ?? 1.0;
            const polMult    = _A44_POLARITY_MULT(pol);
            const boostNominal = Math.round(_A44_BOOST_BASE * angleMult * planetMult * polMult * _A44_DISCOUNT);
            if (boostNominal <= 0) continue;
            // Cap cumulatif par signature : la somme des boosts angulaires sur cette sig
            // ne peut pas dépasser _A44_CUMUL_CAP (= +6, calibration Q-OPS-3).
            const cumulSoFar = (target._anglesBoost44 || []).reduce((acc, b) => acc + b.boostApplied, 0);
            const remaining  = Math.max(0, _A44_CUMUL_CAP - cumulSoFar);
            const before = target.confidence;
            let after  = Math.min(_A44_CAP, before + Math.min(boostNominal, remaining));
            // SPRINT 5.0 (2026-05-08) — P1b : Garde-fou anti-régression M1 SUPPRIMÉ.
            // Cette règle plafonnait les boosts maléfiques à (top1Before.confidence - 1)
            // quand le top-1 pré-boost était bénéfique (= CARRIERE_UP dans 87/100 cas V1
            // et 80/100 cas V2). Effet pervers : DEUIL/SEPARATION/SANTE_DOWN ne pouvaient
            // JAMAIS détrôner CARRIERE_UP même avec transits massifs (Pluton sur Asc).
            // Lecture astrologue retour 5.0 P1b : "le deuil n'attend pas que la promotion
            // soit terminée pour frapper". Réf : PREV-FORENSIC §4.
            // Bloc d'origine (suppression intentionnelle) :
            //   const _polIsMalefic = (pol === "malefic" || pol === "malefic_rupture" || pol === "malefic_dissolve");
            //   if (_polIsMalefic && _A44_TOP1_IS_BENEFIC && _a44Top1Before && target.code !== _a44Top1Before.code) {
            //       const ceiling = Math.max(_a44Top1Before.confidence - 1, before);
            //       if (after > ceiling) after = ceiling;
            //   }
