// Extracteur de contexte pour une signature donnée.
// À partir du transitTrace[sig], identifie :
//   - dominantPlanet : la planète de transit qui a contribué le plus de score
//   - dominantNatalHouse : la maison natale la plus impactée (somme des scores)
//   - dominantAspect : l'aspect majoritaire
//   - topTriggers : top 3 transits par score (utile pour debug & LLM)
// Retourne null si aucun trace disponible.
function extractSignatureContext(traceArr) {
  if (!traceArr || traceArr.length === 0) return null;

  const byPlanet = {};
  const byHouse = {};
  const byAspect = {};
  for (const t of traceArr) {
    const p = t.transitP || "?";
    const h = t.natalHouse;
    const a = t.aspectName || "?";
    byPlanet[p] = (byPlanet[p] || 0) + (t.score || 0);
    if (h != null && h !== "?") byHouse[h] = (byHouse[h] || 0) + (t.score || 0);
    byAspect[a] = (byAspect[a] || 0) + (t.score || 0);
  }

  const top = (obj) => {
    const e = Object.entries(obj).sort((a, b) => b[1] - a[1])[0];
    return e ? e[0] : null;
  };

  const topTriggers = [...traceArr]
    .sort((a, b) => (b.score || 0) - (a.score || 0))
    .slice(0, 3)
    .map(t => ({
      transitP: t.transitP,
      aspect: t.aspectName,
      natalP: t.natalP,
      natalHouse: t.natalHouse,
      orb: typeof t.orb === "number" ? +t.orb.toFixed(2) : t.orb,
      score: typeof t.score === "number" ? +t.score.toFixed(2) : t.score
    }));

  return {
    dominantPlanet: top(byPlanet),
    dominantNatalHouse: top(byHouse) ? Number(top(byHouse)) : null,
    dominantAspect: top(byAspect),
    topTriggers
  };
}

