function _tg3ApplyModifier(code, c5, emp, natalDict) {
  if (!c5 || c5 <= 0) return c5;
  const conf = TG3_MODIFICATEURS[code];
  if (!conf || !emp || !natalDict) return c5;
  const blob = (emp.permissionTop || "") + " " + (emp.lentRoofPattern || "") + " " + (emp.declencheurTop || "");
  if (!blob.trim()) return c5;
  // Polarité des aspects natals qui modulent ce code
  const family_atten = conf.polarite === "UP" ? "hard" : "harmonic";
  const family_amp   = conf.polarite === "UP" ? "harmonic" : "hard";
  for (let i = 0; i < conf.cibles.length; i++) {
    const cible = conf.cibles[i];
    if (!natalDict[cible]) continue;
    let cibleHit = false;
    if (cible === "Vénus") cibleHit = /Vénus|Venus/.test(blob);
    else if (cible === "Milieu du Ciel") cibleHit = /Milieu du Ciel|MC\b/.test(blob);
    else cibleHit = new RegExp("\\b" + cible + "\\b").test(blob);
    if (!cibleHit) continue;
    // R1/R3 atténuation (prioritaire au sein d'une cible)
    const att = conf.attenuators || [];
    for (let j = 0; j < att.length; j++) {
      if (_pnaHasNatalAspect(natalDict, cible, att[j], family_atten)) {
        return Math.round(c5 * conf.mod_atten * 100) / 100;
      }
    }
    // R2/R4 amplification
    const amp = conf.amplifiers || [];
    for (let j = 0; j < amp.length; j++) {
      if (_pnaHasNatalAspect(natalDict, cible, amp[j], family_amp)) {
        return Math.round(c5 * conf.mod_amp * 100) / 100;
      }
    }
  }
  return c5;
}

