const SURFACE_FACTORS = {};
for (const [sig, w] of Object.entries(DTC_WEIGHTS)) {
  const sumPlanets = Object.values(w.planets).reduce((a, b) => a + b, 0);
  const sumHouses = Object.values(w.houses).reduce((a, b) => a + b, 0);
