// Note 205 : orbMultiplier scindé par vitesse planétaire.
// Doctrine : un orbe de 1° pour la Lune (3h) ≠ 1° pour Pluton (1 an).
// Les lentes en orbe large = climat de fond, pas événement déclencheur.
const SLOW_TRANSITERS = new Set(["Jupiter", "Saturne", "Uranus", "Neptune", "Pluton", "Nœud Nord", "Nœud Sud", "Chiron"]);

function orbMultiplier(orb, transitP = null) {
  if (!isFinite(orb)) return 1.0;
  const stripped = (transitP || "").replace(/^(ARC|PS|TP|fast_|slow_)\s*/, "");
  const isSlow = SLOW_TRANSITERS.has(stripped);

  if (isSlow) {
    // Lentes : identique aux rapides jusqu'à 1.5°, pénalité douce au-delà
    if (orb <= 0.1) return 1.5;
    if (orb <= 0.5) return 1.2;
    if (orb <= 1.0) return 1.0;
    if (orb <= 1.5) return 0.8;
    return 0.35;
  }
  // Rapides : courbe v31 souple (la fenêtre temporelle est courte)
  if (orb <= 0.1) return 1.5;
  if (orb <= 0.5) return 1.2;
  if (orb <= 1.0) return 1.0;
  if (orb <= 1.5) return 0.8;
  return 0.5;
}

function computeNatalResilience(ctx) {
  const RN = {};
  let RN_global = 0;

  const ETOILE_VALUES = {
    "royale_succes": 0.6,
    "benefic_pur": 0.6,
    "benefic_succes": 0.4,
    "royale_martial": 0.2,
    "martial": 0.2,
    "chagrin": -0.3,
    "malefic_pur": -0.6,
    "neutre": 0.0
  };

  const SECTE_DIURNE = ["Soleil", "Jupiter", "Saturne"];
  const SECTE_NOCTURNE = ["Lune", "Vénus", "Mars"];

  const planetsAndAngles = [
    "Soleil", "Lune", "Mercure", "Vénus", "Mars", "Jupiter", "Saturne", "Uranus", "Neptune", "Pluton",
    "Ascendant", "Milieu du Ciel", "Descendant", "Imum Coeli"
  ];

  for (const p of planetsAndAngles) {
    let score = 0;

    // 1. Étoiles fixes
    if (Array.isArray(ctx.etoiles)) {
      const em = ctx.etoiles.find(e => e.planete === p);
      if (em) {
        const nature = STAR_NATURES[em.etoile] || "neutre";
        const natureValue = ETOILE_VALUES[nature] || 0;
        const orbMax = ["Soleil", "Lune", "Ascendant", "Milieu du Ciel", "Descendant", "Imum Coeli"].includes(p) ? 2.0 : 1.5;
        const orb = parseFloat(em.orb);
        if (isFinite(orb) && orb <= orbMax) {
          const intensite = 1.0 - (orb / orbMax);
          score += natureValue * intensite;
        }
      }
    }

    // 2. Dignités
    const nd = ctx.natalDict && ctx.natalDict[p];
    if (nd) {
      if (nd.dignite === "Domicile" || nd.dignite === "Exaltation") score += 0.3;
      else if (nd.dignite === "Chute" || nd.dignite === "Exil") score -= 0.3;
    }

    // 3. Secte
    if (ctx.isDayChart !== undefined && nd) {
      if (ctx.isDayChart && SECTE_DIURNE.includes(p)) score += 0.1;
      else if (!ctx.isDayChart && SECTE_NOCTURNE.includes(p)) score += 0.1;
    }

    RN[p] = Math.max(-1.0, Math.min(1.0, score));
  }

  const ascRN = RN["Ascendant"] || 0;
  const mcRN = RN["Milieu du Ciel"] || 0;
  RN_global = Math.max(0, ascRN, mcRN); // On ne prend que le positif pour le bouclier global

  return { RN, RN_global };
}

