//   4. Transit Sol/Lun (luminaires) considérés actifs en permanence       → ×1.0
//   Sinon (transit "secondaire", typiquement outer-on-outer)              → ×0.3 (SOFT)
// Ne s'applique qu'aux 7 planètes traditionnelles pour le LotY (catégorie 1)
// — les modernes (Ur/Ne/Pl) ne peuvent JAMAIS être seigneur de l'année (Brennan/Brady).
// Chiron : exclu du filtre (traité doctrinalement par C3 quand DP).
// SOFT vs STRICT : SOFT (×0.3) retenu pour ne pas casser la régression.
function _c5LotyFilterMult(transitP, natalP, transitHouse, ctx) {
  // TEMP BENCH 2 2026-05-29 : flag hardcoded true pour mesure entonnoir C5 LotY.
  //   Au retour du bench, remettre env-driven default OFF.
  const DTC_C5_FILTRE_LOTY = true; // TEMP BENCH 2 (était env-driven default OFF)
  if (!DTC_C5_FILTRE_LOTY) return 1.0;
  // V22 bypass — Brennan Ch.17 LoY filter retiré en mode V22 (filtre catégoriel Brennan non utilisé).
  if (DTC_V22_NO_LOTY_FILTER) return 1.0;
  if (!ctx || !ctx.payload) return 1.0;

  const TRADITIONAL_7 = ["Soleil", "Lune", "Mercure", "Venus", "Mars", "Jupiter", "Saturne"];
  const SLOW_PLANETS  = ["Saturne", "Jupiter", "Uranus", "Neptune", "Pluton"];
  const FAST_PLANETS  = ["Soleil", "Lune", "Mercure", "Venus", "Mars"];
  const ANGLES        = ["ASC", "MC", "DSC", "IC", "Ascendant", "Milieu du Ciel"];

  // ── Cat. 4 : luminaires actifs en permanence
  if (transitP === "Soleil" || transitP === "Lune") return 1.0;

  // ── Cat. 1 : LotY impliqué (transitor OU receveur)
  const lordYear = ctx.payload && ctx.payload._profections && ctx.payload._profections.annuelle && ctx.payload._profections.annuelle.seigneur;
  if (lordYear && TRADITIONAL_7.indexOf(lordYear) >= 0) {
    if (transitP === lordYear || natalP === lordYear) return 1.0;
  }

  // ── Cat. 2 : planète lente sur planète rapide ou angle
  if (SLOW_PLANETS.indexOf(transitP) >= 0) {
    if (FAST_PLANETS.indexOf(natalP) >= 0) return 1.0;
    if (ANGLES.indexOf(natalP) >= 0) return 1.0;
  }

  // ── Cat. 3 : planète lente traversant la maison profectée annuelle
  // transitHouse = maison NATALE traversée par le transit (5e param de dtcAtomScore)
  const houseYear = ctx.payload && ctx.payload._profections && ctx.payload._profections.annuelle && ctx.payload._profections.annuelle.maison;
  if (houseYear && SLOW_PLANETS.indexOf(transitP) >= 0 && transitHouse === houseYear) return 1.0;

  // ── Sinon : transit "secondaire" → atténuation SOFT
  return 0.3;
}

// ─── DTC v10 — FEC additif plafonné (Gemini Note 162) ────────────────────────
// Au lieu de multiplier les facteurs (effet boule de neige x1.5×x1.5×x1.5),
// on accumule des deltas signés pondérés et on plafonne dans [0.4 ; 2.5].
// Les 4 piliers traditionnels (Secte, Dignité Natale, Étoile, Profection) +
// Configurations natales s'expriment via leur Δ propre, sans cumul exponentiel.
function dtcAtomScore(sig, transitP, natalP, aspectName, transitHouse, natalHouse, orb, isProg, ctx) {
  const w = DTC_WEIGHTS[sig];
  if (!w) return 0;

  // Note 207 : les Lots sont filtrés sauf si la matrice les déclare explicitement
  // (whitelist via les planets de la signature).
  if (natalP && natalP.includes("Lot") && !(w.planets[natalP] > 0)) return 0;

  const pT = w.planets[transitP] || 0.1;
  const pN = w.planets[natalP] || 0.1;
  const pWeight = pT * pN;

  const aWeight = w.aspects[aspectName] || 0;
  if (aWeight === 0) return 0;

  const hWeightT = w.houses[transitHouse] || 0;
  const hWeightN = w.houses[natalHouse] || 0;
  // Le max garantit que si l'une des maisons est topique, la signature s'active.
  // On ajoute un petit bonus (+0.5 * min) si la DEUXIÈME maison est aussi topique (double résonance),
  // mais on plafonne strictement à 1.2 pour éviter l'inflation des scores.
  let hWeight = Math.min(1.2, Math.max(hWeightT, hWeightN) + (Math.min(hWeightT, hWeightN) * 0.5));

  // Note 219 — Règle 2 : Déclencheur restrictif sur Maître
  // Si le transit touche le maître d'une maison topique, il déclenche la signature
  // MÊME SI la maison physique n'est pas touchée.
  // Condition stricte : transit majeur (Lente/Prog), aspect dur, orbe ≤ 1.0°
  if (hWeight === 0 && ctx && ctx.houseLords) {
    const topiques = CODE_HOUSES[sig] || [];
    let isTopicalLord = false;
    for (const h of topiques) {
      if (ctx.houseLords[h] === natalP) {
        isTopicalLord = true;
        break;
      }
    }

    if (isTopicalLord) {
      const isSlowOrProg = isProg || ["Jupiter", "Saturne", "Uranus", "Neptune", "Pluton", "Chiron"].includes(transitP);
      // Note 222 : On retire la restriction aux aspects durs. La matrice DTC_WEIGHTS 
      // filtre déjà les aspects pertinents (ex: FINANCE_UP accepte les Trigones).
      if (isSlowOrProg && orb <= 1.0) {
        hWeight = 0.5; // Poids plancher pour déclencher
      }
    }
  }

  // ─────────────────────────────────────────────────────────────────
  // Note 229 — Antisces (Aspects cachés de solstice)
  // On teste si la planète de transit forme un antisce ou contre-antisce
  // avec une planète natale ciblée par la signature.
  // Orbe très serré : ≤ 1.0° (les antisces sont des points mathématiques précis).
  // ─────────────────────────────────────────────────────────────────
  let antisceHit = false;
  let contraHit = false;
  if (ctx && ctx.natalAntisces && ctx.natalAntisces[natalP] && typeof transitDeg === "number") {
    const nAnt = ctx.natalAntisces[natalP].antisce;
    const nContra = ctx.natalAntisces[natalP].contra;

    // Calcul de la distance la plus courte sur le cercle (0-180)
    const distAnt = Math.min(Math.abs(transitDeg - nAnt), 360 - Math.abs(transitDeg - nAnt));
    const distContra = Math.min(Math.abs(transitDeg - nContra), 360 - Math.abs(transitDeg - nContra));

    if (distAnt <= 1.0) antisceHit = true;
    if (distContra <= 1.0) contraHit = true;
  }

  if (antisceHit || contraHit) {
    // Un antisce agit comme une conjonction (poids 1.0), un contre-antisce comme une opposition (poids 0.8)
    const antWeight = antisceHit ? 1.0 : 0.8;

    // On ne l'applique que si l'aspect "normal" n'a pas déjà un poids supérieur
    if (hWeight < antWeight) {
      hWeight = antWeight;
      // On ajoute un petit bonus pour signaler la nature "cachée/soudaine" de l'antisce
      fec += 0.10; 
    }
  }

  if (hWeight === 0) return 0;

  // Q190-bis (Gemini Note 165 Q-D19 / Note 166 Q-D26) — BENEFIC_BOOST strict
  // Note 185 : Supprimé car il crée une inflation artificielle face aux maléfiques
  let boostT = 1.0;

  // Note 185/187 : Malefic Boost restreint aux maisons de crise
  // Saturne, Neptune, Pluton en aspect dur sur planètes perso ou angles = x1.5
  // SEULEMENT SI la maison de transit ou la maison natale est 6, 8 ou 12.
  // Note 217 — Règle 3 (Secte) : Mars rejoint la liste UNIQUEMENT en thème
  // diurne (où il est le maléfique hors secte). En thème nocturne, c'est
  // Saturne qui est hors secte (boost déjà couvert) ; Mars est alors en secte
  // et n'amplifie PAS la crise (constructeur, action décisive).
  let maleficBoost = 1.0;
  const isHardMalef = ["Saturne", "Neptune", "Pluton"].includes(transitP)
    || (transitP === "Mars" && ctx && ctx.isDayChart === true);
  if (!isProg && isHardMalef) {
    const isPersonalOrAngle = ["Soleil", "Lune", "Mercure", "Vénus", "Mars", "Ascendant", "Milieu du Ciel", "Descendant", "Imum Coeli"].includes(natalP);
    const involvesCrisisHouse = [6, 8, 12].includes(transitHouse) || [6, 8, 12].includes(natalHouse);
    if (isPersonalOrAngle && involvesCrisisHouse && ["Conjonction", "Carré", "Opposition"].includes(aspectName)) {
      maleficBoost = 1.5;
    }
  }
  // Note 217 — Atténuation Saturne EN secte (thème diurne) : Saturne reste un
  // maléfique mais constructif/structurant en secte. On atténue son boost crise
  // pour respecter la doctrine de la secte tout en gardant la signature visible.
  if (!isProg && transitP === "Saturne" && ctx && ctx.isDayChart === true && maleficBoost > 1.0) {
    maleficBoost = 1.25; // au lieu de 1.5
  }

  // Q-G92 Arcs Solaires Majeurs (Gemini Note 165 Q-D19 INTÉGRER)
  // Lents en progression (ARC/PS) sur angles natals = années charnières.
  if (isProg && ["Saturne", "Jupiter", "Uranus", "Neptune", "Pluton"].includes(transitP)
      && ["Ascendant", "Milieu du Ciel", "Descendant", "Imum Coeli"].includes(natalP)) {
    boostT *= LENTES_SUR_AXES_MULT;
  }
  // Q-G91/Q-G88c/Q-G86/Q189-bis/Q-G85 : déplacés dans detectDoctrinalFlags
  // et appliqués globalement post-Convergence (cf. computeScores).

  // Trou n°3 corrigé (DTC v12) : RAPID_PENALTY conditionnel.
  // Mars est rapide mais ses configs avec Neptune/Pluton/Saturne (en M6/M8/M12)
  // ou avec lui-même sont des déclencheurs MAJEURS d'événements (SANTE_DOWN
  // psychique, ACCIDENT, DEUIL). Robin Williams 2014 : Mars Conj Neptune M12
  // 0.02° écrasé à 0.36 par le penalty alors que c'est LA signature de sa
  // dépression. Pareil pour Mars/Mars (récurrence martiale).
  const isRapid = ["Soleil", "Lune", "Mercure", "Vénus", "Mars"].includes(transitP);
  let rapidPenalty = 1.0;
  if (!isProg && isRapid) {
    // Whitelist des configs "non-pénalisées" même quand Mars est rapide
    const sensitivePair =
      (transitP === "Mars"   && ["Neptune","Pluton","Mars"].includes(natalP)) ||
      (transitP === "Mars"   && natalP === "Saturne" && [6,8,12].includes(natalHouse)) ||
      (transitP === "Vénus"  && natalP === "Vénus") ||
      (transitP === "Soleil" && ["Soleil","Milieu du Ciel","Ascendant"].includes(natalP));
    rapidPenalty = sensitivePair ? 1.0 : 0.3;
  }

  const isPositiveSig = ["CARRIERE_UP", "MARIAGE", "FINANCE_UP", "ENFANT", "RELOCATION"].includes(sig);
  const isDownSig = ["CARRIERE_DOWN", "SCANDALE", "JURIDIQUE_DOWN", "FINANCE_DOWN", "SANTE_DOWN", "ACCIDENT", "SEPARATION", "DEUIL"].includes(sig);
  const deltas = [];

  // Pilier A — Secte (Diurne / Nocturne)
  if (ctx && ctx.isDayChart !== undefined && !isProg) {
    if (ctx.isDayChart) {
      if (transitP === "Mars")    deltas.push(isPositiveSig ? -0.20 : +0.40);
      if (transitP === "Saturne") deltas.push(isPositiveSig ? +0.10 : -0.20);
    } else {
      if (transitP === "Saturne") deltas.push(isPositiveSig ? -0.20 : +0.40);
      if (transitP === "Mars")    deltas.push(isPositiveSig ? +0.10 : -0.20);
    }
  }

  // Piliers C/D + Configs : tout ce qui dépend de la planète natale touchée
  if (natalP && ctx && ctx.natalDict && ctx.natalDict[natalP]) {
    const nd = ctx.natalDict[natalP];

    // Dignité natale (déplacé dans RN, mais on garde l'impact FEC classique pour la force de l'événement)
    if (nd.dignite === "Domicile" || nd.dignite === "Exaltation") {
      deltas.push(isPositiveSig ? +0.30 : -0.20);
    } else if (nd.dignite === "Chute" || nd.dignite === "Exil") {
      deltas.push(isPositiveSig ? -0.20 : +0.30);
    }

    // Configurations natales — Phase R (16/05/26) : NEUTRALISÉES.
    //   Avant Phase R, le bench local tournait avec _configs=[] (bug build-payload-cache
    //   utilisant `configs` au lieu de `natalConfigurations`) ; toute la calibration
    //   DTC v18 (Phases L→Q) a donc été faite sans configs. À l'activation des configs
    //   en n8n live (PREPROD), M5 a chuté de 70% → 63%, M1 de 16% → 12%.
    //   Tests T1 (+0.10 globaux), T2 (+0.10 + ACCIDENT exclu) et T3 (désactivation totale) :
    //   seul T3 récupère M5=70%. Conclusion : les boosts configs sont du bruit pour la
    //   calibration actuelle. Code conservé pour réactivation future après recalibration.
    if (false && Array.isArray(ctx.configs)) {
      const inTension   = ctx.configs.some(c => ["T-Carré","Grand Carré","Yod"].includes(c.type)        && c.planets && c.planets.includes(natalP));
      const inFacilite  = ctx.configs.some(c => ["Grand Trigone","Cerf-Volant"].includes(c.type)        && c.planets && c.planets.includes(natalP));
      const inStellium  = ctx.configs.some(c => c.type === "Stellium"                                    && c.planets && c.planets.includes(natalP));
      if (inStellium)                  deltas.push(+0.30);
      if (inTension  && !isPositiveSig) deltas.push(+0.30);
      if (inFacilite &&  isPositiveSig) deltas.push(+0.30);
    }
  }

  // Note 219 — Règle 1 : Promesse des Maîtres de Maisons (Dignité)
  // Intégration douce via le FEC. Si le maître de la maison de transit OU
  // de la maison natale est en dignité forte, il teinte la réception du transit.
  // Restriction : on n'applique ce bonus/malus QUE si la maison (transit ou natale)
  // est TOPIQUE pour la signature évaluée.
  if (ctx && ctx.houseLords && ctx.natalDict) {
    const topiques = CODE_HOUSES[sig] || [];
    const lordsToEval = new Set();

    if (transitHouse && topiques.includes(transitHouse) && ctx.houseLords[transitHouse]) {
      lordsToEval.add(ctx.houseLords[transitHouse]);
    }
    if (natalHouse && topiques.includes(natalHouse) && ctx.houseLords[natalHouse]) {
      lordsToEval.add(ctx.houseLords[natalHouse]);
    }

    for (const lord of lordsToEval) {
      const nd = ctx.natalDict[lord];
      if (nd) {
        // En M3/M5, un delta de 0.05 suffit à faire basculer un score serré.
        // On garde l'asymétrie : un maître fort protège légèrement du pire (-0.05 sur DOWN)
        // et favorise le meilleur (+0.05 sur UP).
        if (nd.dignite === "Domicile" || nd.dignite === "Exaltation") {
          deltas.push(isPositiveSig ? +0.05 : -0.05);
        } else if (nd.dignite === "Chute" || nd.dignite === "Exil") {
          deltas.push(isPositiveSig ? -0.05 : +0.05);
        }
      }
    }
  }

  // Pilier D — Profection (Maison de l'année)
  // Note 205 : Le Seigneur de l'Année a été sorti du FEC additif (sous-évalué à +0.30)
  // pour devenir un multiplicateur direct ×1.4 (cf. plus bas dans le return).
  if (ctx && ctx.profections && ctx.profections.annuelle) {
    const profHouse = ctx.profections.annuelle.maison;
    if (transitHouse === profHouse) deltas.push(+0.20);
    if (ctx.natalDict && ctx.natalDict[natalP] && ctx.natalDict[natalP].house === profHouse) deltas.push(+0.20);
  }

  // Pilier E — Firdaria (Chronocrateur de période, Note 230)
  // Doctrine persane : la planète Firdaria majeure gouverne la période de vie.
  // Tentative atomique : delta +0.05/+0.075/+0.10 → tous neutres ou régressifs
  // sur le panel actuel. Code conservé en désactivé pour audit doctrinal.
  // if (ctx && ctx.firdaria) {
  //   const fMaj = ctx.firdaria.major;
  //   if (fMaj && (transitP === fMaj || natalP === fMaj)) deltas.push(+0.075);
  // }

  const totalDelta = deltas.reduce((s, d) => s + d, 0);
  const fec = Math.max(0.4, Math.min(2.5, 1.0 + totalDelta));

  // Note 205 : Seigneur de l'Année — multiplicateur ×1.4 (doctrine hellénistique)
  // « Un transit impliquant le Seigneur de l'Année est LE transit majeur de l'année »
  let profLordBoost = 1.0;
  if (ctx && ctx.profections && ctx.profections.annuelle) {
    const profLord = ctx.profections.annuelle.seigneur;
    if (profLord && (transitP === profLord || natalP === profLord)) {
      profLordBoost = 1.30;
    }
  }

  // Note 189 (Pattern C) : Malus retour Mars-Mars (transit banal cyclique 2 ans)
  let marsReturnPenalty = 1.0;
  if (!isProg && transitP === "Mars" && natalP === "Mars" && aspectName === "Conjonction") {
    marsReturnPenalty = 0.5;
  }

  // Note 198 : ROLLBACK v32 — aspectMod & slowMod désactivés
  // ─── DTC v17 — Filtre LotY (DOCTRINE-FILTRE-TRANSITS-LOTY-2026-05-28.md) ────
  // Helper retourne 1.0 si flag OFF (no-op) ou si transit "actif" (cat. 1-4).
  // Retourne 0.3 (SOFT) si transit secondaire (typiquement outer-on-outer).
  const lotyFilterMult = _c5LotyFilterMult(transitP, natalP, transitHouse, ctx);
  return pWeight * aWeight * hWeight * orbMultiplier(orb, transitP) * boostT * maleficBoost * rapidPenalty * marsReturnPenalty * fec * profLordBoost * lotyFilterMult;
}

function normalizeScore(sig, rawScore) {
  const surface = SURFACE_FACTORS[sig] || 1.0;
  const finalScore = (rawScore / surface) * 100;
  return finalScore < 5.0 ? 0 : Math.round(finalScore);
}

