// 2.B — DOCTRINE — Perles Q-N INTÉGRER (Gemini Note 165 Q-D19)
// ════════════════════════════════════════════════════════════════════
// Régences traditionnelles (Maîtres des 12 signes du zodiaque).
// Utilisé pour identifier le Maître de l'Ascendant (Q-G86 ACCIDENT_PHYSIQUE).
const TRAD_RULERS = {
  "Bélier": "Mars",      "Taureau": "Vénus",     "Gémeaux": "Mercure",
  "Cancer": "Lune",      "Lion": "Soleil",       "Vierge": "Mercure",
  "Balance": "Vénus",    "Scorpion": "Mars",     "Sagittaire": "Jupiter",
  "Capricorne": "Saturne","Verseau": "Saturne",  "Poissons": "Jupiter"
};

const HARD_ASPECTS = new Set(["Carré", "Opposition", "Conjonction"]);

// Note 217 — Maîtres de Maisons (depuis payload._houseLords, source N8N précise)
// Calcul en système traditionnel (cohérent avec les profections hellénistiques).
// Whole-sign fallback si la donnée N8N n'est pas exposée.
const ZODIAC_ORDER = ["Bélier", "Taureau", "Gémeaux", "Cancer", "Lion", "Vierge",
                      "Balance", "Scorpion", "Sagittaire", "Capricorne", "Verseau", "Poissons"];

function getHouseLords(payload) {
  const exposed = payload?._houseLords || null;
  const lords = {};
  if (exposed && typeof exposed === "object") {
    for (let h = 1; h <= 12; h++) {
      const entry = exposed[h] || exposed[String(h)];
      const signe = entry?.signe;
      lords[h] = signe ? (TRAD_RULERS[signe] || null) : null;
    }
    return lords;
  }
  const ascSign = payload?._natalDict?.["Ascendant"]?.sign;
  if (!ascSign) return lords;
  const ascIdx = ZODIAC_ORDER.indexOf(ascSign);
  if (ascIdx < 0) return lords;
  for (let h = 1; h <= 12; h++) {
    const signIdx = (ascIdx + h - 1) % 12;
    lords[h] = TRAD_RULERS[ZODIAC_ORDER[signIdx]] || null;
  }
  return lords;
}

// ════════════════════════════════════════════════════════════════════
// Helpers C6 — DÉTONATEUR (Phase 4 V4, 2026-05-28).
// Boussole : DOCTRINE-ENTONNOIR-VS-MOTEUR.md § 9.6.
// Doctrine :
//   • Éclipse alignée maison topique du code (Brady ch.6 p.230-233 :
//     "Si une éclipse tombe sur une planète natale impliquée dans l'une
//      de vos signatures, elle encadre la période exacte où l'événement
//      va se précipiter").
//   • Station planète lente (Saturne/Uranus/Neptune/Pluton) sur signifiant
//     natal du code (Rushman ch.7 p.196 : "Saturn stationed on my natal
//     Venus … My husband proposed marriage to me at that time").
// Anti-FP : double condition cumulée (les deux requises pour le boost).
// PROD-safe : ne référence aucun module externe, juste payload.
// Usage : appelés depuis le bloc C6 post-cap C1 dans computeScores.
// ════════════════════════════════════════════════════════════════════
function _c6EclipseAlignedCode(payload, code, orbMax) {
  if (!payload) return null;
  const topiques = CODE_HOUSES[code] || [];
  const signifiants = C6_SIGNIFIANTS_EXTRA[code] || [];
  if (signifiants.length === 0 && topiques.length === 0) return null;
  // Brady ch.6 strict (p.230-233) : éclipse partile sur planète natale
  // SIGNIFIANTE du code, en orbe ≤ orbMax (default 1.5°). Anti-Pénombrales.
  // Format n8n : { planet, house, orb, date, eclType, eclAstre, eclHouse }.
  // Champ _mdseEclipseNatalHits = filtre n8n des éclipses qui touchent une
  // planète natale en orbe doctrinal (≤ ~2° côté serveur).
  const natalHits = Array.isArray(payload._mdseEclipseNatalHits) ? payload._mdseEclipseNatalHits : [];
  // Union signifiants + maîtres topiques (acceptés comme planètes éligibles).
  const eligiblePlanets = new Set(signifiants);
  const lords = getHouseLords(payload);
  if (lords) {
    for (let i = 0; i < topiques.length; i++) {
      const lord = lords[topiques[i]];
      if (lord) eligiblePlanets.add(lord);
    }
  }
  if (eligiblePlanets.size === 0) return null;
  for (let i = 0; i < natalHits.length; i++) {
    const h = natalHits[i];
    if (!h) continue;
    if (/Pénombrale/i.test(h.eclType || "")) continue;
    if (typeof h.orb === "number" && h.orb > orbMax) continue;
    if (!h.planet || !eligiblePlanets.has(h.planet)) continue;
    return {
      kind: "natalHit",
      planet: h.planet,
      house: Number.isFinite(h.house) ? h.house : (Number.isFinite(h.eclHouse) ? h.eclHouse : null),
      type: h.eclType,
      orb: typeof h.orb === "number" ? h.orb : null,
      short: "ecl-" + (h.eclType || "?") + "/" + h.planet + "@" + (typeof h.orb === "number" ? h.orb.toFixed(2) + "°" : "?")
    };
  }
  return null;
}

function _c6SlowStationOnSignifier(payload, code, orbMax) {
  if (!payload || !payload._natalDict || !Array.isArray(payload._mdseStations)) return null;
  const topiques = CODE_HOUSES[code] || [];
  const extras = C6_SIGNIFIANTS_EXTRA[code] || [];
  const lords = getHouseLords(payload);
  const targets = new Set();
  for (let i = 0; i < extras.length; i++) targets.add(extras[i]);
  if (lords) {
    for (let j = 0; j < topiques.length; j++) {
      const lord = lords[topiques[j]];
      if (lord) targets.add(lord);
    }
  }
  if (targets.size === 0) return null;
  for (let k = 0; k < payload._mdseStations.length; k++) {
    const st = payload._mdseStations[k];
    if (!st || !C6_SLOW_STATION_PLANETS.has(st.planete)) continue;
    if (typeof st.fullDegree !== "number") continue;
    for (const tgt of targets) {
      const nData = payload._natalDict[tgt];
      if (!nData || typeof nData.deg !== "number") continue;
      const d = Math.abs(st.fullDegree - nData.deg);
      const dist = Math.min(d, 360 - d);
      if (dist <= orbMax) {
        return { planet: st.planete, target: tgt, orb: dist, short: st.planete + "->" + tgt + "@" + dist.toFixed(2) + "°" };
      }
    }
  }
  return null;
}

