const C4A_MAJOR_ASPECTS = new Set(["Conjonction", "Opposition", "Trigone", "Carré", "Carre"]);

function _c4aLunaProgAlignedCode(payload, code, orbMax) {
  if (!payload || !payload._progressedActivations) return null;
  const topiques = CODE_HOUSES[code] || [];
  const extras = C6_SIGNIFIANTS_EXTRA[code] || [];
  const lords = getHouseLords(payload);
  const targets = new Set();
  for (let i = 0; i < extras.length; i++) targets.add(extras[i]);
  if (lords) {
    for (let j = 0; j < topiques.length; j++) {
      const lord = lords[topiques[j]];
      if (lord) targets.add(lord);
    }
  }
  // Inclure luminaires comme cible doctrinale (Brennan ch.17 : lights = primary)
