  targets.add("Lune");
  if (targets.size === 0) return null;
  for (const tgt of targets) {
    const acts = payload._progressedActivations[tgt];
    if (!Array.isArray(acts) || acts.length === 0) continue;
    for (let k = 0; k < acts.length; k++) {
      const a = acts[k];
      if (!a || !a.pProg) continue;
      const promRaw = String(a.pProg).replace(/^Arc /i, "").replace(/^T→P /i, "").replace(/^T->P /i, "").split(/→|->/)[0].trim();
      if (promRaw !== "Lune") continue;
      const orb = parseFloat(a.orbe);
      if (!isFinite(orb) || orb > orbMax) continue;
      if (!C4A_MAJOR_ASPECTS.has(a.aspName)) continue;
      return { signif: tgt, asp: a.aspName, orb: orb, short: "LuneP·" + a.aspName + "·" + tgt + "@" + orb.toFixed(2) + "°" };
    }
  }
  return null;
}

