// Itère sur tous les aspects de transit (lents + rapides) et retourne ceux
// matchant un prédicat. Format de retour : { transitP, natalP, aspectName,
// natalHouse, orb }.
function findTransitHits(payload, predicate) {
  const blocks = [payload._aspectsSuiviLent || {}, payload._aspectsSuiviRap || {}];
  const hits = [];
  for (const block of blocks) {
    for (const [key, val] of Object.entries(block)) {
      if (!key || !val || !Array.isArray(val.waves) || val.waves.length === 0) continue;
      const parts = key.split("|||");
      const transitP = parts[0] ? parts[0].replace(/^fast_|^slow_/, "") : null;
      const aspectName = parts[1];
      const natalP = parts[2];
      const natalHouse = val.natalHouse;
      for (const wave of val.waves) {
        const orb = parseFloat(wave.minOrb);
        if (!isFinite(orb)) continue;
        const transitHouse = wave.transitHouseAtPeak || wave.transitHouseAtStart || null;
        const hit = { transitP, natalP, aspectName, natalHouse, transitHouse, orb };
        if (predicate(hit)) hits.push(hit);
      }
    }
  }

  if (payload._progressedActivations) {
    for (const [natalP, acts] of Object.entries(payload._progressedActivations)) {
      if (!Array.isArray(acts)) continue;
      for (const act of acts) {
        const transitP = act.pProg;
        const aspectName = act.aspName;
        const orb = act.orbe;
        const natalHouse = payload._natalDict?.[natalP]?.house || null;
        const hit = { transitP, natalP, aspectName, natalHouse, orb, isProg: true };
        if (predicate(hit)) hits.push(hit);
      }
    }
  }

  return hits;
}

// Détecte une fois par cas les configurations doctrinales déclencheuses.
// Retourne un objet de flags qui sera utilisé par computeScores pour
// appliquer des malus/boosts globaux par signature (post-Convergence).
function detectDoctrinalFlags(payload) {
  const natalDict = payload._natalDict || {};

  // Maître de l'Ascendant (Q-G86, base médiévale ACCIDENT_PHYSIQUE)
  const ascSign = natalDict["Ascendant"]?.sign;
  const ascRuler = ascSign ? TRAD_RULERS[ascSign] : null;

  // Q-G85 Anti-Gloire — Saturne/Uranus en transit dur sur Soleil/MC natal
  const antiGloireHits = findTransitHits(payload, h =>
    ["Saturne", "Uranus"].includes(h.transitP)
    && ["Soleil", "Milieu du Ciel"].includes(h.natalP)
    && HARD_ASPECTS.has(h.aspectName)
    && h.orb <= 2.0
  );

  // Q-G91 Honneurs M10/11 — Mars/Saturne en transit dur sur Soleil/MC natal
  const honneursAfflicHits = findTransitHits(payload, h =>
    ["Mars", "Saturne"].includes(h.transitP)
    && ["Soleil", "Milieu du Ciel"].includes(h.natalP)
    && HARD_ASPECTS.has(h.aspectName)
    && h.orb <= 1.5
  );

  // Q189-bis True Accident — Mars en transit dur sur Asc / planète en M6/M8,
  // orbe strict ≤ 1°.
  const trueAccidentHits = findTransitHits(payload, h => {
    if (h.transitP !== "Mars") return false;
    if (!HARD_ASPECTS.has(h.aspectName)) return false;
    if (!(h.orb <= 1.0)) return false;
    if (h.natalP === "Ascendant") return true;
    const np = natalDict[h.natalP];
    return np && [6, 8].includes(np.house);
  });

  // Q-G86 ACCIDENT_PHYSIQUE — Mars/Saturne/Pluton transit dur sur Maître Asc
  const accidentMaitreHits = ascRuler ? findTransitHits(payload, h =>
    ["Mars", "Saturne", "Pluton"].includes(h.transitP)
    && h.natalP === ascRuler
    && HARD_ASPECTS.has(h.aspectName)
    && h.orb <= 1.5
  ) : [];

  // Q-G88c REFORMULÉ — Saturne/Pluton en transit dur sur Mercure natal
  // → JURIDIQUE_DOWN (contrats bloqués, enquêtes).
  const juridiqueMercureHits = findTransitHits(payload, h =>
    ["Saturne", "Pluton"].includes(h.transitP)
    && h.natalP === "Mercure"
    && HARD_ASPECTS.has(h.aspectName)
    && h.orb <= 1.5
  );

  // Q-G91' (Note 166 Q-D21) — Scandale Médiatique
  // Mars/Saturne dur sur Mercure natal → SCANDALE
  const scandaleMediatiqueHits = findTransitHits(payload, h =>
    ["Mars", "Saturne"].includes(h.transitP)
    && h.natalP === "Mercure"
    && HARD_ASPECTS.has(h.aspectName)
    && h.orb <= 1.5
  );

  // Co-trigger Scandale Sexuel (Note 166 Q-D22 / Note 167 Q-D33)
  // Neptune/Uranus/Pluton dur sur Vénus ou Mars natale
  const scandaleSexuelHits = findTransitHits(payload, h =>
    ["Neptune", "Uranus", "Pluton"].includes(h.transitP)
    && ["Vénus", "Mars"].includes(h.natalP)
    && HARD_ASPECTS.has(h.aspectName)
    && h.orb <= 1.5
  );

  // Promesse Natale SCANDALE (Note 167 Q-D32 - ancienne Piste E)
  // Mercure ou Vénus natal en M3, M5 ou M10
  const promesseScandale = ["Mercure", "Vénus"].some(p => {
    const nd = natalDict[p];
    return nd && [3, 5, 10].includes(nd.house);
  });

  // Règle Anti-Téflon (Note 167 Q-D34)
  // Jupiter natal digne (Domicile/Exaltation) OU en aspect harmonique (Trigone/Sextile) au Soleil/MC
  let teflonNatal = false;
  const jupN = natalDict["Jupiter"];
  if (jupN) {
    if (jupN.dignite === "Domicile" || jupN.dignite === "Exaltation") {
      teflonNatal = true;
    } else if (payload._configs) {
      // On cherche si Jupiter fait partie d'une config harmonieuse avec Soleil/MC, ou on vérifie les aspects natals
      // Pour simplifier, on regarde si on a un Grand Trigone ou Cerf-Volant incluant Jupiter et Soleil/MC
      const hasHarmonic = payload._configs.some(c => 
        ["Grand Trigone", "Cerf-Volant"].includes(c.type) && 
        c.planets && c.planets.includes("Jupiter") && 
        (c.planets.includes("Soleil") || c.planets.includes("Milieu du Ciel"))
      );
      if (hasHarmonic) teflonNatal = true;
    }
  }

  return {
    ascRuler,
    antiGloire: antiGloireHits.length > 0,
    antiGloireHits,
    honneursAfflic: honneursAfflicHits.length > 0,
    honneursAfflicHits,
    trueAccident: trueAccidentHits.length > 0,
    trueAccidentHits,
    accidentMaitre: accidentMaitreHits.length > 0,
    accidentMaitreHits,
    juridiqueMercure: juridiqueMercureHits.length > 0,
    juridiqueMercureHits,
    scandaleMediatique: scandaleMediatiqueHits.length > 0,
    scandaleSexuel: scandaleSexuelHits.length > 0,
    promesseScandale,
    teflonNatal,
    natalDict
  };
}

