// 4. SCORING — application de la matrice DTC
// ════════════════════════════════════════════════════════════════════
function classifyProgKind(pProgRaw) {
  if (!pProgRaw) return null;
  if (/^Arc /i.test(pProgRaw)) return "ARC";
  if (/^T→P /i.test(pProgRaw) || /^T->P /i.test(pProgRaw)) return "TP";
  return "PS"; // Progression secondaire par défaut
}

function extractProgPlanet(pProgRaw) {
  if (!pProgRaw) return null;
  return pProgRaw.replace(/^Arc /i, "").replace(/^T→P /i, "").replace(/^T->P /i, "").split("→")[0].trim();
}

// ════════════════════════════════════════════════════════════════════
// 4.A — COUCHE 1 : LA PROMESSE DE L'ANNÉE (Profections + Progressions)
// ════════════════════════════════════════════════════════════════════
// "Un transit sans promesse ne produit rien de majeur. Une promesse sans
//  transit ne se déclenche pas." (Doctrine traditionnelle hellénistique)
//
// Pour chaque signature, on calcule un score de "Climat de Promesse"
// basé sur :
//   - la maison de l'année et son seigneur (Profection annuelle)
//   - les activations progressées (PS, ARC) qui touchent les planètes/maisons
//     thématiques de la signature
//
// Puis on convertit ce score en multiplicateur via une fonction logistique
// bornée [0.3 ; 2.0] qui s'applique aux Transits.
function computePromise(payload, debug) {
  const w_all = DTC_WEIGHTS;
  const natalDict = payload._natalDict || {};
  const progActs = payload._progressedActivations || {};
  const profections = payload._profections || null;

  // Extraction de l'âge pour le malus de cycle de vie (Gemini Note 163)
  const age = profections?.age || 30; // Par défaut adulte si non trouvé

  const promiseRaw = {};
  const promiseTrace = {};
  for (const sig of Object.keys(w_all)) {
    promiseRaw[sig] = 0;
    promiseTrace[sig] = [];
  }

  // ── Profection annuelle ────────────────────────────────────────
  if (profections && profections.annuelle) {
    const profHouse = profections.annuelle.maison;
    const profLord  = profections.annuelle.seigneur;
    const lordNatalHouse = profLord && natalDict[profLord] ? natalDict[profLord].house : null;

    for (const sig of Object.keys(w_all)) {
      const w = w_all[sig];
      const houseW = w.houses[profHouse] || 0;
      const lordW  = w.planets[profLord] || 0;
      const lordHouseW = lordNatalHouse ? (w.houses[lordNatalHouse] || 0) : 0;

      if (houseW > 0) {
        promiseRaw[sig] += houseW * 1.0;
        promiseTrace[sig].push(`Profection M${profHouse} (poids ${houseW.toFixed(1)})`);
      }
      if (lordW > 0) {
        promiseRaw[sig] += lordW * 0.7;
        promiseTrace[sig].push(`Seigneur année ${profLord} (poids ${lordW.toFixed(1)})`);
      }
      if (lordHouseW > 0) {
        promiseRaw[sig] += lordHouseW * 0.5;
        promiseTrace[sig].push(`Seigneur ${profLord} natal en M${lordNatalHouse} (poids ${lordHouseW.toFixed(1)})`);
      }
    }
  }

  // ── Progressions secondaires + Arcs solaires + T→P ─────────────
  for (const [pNatal, acts] of Object.entries(progActs)) {
    if (!Array.isArray(acts)) continue;
    const natalHouse = natalDict[pNatal]?.house ?? null;

    for (const a of acts) {
      const kind = classifyProgKind(a.pProg);
      // PS et ARC = vraies promesses ; TP est plus déclencheur, on l'ignore ici
      if (kind === "TP") continue;
      const progPlanet = extractProgPlanet(a.pProg);
      const aspectName = a.aspName;
      const orb = parseFloat(a.orbe);
      const progHouse = a.house ?? natalHouse;
      if (!isFinite(orb)) continue;

      for (const sig of Object.keys(w_all)) {
        const w = w_all[sig];
        const aW = w.aspects[aspectName] || 0;
        if (aW === 0) continue;
        const pNW = w.planets[pNatal]      || 0;
        const pPW = w.planets[progPlanet]  || 0;
        const hNW = w.houses[natalHouse]   || 0;
        const hPW = w.houses[progHouse]    || 0;
        const planetSig = (pNW + pPW) / 2;
        const houseSig  = (hNW + hPW) / 2;
        if (planetSig === 0 && houseSig === 0) continue;

        const orbBonus = orbMultiplier(orb, progPlanet);
        const progMult = PROG_MULT[kind] || 1.0;
        const contrib = (planetSig + houseSig) * aW * orbBonus * progMult * 0.4;
        if (contrib > 0) {
          promiseRaw[sig] += contrib;
          if (debug) promiseTrace[sig].push(`${kind} ${progPlanet}→${pNatal} ${aspectName} ${orb.toFixed(2)}° en M${progHouse} (+${contrib.toFixed(2)})`);
        }
      }
    }
  }

  // ── Conversion brut → multiplicateur logistique [0.20 ; 2.50] ──
  // (Trou n°11 corrigé DTC v13 : recentré sur x=3.0 et pente moins raide
  // pour ne pas saturer trop vite. v12 saturait dès x=4 → on perdait toute
  // discrimination entre une promesse forte et très forte.)
  // climat = 0      → mult = 0.31
  // climat = 1.0    → mult = 0.47
  // climat = 2.0    → mult = 0.78
  // climat = 3.0    → mult = 1.35  ← point pivot
  // climat = 4.0    → mult = 1.92
  // climat = 5.0    → mult = 2.23
  // climat = 7.0+   → mult = 2.45 (asymptote)
  const promiseMult = {};
  for (const sig of Object.keys(w_all)) {
    const x = promiseRaw[sig];
    promiseMult[sig] = 0.20 + 2.30 / (1 + Math.exp(-1.0 * (x - 3.0)));
  }

  return { promiseRaw, promiseMult, promiseTrace };
}

// ════════════════════════════════════════════════════════════════════
// 4.B — COUCHE 2 : LE DÉCLENCHEUR (Transits uniquement)
// ════════════════════════════════════════════════════════════════════
// Note 215 — Pour chaque signature, ensemble des Maîtres des maisons clés.
function computeTopicalLords(houseLords) {
  const topicalLords = {};
  for (const [sig, houses] of Object.entries(CODE_HOUSES)) {
    const set = new Set();
    for (const h of houses) {
      if (houseLords[h]) set.add(houseLords[h]);
    }
    topicalLords[sig] = set;
  }
  return topicalLords;
}

function computeTriggers(payload, debug) {
  const aspectsLents = payload._aspectsSuiviLent || {};
  const aspectsRaps  = payload._aspectsSuiviRap  || {};
  const natalDict    = payload._natalDict        || {};
  const configs      = payload._configs          || [];

  // ═══════════════════════════════════════════════════════════════════
  // Note 229 — Antisces (Aspects cachés de solstice)
  //   L'antisce est le point miroir par rapport à l'axe Cancer-Capricorne (0° Cancer - 0° Capricorne).
  //   Deux planètes en antisce "se voient" et agissent comme une conjonction secrète.
  //   Calcul : Antisce = 360° - (Degré de la planète) si on part de 0° Bélier.
  //   Mais l'axe de symétrie est 90° (Cancer) / 270° (Capricorne).
  //   Formule exacte : Antisce = (180 - Degré) % 360.
  //   Le contre-antisce est l'opposition de l'antisce : Contre-Antisce = (360 - Degré) % 360.
  //   On va précalculer les antisces et contre-antisces natals pour chaque planète.
  // ═══════════════════════════════════════════════════════════════════
  const _calcAntisce = (deg) => (180 - deg + 360) % 360;
  const _calcContraAntisce = (deg) => (360 - deg) % 360;

  const natalAntisces = {};
  if (natalDict) {
    for (const [p, data] of Object.entries(natalDict)) {
      if (typeof data.deg === "number") {
        natalAntisces[p] = {
          antisce: _calcAntisce(data.deg),
          contra: _calcContraAntisce(data.deg)
        };
      }
    }
  }

  const houseLords   = getHouseLords(payload);
  const topicalLords = computeTopicalLords(houseLords);

  const ctx = { natalDict, configs, isDayChart: payload._isDayChart, profections: payload._profections, firdaria: payload.firdariaActive || payload._firdariaActive, houseLords, topicalLords, natalAntisces };

  const transitScores = {};
  const transitTrace  = {};
  for (const sig of Object.keys(DTC_WEIGHTS)) {
    transitScores[sig] = [];
    transitTrace[sig]  = [];
  }

  const processBlock = (block) => {
    for (const [key, val] of Object.entries(block)) {
      if (!key || !val || !val.waves || !val.waves.length) continue;
      const parts = key.split("|||");
      const transitP = parts[0] ? parts[0].replace(/^fast_|^slow_/, "") : null;
      const aspectName = parts[1];
      const natalP = parts[2];
      const natalHouse = val.natalHouse;

      for (const wave of val.waves) {
        const transitHouse = wave.transitHouseAtPeak;
        const orb = parseFloat(wave.minOrb);
        if (!isFinite(orb)) continue;

        for (const sig of Object.keys(DTC_WEIGHTS)) {
          let s = dtcAtomScore(sig, transitP, natalP, aspectName, transitHouse, natalHouse, orb, false, ctx);
          if (s > 0) {
            // Trou n°15 corrigé : Boost de Pureté Angulaire (Q-D14)
            // Un transit exact (≤0.5°) d'une planète lente sur un Angle vaut double.
            const isLente = ["Jupiter", "Saturne", "Uranus", "Neptune", "Pluton"].includes(transitP);
            const isAngle = ["Ascendant", "Milieu du Ciel", "Descendant", "Imum Coeli"].includes(natalP);
            if (isLente && isAngle && orb <= 0.5 && ["Conjonction", "Opposition", "Carré"].includes(aspectName)) {
              s *= 2.0;
            }

            transitScores[sig].push(s);
            // Note 200 : transitTrace toujours rempli (garde-fous et pistes β/γ en dépendent)
            transitTrace[sig].push({ transitP, aspectName, natalP, transitHouse, natalHouse, orb, score: s, source: "transit" });
          }
        }
      }
    }
  };
  processBlock(aspectsLents);
  processBlock(aspectsRaps);

  // DTC v13 — Corrections du Trou n°9 (TP Mars/Angles polluants)
  //   • TP rapides (Mars/Vénus/Mercure/Soleil/Lune) → multiplier abaissé à 0.7
  //     (vs ARC=2.5, PS=2.0) car ils sont fréquents et peu différenciants.
  //   • Limite max de 1 TP rapide retenu par signature pour éviter la submersion.
  //   • RAPID_PENALTY (intégré dans dtcAtomScore via isProg=true gating) — NB: les
  //     progressions ne déclenchent pas le RAPID_PENALTY natif → on l'applique ici
  //     manuellement sur les TP rapides.
  const TRIGGER_PROG_MULT = { ARC: 2.5, PS: 2.0, TP: 0.7, DP: 2.0 };
  const RAPID_PROG = new Set(["Mars", "Vénus", "Mercure", "Soleil", "Lune"]);

  const progActs = payload._progressedActivations || {};
  // Comptage des TP rapides par signature pour appliquer le cap "1 max"
  const tpRapidCount = {};
  for (const sig of Object.keys(DTC_WEIGHTS)) tpRapidCount[sig] = 0;

  // Tri des progressions : on traite les ARC/PS d'abord (poids fort),
  // puis les TP triés par orbe pour ne garder que les plus précis.
  const allProgEntries = [];
  for (const [pNatal, acts] of Object.entries(progActs)) {
    if (!Array.isArray(acts)) continue;
    for (const a of acts) {
      allProgEntries.push({ pNatal, a, kind: classifyProgKind(a.pProg) });
    }
  }
  // ARC/PS d'abord, puis TP par orbe croissant (plus précis = plus important)
  allProgEntries.sort((a, b) => {
    if (a.kind !== b.kind) {
      if (a.kind === "TP" && b.kind !== "TP") return 1;
      if (b.kind === "TP" && a.kind !== "TP") return -1;
    }
    return parseFloat(a.a.orbe) - parseFloat(b.a.orbe);
  });

  for (const { pNatal, a, kind } of allProgEntries) {
    const natalHouse = natalDict[pNatal]?.house ?? null;
    const trigMult = TRIGGER_PROG_MULT[kind] || 1.0;
    const progPlanet = extractProgPlanet(a.pProg);
    const aspectName = a.aspName;
    const orb = parseFloat(a.orbe);
    const progHouse = a.house ?? natalHouse;
    if (!isFinite(orb)) continue;

    const isTpRapid = (kind === "TP" && RAPID_PROG.has(progPlanet));

    for (const sig of Object.keys(DTC_WEIGHTS)) {
      // Cap "1 max" pour les TP rapides
      if (isTpRapid && tpRapidCount[sig] >= 1) continue;

      const base = dtcAtomScore(sig, progPlanet, pNatal, aspectName, progHouse, natalHouse, orb, true, ctx);
      if (base > 0) {
        let triggerS = base * trigMult;
        // RAPID_PENALTY étendu aux TP rapides (sauf configs sensibles déjà whitelisted dans dtcAtomScore)
        if (isTpRapid) triggerS *= 0.4;

        // Q-D57 (Gemini Note 174) : Amplifier les progressions pour RELOCATION et SANTE_DOWN
        if (["ARC", "PS"].includes(kind) && ["RELOCATION", "SANTE_DOWN"].includes(sig)) {
          triggerS *= 1.5;
        }

        // Note 200 — Pattern D (ARC repolarisation) supprimé (audit A/B v199 : effet quasi-nul)

        transitScores[sig].push(triggerS);
        if (isTpRapid) tpRapidCount[sig]++;
        // Note 200 : transitTrace toujours rempli
        transitTrace[sig].push({ transitP: `${kind} ${progPlanet}`, aspectName, natalP: pNatal, transitHouse: progHouse, natalHouse, orb, score: triggerS, source: kind });
      }
    }
  }

  return { transitScores, transitTrace };
}

function computeStarBias(payload) {
  const etoiles = payload._etoileMatchesNatal || [];
  const etoilesCusp = payload._etoileCuspMatchesNatal || []; // Si on l'a
  const natalDict = payload._natalDict || {};
  const ascSign = natalDict["Ascendant"]?.sign;
  const ascRuler = ascSign ? TRAD_RULERS[ascSign] : null;

  const bias = {};
  for (const sig of Object.keys(DTC_WEIGHTS)) bias[sig] = 0;

  const processStar = (em, isAngleMatch) => {
    const info = STAR_CODE_MAP[em.etoile];
    if (!info) return;

    const nP = isAngleMatch ? em.angle : em.planete;
    const nHouse = em.maison || (natalDict[nP]?.house) || null;
    const orb = parseFloat(em.orb);
    if (!isFinite(orb)) return;

    // OrbMax adaptatif
    let orbMax = 1.5;
    if (info.orbMax) orbMax = info.orbMax; // Maléfiques garde-fou (1.0)
    if (["Soleil", "Lune", "Ascendant", "Milieu du Ciel", "Descendant", "Imum Coeli"].includes(nP)) orbMax = 2.0;
    if (orb > orbMax) return;

    // Filtre Points de Pouvoir (Q112-C épuré)
    let isPowerPoint = false;
    if (["Ascendant", "Milieu du Ciel", "Descendant", "Imum Coeli"].includes(nP)) isPowerPoint = true;
    if (["Soleil", "Lune", ascRuler].includes(nP)) isPowerPoint = true;

    // On évalue pour chaque code de l'étoile
    let activeCodes = info.codes;
    let currentBoost = info.boost;

    // Modulation contextuelle (Q-D45)
    if (info.contextualModifier) {
      const mod = info.contextualModifier(null, nHouse, nP); // Pas de transit ici, juste le natal
      if (mod) {
        if (mod.codes) activeCodes = mod.codes;
        if (mod.boost) currentBoost = mod.boost;
      }
    }

    for (const code of activeCodes) {
      let codeActivated = isPowerPoint;

      // Note 219 — Règle 4 : Teinture Stellaire des Maîtres (ISO Doctrine)
      // Si la planète touchée par l'étoile est le maître d'une maison topique pour ce code,
      // elle active l'étoile pour cette signature.
      if (!codeActivated) {
        const targetHouses = CODE_HOUSES[code] || [];
        const houseLords = getHouseLords(payload);
        if (houseLords) {
          for (const h of targetHouses) {
            if (houseLords[h] === nP) {
              codeActivated = true;
              break;
            }
          }
        }
      }

      // Astrologie locative : la planète est physiquement dans la maison du code
      if (!codeActivated && nHouse) {
        const targetHouses = CODE_HOUSES[code] || [];
        if (targetHouses.includes(nHouse)) codeActivated = true;
      }

      if (codeActivated) {
        let finalBoost = currentBoost;
        // Amplification sur les angles
        if (isAngleMatch) {
          if (nP === "Ascendant" && ["ACCIDENT", "SANTE_DOWN"].includes(code)) finalBoost *= 1.5;
          if (nP === "Milieu du Ciel" && ["CARRIERE_UP", "CARRIERE_DOWN", "SCANDALE"].includes(code)) finalBoost *= 1.5;
          if (nP === "Descendant" && ["MARIAGE", "SEPARATION"].includes(code)) finalBoost *= 1.5;
          if (nP === "Imum Coeli" && ["DEUIL", "RELOCATION"].includes(code)) finalBoost *= 1.5;
        }
        bias[code] += finalBoost;
      }
    }
  };

  for (const em of etoiles) processStar(em, false);
  for (const ec of etoilesCusp) processStar(ec, true);

  // Plafond de biais stellaire par code (+0.5 max)
  for (const sig of Object.keys(bias)) {
    bias[sig] = Math.min(0.5, bias[sig]);
  }

  return bias;
}

