// ─────────────────────────────────────────────────────────────────────
const _PNA_HARMONIC_ASPECTS = [
  { name: "Conjonction", deg: 0,   maxOrb: 8 },
  { name: "Sextile",     deg: 60,  maxOrb: 4 },
  { name: "Trigone",     deg: 120, maxOrb: 6 },
];
const _PNA_HARD_ASPECTS = [
  { name: "Carré",       deg: 90,  maxOrb: 6 },
  { name: "Opposition",  deg: 180, maxOrb: 8 },
];

function _pnaHasNatalAspect(natalDict, p1, p2, family, maxOrbOverride) {
  if (!natalDict) return null;
  const a = natalDict[p1];
  const b = natalDict[p2];
  if (!a || !b || a.deg == null || b.deg == null) return null;
  let diff = Math.abs(a.deg - b.deg);
  if (diff > 180) diff = 360 - diff;
  const aspects = family === "harmonic" ? _PNA_HARMONIC_ASPECTS : _PNA_HARD_ASPECTS;
  for (let i = 0; i < aspects.length; i++) {
    const asp = aspects[i];
    const maxO = (maxOrbOverride != null) ? maxOrbOverride : asp.maxOrb;
    if (Math.abs(diff - asp.deg) <= maxO) return asp.name;
  }
  return null;
}

function _pnaHouseOf(natalDict, p) { return natalDict[p] ? natalDict[p].house : undefined; }

// ─────────────────────────────────────────────────────────────────────
// _pnaApplyingAspectsCount(natalDict, planetName)
// Rushman ch.7 l.349-373 + l.495-498 — Compte les aspects majeurs
// (conjonction, sextile, carré, trine, opposition) que `planetName`
// applique aux planètes plus lentes AVANT de quitter son signe natal.
//
// Doctrine :
//   - Soleil ne peut applier qu'aux planètes plus lentes : Mars, Jupiter,
//     Saturne, Uranus, Neptune, Pluton (Rushman l.366-367).
//   - Lune peut applier à toutes les planètes (la plus rapide).
//   - "Avant qu'il quitte son signe" = parcours restant = (30 - deg_in_sign).
//   - Aspect Sun-Moon compte (Rushman l.369).
//
// PROD-safe : aucune dépendance externe, pas de process.env.
// ─────────────────────────────────────────────────────────────────────
function _pnaApplyingAspectsCount(natalDict, planetName) {
  if (!natalDict || !natalDict[planetName]) return 0;
  const p = natalDict[planetName];
  if (typeof p.deg !== "number") return 0;
  const PLANETARY_ORDER = ["Lune","Mercure","Vénus","Soleil","Mars","Jupiter","Saturne","Uranus","Neptune","Pluton"];
  const pIdx = PLANETARY_ORDER.indexOf(planetName);
  if (pIdx < 0) return 0;
  const slowerPlanets = PLANETARY_ORDER.slice(pIdx + 1);
  const ASPECTS_DEG = [0, 60, 90, 120, 180];
  const degInSign_p = ((p.deg % 30) + 30) % 30;
  const degTillExit = 30 - degInSign_p;
  let count = 0;
  for (let i = 0; i < slowerPlanets.length; i++) {
    const q = slowerPlanets[i];
    if (!natalDict[q] || typeof natalDict[q].deg !== "number") continue;
    const degAbs_q = natalDict[q].deg;
    for (let j = 0; j < ASPECTS_DEG.length; j++) {
      const aspDeg = ASPECTS_DEG[j];
      // Deux cibles possibles : q + asp ou q - asp
      const targets = [
        (((degAbs_q + aspDeg) % 360) + 360) % 360,
        (((degAbs_q - aspDeg) % 360) + 360) % 360,
      ];
      for (let k = 0; k < targets.length; k++) {
        const delta = ((targets[k] - p.deg) % 360 + 360) % 360;
        if (delta > 0 && delta < degTillExit) count++;
      }
    }
  }
  return count;
}

// _pnaLuminaireForGender(payload) → "Soleil" (F), "Lune" (M), ou null si genre inconnu.
// Sources possibles : payload.genre (n8n webhook étalé), payload.prev_business_fields.genre,
// payload._dtc_meta.genre (LABO). Fallback safe à null si aucune source.
function _pnaLuminaireForGender(payload) {
  if (!payload) return null;
  let g = null;
  if (payload.genre) g = payload.genre;
  else if (payload.prev_business_fields && payload.prev_business_fields.genre) g = payload.prev_business_fields.genre;
  else if (payload._dtc_meta && payload._dtc_meta.genre) g = payload._dtc_meta.genre;
  if (!g) return null;
  const gLower = String(g).trim().toLowerCase();
  if (gLower === "f" || gLower === "femme" || gLower === "female" || gLower === "woman" || gLower === "feminin" || gLower === "féminin") return "Soleil";
  if (gLower === "m" || gLower === "homme" || gLower === "male" || gLower === "man" || gLower === "masculin") return "Lune";
  return null;
}

// Phase 4.d (2026-05-27) — Comptage des axes PNA matchés par code.
// Implémente la Couche 2 doctrinale (Règle de Trois Valens) :
//   0 axe = promesse nulle (cap dur DTC_C1_CAP_VALUE)
//   1 axe = promesse marginale (atténuation DTC_C1_CAP_MULT_SOFT)
