// IMPORTANT : doit rester en miroir parfait des conditions de computeThematicPromises
// V1/V2 ci-dessus — sinon le cap conditionnel sera désaligné de la doctrine PNA.
function _pnaAxesCount(natalDict, payload, code) {
  if (!natalDict) return 0;
  const masterAsc = _pnaLord(payload, 1);
  let n = 0;

  // ─────────────────────────────────────────────────────────────────
  // V3 DOCTRINAL (2026-05-27) — Comptage miroir de la matrice V3 stricte.
  // Doit rester en miroir parfait des conditions p.<CODE> de
  // computeThematicPromises sous DTC_PNA_V3_DOCTRINAL=1.
  // ─────────────────────────────────────────────────────────────────
  if (DTC_PNA_V3_DOCTRINAL) {
    const m1v = masterAsc;
    const m2v = _pnaLord(payload, 2);
    // D1bis (2026-05-29) — Ajout maîtres M4/M6/M8/M9 pour miroir des codes
    //   Phase 2 (ACCIDENT/DEUIL/HÉRITAGE/RELOCATION/SEPARATION/JURIDIQUE_DOWN)
    //   et Phase 3 (SANTE/CARRIERE/FINANCE_DOWN, SCANDALE) — cf. doctrine miroir
    //   parfait avec computeThematicPromises L2669-2850.
    const m4v = _pnaLord(payload, 4);
    const m5v = _pnaLord(payload, 5);
    const m6v = _pnaLord(payload, 6);
    const m7v = _pnaLord(payload, 7);
    const m8v = _pnaLord(payload, 8);
    const m9v = _pnaLord(payload, 9);
    const m10v = _pnaLord(payload, 10);

    if (code === "CARRIERE_UP") {
      if (["Jupiter","Soleil","Mercure","Vénus","Mars","Lune","Saturne","Pluton"]
            .some(x => [10,11].includes(_pnaHouseOf(natalDict,x)))) n++;
      if (m10v && natalDict[m10v] && [1,2,10,11].includes(natalDict[m10v].house)) n++;
      if (m1v && natalDict[m1v] && [10,11].includes(natalDict[m1v].house)) n++;
      const lv = natalDict["Lot de Vocation"] || natalDict["Lot Vocation"];
      if (lv && [10,11].includes(lv.house)) n++;
      const lesp = natalDict["Lot de l'Esprit"] || natalDict["Lot d'Esprit"] || natalDict["Lot du Daemon"] || natalDict["Lot de Daimon"];
      if (lesp && [1,10,11].includes(lesp.house)) n++;
      const lex = natalDict["Lot d'Exaltation"];
      if (lex && [10,11].includes(lex.house)) n++;
      if (_pnaHasNatalAspect(natalDict, "Soleil", "Milieu du Ciel", "harmonic")) n++;
      if (_pnaHasNatalAspect(natalDict, "Soleil", "Jupiter", "harmonic")) n++;
      if (_pnaHasNatalAspect(natalDict, "Saturne", "Milieu du Ciel", "hard")) n++;
      if (_pnaHasNatalAspect(natalDict, "Saturne", "Milieu du Ciel", "harmonic")) n++;
      if (_pnaHasNatalAspect(natalDict, "Pluton", "Milieu du Ciel", "hard")) n++;
      if (_pnaHasNatalAspect(natalDict, "Pluton", "Milieu du Ciel", "harmonic")) n++;
      const juCar = natalDict["Junon"];
      if (juCar && [10,11].includes(juCar.house)) n++;
      const mcSign = _pnaSignOnCusp(payload, 10);
      if (mcSign && (["Sagittaire","Capricorne","Lion","Scorpion","Vierge"].includes(mcSign)
                     || _PNA_CARDINAL_SIGNS.includes(mcSign))) n++;
      if (_pnaNodeInHouse(natalDict, 10)) n++;
      if (_pnaHasNatalAspect(natalDict, "Lune", "Vénus", "harmonic")) n++;
      if (_pnaHasNatalAspect(natalDict, "Lune", "Jupiter", "harmonic")) n++;
      if (_pnaStarActivates(payload, "CARRIERE_UP")) n++;
      return n;
    }

    if (code === "FINANCE_UP") {
      if (["Jupiter","Vénus","Soleil","Lune"].some(x => [2,5,8,11].includes(_pnaHouseOf(natalDict,x)))) n++;
      if (m2v && natalDict[m2v] && [1,2,5,8,10,11].includes(natalDict[m2v].house)) n++;
      const lf = natalDict["Part de Fortune"] || natalDict["Lot de Fortune"];
      if (lf && [2,5,8,11].includes(lf.house)) n++;
      const lesp2 = natalDict["Lot de l'Esprit"] || natalDict["Lot d'Esprit"];
      if (lesp2 && [2,5,11].includes(lesp2.house)) n++;
      if (_pnaHasNatalAspect(natalDict, "Vénus", "Jupiter", "harmonic")) n++;
      if (_pnaHasNatalAspect(natalDict, "Vénus", "Jupiter", "hard")) n++;
      if (_pnaHasNatalAspect(natalDict, "Pluton", "Jupiter", "harmonic")) n++;
      if (_pnaHasNatalAspect(natalDict, "Pluton", "Vénus", "harmonic")) n++;
      if (_pnaHasNatalAspect(natalDict, "Uranus", "Jupiter", "harmonic")) n++;
      if (_pnaHasNatalAspect(natalDict, "Uranus", "Vénus", "harmonic")) n++;
      if (_pnaHasNatalAspect(natalDict, "Neptune", "Jupiter", "harmonic")) n++;
      if (_pnaHasNatalAspect(natalDict, "Neptune", "Vénus", "harmonic")) n++;
      if (_pnaHasNatalAspect(natalDict, "Jupiter", "Saturne", "harmonic")) n++;
      if (_pnaHasNatalAspect(natalDict, "Jupiter", "Saturne", "hard")) n++;
