      if (m7v && natalDict[m7v] && [1,5,7,10,11].includes(natalDict[m7v].house)) n++;
      if (m1v && natalDict[m1v] && natalDict[m1v].house === 7) n++;
      const lm = natalDict["Lot du Mariage"] || natalDict["Lot de Mariage"];
      if (lm && [1,5,7,11].includes(lm.house)) n++;
      const ju = natalDict["Junon"];
      if (ju && [1,5,7,10,11].includes(ju.house)) n++;
      if (lm && [2,8].includes(lm.house)) n++;
      const leros = natalDict["Lot d'Éros"] || natalDict["Lot d'Eros"];
      if (leros && [5,7,11].includes(leros.house)) n++;
      const cusp7 = _pnaSignOnCusp(payload, 7);
      if (cusp7 === "Sagittaire") n++;
      if (_pnaHouseOf(natalDict, "Jupiter") === 7) n++;
      const cuspAsc = _pnaSignOnCusp(payload, 1);
      if (cuspAsc && _PNA_MUTABLE_SIGNS.includes(cuspAsc)) n++;
      if (cusp7 && _PNA_MUTABLE_SIGNS.includes(cusp7)) n++;
      if (m1v && m7v && m1v !== m7v && _pnaHasNatalAspect(natalDict, m1v, m7v, "harmonic")) n++;
      if (_pnaStarActivates(payload, "MARIAGE")) n++;
      // Phase B+ Manque #1 (2026-05-30) — Rushman l.349, 362-373 (sous flag isolation).
      //   Cap à 3 = "potential number of marriages" doctrinal (Rushman).
      if (_DTC_ENABLE_APPLYING_MARIAGE) {
        const luminary = _pnaLuminaireForGender(payload);
        if (luminary) {
          const applying = _pnaApplyingAspectsCount(natalDict, luminary);
          if (applying > 0) n += Math.min(3, applying);
        }
      }
      return n;
    }

