        else if (_pnaHasNatalAspect(natalDict, "Saturne", "Neptune", "hard")) n++;
      }
      if (_pnaHouseOf(natalDict, "Neptune") === 10) {
        const protect = _pnaHasNatalAspect(natalDict, "Neptune", "Jupiter", "harmonic")
                     || _pnaHasNatalAspect(natalDict, "Neptune", "Vénus", "harmonic");
        if (!protect) n++;
      }
      if (m1v && natalDict[m1v] && [6,8,12].includes(natalDict[m1v].house)) n++;
      if (_pnaStarActivates(payload, "CARRIERE_DOWN")) n++;
      return _d1bisAxesGate(n, code);
    }

    return 0;
  }

  if (code === "CARRIERE_UP") {
    if (["Jupiter","Soleil","Mercure"].some(x => [10,11].includes(_pnaHouseOf(natalDict,x)))) n++;
    const m10 = _pnaLord(payload, 10);
    if (m10 && natalDict[m10] && [1,2,10,11].includes(natalDict[m10].house)) n++;
    if (masterAsc && natalDict[masterAsc] && [10,11].includes(natalDict[masterAsc].house)) n++;
    const lv = natalDict["Lot de Vocation"] || natalDict["Lot Vocation"];
    if (lv && [10,11].includes(lv.house)) n++;
    const lesp = natalDict["Lot de l'Esprit"] || natalDict["Lot d'Esprit"];
    if (lesp && [1,10].includes(lesp.house)) n++;
    if (_pnaHasNatalAspect(natalDict, "Soleil", "Milieu du Ciel", "harmonic")) n++;
    if (_pnaHasNatalAspect(natalDict, "Soleil", "Jupiter", "harmonic")) n++;
    if (DTC_PNA_REFONTE_V2) {
      if (["Saturne","Pluton","Vénus","Mars","Lune"].some(x => [10,11].includes(_pnaHouseOf(natalDict,x)))) n++;
      if (_pnaHasNatalAspect(natalDict, "Saturne", "Milieu du Ciel", "hard")) n++;
      if (_pnaHasNatalAspect(natalDict, "Saturne", "Milieu du Ciel", "harmonic")) n++;
      if (_pnaHasNatalAspect(natalDict, "Pluton", "Milieu du Ciel", "hard")) n++;
      if (_pnaHasNatalAspect(natalDict, "Pluton", "Milieu du Ciel", "harmonic")) n++;
      if (_pnaHasNatalAspect(natalDict, "Soleil", "Saturne", "hard")) n++;
      if (_pnaHasNatalAspect(natalDict, "Jupiter", "Ascendant", "harmonic")) n++;
      // V2.b miroir
      if (_pnaHasNatalAspect(natalDict, "Soleil", "Saturne", "harmonic")) n++;
      if (_pnaHasNatalAspect(natalDict, "Soleil", "Milieu du Ciel", "hard")) n++;
      const ju = natalDict["Junon"];
      if (ju && [10,11].includes(ju.house)) n++;
      const ld = natalDict["Lot du Daemon"] || natalDict["Lot de Daimon"];
      if (ld && [10,11].includes(ld.house)) n++;
      const lex = natalDict["Lot d'Exaltation"];
      if (lex && [10,11].includes(lex.house)) n++;
    }
    return n;
  }

  if (code === "FINANCE_UP") {
    if (["Jupiter","Vénus","Soleil","Lune"].some(x => [2,5,8,11].includes(_pnaHouseOf(natalDict,x)))) n++;
    const m2 = _pnaLord(payload, 2);
    if (m2 && natalDict[m2] && [1,2,5,8,10,11].includes(natalDict[m2].house)) n++;
    const lf = natalDict["Part de Fortune"] || natalDict["Lot de Fortune"];
    if (lf && [2,5,8,11].includes(lf.house)) n++;
    const lesp = natalDict["Lot de l'Esprit"] || natalDict["Lot d'Esprit"];
    if (lesp && [2,5,11].includes(lesp.house)) n++;
    return n;
  }

  if (code === "MARIAGE") {
    if (["Vénus","Jupiter","Lune"].some(x => [5,7,11].includes(_pnaHouseOf(natalDict,x)))) n++;
    const m7 = _pnaLord(payload, 7);
    if (m7 && natalDict[m7] && [1,5,7,10,11].includes(natalDict[m7].house)) n++;
    if (masterAsc && natalDict[masterAsc] && natalDict[masterAsc].house === 7) n++;
    const lm = natalDict["Lot du Mariage"] || natalDict["Lot de Mariage"];
    if (lm && [1,5,7,11].includes(lm.house)) n++;
    const ju = natalDict["Junon"];
    if (ju && [5,7,11].includes(ju.house)) n++;
    if (DTC_PNA_REFONTE_V2) {
      if (ju && [1,10].includes(ju.house)) n++;
      if (_pnaHasNatalAspect(natalDict, "Vénus", "Saturne", "harmonic")) n++;
      if (_pnaHasNatalAspect(natalDict, "Vénus", "Saturne", "hard")) n++;
      if (_pnaHasNatalAspect(natalDict, "Vénus", "Junon", "harmonic")) n++;
      if (lm && [2,8].includes(lm.house)) n++;
      const leros = natalDict["Lot d'Éros"] || natalDict["Lot d'Eros"];
      if (leros && [5,7,11].includes(leros.house)) n++;
      // V2.c miroir
      if (ju && ju.house === 4) n++;
      const m7Lord = _pnaLord(payload, 7);
      if (m7Lord && natalDict[m7Lord]) {
        const dig = natalDict[m7Lord].dignite;
        if (dig === "Domicile" || dig === "Exaltation") n++;
      }
    }
    return n;
  }

  if (code === "ENFANT") {
    if (["Jupiter","Lune","Vénus","Cérès","Soleil"].some(x => [5,11].includes(_pnaHouseOf(natalDict,x)))) n++;
    const m5 = _pnaLord(payload, 5);
    if (m5 && natalDict[m5] && [1,5,11].includes(natalDict[m5].house)) n++;
    const le = natalDict["Lot des Enfants"] || natalDict["Lot d'Enfant"];
    if (le && [1,5,7,11].includes(le.house)) n++;
    if (DTC_PNA_REFONTE_V2) {
      const ju = natalDict["Junon"];
      if (ju && ju.house === 5) n++;
      const FERTILE_SIGNS = ["Cancer","Taureau","Poissons","Scorpion"];
      const moonSign = natalDict["Lune"] && natalDict["Lune"].sign;
      if (moonSign && FERTILE_SIGNS.includes(moonSign)) n++;
      const venusSign = natalDict["Vénus"] && natalDict["Vénus"].sign;
      if (venusSign && ["Cancer","Taureau","Poissons"].includes(venusSign)) n++;
      const ceresSign = natalDict["Cérès"] && natalDict["Cérès"].sign;
      if (ceresSign && ["Cancer","Scorpion","Poissons"].includes(ceresSign)) n++;
      if (_pnaHasNatalAspect(natalDict, "Lune", "Vénus", "harmonic")) n++;
      if (_pnaHasNatalAspect(natalDict, "Lune", "Jupiter", "harmonic")) n++;
      // V2.c miroir
      const ce = natalDict["Cérès"];
      if (ce && [10,11].includes(ce.house)) n++;
      const lu = natalDict["Lune"];
      if (lu && lu.house === 1) n++;
    }
    return n;
  }

  return 0;
}

// ─────────────────────────────────────────────────────────────────────
// DTC v17 — Helper C2 V2 doctrinal (Brennan Ch.16 « Rule of Three »)
// Compte le nombre de CATÉGORIES INDÉPENDANTES activées (planet/house/lot)
// pour un code donné, à partir de CODE_RULE_OF_THREE et du natalDict.
// Retour : 0, 1, 2 ou 3.
// 1 = possible (Valens), 2 = probable, 3 = certain.
// Sourcing détaillé : DOCTRINE-CODE-RULE-OF-THREE-2026-05-28.md
// ─────────────────────────────────────────────────────────────────────
function _c2CategoriesActivated(natalDict, payload, code) {
  const conf = _getRule3Conf(code);
  if (!conf || !natalDict) return 0;
  const cats = { planet: false, house: false, lot: false };

  // ── CATÉGORIE 1 : planète signifiante naturelle dans une topique du code ──
  for (const p of conf.planets) {
    const np = natalDict[p];
    if (np && conf.houses.includes(np.house)) { cats.planet = true; break; }
  }
  // OU planète signifiante = maître d'une topique du code
  if (!cats.planet) {
    const lords = getHouseLords(payload);
    if (lords) {
      for (const h of conf.houses) {
        const lord = lords[h];
        if (lord && conf.planets.includes(lord)) { cats.planet = true; break; }
      }
    }
  }

  // ── CATÉGORIE 2 : maître d'une topique en maison appropriée au régime du code ──
  //
  // 2026-05-31 — Refonte asymétrique UP/DOWN (audit harmonisation doctrinale,
  //   TODO-AUDIT-HARMONISATION-DOCTRINALE.md §7.3 + AUDIT-VAGUE3 + audit cats).
  //
  // Convention initiale (UP-centrée) : maître EN « well-situated » M1/M5/M10/M11.
  //   Justifiée pour les codes UP par Brennan Ch.13 (Valens delineations « bien
  //   placés ») + joies des bénéfiques (M5=Vénus, M11=Jupiter).
  //
  // Pour les codes DOWN cette convention est inversée doctrinalement :
  //   - Brennan L17738 « M6 = Bad Fortune, joie de Mars »
  //   - Brennan Ch.10 M8 = mort, perte par autrui
  //   - Brennan L18382/L18963 M12 = joie de Saturne, enemies / afflicting causes
  //   - Rushman L577 « cancer or serious illness ... the natal setup has to be
  //     stimulated » — la promesse natale DOWN s'exprime par AFFLICTION, pas par
  //     bonne fortune.
  //
  // Donc :
  //   - codes UP (et codes Rule of 3 « positifs ») : maître EN {1,5,10,11} ∪ topique
  //   - codes DOWN (_ROT3_DOWN_3D_SET) : maître EN {6,8,12} ∪ topique
  //
  // Cette asymétrie élimine le bruit FP massif observé en audit cats 2026-05-31
  //   (SANTE_DOWN s'activait sur 13/14 cas non-DOWN absents = 93 % par la conven-
  //   tion UP). Voir _audit-cats-down-2026-05-31.json avant/après refonte.
  //
  // PROD-safe : _ROT3_DOWN_3D_SET est défini module-level (L667) ; comportement
  //   sans flag DTC_PHASE_B_DOWN_3D inchangé car _getRule3Conf retourne undefined
  //   pour les 4 codes DOWN et la fonction sort à `if (!conf)` ci-dessus.
  const lords2 = getHouseLords(payload);
  if (lords2) {
    // Extension Phase 2 LEGACY 2026-05-31 : convention DOWN inversée étendue aux
    //   4 codes Phase 2 DOWN-orientés (DEUIL, SEPARATION, JURIDIQUE_DOWN, ACCIDENT).
    //   Sans cette extension, ces 4 codes utilisaient la convention UP par défaut
    //   (maître M_topique en [1,5,10,11] = cats.house = true) qui sur-active les
    //   cats et génère des FP top1 massifs en mode LEGACY (bench 2026-05-31 :
    //   −24.7 pp M5 BLOC A vs OFF, FP type DEUIL@59 sur Jobs 2003 attendu SANTE_DOWN).
    //   Doctrine extension : Brennan ch.10 (M8 mort, M6 maladie, M12 enemies) +
    //   Rushman L577 ("natal setup has to be stimulated" pour DOWN). Voir
    //   AUDIT-DOCTRINAL-PNAAXES-LEGACY-2026-05-31.md §3.
    //   PROD-safe : extension flag-gated via DTC_C2_DOWN_INVERTED_PHASE2=1.
    //   Sans flag : comportement antérieur (4 codes Phase 2 en convention UP) intact.
    const _c2DownInvertedPhase2 = (typeof process !== "undefined" && process.env && process.env.DTC_C2_DOWN_INVERTED_PHASE2) ? true : false;
    const _phase2DownCodes = ["DEUIL", "SEPARATION", "JURIDIQUE_DOWN", "ACCIDENT"];
    // Phase C-1 Grappe 1 (2026-06-01) : convention DOWN inversée universelle
    //   sur les 8 codes _ROT3_DOWN_SET (4 Phase 3 + 4 Phase 2 DOWN). Avant
    //   bundle, seuls les 4 Phase 3 DOWN avaient la convention par défaut
    //   (les 4 Phase 2 attendaient le flag legacy `DTC_C2_DOWN_INVERTED_PHASE2`).
    //   Doctrine D8 + sources : SYNTHESE-PHASE-B-GRAPPE-1-SCORING-2026-06-01.md
    //   §1.2 + DOCTRINE-RUSHMAN-CH2-NATAL-PROMISE-2026-06-01.md §3 (BUG-C1-01).
    const isDownCode = _DTC_PHASE_C1_GRAPPE1
      ? Boolean(_ROT3_DOWN_SET[code])
      : Boolean(_ROT3_DOWN_3D_SET[code]) || (_c2DownInvertedPhase2 && _phase2DownCodes.includes(code));
    const regimeHouses = isDownCode ? [6, 8, 12] : [1, 5, 10, 11];
    const activationHouses = new Set(regimeHouses.concat(conf.houses));
    for (const h of conf.houses) {
      const lord = lords2[h];
      const nl = lord && natalDict[lord];
      if (nl && activationHouses.has(nl.house)) { cats.house = true; break; }
    }
  }

  // ── CATÉGORIE 3 : lot doctrinal en topique du code ──
  for (const lotName of conf.lots) {
    const nl = natalDict[lotName];
    if (nl && conf.houses.includes(nl.house)) { cats.lot = true; break; }
  }

  return (cats.planet ? 1 : 0) + (cats.house ? 1 : 0) + (cats.lot ? 1 : 0);
}

// ─────────────────────────────────────────────────────────────────────
// DTC v17 — Gate temporel C2 V2 (niveau 1 hellénistique sourcé)
// Brennan Ch.17 l.28098-28100 :
//   « When the annual profection comes to a specific place in a chart,
//     the topics associated with that place become activated during the
//     course of that year of the native's life. »
// Brennan Ch.17 l.28396-28397 :
//   « Whatever the planet promises in the natal chart will manifest when
//     it becomes activated as a time-lord. »
// Rushman l.320 :
//   « that potential must be found in the natal chart first ; then ...
//     determine if and when a stimulus will come along to actualize it. »
//
// Doctrine : la promesse natale (Rule of Three Ch.16) ne s'actualise pas
// d'elle-même. Pour autoriser le boost C2 V2 sur l'année courante, il
// faut au moins UN signal de timing hellénistique :
//   (1) maison profectée annuelle ∈ maisons topiques du code, OU
//   (2) seigneur de l'année (LotY) ∈ planètes signifiantes du code.
//
// Sans cette convergence profection/LotY, la promesse reste « dormante »
// (Brennan l.27981 « lie dormant ... until awakened as time-lords »).
//
// Niveau 2 plus strict (transit/DP/progression/éclipse convergent) =
// extension future, pas implémenté en phase 1 (à mesurer après le gate
// niveau 1).
// ─────────────────────────────────────────────────────────────────────
function _c2TemporalGateOK(code, payload) {
  const conf = _getRule3Conf(code);
  if (!conf) return false;
  const profAnn = payload && payload._profections && payload._profections.annuelle;
  if (!profAnn) return false;
  const houseMatch = (typeof profAnn.maison === "number") && conf.houses.includes(profAnn.maison);
  const lordMatch  = profAnn.seigneur && conf.planets.includes(profAnn.seigneur);
  return Boolean(houseMatch || lordMatch);
}

// ─────────────────────────────────────────────────────────────────────
// DTC v17 — Helpers signifiants stricts d'un code (pour gate niveau 2)
// Brennan Ch.16 l.27026 (planète) + Ch.13 Valens (maître Mx topique)
//   + Ch.16 l.27030 (lots doctrinaux) + angles spécifiques (CARRIERE_UP=MC,
//   MARIAGE=DSC).
// ─────────────────────────────────────────────────────────────────────
function _c2SignificantsForCode(code, payload) {
  const conf = _getRule3Conf(code);
  if (!conf) return new Set();
  const sigs = new Set();
  for (const p of conf.planets) sigs.add(p);
  const lords = getHouseLords(payload);
  if (lords) {
    for (const h of conf.houses) {
      if (lords[h]) sigs.add(lords[h]);
    }
  }
  for (const lot of conf.lots) sigs.add(lot);
  if (code === "CARRIERE_UP") sigs.add("Milieu du Ciel");
  if (code === "MARIAGE")     sigs.add("Descendant");
  return sigs;
}

function _c2SignificantPlanetsForCode(code, payload) {
  const conf = _getRule3Conf(code);
  if (!conf) return new Set();
  const sigs = new Set(conf.planets);
  const lords = getHouseLords(payload);
  if (lords) for (const h of conf.houses) if (lords[h]) sigs.add(lords[h]);
  return sigs;
}

// ─────────────────────────────────────────────────────────────────────
// DTC v17 — Gate temporel niveau 2 (convergence ≥ 2 familles)
// Source : DOCTRINE-GATE-NIVEAU-2-2026-05-29.md
//   - Brennan l.28620-28628 (Hephaestio : transits LotY/profected sign)
//   - Brennan l.28637-28639 (profections filtrent quels transits comptent)
//   - Rushman l.644 : « one planetary influence … will not produce a major event »
//   - Rushman l.1488 : « never just one planetary influence »
//   - Rushman l.425 : « several progressions, reinforcing transits, and an eclipse »
//   - Brady l.4723-4725 : orbe transit standard 1°
//   - Brady l.11118-11121 : orbes éclipse (conj 2.5° / opp 2° / sqr 1°)
//   - Rushman l.1443-1457 : station ±3-4°
//   - Brady l.12916-12941 : solar arc (LACUNE Brennan général)
// Convergence : ≥ 2 familles parmi {transit_lent, progression, lune_progressee,
//   dp, eclipse, station}, chaque famille = ≥ 1 hit sur signifiant strict
//   du code (planète canonique OU maître Mx topique OU lot doctrinal OU angle).
// PROD-safe : retourne false si payload incomplet ; pas de process direct.
// ─────────────────────────────────────────────────────────────────────
function _c2TemporalGateLevel2(code, payload) {
  if (!_getRule3Conf(code)) return false;
  if (!payload) return false;
  const sigs = _c2SignificantsForCode(code, payload);
  const sigPlanets = _c2SignificantPlanetsForCode(code, payload);
  if (sigs.size === 0) return false;

  const HELLENISTIC_SLOW = new Set(["Saturne", "Jupiter", "Uranus", "Neptune", "Pluton"]);
  const HARD_ASPECTS = new Set(["Conjonction", "Carré", "Opposition"]);
  const ORB_TRANSIT = 1.0;
  const ORB_DP      = 1.0;
  const ORB_ECLIPSE_CONJ = 2.5;

  const families = new Set();

  // (a) Transits lents (Brennan l.28620-28628 ; orbe Brady l.4723)
  const lentDict = payload._aspectsSuiviLent || {};
  for (const k of Object.keys(lentDict)) {
    if (families.has("transit_lent")) break;
    const parts = k.split("|||");
    if (parts.length !== 3) continue;
    const transitor = parts[0].replace(/^slow_/, "");
    const aspect    = parts[1];
    const cible     = parts[2];
    if (!HELLENISTIC_SLOW.has(transitor)) continue;
    if (!HARD_ASPECTS.has(aspect)) continue;
    if (!sigs.has(cible)) continue;
    const waves = (lentDict[k] && lentDict[k].waves) || [];
    let minOrb = Infinity;
    for (const w of waves) {
      const o = parseFloat(w.minOrb);
      if (isFinite(o) && o < minOrb) minOrb = o;
    }
    if (!isFinite(minOrb) || minOrb > ORB_TRANSIT) continue;
    families.add("transit_lent");
  }

  // (b) Progressions secondaires (Rushman l.636-642 ; orbe Brady l.5888 ~1°)
  const progDict = payload._progressedActivations || {};
  for (const target of Object.keys(progDict)) {
    if (families.has("progression")) break;
    if (!sigs.has(target)) continue;
    const arr = progDict[target] || [];
    const hasHard = arr.some(a => HARD_ASPECTS.has(a.aspName) && (typeof a.orbe === "number") && a.orbe <= 1.0 && (typeof a.weight !== "number" || a.weight >= 0.5) && a.pProg !== "Lune");
    if (hasHard) families.add("progression");
  }

  // (c) Lune progressée (Rushman l.776-778 ; orbe 3°)
  for (const target of Object.keys(progDict)) {
    if (families.has("lune_progressee")) break;
    if (!sigs.has(target)) continue;
    const arr = progDict[target] || [];
    const hasMoon = arr.some(a => a.pProg === "Lune" && (typeof a.orbe === "number") && a.orbe <= 3.0);
    if (hasMoon) families.add("lune_progressee");
  }

  // (d) Direction primaire / Solar Arc (Brady l.12916-12941)
  const dpArr = payload._mdsePrimaryDirections || [];
  for (const dp of dpArr) {
    if (families.has("dp")) break;
    if (!HARD_ASPECTS.has(dp.aspect)) continue;
    if (!(sigs.has(dp.significator) || sigPlanets.has(dp.promissor))) continue;
    if (typeof dp.orbDeg === "number" && dp.orbDeg > ORB_DP) continue;
    families.add("dp");
  }

  // (e) Éclipses (Brady l.11118-11121 + Rushman l.1625-1627)
  const eclArr = payload._mdseEclipseNatalHits || [];
  const houses = (_getRule3Conf(code) && _getRule3Conf(code).houses) || [];
  for (const e of eclArr) {
    if (families.has("eclipse")) break;
    if (!(typeof e.orb === "number") || e.orb > ORB_ECLIPSE_CONJ) continue;
    const isSig = sigPlanets.has(e.planet) || (typeof e.house === "number" && houses.includes(e.house));
    if (isSig) families.add("eclipse");
  }

  // (f) Stations (Rushman l.1443-1457) — planète signifiante ET hellénistique lente
  const stArr = payload._mdseStations || [];
  for (const s of stArr) {
    if (families.has("station")) break;
    if (sigPlanets.has(s.planete) && HELLENISTIC_SLOW.has(s.planete)) families.add("station");
  }

  // Convergence ≥ 2 familles (Rushman l.425, l.644)
  return families.size >= 2;
}

// IMPORTANT : payload._houseLords[h] peut être soit une string (legacy bench cache)
// soit un objet { signe, maitre } (méga-node n8n). Cette fonction normalise les
// deux formats vers le nom de planète. Sans cela, toutes les conditions
// « Maître Mx en My » sont silencieusement mortes en PROD.
function _pnaLord(payload, h) {
  if (!payload || !payload._houseLords) return null;
  const entry = payload._houseLords[h];
  if (!entry) return null;
  if (typeof entry === "string") return entry;
  if (typeof entry === "object" && entry.maitre) return entry.maitre;
  return null;
}

// ─────────────────────────────────────────────────────────────────────
// V3 Doctrinal (2026-05-27) — Pont étoiles fixes → matrice PNA
// Brady's Book of Fixed Stars : les étoiles sur Points de Pouvoir (ASC/MC/DESC/IC
// + luminaires) constituent une couche de promesse natale au même titre que les
// configurations planète/maison/lot. Cette fonction réutilise la table
// STAR_CODE_MAP (33 étoiles) déjà mappée à des codes PNA, sans dupliquer le
// scoring bias de processStar(). Activation : si une étoile dont la liste de
// codes contient `code` touche un Point de Pouvoir avec un orbe ≤ orbMax,
// alors la promesse natale du code est activée.
// ─────────────────────────────────────────────────────────────────────
const _PNA_POWER_POINTS = new Set([
  "Soleil","Lune","Ascendant","Milieu du Ciel","Descendant","Imum Coeli","MC","ASC","DESC","IC"
]);

function _pnaStarActivates(payload, code) {
  if (!payload) return false;
  const matches = payload._etoileMatchesNatal;
  if (!Array.isArray(matches) || matches.length === 0) return false;
  for (let i = 0; i < matches.length; i++) {
    const em = matches[i];
    if (!em) continue;
    const hit = _PNA_POWER_POINTS.has(em.planete) || _PNA_POWER_POINTS.has(em.angle);
    if (!hit) continue;
    const info = STAR_CODE_MAP[em.etoile];
    if (!info) continue;
    let codes = info.codes;
    if (typeof info.contextualModifier === "function") {
      const mod = info.contextualModifier(em.tHouse, em.nHouse, em.planete);
      if (mod && Array.isArray(mod.codes)) codes = mod.codes;
    }
    if (!Array.isArray(codes) || !codes.includes(code)) continue;
    const orb = parseFloat(em.orb);
    const orbMax = info.orbMax || 1.5;
    if (isFinite(orb) && orb <= orbMax) return true;
  }
  return false;
}

// ─────────────────────────────────────────────────────────────────────
// V3 Doctrinal (2026-05-27) — Helpers signe / cuspide / nœuds
// ─────────────────────────────────────────────────────────────────────
const _PNA_FERTILE_SIGNS = ["Cancer","Taureau","Poissons","Scorpion"];
const _PNA_MUTABLE_SIGNS = ["Gémeaux","Vierge","Sagittaire","Poissons"];
const _PNA_CARDINAL_SIGNS = ["Bélier","Cancer","Balance","Capricorne"];

function _pnaSignOnCusp(payload, h) {
  if (!payload || !payload._houseLords) return null;
  const entry = payload._houseLords[h];
  if (!entry || typeof entry !== "object") return null;
  return entry.signe || entry.sign || null;
}

function _pnaIsAngular(natalDict, p) {
  const h = _pnaHouseOf(natalDict, p);
  return h === 1 || h === 4 || h === 7 || h === 10;
}

function _pnaNodeInHouse(natalDict, h) {
  const nn = natalDict["Nœud Nord"] || natalDict["Noeud Nord"] || natalDict["Noeud nord"];
  const ns = natalDict["Nœud Sud"] || natalDict["Noeud Sud"] || natalDict["Noeud sud"];
  if (nn && nn.house === h) return true;
  if (ns && ns.house === h) return true;
  return false;
}

function computeThematicPromises(natalDict, payload = null) {
  // ─────────────────────────────────────────────────────────────────
  // Phase 4.b V3 (2026-05-27) — Matrice PNA DOCTRINAL STRICT sous flag
  // DTC_PNA_V3_DOCTRINAL. Source : AUDIT-EXHAUSTIF-BOUQUINS-2026-05.md.
  //   • 14 axes INVENTED purgés (CARRIERE_UP 4, MARIAGE 5, ENFANT 5)
  //   • ~30 axes Rushman/Brennan ajoutés (CARRIERE_UP signes MC + Nœuds M10 +
  //     Lune-Vénus/Jup harm ; MARIAGE Sag M7/Jup M7/mutables/Maître 1-7 harm ;
  //     ENFANT Gémeaux M5 ; FINANCE_UP 5 ; HÉRITAGE 2 ; DEUIL 1 ; SCANDALE 1)
  //   • Matrices SEPARATION (7 axes Rushman l.439-446) et CARRIERE_DOWN (3 axes
  //     Brennan + Rushman) intégralement implémentées
  //   • Pont étoiles fixes → PNA via _pnaStarActivates (33 étoiles, points de
  //     pouvoir, orbe doctrinal STAR_CODE_MAP)
  // PROD-safe : flag OFF par défaut → comportement V1/V2/legacy inchangé.
  // ─────────────────────────────────────────────────────────────────
  if (DTC_PNA_V3_DOCTRINAL && natalDict) {
    const p = {};
    const masterAsc = _pnaLord(payload, 1);
    const m1 = masterAsc;
    const m2 = _pnaLord(payload, 2);
    const m4 = _pnaLord(payload, 4);
    const m5 = _pnaLord(payload, 5);
    const m6 = _pnaLord(payload, 6);
    const m7 = _pnaLord(payload, 7);
    const m8 = _pnaLord(payload, 8);
    const m9 = _pnaLord(payload, 9);
    const m10 = _pnaLord(payload, 10);

    // ─── CARRIERE_UP — Rushman l.601-618, Brennan l.18888-18913, l.23806 ───
    p.CARRIERE_UP = (() => {
      // Axe 1 — Planètes carrière en M10/M11 (Rushman l.606-618 enrichi)
      if (["Jupiter","Soleil","Mercure","Vénus","Mars","Lune","Saturne","Pluton"]
            .some(x => [10,11].includes(_pnaHouseOf(natalDict,x)))) return true;
      // Axe 2 — Maître M10 en M1/M2/M10/M11 (Brennan l.23806)
      if (m10 && natalDict[m10] && [1,2,10,11].includes(natalDict[m10].house)) return true;
      // Axe 3 — Maître ASC en M10/M11 (tradition régent du I)
      if (m1 && natalDict[m1] && [10,11].includes(natalDict[m1].house)) return true;
      // Axe 4 — Lot de Vocation en M10/M11 (Brennan l.27445)
      const lv = natalDict["Lot de Vocation"] || natalDict["Lot Vocation"];
      if (lv && [10,11].includes(lv.house)) return true;
      // Axe 5 — Lot de l'Esprit / Daemon en M1/M10 (Brennan l.26991)
      const lesp = natalDict["Lot de l'Esprit"] || natalDict["Lot d'Esprit"] || natalDict["Lot du Daemon"] || natalDict["Lot de Daimon"];
      if (lesp && [1,10,11].includes(lesp.house)) return true;
      // Axe 6 — Lot d'Exaltation en M10/M11 (Brennan l.27467, extrapolation maison)
      const lex = natalDict["Lot d'Exaltation"];
      if (lex && [10,11].includes(lex.house)) return true;
      // Axe 7 — Soleil aspect MC harmonique (extrapolation Brady transits Sol-MC)
      if (_pnaHasNatalAspect(natalDict, "Soleil", "Milieu du Ciel", "harmonic")) return true;
      // Axe 8 — Soleil-Jupiter harmonique (Rushman l.612 Jupiter=career luck)
      if (_pnaHasNatalAspect(natalDict, "Soleil", "Jupiter", "harmonic")) return true;
      // Axe 9-12 — Saturne/Pluton aspectant MC (extrapolation Brady transits Sat-MC/Plu-MC)
      if (_pnaHasNatalAspect(natalDict, "Saturne", "Milieu du Ciel", "hard")) return true;
      if (_pnaHasNatalAspect(natalDict, "Saturne", "Milieu du Ciel", "harmonic")) return true;
      if (_pnaHasNatalAspect(natalDict, "Pluton", "Milieu du Ciel", "hard")) return true;
      if (_pnaHasNatalAspect(natalDict, "Pluton", "Milieu du Ciel", "harmonic")) return true;
      // Axe 13 — Junon en M10/M11 (Demetra George — engagement public)
      const ju = natalDict["Junon"];
      if (ju && [10,11].includes(ju.house)) return true;
      // ─── AJOUTS DOCTRINAUX V3 (Rushman l.601-602, l.550, l.575) ──────
      // Axe 14 — Signe sur MC : Sagittaire/Capricorne/Lion/Scorpion/Vierge ou cardinal
      const mcSign = _pnaSignOnCusp(payload, 10);
      if (mcSign && (["Sagittaire","Capricorne","Lion","Scorpion","Vierge"].includes(mcSign)
                     || _PNA_CARDINAL_SIGNS.includes(mcSign))) return true;
      // Axe 15 — Nœud Nord OU Sud sur M10 (Rushman l.550 — angular nodes for success)
      if (_pnaNodeInHouse(natalDict, 10)) return true;
      // Axe 16 — Lune-Vénus harmonique (Rushman l.575 — public acceptance)
      if (_pnaHasNatalAspect(natalDict, "Lune", "Vénus", "harmonic")) return true;
      // Axe 17 — Lune-Jupiter harmonique (Rushman l.575)
      if (_pnaHasNatalAspect(natalDict, "Lune", "Jupiter", "harmonic")) return true;
      // Axe 18 — Pont étoiles fixes (Brady FS : Régulus/Aldébaran/Sirius/Spica/Bételgeuse/
      //   Capella/Rigel/Mirfak/Véga/Altaïr/Deneb/Castor/Procyon/Arcturus/Toliman/Sadalmelik/
      //   Polis/Alphecca/Fomalhaut sur Point de Pouvoir)
      if (_pnaStarActivates(payload, "CARRIERE_UP")) return true;
      return false;
    })();

    // ─── FINANCE_UP — Brennan l.18555-18603, Rushman l.514-542 ─────────
    p.FINANCE_UP = (() => {
      // Axe 1 — Bénéfiques en M2/M5/M8/M11 (Rushman l.520-522, Brennan l.18555)
      if (["Jupiter","Vénus","Soleil","Lune"].some(x => [2,5,8,11].includes(_pnaHouseOf(natalDict,x)))) return true;
      // Axe 2 — Maître M2 en M1/M2/M5/M8/M10/M11 (tradition)
      if (m2 && natalDict[m2] && [1,2,5,8,10,11].includes(natalDict[m2].house)) return true;
      // Axe 3 — Lot de Fortune en M2/M5/M8/M11 (Brennan ch.16)
      const lf = natalDict["Part de Fortune"] || natalDict["Lot de Fortune"];
      if (lf && [2,5,8,11].includes(lf.house)) return true;
      // Axe 4 — Lot de l'Esprit en M2/M5/M11 (extrapolation Brennan l.26991)
      const lesp = natalDict["Lot de l'Esprit"] || natalDict["Lot d'Esprit"];
      if (lesp && [2,5,11].includes(lesp.house)) return true;
      // ─── AJOUTS DOCTRINAUX V3 (Rushman l.514-542) ──────────────────
      // Axe 5 — Vénus-Jupiter aspect (n'importe lequel) — Rushman l.542
      //   « any Venus/Jupiter aspect = lucky, marry/inherit/create/win money »
      if (_pnaHasNatalAspect(natalDict, "Vénus", "Jupiter", "harmonic")) return true;
      if (_pnaHasNatalAspect(natalDict, "Vénus", "Jupiter", "hard")) return true;
      // Axe 6 — Pluton-Jupiter / Pluton-Vénus aspects (Rushman l.516 — money inherited)
      if (_pnaHasNatalAspect(natalDict, "Pluton", "Jupiter", "harmonic")) return true;
      if (_pnaHasNatalAspect(natalDict, "Pluton", "Vénus", "harmonic")) return true;
      // Axe 7 — Uranus/Neptune-Vénus/Jupiter harmoniques (Rushman l.514 — windfall)
      if (_pnaHasNatalAspect(natalDict, "Uranus", "Jupiter", "harmonic")) return true;
      if (_pnaHasNatalAspect(natalDict, "Uranus", "Vénus", "harmonic")) return true;
      if (_pnaHasNatalAspect(natalDict, "Neptune", "Jupiter", "harmonic")) return true;
      if (_pnaHasNatalAspect(natalDict, "Neptune", "Vénus", "harmonic")) return true;
      // Axe 8 — Jupiter-Saturne aspect trigone OU carré (Rushman l.519)
      if (_pnaHasNatalAspect(natalDict, "Jupiter", "Saturne", "harmonic")) return true;
      if (_pnaHasNatalAspect(natalDict, "Jupiter", "Saturne", "hard")) return true;
      // Axe 9 — Soleil angular M1/M4/M7/M10 (Rushman l.528 — "push to make it")
      if (_pnaIsAngular(natalDict, "Soleil")) return true;
      // Axe 10 — Pont étoiles fixes (Aldébaran, Spica, Sirius, Capella, Rigel, Véga,
      //   Arcturus, Zubeneschamali, Mirach, Ascella, Deneb Algedi sur Point de Pouvoir)
      if (_pnaStarActivates(payload, "FINANCE_UP")) return true;
      return false;
    })();

    // ─── MARIAGE — Brennan l.18792-18805, l.23436-23449, Rushman l.331-435 ──
    p.MARIAGE = (() => {
      // Axe 1 — Bénéfiques mariage en M5/M7/M11 (Rushman l.351, l.417-420)
      if (["Vénus","Jupiter","Lune"].some(x => [5,7,11].includes(_pnaHouseOf(natalDict,x)))) return true;
      // Axe 2 — Maître M7 en M1/M5/M7/M10/M11 (Rushman l.350, Brennan l.23436+)
      if (m7 && natalDict[m7] && [1,5,7,10,11].includes(natalDict[m7].house)) return true;
      // Axe 3 — Maître ASC en M7 (Rushman l.352 — rulers of 1st and 7th)
      if (m1 && natalDict[m1] && natalDict[m1].house === 7) return true;
      // Axe 4 — Lot du Mariage en M1/M5/M7/M11 (Brennan l.23232, l.27030)
      const lm = natalDict["Lot du Mariage"] || natalDict["Lot de Mariage"];
      if (lm && [1,5,7,11].includes(lm.house)) return true;
      // Axe 5 — Junon en M5/M7/M11 ou M1/M10 (Demetra George — épouse identité/public)
      const ju = natalDict["Junon"];
      if (ju && [1,5,7,10,11].includes(ju.house)) return true;
      // Axe 6 — Lot du Mariage en M2/M8 (Brennan l.26965 — exemple explicite M2)
      if (lm && [2,8].includes(lm.house)) return true;
      // Axe 7 — Lot d'Éros en M5/M7/M11 (Brennan l.27595 — desire/friendship)
      const leros = natalDict["Lot d'Éros"] || natalDict["Lot d'Eros"];
      if (leros && [5,7,11].includes(leros.house)) return true;
      // ─── AJOUTS DOCTRINAUX V3 (Rushman l.335, l.417, l.426, l.421) ───
      // Axe 8 — Sagittaire sur cuspide M7 OU Jupiter en M7 (Rushman l.335 — multiple marriages)
      const cusp7 = _pnaSignOnCusp(payload, 7);
      if (cusp7 === "Sagittaire") return true;
      if (_pnaHouseOf(natalDict, "Jupiter") === 7) return true;
      // Axe 9 — Signes mutables sur axe ASC-DESC (Rushman l.426)
      const cuspAsc = _pnaSignOnCusp(payload, 1);
      if (cuspAsc && _PNA_MUTABLE_SIGNS.includes(cuspAsc)) return true;
      if (cusp7 && _PNA_MUTABLE_SIGNS.includes(cusp7)) return true;
      // Axe 10 — Maître M1 - Maître M7 harmoniques (Rushman l.421)
      if (m1 && m7 && m1 !== m7) {
        if (_pnaHasNatalAspect(natalDict, m1, m7, "harmonic")) return true;
      }
      // Axe 11 — Pont étoiles fixes (Véga, Deneb, Alphecca, Mirach, Ascella, Spica sur PoP)
      if (_pnaStarActivates(payload, "MARIAGE")) return true;
      // Axe 12 (Phase B+, sous flag, Rushman l.349, 362-373) — applying aspects luminaire genre
      if (_DTC_ENABLE_APPLYING_MARIAGE) {
        const lum = _pnaLuminaireForGender(payload);
        if (lum && _pnaApplyingAspectsCount(natalDict, lum) > 0) return true;
      }
      return false;
    })();

    // ─── ENFANT — Brennan l.18711, l.27080, Rushman l.493-512 ──────────
    p.ENFANT = (() => {
      // Axe 1 — Bénéfiques fécondité en M5/M11 (Rushman l.505, l.508)
      if (["Jupiter","Lune","Vénus","Cérès","Soleil"].some(x => [5,11].includes(_pnaHouseOf(natalDict,x)))) return true;
      // Axe 2 — Maître M5 en M1/M5/M11 (Rushman l.495)
      if (m5 && natalDict[m5] && [1,5,11].includes(natalDict[m5].house)) return true;
      // Axe 3 — Lot des Enfants en M1/M5/M7/M11 (Brennan l.23229 contre M8)
      const le = natalDict["Lot des Enfants"] || natalDict["Lot d'Enfant"];
      if (le && [1,5,7,11].includes(le.house)) return true;
      // Axe 4 — Lune en signes féconds (Brennan l.27080, tradition hellénistique)
      const moonSign = natalDict["Lune"] && natalDict["Lune"].sign;
      if (moonSign && _PNA_FERTILE_SIGNS.includes(moonSign)) return true;
      // Axe 5 — Vénus en signes féconds Cancer/Taureau/Poissons (extrapolation Brennan)
      const venusSign = natalDict["Vénus"] && natalDict["Vénus"].sign;
      if (venusSign && ["Cancer","Taureau","Poissons"].includes(venusSign)) return true;
      // Axe 6 — Cérès en signes d'eau (Demetra George)
      const ceresSign = natalDict["Cérès"] && natalDict["Cérès"].sign;
      if (ceresSign && ["Cancer","Scorpion","Poissons"].includes(ceresSign)) return true;
      // ─── AJOUTS DOCTRINAUX V3 (Rushman l.507) ──────────────────────
      // Axe 7 — Gémeaux sur cuspide M5 (Rushman l.507 — twins)
      const cusp5 = _pnaSignOnCusp(payload, 5);
      if (cusp5 === "Gémeaux") return true;
      // Axe 8 — Pont étoiles fixes (rare pour enfants, mais possible via Cérès/M5)
      if (_pnaStarActivates(payload, "ENFANT")) return true;
      // Axe 9 (Phase B+, sous flag, Rushman l.495, 498) — applying aspects maître M5
      if (_DTC_ENABLE_APPLYING_ENFANT) {
        if (m5 && _pnaApplyingAspectsCount(natalDict, m5) > 0) return true;
      }
      return false;
    })();

    // ─── SANTE_DOWN — Brennan l.18744-18748, l.18963-18966 ─────────────
    p.SANTE_DOWN = (() => {
      // Axe 1 — Maléfiques en M1/M6/M12 (Brennan M6/M12 = suffering, injuries).
      // R2 CORRECTIF 2026-05-30 : Mars restreint à M6 (Brennan l.18744 joy of Mars).
      //   Mars M1 = ACCIDENT (Rushman l.738), Mars M12 = JURIDIQUE (Brennan l.24023).
      if (["Saturne","Neptune","Pluton"].some(x => [1,6,12].includes(_pnaHouseOf(natalDict,x)))) return true;
      if (_pnaHouseOf(natalDict, "Mars") === 6) return true;
      // Axe 2 — Chiron en M6/M8/M12 (Note 180 doctrine projet + tradition)
      const ch = natalDict["Chiron"];
      if (ch && [6,8,12].includes(ch.house)) return true;
      // Axe 3 — Maître ASC en M6/M8/M12 (corps en peine)
      if (m1 && natalDict[m1] && [6,8,12].includes(natalDict[m1].house)) return true;
      // Axe 4 — Maître M6 en M1/M6/M8/M12 (tradition)
      if (m6 && natalDict[m6] && [1,6,8,12].includes(natalDict[m6].house)) return true;
      // Axe 5 — Lot de Maladie en M1/M6/M8/M12 (extrapolation Brennan ch.16)
      const lmal = natalDict["Lot de Maladie"];
      if (lmal && [1,6,8,12].includes(lmal.house)) return true;
      // Axe 6 — Pont étoiles fixes (Algol/Pléiades/Lesath/Scheat/Facies sur PoP)
      if (_pnaStarActivates(payload, "SANTE_DOWN")) return true;
      return false;
    })();

    // ─── ACCIDENT — Brennan M6/M8/M12, Rushman l.586 ───────────────────
    p.ACCIDENT = (() => {
      if (["Mars","Uranus"].some(x => [1,6,8,12].includes(_pnaHouseOf(natalDict,x)))) return true;
      const ch = natalDict["Chiron"];
      if (ch && ch.house === 8) return true;
      if (m1 && natalDict[m1] && [6,8,12].includes(natalDict[m1].house)) return true;
      if (_pnaHasNatalAspect(natalDict, "Mars", "Uranus", "hard")) return true;
      if (_pnaHasNatalAspect(natalDict, "Mars", "Saturne", "hard")) return true;
      if (_pnaHasNatalAspect(natalDict, "Mars", "Pluton", "hard")) return true;
      // Axe pont étoiles fixes (Algol/Mirfak/Bellatrix/Castor-Pollux/Pléiades/
      //   Zubenelgenubi/Lesath/Facies sur PoP)
      if (_pnaStarActivates(payload, "ACCIDENT")) return true;
      return false;
    })();

    // ─── RELOCATION — Brennan M3/M4/M9 ─────────────────────────────────
    p.RELOCATION = (() => {
      if (["Uranus","Lune","Mercure"].some(x => [3,4,9].includes(_pnaHouseOf(natalDict,x)))) return true;
      if (m4 && natalDict[m4] && [3,9,12].includes(natalDict[m4].house)) return true;
      if (m9 && natalDict[m9] && [3,4,9].includes(natalDict[m9].house)) return true;
      // Axe pont étoiles fixes (Canopus/Altaïr sur PoP)
      if (_pnaStarActivates(payload, "RELOCATION")) return true;
      return false;
    })();

    // ─── JURIDIQUE_DOWN — Brennan M9/M12, M7 ───────────────────────────
    p.JURIDIQUE_DOWN = (() => {
      if (["Saturne","Mars"].some(x => [7,9,12].includes(_pnaHouseOf(natalDict,x)))) return true;
      if (m9 && natalDict[m9] && [6,8,12].includes(natalDict[m9].house)) return true;
      if (m7 && natalDict[m7] && [6,8,12].includes(natalDict[m7].house)) return true;
      // Axe pont étoiles fixes (Antarès/Zubenelgenubi/Castor/Pollux sur PoP)
      if (_pnaStarActivates(payload, "JURIDIQUE_DOWN")) return true;
      return false;
    })();

    // ─── SCANDALE — Rushman l.617, Brennan M12 ─────────────────────────
    p.SCANDALE = (() => {
      // Axe 1 — Neptune/Pluton en M10/M12 (Rushman l.617, Brennan M12)
      // Phase B' ROLLBACK (2026-05-30) : restauration baseline Phase A stricte.
      //   Correction SCANDALE − Pluton M10 (Rushman l.570) doctrinalement defendable
      //   mais reportee a investigation isolee post-bench pour mesurer effet propre.
      if (["Neptune","Pluton"].some(x => [10,12].includes(_pnaHouseOf(natalDict,x)))) return true;
      // Axe 2 — Neptune en M10 afflicté (Rushman l.617 — "if Neptune is afflicted")
      const nep = natalDict["Neptune"];
      if (nep && nep.house === 10) {
        if (_pnaHasNatalAspect(natalDict, "Neptune", "Saturne", "hard")) return true;
        if (_pnaHasNatalAspect(natalDict, "Neptune", "Mars", "hard")) return true;
        if (_pnaHasNatalAspect(natalDict, "Neptune", "Soleil", "hard")) return true;
      }
      // Axe 3 — Pont étoiles fixes (Fomalhaut "scandale par idéaux" sur PoP)
      if (_pnaStarActivates(payload, "SCANDALE")) return true;
      return false;
    })();

    // ─── DEUIL — Brennan ch.10 M4/M8/M10, l.27018-21 ───────────────────
    p.DEUIL = (() => {
      // Axe 1 — Maléfiques en M4/M8/M10 (Brennan, tradition)
      if (["Saturne","Pluton","Mars"].some(x => [4,8,10].includes(_pnaHouseOf(natalDict,x)))) return true;
      // Axe 2 — Lot du Père OU de la Mère afflicté par maléfiques (carré/opposition)
      //   Brennan l.27018-21 — Dorotheus : « malefics configured to lots = death of parent »
      const lotPere = natalDict["Lot du Père"] || natalDict["Lot du Pere"];
      const lotMere = natalDict["Lot de la Mère"] || natalDict["Lot de la Mere"];
      const MAL = ["Saturne","Mars","Pluton"];
      for (const lot of [lotPere, lotMere]) {
        if (!lot || lot.deg == null) continue;
        for (const m of MAL) {
          const pl = natalDict[m];
          if (!pl || pl.deg == null) continue;
          let diff = Math.abs(lot.deg - pl.deg);
          if (diff > 180) diff = 360 - diff;
          if (Math.abs(diff - 90) <= 6 || Math.abs(diff - 180) <= 8) return true;
        }
      }
      // Axe 3 — Pont étoiles fixes (Algol/Vindemiatrix/Pléiades/Scheat/Deneb Algedi sur PoP)
      if (_pnaStarActivates(payload, "DEUIL")) return true;
      return false;
    })();

    // ─── FINANCE_DOWN — tradition + Rushman l.536 ──────────────────────
    p.FINANCE_DOWN = (() => {
      // Axe 1 — Saturne/Neptune en M2/M8 (tradition)
      if (["Saturne","Neptune"].some(x => [2,8].includes(_pnaHouseOf(natalDict,x)))) return true;
      // Axe 2 — Maître M2 en M6/M8/M12 (tradition hellénistique — maître en chute)
      if (m2 && natalDict[m2] && [6,8,12].includes(natalDict[m2].house)) return true;
      return false;
    })();

    // ─── HÉRITAGE — Brennan l.18835, l.23800, Rushman l.516, l.530 ─────
    p.HÉRITAGE = (() => {
      // Axe 1 — Pluton/Saturne/Neptune en M8 (Brennan l.18835)
      if (["Pluton","Saturne","Neptune"].some(x => _pnaHouseOf(natalDict,x) === 8)) return true;
      // Axe 2 — Maître M8 en M6/M8/M12 (tradition — maître "porte" la maison)
      if (m8 && natalDict[m8] && [6,8,12].includes(natalDict[m8].house)) return true;
      // Axe 3 — Maître M8 en M10 (Brennan l.23800 — Valens "increases through inheritance")
      if (m8 && natalDict[m8] && natalDict[m8].house === 10) return true;
      // Axe 4 — Lot d'Héritage en M2/M4/M8 OU Lot de Fortune en M8 (Brennan ch.16)
      const lh = natalDict["Lot d'Héritage"] || natalDict["Lot Héritage"] || natalDict["Lot de l'Héritage"];
      if (lh && [2,4,8].includes(lh.house)) return true;
      const lf = natalDict["Part de Fortune"] || natalDict["Lot de Fortune"];
      if (lf && lf.house === 8) return true;
      // Axe 5 — Pluton-Jupiter / Pluton-Vénus aspects (Rushman l.516 — money inherited)
      if (_pnaHasNatalAspect(natalDict, "Pluton", "Jupiter", "harmonic")) return true;
      if (_pnaHasNatalAspect(natalDict, "Pluton", "Vénus", "harmonic")) return true;
      // Axe 6 — Pont étoiles fixes (Spica modifier M8 = HÉRITAGE)
      if (_pnaStarActivates(payload, "HÉRITAGE")) return true;
      return false;
