  //              OU Lot de Fortune en M2/M5/M11, OU Lot de Manne.
  promises.FINANCE_UP = (() => {
    if (["Jupiter", "Vénus"].some(p => [2, 8].includes(natalDict[p]?.house))) return true;
    if (payload?._houseLords) {
      const masterM2 = payload._houseLords[2];
      if (masterM2 && natalDict[masterM2] && [2, 5, 8, 11].includes(natalDict[masterM2].house)) return true;
    }
    const lotF = natalDict["Part de Fortune"] || natalDict["Lot de Fortune"];
    if (lotF && [2, 5, 11].includes(lotF.house)) return true;
    return false;
  })();

  // MARIAGE : Vénus/Jupiter en M5/M7/M11, OU Maître M7 en M1/M5/M7/M10/M11,
  //           OU Lot du Mariage en M1/M7, OU Junon en M5/M7.
  promises.MARIAGE = (() => {
    if (["Vénus", "Jupiter"].some(p => [5, 7, 11].includes(natalDict[p]?.house))) return true;
    if (payload?._houseLords) {
      const masterM7 = payload._houseLords[7];
      if (masterM7 && natalDict[masterM7] && [1, 5, 7, 10, 11].includes(natalDict[masterM7].house)) return true;
    }
    const lotM = natalDict["Lot du Mariage"] || natalDict["Lot de Mariage"];
    if (lotM && [1, 7].includes(lotM.house)) return true;
    const junon = natalDict["Junon"];
    if (junon && [5, 7].includes(junon.house)) return true;
    return false;
  })();

  // ENFANT : Jupiter/Lune/Vénus/Cérès en M5/M11, OU Maître M5 en M1/M5/M11,
  //          OU Lot des Enfants en M5.
  promises.ENFANT = (() => {
    if (["Jupiter", "Lune", "Vénus", "Cérès"].some(p => [5, 11].includes(natalDict[p]?.house))) return true;
    if (payload?._houseLords) {
      const masterM5 = payload._houseLords[5];
      if (masterM5 && natalDict[masterM5] && [1, 5, 11].includes(natalDict[masterM5].house)) return true;
    }
    const lotE = natalDict["Lot des Enfants"] || natalDict["Lot d'Enfant"];
    if (lotE && [5, 11].includes(lotE.house)) return true;
    return false;
  })();

  return promises;
}

function computeScores(payload, debug = false) {
  const { promiseRaw, promiseMult, promiseTrace } = computePromise(payload, debug);
  const { transitScores, transitTrace }            = computeTriggers(payload, debug);

  const finalScores = {};
  const breakdown = {};
  const age = payload._profections?.age || 30;

  const thematicPromises = computeThematicPromises(payload._natalDict || {}, payload);

  // RS Modulators
  const rsModulators = {};
  const dpModulators = {};
  for (const sig of Object.keys(DTC_WEIGHTS)) {
    rsModulators[sig] = 1.0;
    dpModulators[sig] = 1.0;
  }

  const rsAngleCrosses = payload._mdseRSAngleCrosses || [];
  const rsHousesRS = payload._mdseRSHousesRS || payload._mdseRSHouses || {};
  const CRISES = ["ACCIDENT", "SANTE_DOWN", "SCANDALE", "DEUIL", "CARRIERE_DOWN", "JURIDIQUE_DOWN", "SEPARATION", "FINANCE_DOWN"];
  const EXPANSIONS = ["CARRIERE_UP", "FINANCE_UP", "MARIAGE"];

  for (const cross of rsAngleCrosses) {
    if (cross.orb <= 3.0 && (cross.angle === "ASC_RS" || cross.angle === "MC_RS")) {
      if (["Mars", "Saturne", "Uranus", "Neptune", "Pluton"].includes(cross.planet)) {
        for (const sig of CRISES) rsModulators[sig] = Math.max(rsModulators[sig], 1.2);
      } else if (["Jupiter", "Vénus"].includes(cross.planet)) {
        for (const sig of EXPANSIONS) rsModulators[sig] = Math.max(rsModulators[sig], 1.2);
      }
    }
  }

  for (const [p, info] of Object.entries(rsHousesRS)) {
    const h = info.rsHouse || info.house;
    if ([1, 4, 7, 10].includes(h)) {
      if (["Mars", "Saturne", "Uranus", "Neptune", "Pluton"].includes(p)) {
        for (const sig of CRISES) rsModulators[sig] = Math.max(rsModulators[sig], 1.2);
      } else if (["Jupiter", "Vénus"].includes(p)) {
        for (const sig of EXPANSIONS) rsModulators[sig] = Math.max(rsModulators[sig], 1.2);
      }
    }
  }

  // DP Modulators
  // Note 230 — BUG FIX : les champs étaient lus comme `orbY`, `pTransit`, `pNatal`
  // alors que le payload N8N expose `orbYears`, `promissor`, `significator`.
  // Conséquence : aucune Direction Primaire n'était prise en compte avant ce fix.
  const primaryDirections = payload._primaryDirections || payload._mdsePrimaryDirections || [];
  for (const dp of primaryDirections) {
    const orbY = parseFloat(dp.orbYears ?? dp.orbY);
    if (!isFinite(orbY)) continue;
    let force = 1.0;
    if (orbY <= 0.1) force = 1.5;
    else if (orbY <= 0.5) force = 1.2;

    if (force > 1.0) {
      const prom = dp.promissor || dp.pTransit;
      const sig_ = dp.significator || dp.pNatal;
      const involvesMalefic = ["Mars", "Saturne", "Uranus", "Neptune", "Pluton"].includes(prom) || ["Mars", "Saturne", "Uranus", "Neptune", "Pluton"].includes(sig_);
      const involvesBenefic = ["Jupiter", "Vénus", "Soleil", "Milieu du Ciel", "MC"].includes(prom) || ["Jupiter", "Vénus", "Soleil", "Milieu du Ciel", "MC"].includes(sig_);
      if (involvesMalefic) {
        for (const sig of CRISES) dpModulators[sig] = Math.max(dpModulators[sig], force);
      }
      if (involvesBenefic) {
        for (const sig of EXPANSIONS) dpModulators[sig] = Math.max(dpModulators[sig], force);
      }
    }
  }

  for (const sig of Object.keys(DTC_WEIGHTS)) {
    const sortedTransits = transitScores[sig].sort((a, b) => b - a);

    let sigMult = SIG_MULTIPLIER[sig] || 1.0;
    let pMult   = promiseMult[sig];

    // Note 279-R G72 — Floor Chanel isolé (CARRIERE_UP uniquement)
    // Doctrine Gemini : les destins atypiques (Chanel, Edith Piaf, Marilyn) ont une
    // promesse natale CU faible mais leur carrière publique est massive. Si la promesse
    // brute est < 1.0 et le multiplicateur < 1.0, on force le multiplicateur à 1.0
    // pour éviter la double pénalisation (promesse faible × mult faible = écrasement).
    // Isolé du reste de la Phase V CU (rollbackée). Ne touche pas aux maluses.
    // Note 280-bis : flag DTC_NO_PHASEW=1 désactive pour mesure baseline pré-W.
    if (sig === "CARRIERE_UP" && promiseRaw[sig] < 1.0 && pMult < 1.0 && !DTC_NO_PHASEW) {
      pMult = 1.0;
    }

    // Note 180 : Bonus Partilité Chiron (ACCIDENT, SANTE_DOWN)
    const chironNatal = payload._natalDict?.["Chiron"];
    let chironPartilityBoost = 1.0;
    if (chironNatal && ["ACCIDENT", "SANTE_DOWN"].includes(sig)) {
      const chironHits = (payload.transits || []).filter(t => 
        t.target === "Chiron" && 
        ["Mars", "Saturne", "Uranus", "Neptune", "Pluton"].includes(t.transit) &&
        ["Conjonction", "Carré", "Opposition"].includes(t.aspect) &&
        t.orb <= 1.5
      );
      if (chironHits.length > 0) {
        chironPartilityBoost = 1.3;
      }
    }

