      if (thematicPromises[sig]) {
        // Gating d'actualisation : la promesse ne s'active que si confirmée par DP ou un transit majeur
        if (dpModulators[sig] > 1.0 || (sortedTransits[0] && sortedTransits[0] > 1.5)) {
          sigMult *= 1.3; // Amplification modérée si promesse activée
        } else {
          sigMult *= 1.0; // Promesse dormante
        }
      } else {
        sigMult *= 0.8; // Amortissement adouci si aucune promesse
      }
    }

