    // natal, le score HÉRITAGE ne doit pas dominer.
    // Note 256 — Pour distinguer "promesse natale + événement actif" vs
    // "promesse natale seule" (qui ne devrait pas générer de score), on
    // exige un transit lent (Pluton/Saturne/Jupiter/Neptune) actif sur M8
    // ou son maître pour ne pas amortir.
    if (sig === "HÉRITAGE") {
      const natalDictHer8 = payload._natalDict || {};
      const hlHer8 = getHouseLords(payload);
      const masterM8N = hlHer8 ? hlHer8[8] : null;
      const hasActiveM8Transit = transitTrace[sig] && transitTrace[sig].some(t => {
        if (!isFinite(t.orb) || t.orb > 2.0) return false;
        const tP = (t.transitP || "").replace(/^(fast_|slow_|ARC |PS |TP )/, "");
        if (!["Pluton","Saturne","Jupiter","Neptune"].includes(tP)) return false;
        if (t.transitHouse === 8) return true;
        if (t.natalHouse === 8) return true;
        if (masterM8N && t.natalP === masterM8N) return true;
        return false;
      });
      if (thematicPromises.HÉRITAGE && hasActiveM8Transit) {
        sigMult *= 1.3;  // Promesse + déclencheur M8 actif
      } else if (thematicPromises.HÉRITAGE) {
        sigMult *= 0.3;  // Promesse mais pas de transit M8 actif → étouffer
      } else if (hasActiveM8Transit) {
        sigMult *= 0.5;  // Transit M8 actif mais pas de promesse natale
      } else {
        sigMult *= 0.1;  // Ni l'un ni l'autre → étouffer fort
      }
    }

    // ─── G1 Note 253 — PromiseGuard MARIAGE/ENFANT ──────────────────
    // ⚠ ABANDONNÉ Note 253 v2 selon protocole "doctrine d'abord mais
    // régression = abandon" :
    //   - ×0.9 sur 4 codes (CARRIERE_UP/FINANCE_UP/MARIAGE/ENFANT) →
    //     régression Chanel et Obama (-2 M3)
    //   - ×0.9 sur 2 codes (MARIAGE/ENFANT) → bilan net +1 M1 (Kate)
    //     mais -1 M3 (Obama, effet de ricochet sur le ranking)
    //   - ×0.95 doux → bench identique baseline (doctrine inopérante)
    // Les pistes v18 existantes (β, μ, φ, λ v2, ν, ω) couvrent
    // implicitement la doctrine de promesse natale pour ces 4 codes.
    // Reprise possible si la cohorte 60 expose des faux positifs
    // MARIAGE/ENFANT sans promesse natale.
    // Les promesses CARRIERE_UP/FINANCE_UP/MARIAGE/ENFANT sont
    // calculées dans computeThematicPromises mais non utilisées
    // (archive doctrinale, zéro impact sur scores).

    // Application du boost Chiron
    sigMult *= chironPartilityBoost;
    // Note 278-R G64 — Application du boost Mars natal trauma (ACCIDENT)
    sigMult *= marsNatalTraumaBoost;

    // Trou n°14 corrigé : Malus d'âge pour la carrière (Q-D13)
    // Avant le premier retour de Saturne (28 ans), la carrière publique
