    if (age < 25 && (sig === "CARRIERE_UP" || sig === "CARRIERE_DOWN")) {
      sigMult *= 0.5;
    }

    // Note 279-R G73 — Malus de direction MC (CARRIERE_UP uniquement).
    // Doctrine Gemini : un transit dur de Saturne/Uranus/Pluton (Conjonction,
