    // DESCENDANTE de carrière (chute, scandale, démission forcée), pas une
    // ascension. La matrice CU capte ce signal MC mais ne le qualifie pas.
    // Ce malus ×0.7 qualifie la direction. Exemples cibles : Weiner 2011
    // (Pluton/Saturne sur MC → CU 136 incongru), Marilyn 1962, Madoff 2008.
    // Important : ne s'applique PAS si genieAscensionnelFloor est actif
    // (Jupiter sur MC = ascension réelle même si autres transits durs).
    if (sig === "CARRIERE_UP" && !DTC_NO_PHASEW) {
      const isGenieAscMC = breakdown["CARRIERE_UP"] && breakdown["CARRIERE_UP"].genieAscensionnelFloor;
      if (!isGenieAscMC) {
        const mcDirectionMalus = (payload.transits || []).find(t =>
          t.target === "Milieu du Ciel" &&
          ["Saturne", "Uranus", "Pluton"].includes(t.transit) &&
          ["Conjonction", "Carré", "Opposition"].includes(t.aspect) &&
          t.orb <= 2.0
        );
        if (mcDirectionMalus) {
          sigMult *= 0.7;
          if (!breakdown["CARRIERE_UP"]) breakdown["CARRIERE_UP"] = {};
          breakdown["CARRIERE_UP"].mcDirectionMalus = 0.7;
          breakdown["CARRIERE_UP"].mcDirectionReason = `${mcDirectionMalus.transit} ${mcDirectionMalus.aspect} MC orbe=${mcDirectionMalus.orb}°`;
        }
      }
    }

    // Note 180 : Gating Lilith pour SCANDALE
    let lilithScandaleGating = 1.0;
    if (sig === "SCANDALE") {
      const lilithNatal = payload._natalDict?.["Lilith"];
      let vecteurLilithActif = false;

      // Condition 1 : Promesse natale
      if (lilithNatal && [5, 7, 8, 10, 12].includes(lilithNatal.house)) {
        vecteurLilithActif = true;
      }

      // Condition 2 & 3 : Transits
      if (!vecteurLilithActif) {
        const lilithTransits = (payload.transits || []).filter(t => 
          (t.target === "Lilith" && ["Saturne", "Uranus", "Neptune", "Pluton"].includes(t.transit) && t.orb <= 2.0) ||
          (t.transit === "Lilith" && ["Vénus", "Mars", "Milieu du Ciel", "Ascendant"].includes(t.target) && t.orb <= 2.0)
        );
        if (lilithTransits.length > 0) {
          vecteurLilithActif = true;
        }
      }

      if (!vecteurLilithActif) {
        // Note 199 : Patch C confirmé utile (sans lui M1/M5 chutent) → maintien valeur Note 191
        lilithScandaleGating = 0.3;
