    // ⚠ ABANDONNÉ Note 253 v2 : test ×0.8 sur Lilith en M1/4/7/10 a fait
    // régresser Prince William 2011 (MARIAGE → SEPARATION top1). Selon
    // protocole "doctrine d'abord, empirisme jamais", G7 étant doctrine
    // semi-classique non vitale, on abandonne le patch. Reprise possible
    // si futur cas hors-panel justifie une calibration plus fine
    // (orbe ≤ 3° vs angles, exposition de longitude requise).

    // Note 180 : Boost Lilith pour SEPARATION
    let lilithSeparationBoost = 1.0;
    if (sig === "SEPARATION") {
      const lilithSepTransits = (payload.transits || []).filter(t => 
        t.transit === "Lilith" && 
        ["Vénus", "Lune"].includes(t.target) && 
        ["Conjonction", "Carré", "Opposition"].includes(t.aspect) &&
        t.orb <= 2.0
      );
      if (lilithSepTransits.length > 0) {
        lilithSeparationBoost = 1.2;
      }
    }

    // Note 183 : Somme simple top1+top2+top3 (rollback formule partilité v21)
    let top3Sum = (sortedTransits[0] || 0) + (sortedTransits[1] || 0) + (sortedTransits[2] || 0);

    // CONVERGENCE : Trigger × Promise (multiplicatif)
    // Le facteur 6 conserve la magnitude des scores des versions précédentes.
    // Note 200 : Plafond promesses thématiques à x1.5 (relâché de 1.35, audit A/B v199 : +4 M5)
    sigMult = Math.min(sigMult, 1.5);

    // Note 183 : Désactivation RS/DP du score final (restent dans le breakdown)
    let finalS = top3Sum * pMult * sigMult * 6 * lilithScandaleGating * lilithSeparationBoost;

    // Malus d'absence de DP sur les signatures de CRISE (Note 178)
    // Note 183 : Désactivé car DP n'est plus fiable
    // if (CRISES.includes(sig) && dpModulators[sig] === 1.0) {
    //   finalS *= 0.9;
    // }

    // Cap global (nouveau garde-fou)
    if (finalS > 150) {
        finalS = 150 + (finalS - 150) * 0.1;
    }

    finalScores[sig] = Math.round(finalS);

    breakdown[sig] = {
      trigger: top3Sum.toFixed(2),
      hits: transitScores[sig].length,
      promise_raw: promiseRaw[sig].toFixed(2),
      promise_mult: pMult.toFixed(2),
      sig_mult: sigMult,
      rs_mod: rsModulators[sig],
      dp_mod: dpModulators[sig],
      final: finalScores[sig]
    };
  }

