    // Les malus (mult < 1) s'appliquent directement, les boosts s'accumulent
    if (mult < 1.0) {
      finalScores[sig] = Math.round(finalScores[sig] * mult);
      breakdown[sig].final = finalScores[sig];
      breakdown[sig].malus = (breakdown[sig].malus || 1.0) * mult;
    } else {
      sigMultipliers[sig] *= mult;
    }
