  const cuScore = finalScores["CARRIERE_UP"] || 0;
  const ageLennon = (payload._profections && payload._profections.age) ? payload._profections.age : 30;
  const saturneM10 = natalDictPhaseL["Saturne"] && natalDictPhaseL["Saturne"].house === 10;
  if (deuilScore >= 60 && cuScore > 60 && (ageLennon > 50 || saturneM10)) {
