      const aspectName = parts[1];
      const natalP = parts[2];
      if (!["Pluton", "Uranus", "Saturne"].includes(transitP)) continue;
      if (!accidentHardTargets.has(natalP)) continue;
      if (!hardAspects.has(aspectName)) continue;
      const val = block[k];
      for (const w of (val.waves || [])) {
        const orb = parseFloat(w.minOrb);
        if (isFinite(orb) && orb <= 1.5) {
          accidentHardHits.push({ transitP, aspectName, natalP, orb });
        }
      }
    }
  }
  const accidentConvergence = accidentHardHits.length >= 1;

  // ─── Note 267 — Phase S (G45/G46/G49 Gemini) ────────────────────
  // Doctrine ACCIDENT : un ACCIDENT physique exige la rencontre
  //   AGRESSEUR (Mars natal OU activation M8) + VICTIME (corps : Asc/Soleil/Lune).
  // Le floor angulaire (basé sur la VICTIME seule) générait 17/20 FP top-1.
  // On le conditionne désormais à la présence d'un AGRESSEUR.
  //
  // AGRESSEUR — cibles natales :
  //   - Mars natal (la "lame" du conflit)
  //   - toute planète natale occupant M8 (la zone topique du trauma)
  //   Le Maître naturel de M8 a été testé puis retiré : chaque thème a son
  //   Maître M8 et il est régulièrement touché par les transits durs lents,
  //   ce qui rouvrait la porte aux FP (Brad Pitt 1992, Madonna, Edward VIII…).
  //
  // AGRESSEUR — transits acceptés :
  //   - Saturne / Uranus / Pluton / Neptune (planètes lentes) : aspect dur,
  //     orbe ≤ 1.0° (doctrine Gemini G46).
  //   - Mars en transit : autorisé UNIQUEMENT sur une planète occupant M8
  //     autre que Mars natal. La paire Mars→Mars natal est exclue car le
  //     retour cyclique de Mars (~2 ans) génère trop de bruit (Steve Jobs
  //     2003, Madonna, Nixon Mars/Mars en orbe 0.0X°). Cas-limite assumé :
  //     Lauda 1976 (Mars Opp Mars natal en M8) peut basculer en MISS si
  //     aucun autre hit. Lennon (Saturne→Mars) et Kahlo (Mars→Saturne M8)
  //     restent capturés.
  const _natalDict267 = payload._natalDict || {};
  // Whitelist des "vraies planètes" : on exclut les Lots (Lot du Mariage,
  // Lot de Maladie, Lot d'Héritage, etc.) qui sont des points arabiques
  // calculés, pas des planètes tangibles, et qui sinon ouvrent l'agresseur
  // M8 chez tout natif ayant un Lot tombant en M8 (Brad Pitt 1992 →
  // Lot du Mariage en M8 touché par Saturne, FP injustifié).
  const _accidentAggressorPlanetsWhitelist = new Set([
    "Soleil", "Lune", "Mercure", "Vénus", "Mars", "Jupiter",
    "Saturne", "Uranus", "Neptune", "Pluton",
    "Chiron", "Nœud Nord", "Nœud Sud"
  ]);
  const accidentAggressorTargets = new Set(["Mars"]);
  for (const [pl, info] of Object.entries(_natalDict267)) {
    if (info && info.house === 8 && _accidentAggressorPlanetsWhitelist.has(pl)) {
      accidentAggressorTargets.add(pl);
    }
  }
  const accidentAggressorHits = [];
  for (const block of _aspectsBlocks) {
    for (const k of Object.keys(block)) {
      const parts = k.split("|||");
      if (parts.length < 3) continue;
      let transitP = parts[0].replace(/^(slow_|rap_)/, "");
      const aspectName = parts[1];
      const natalP = parts[2];
      if (!hardAspects.has(aspectName)) continue;
      if (!accidentAggressorTargets.has(natalP)) continue;
      const isSlow = ["Saturne", "Uranus", "Pluton", "Neptune"].includes(transitP);
      const isMars = transitP === "Mars";
      if (!isSlow && !isMars) continue;
      // Mars en transit : exclure la paire Mars→Mars natal (cycle 2 ans).
      // Mars autorisé seulement sur une planète occupant M8 (autre que Mars).
      if (isMars && natalP === "Mars") continue;
      const val = block[k];
      for (const w of (val.waves || [])) {
        const orb = parseFloat(w.minOrb);
        if (isFinite(orb) && orb <= 1.0) {
          accidentAggressorHits.push({ transitP, aspectName, natalP, orb });
        }
      }
    }
  }
  // Doctrine renforcée (Note 267 v2) : exiger ≥ 2 cibles natales distinctes
  // touchées par agresseur. Élimine les FP "1 hit lent ultra-serré" (Charles
  // III Neptune→Mars 0.00°, Nixon Saturne→Mars 0.02°, Madonna Saturne→Mars
  // 0.00°) qui sont des configurations doctrinalement durables (~5-10 ans
  // d'orbe) mais s'incarnent généralement en CARRIERE_DOWN / SCANDALE,
  // pas en ACCIDENT physique. Une seule cible touchée = signature trop
  // unique pour porter un événement aussi rare qu'un accident grave.
  const accidentAggressorTargetsHit = new Set(accidentAggressorHits.map(h => h.natalP));
  const accidentAggressorPresent = accidentAggressorTargetsHit.size >= 2;

  // Signature d'addiction/dépression chronique :
  //   Au moins 2 paires distinctes (transitP→natalP) parmi :
  //   - transit : Neptune, Pluton, Saturne, Chiron (planètes chroniques/dégénératives)
  //     Chiron inclus car capture Whitney 2012 (Chiron Conj Asc 0.02° + Chiron Opp Mercure)
  //   - natal : Lune (psyché), Mercure (mental), Ascendant (corps)
  //   - aspect : Conj/Carré/Opposition
  //   - orbe ≤ 1° pour Neptune/Pluton/Saturne, ≤ 2° pour Chiron (cycle plus rapide ~50 ans)
  //   Cas cibles : Marilyn 1962, Whitney 2012, Robin Williams 2014, Amy 2011.
  const sdHitPairs = new Set();
  for (const block of _aspectsBlocks) {
    for (const k of Object.keys(block)) {
      const parts = k.split("|||");
      if (parts.length < 3) continue;
      let transitP = parts[0].replace(/^(slow_|rap_)/, "");
      const aspectName = parts[1];
      const natalP = parts[2];
      if (!["Neptune", "Pluton", "Saturne", "Chiron"].includes(transitP)) continue;
      if (!["Lune", "Mercure", "Ascendant"].includes(natalP)) continue;
      if (!hardAspects.has(aspectName)) continue;
      const maxOrb = transitP === "Chiron" ? 2.0 : 1.0;
      const val = block[k];
      for (const w of (val.waves || [])) {
        const orb = parseFloat(w.minOrb);
        if (isFinite(orb) && orb <= maxOrb) {
          sdHitPairs.add(transitP + "→" + natalP);
          break;
        }
      }
    }
  }
  const sdConvergence = sdHitPairs.size >= 2;

  // Filtre Diana fantôme : RETIRÉ.
  // Justification : pénaliser DEUIL en présence d'une signature ACCIDENT
  // touche aussi les vrais cas DEUIL (Yoko 1980, etc.) qui ont fréquemment
  // des transits durs sur Asc/Soleil. Le coût est trop élevé.
  // On accepte que ACCIDENT et DEUIL co-existent en top5 (Diana 1997 aura
  // les deux ; à charge des LLM aval de choisir le bon).

  // Application des boosts avec plafond global ×1.5
  for (const sig of Object.keys(DTC_WEIGHTS)) {
    if (sigMultipliers[sig] > 1.0) {
      const cappedMult = Math.min(1.5, sigMultipliers[sig]);
      finalScores[sig] = Math.round(finalScores[sig] * cappedMult);
      breakdown[sig].final = finalScores[sig];
      breakdown[sig].boosts = cappedMult;
    }
  }

  // Note 257 — Floors ACCIDENT et SANTE_DOWN déplacés en fin de computeScores
  // (juste avant le starBias) pour s'appliquer APRÈS tous les gates doctrinaux
  // (marsDominantGuard Phase E, accidentBodyLock, JD/SD garde-fous etc.).
  // Cf bloc "Note 257 — Phase M floors finaux" plus bas.

  // Malus croisé MARIAGE -> CARRIERE_UP (Note 167 Q-D36)
  // Si MARIAGE > 80 et que le top trigger implique Vénus ou la M7
  if (finalScores["MARIAGE"] > 80 && transitTrace["MARIAGE"] && transitTrace["MARIAGE"].length > 0) {
    const topTrigger = transitTrace["MARIAGE"].sort((a, b) => b.score - a.score)[0];
    if (topTrigger && (topTrigger.transitP === "Vénus" || topTrigger.natalP === "Vénus" || topTrigger.transitHouse === 7 || topTrigger.natalHouse === 7)) {
      if (finalScores["CARRIERE_UP"] > 0) {
        finalScores["CARRIERE_UP"] = Math.round(finalScores["CARRIERE_UP"] * 0.6);
        breakdown["CARRIERE_UP"].final = finalScores["CARRIERE_UP"];
        breakdown["CARRIERE_UP"].mariageCrossMalus = 0.6;
      }
    }
  }

  // Condition JURIDIQUE_DOWN (Note 166 Q-D23, élargie en Note 233 v4)
  // Note 281-R H_JD_e : seuil de déclenchement abaissé 80 → 40 (Gemini).
  //   Le check ne se déclenchait que pour JD > 80 et laissait le ventre mou
  //   des FP (Jackie K. JD@127 sans promesse) passer pour 1 cas spécifique,
  //   tout en ignorant tous les vrais REEL (OJ 31, Berlusconi 22, etc.).
  //   Baisser à 40 permet de filtrer toutes les pollutions sémantiques.
  //   Note 233 v4 — Élargissement Q-D23 avec critère de CONCENTRATION :
  //   les maisons malefiques sont élargies à [7, 8, 9, 10, 11, 12], mais
  //   la promesse n'est validée que si AU MOINS 2 planètes parmi
  //   {Saturne, Mars, Pluton} sont dans ces maisons.
  //   Validation REEL :
  //     - Bill Clinton (Sat M11 + Plu M11)        → 2 ✅
  //     - Berlusconi (Mars M11 + Plu M10)         → 2 ✅
  //     - DSK (Sat M10 + Mars M7 + Plu M10)       → 3 ✅
  //     - OJ (Sat M12 + Mars M10 + Plu M12)       → 3 ✅
  //     - Trump (Sat M11 + Mars M12 + Plu M12)    → 3 ✅
  if (finalScores["JURIDIQUE_DOWN"] > 40) {
    let promiseCount = 0;
    for (const p of ["Saturne", "Mars", "Pluton"]) {
      const nd = flags.natalDict[p];
      if (nd && [7, 8, 9, 10, 11, 12].includes(nd.house)) {
        promiseCount++;
      }
    }
    if (promiseCount < 2) {
      finalScores["JURIDIQUE_DOWN"] = Math.round(finalScores["JURIDIQUE_DOWN"] * 0.5);
      breakdown["JURIDIQUE_DOWN"].final = finalScores["JURIDIQUE_DOWN"];
      breakdown["JURIDIQUE_DOWN"].jdPromiseMalus = 0.5;
      breakdown["JURIDIQUE_DOWN"].jdPromiseCount = promiseCount;
    }
  }

  // ═══════════════════════════════════════════════════════════════════
  // Note 281-R H_JD_b — Guard MARIAGE/DEUIL/SANTE/ACCIDENT (Gemini, 16/05/2026)
  // ────────────────────────────────────────────────────────────────────
  // Si MARIAGE/DEUIL/SANTE_DOWN/ACCIDENT > 50, on amortit JD ×0.5.
  // Logique : la matrice JD reste sensible aux signatures relationnelles
  // ou corporelles qui se confondent avec ses signatures juridiques.
  // Ce guard désamorce les FP catastrophiques :
  //   - Jackie K. 1953 (mariage JFK)   → MARIAGE → JD ×0.5
  //   - JFK 1963 (assassinat)          → DEUIL   → JD ×0.5
  //   - Magic Johnson 1991 (HIV)       → SANTE_DOWN → JD ×0.5
  //   - Niki Lauda 1976 (crash F1)     → ACCIDENT → JD ×0.5
  //   - Kahlo 1925 (accident bus)      → ACCIDENT → JD ×0.5
  // ═══════════════════════════════════════════════════════════════════
  if ((finalScores["JURIDIQUE_DOWN"] || 0) > 0) {
    const mariageRaw  = finalScores["MARIAGE"] || 0;
    const deuilRaw    = finalScores["DEUIL"] || 0;
    const santeDown   = finalScores["SANTE_DOWN"] || 0;
    const accidentRaw = finalScores["ACCIDENT"] || 0;
    if (mariageRaw > 50 || deuilRaw > 50 || santeDown > 50 || accidentRaw > 50) {
      finalScores["JURIDIQUE_DOWN"] = Math.round(finalScores["JURIDIQUE_DOWN"] * 0.5);
      breakdown["JURIDIQUE_DOWN"] = breakdown["JURIDIQUE_DOWN"] || {};
      breakdown["JURIDIQUE_DOWN"].final = finalScores["JURIDIQUE_DOWN"];
      breakdown["JURIDIQUE_DOWN"].crossSemanticGuardMalus = 0.5;
      breakdown["JURIDIQUE_DOWN"].crossSemanticGuardReason =
        `MARIAGE=${mariageRaw} DEUIL=${deuilRaw} SANTE_DOWN=${santeDown} ACCIDENT=${accidentRaw}`;
    }
  }

  // ═══════════════════════════════════════════════════════════════════
  // Note 279-R G71 — genieAscensionnelFloor (CARRIERE_UP)
  // ═══════════════════════════════════════════════════════════════════
  // Doctrine Gemini : si Jupiter transit forme une Conjonction au MC natal
  // orbe ≤ 1°, on déclare une "ascension fulgurante" (symétrique de
  // genieLucratifFloor pour FINANCE_UP). Conséquences :
  //   1) Floor à 55 sur CARRIERE_UP si actuellement < 55
  //   2) Flag breakdown["CARRIERE_UP"].genieAscensionnelFloor = true
  //      → exempte CU du qG89Malus (G69) ET du crisisOverrideMalus (G70)
  if (!DTC_NO_PHASEW) {
    const mcNatal = payload._natalDict?.["Milieu du Ciel"];
    if (mcNatal) {
      const jupiterMC = (payload.transits || []).find(t =>
        t.target === "Milieu du Ciel" &&
        t.transit === "Jupiter" &&
        t.aspect === "Conjonction" &&
        t.orb <= 1.0
      );
      if (jupiterMC) {
        if (!breakdown["CARRIERE_UP"]) breakdown["CARRIERE_UP"] = {};
        breakdown["CARRIERE_UP"].genieAscensionnelFloor = 55;
        breakdown["CARRIERE_UP"].genieAscensionnelReason = `Jupiter Conj MC orbe=${jupiterMC.orb}°`;
        if ((finalScores["CARRIERE_UP"] || 0) < 55) {
          finalScores["CARRIERE_UP"] = 55;
          breakdown["CARRIERE_UP"].final = 55;
        }
      }
    }
  }

  // ═══════════════════════════════════════════════════════════════════
  // Q-G89 REFORMULÉ (Gemini Note 165 Q-D19 / Note 166 Q-D24)
  // ═══════════════════════════════════════════════════════════════════
  // Si la somme des scores DOWN (CARRIERE_DOWN + SCANDALE + JURIDIQUE_DOWN)
  // dépasse 100, c'est qu'on est dans une signature de chute publique
  // doctrinalement écrasante : un CARRIERE_UP fort ne peut pas coexister
  // avec une telle convergence négative. On applique un MALUS MULTIPLICATIF
  // ×0.5 (et non un cap absolu), ce qui préserve la variance et la
  // hiérarchie relative entre cas.
  const downScoreCU = (finalScores["CARRIERE_DOWN"] || 0)
                    + (finalScores["SCANDALE"] || 0)
                    + (finalScores["JURIDIQUE_DOWN"] || 0);
  // Note 279-R G69 — qG89Malus conditionnel au top1 effectivement = crise.
  // Doctrine Gemini : la somme downScoreCU > 100 peut être atteinte par convergence
  // diffuse sans qu'aucune crise réelle ne domine. On exige que le top1 actuel
  // (avant ce malus) soit lui-même une crise PUBLIQUE (CARRIERE_DOWN/SCANDALE/
  // JURIDIQUE_DOWN), sinon le malus est trompeur (Mère Teresa, Edith Piaf...).
  // G71 : genieAscensionnel actif → bypass qG89.
  const isGenieAscensionnel = breakdown["CARRIERE_UP"] && breakdown["CARRIERE_UP"].genieAscensionnelFloor;
  if (downScoreCU > 100 && finalScores["CARRIERE_UP"] > 0 && !isGenieAscensionnel) {
    const G69_CRISES_PUB = new Set(["CARRIERE_DOWN", "SCANDALE", "JURIDIQUE_DOWN"]);
    const topCode = Object.entries(finalScores)
      .sort((a, b) => b[1] - a[1])[0]?.[0];
    // Note 280-bis : DTC_NO_PHASEW=1 → comportement pré-W (pas de filtre top1).
    if (DTC_NO_PHASEW || G69_CRISES_PUB.has(topCode)) {
      finalScores["CARRIERE_UP"] = Math.round(finalScores["CARRIERE_UP"] * 0.5);
      breakdown["CARRIERE_UP"].final = finalScores["CARRIERE_UP"];
      breakdown["CARRIERE_UP"].qG89Malus = true;
    }
  }

  // Note 200 — Patches B (FINANCE_DOWN significateur) et v31 SANTE_DOWN cap 70 supprimés
  // (audit A/B v199 : neutres ou néfastes)

  // Note 191 (PUITS 3 Action B) : Gating SCANDALE par Chute Publique
  // Confirmé utile (Note 199 A/B test) : sans lui M1/M5 chutent significativement.
  if (finalScores["SCANDALE"] > 80) {
    const hasChutePublique = findTransitHits(payload, h =>
      ["Saturne", "Pluton"].includes(h.transitP)
      && ["Soleil", "Milieu du Ciel"].includes(h.natalP)
      && HARD_ASPECTS.has(h.aspectName)
      && h.orb <= 1.5
    ).length > 0;
    if (!hasChutePublique) {
      finalScores["SCANDALE"] = Math.round(finalScores["SCANDALE"] * 0.6);
      breakdown["SCANDALE"].final = finalScores["SCANDALE"];
      breakdown["SCANDALE"].noChutePubliqueMalus = 0.6;
    }
  }

  // Note 189 (Pattern B) supprimé (Phase T) car redondant avec combo 233 v3.

  // ═══════════════════════════════════════════════════════════════════
  // Note 200 — Piste β : Pénalité de Banalité sur les puits universels
  // « Un puits ne se réalise que sur transit exact »
  // Si AUCUN transit du top 3 d'une signature-puits n'a un orbe ≤ 0.5°,
  // on rétrograde son score (x0.85). Neutre sur le bench mais doctrinalement
  // protecteur contre des scénarios futurs où l'accumulation domine.
  // ═══════════════════════════════════════════════════════════════════
  {
    const PUITS_UNIVERSELS = ["SANTE_DOWN", "CARRIERE_UP", "SEPARATION", "FINANCE_DOWN", "SCANDALE"];
    for (const sig of PUITS_UNIVERSELS) {
      if (!finalScores[sig] || finalScores[sig] <= 0) continue;
      const trace = transitTrace[sig] || [];
      if (trace.length === 0) continue;
      const top3 = [...trace].sort((a, b) => b.score - a.score).slice(0, 3);
      const hasPartile = top3.some(t => isFinite(t.orb) && t.orb <= 0.5);
      if (!hasPartile) {
        finalScores[sig] = Math.round(finalScores[sig] * 0.85);
        breakdown[sig].final = finalScores[sig];
        breakdown[sig].banalityMalus = 0.85;
      }
    }
  }

  // ═══════════════════════════════════════════════════════════════════
  // Note 200 — Piste γ : Bonus Signature Rare (coef réduit 1.15)
  // « Une signature rare exige un déclencheur rare »
  // Si une signature rare a dans son top 3 un transit d'une planète lente
  // (Saturne/Uranus/Neptune/Pluton) partile (orbe ≤ 0.5°) sur une planète
  // maître de sa matrice (poids ≥ 0.8), on applique x1.15.
  // Coef 1.3 initial réduit à 1.15 pour éviter interférence avec ε (Nœuds).
  // ═══════════════════════════════════════════════════════════════════
  {
    const SIGS_RARES = ["RELOCATION", "ENFANT", "MARIAGE", "DEUIL"];
    const LENTES_RARE = new Set(["Saturne", "Uranus", "Neptune", "Pluton"]);
    for (const sig of SIGS_RARES) {
      if (!finalScores[sig] || finalScores[sig] <= 0) continue;
      const matrixPlanets = (DTC_WEIGHTS[sig] && DTC_WEIGHTS[sig].planets) || {};
      const trace = transitTrace[sig] || [];
      if (trace.length === 0) continue;
      const top3 = [...trace].sort((a, b) => b.score - a.score).slice(0, 3);
      const hasRareSignature = top3.some(t => {
        const tP = (t.transitP || "").replace(/^(ARC|PS|TP) /, "");
        const natalWeight = matrixPlanets[t.natalP] || 0;
        return LENTES_RARE.has(tP)
          && isFinite(t.orb) && t.orb <= 0.5
          && natalWeight >= 0.8;
      });
      if (hasRareSignature) {
        finalScores[sig] = Math.round(finalScores[sig] * 1.15);
        breakdown[sig].final = finalScores[sig];
        breakdown[sig].rareSignatureBoost = 1.15;
      }
    }
  }

  // ═══════════════════════════════════════════════════════════════════
  // Note 200/202/203 — Piste ε : Boosts des Nœuds Lunaires (Axe de la destinée)
  // Doctrine raffinée : un Nœud n'active une signature que si la maison
  // de transit OU la maison de la planète natale aspectée appartient
  // aux maisons topiques (CODE_HOUSES) de la signature.
  //
  // - Nœud Nord (expansion/destinée) : signatures UP / MARIAGE / ENFANT / RELOCATION
  // - Nœud Sud  (détachement/karma)  : signatures DOWN / SEPARATION / DEUIL / SPIRITUEL / RELOCATION / HÉRITAGE
  //
  // Conditions : transit partile (orbe ≤ 0.5°), aspect dur, sur planète
  // personnelle (Soleil, Lune, Mercure, Vénus, Mars), Angle (Asc, MC, Dsc, IC), ou Part de Fortune.
  // Boost ×1.15 si la maison topique correspond.
  // ═══════════════════════════════════════════════════════════════════
  {
    const PERSO_OR_ANGLE = new Set(["Soleil", "Lune", "Ascendant", "Milieu du Ciel", "Descendant", "Imum Coeli", "Vénus", "Mars", "Mercure", "Part de Fortune"]);
    const SIGS_EXPANSION = ["CARRIERE_UP", "FINANCE_UP", "MARIAGE", "ENFANT", "RELOCATION"];
    const SIGS_DETACHE  = ["SANTE_DOWN", "CARRIERE_DOWN", "FINANCE_DOWN", "SEPARATION", "DEUIL", "SPIRITUEL", "RELOCATION", "HÉRITAGE"];

    const nNordHits = findTransitHits(payload, h =>
      h.transitP === "Nœud Nord"
      && PERSO_OR_ANGLE.has(h.natalP)
      && HARD_ASPECTS.has(h.aspectName)
      && isFinite(h.orb) && h.orb <= 0.5
    );
    const nSudHits = findTransitHits(payload, h =>
      h.transitP === "Nœud Sud"
      && PERSO_OR_ANGLE.has(h.natalP)
      && HARD_ASPECTS.has(h.aspectName)
      && isFinite(h.orb) && h.orb <= 0.5
    );

    // Set des maisons touchées par chaque Nœud (natalHouse ∪ transitHouse)
    const collectHouses = (hits) => {
      const houses = new Set();
      for (const h of hits) {
        if (h.natalHouse) houses.add(Number(h.natalHouse));
        if (h.transitHouse) houses.add(Number(h.transitHouse));
      }
      return houses;
    };
    const nordHouses = collectHouses(nNordHits);
    const sudHouses  = collectHouses(nSudHits);

    const matchesHouses = (sig, housesSet) => {
      const topiques = CODE_HOUSES[sig] || [];
      return topiques.some(h => housesSet.has(h));
    };

    if (nordHouses.size > 0) {
      for (const sig of SIGS_EXPANSION) {
        if (!finalScores[sig] || finalScores[sig] <= 0) continue;
        if (!matchesHouses(sig, nordHouses)) continue;
        finalScores[sig] = Math.round(finalScores[sig] * 1.15);
        breakdown[sig].final = finalScores[sig];
        breakdown[sig].nodeNorthBoost = 1.15;
      }
    }
    if (sudHouses.size > 0) {
      for (const sig of SIGS_DETACHE) {
        if (!finalScores[sig] || finalScores[sig] <= 0) continue;
        if (!matchesHouses(sig, sudHouses)) continue;
        finalScores[sig] = Math.round(finalScores[sig] * 1.15);
        breakdown[sig].final = finalScores[sig];
        breakdown[sig].nodeSouthBoost = 1.15;
      }
    }
  }

  // ═══════════════════════════════════════════════════════════════════
  // Note 205 — Piste ζ : Transits lourds sur Nœuds NATALS (axe karmique réveillé)
  // Doctrine : quand une planète lente (Saturne, Uranus, Neptune, Pluton)
  // touche en aspect dur partile (orbe ≤ 1°) un Nœud lunaire natal,
  // l'axe de destinée du natif est "réveillé" → boost sur les signatures
  // d'expansion (Nœud Nord) ou détachement (Nœud Sud).
  //
  // Filtré par CODE_HOUSES comme Piste ε pour éviter dilution :
  // on prend les maisons natale du Nœud + maison du transiteur lent,
  // et on ne booste que les signatures dont la maison topique correspond.
  // Coef ×1.15 (×1.3 saturait massivement → -7 M1, -8 M5/M10).
  // ═══════════════════════════════════════════════════════════════════
  {
    const LENTES_LOURDES = new Set(["Saturne", "Uranus", "Neptune", "Pluton"]);
    const SIGS_EXPANSION_NN = ["CARRIERE_UP", "FINANCE_UP", "MARIAGE", "ENFANT", "RELOCATION"];
    const SIGS_DETACHE_NS  = ["SANTE_DOWN", "CARRIERE_DOWN", "FINANCE_DOWN", "SEPARATION", "DEUIL", "SPIRITUEL", "HÉRITAGE", "RELOCATION"];

    const hitNoeudNord = findTransitHits(payload, h =>
      h.natalP === "Nœud Nord"
      && LENTES_LOURDES.has((h.transitP || "").replace(/^(ARC|PS|TP|fast_|slow_)\s*/, ""))
      && HARD_ASPECTS.has(h.aspectName)
      && isFinite(h.orb) && h.orb <= 1.0
    );
    const hitNoeudSud = findTransitHits(payload, h =>
      h.natalP === "Nœud Sud"
      && LENTES_LOURDES.has((h.transitP || "").replace(/^(ARC|PS|TP|fast_|slow_)\s*/, ""))
      && HARD_ASPECTS.has(h.aspectName)
      && isFinite(h.orb) && h.orb <= 1.0
    );

    const collectHousesZeta = (hits) => {
      const houses = new Set();
      for (const h of hits) {
        if (h.natalHouse) houses.add(Number(h.natalHouse));
        if (h.transitHouse) houses.add(Number(h.transitHouse));
      }
      return houses;
    };
    const nordHousesZ = collectHousesZeta(hitNoeudNord);
    const sudHousesZ  = collectHousesZeta(hitNoeudSud);

    const matchesHousesZ = (sig, housesSet) => {
      const topiques = CODE_HOUSES[sig] || [];
      return topiques.some(h => housesSet.has(h));
    };

    if (nordHousesZ.size > 0) {
      for (const sig of SIGS_EXPANSION_NN) {
        if (!finalScores[sig] || finalScores[sig] <= 0) continue;
        if (!matchesHousesZ(sig, nordHousesZ)) continue;
        finalScores[sig] = Math.round(finalScores[sig] * 1.15);
        breakdown[sig].final = finalScores[sig];
        breakdown[sig].natalNodeNorthBoost = 1.15;
      }
    }
    if (sudHousesZ.size > 0) {
      for (const sig of SIGS_DETACHE_NS) {
        if (!finalScores[sig] || finalScores[sig] <= 0) continue;
        if (!matchesHousesZ(sig, sudHousesZ)) continue;
        finalScores[sig] = Math.round(finalScores[sig] * 1.15);
        breakdown[sig].final = finalScores[sig];
        breakdown[sig].natalNodeSouthBoost = 1.15;
      }
    }
  }

  // ═══════════════════════════════════════════════════════════════════
  // Note 207 — Piste θ : Astéroïdes en TRANSIT (symétrique de Piste ε pour Nœuds)
  // Doctrine : quand un astéroïde transite une planète personnelle ou un angle
  // natal en aspect dur partile (≤ 0.5°), il active la thématique mythologique
  // qu'il porte. Filtré par CODE_HOUSES comme ε.
  //
  // - Junon  : MARIAGE, SEPARATION
  // - Cérès  : DEUIL, ENFANT (nourriture/perte — Déméter/Perséphone)
  // - Vesta  : SPIRITUEL, RELOCATION (foyer/dévotion)
  // - Pallas : JURIDIQUE_UP, JURIDIQUE_DOWN (sagesse/stratégie/justice)
  // - Lilith : SCANDALE, SEPARATION (exclusion/rébellion)
  //
  // Coef ×1.10 (plus modéré que ε car les astéroïdes sont moins universels).
  // ═══════════════════════════════════════════════════════════════════
  {
    const PERSO_OR_ANGLE_T = new Set(["Soleil", "Lune", "Ascendant", "Milieu du Ciel", "Descendant", "Imum Coeli", "Vénus", "Mars", "Mercure", "Part de Fortune"]);
    const ASTEROID_TO_SIGS = {
      "Junon":  ["MARIAGE", "SEPARATION"],
      "Cérès":  ["DEUIL", "ENFANT"],
      "Vesta":  ["SPIRITUEL", "RELOCATION"],
      "Pallas": ["JURIDIQUE_UP", "JURIDIQUE_DOWN"],
      "Lilith": ["SCANDALE", "SEPARATION"],
    };

    for (const [aster, sigs] of Object.entries(ASTEROID_TO_SIGS)) {
      const hits = findTransitHits(payload, h => {
        const tP = (h.transitP || "").replace(/^(ARC|PS|TP|fast_|slow_)\s*/, "");
        return tP === aster
          && PERSO_OR_ANGLE_T.has(h.natalP)
          && HARD_ASPECTS.has(h.aspectName)
          && isFinite(h.orb) && h.orb <= 0.5;
      });
      if (hits.length === 0) continue;

      const housesT = new Set();
      for (const h of hits) {
        if (h.natalHouse) housesT.add(Number(h.natalHouse));
        if (h.transitHouse) housesT.add(Number(h.transitHouse));
      }

      for (const sig of sigs) {
        if (!finalScores[sig] || finalScores[sig] <= 0) continue;
        const topiques = CODE_HOUSES[sig] || [];
        if (!topiques.some(h => housesT.has(h))) continue;
        finalScores[sig] = Math.round(finalScores[sig] * 1.15);
        breakdown[sig].final = finalScores[sig];
        breakdown[sig][`asteroidTransit_${aster}`] = 1.15;
      }
    }
  }

  // ═══════════════════════════════════════════════════════════════════
  // Note 210 / 224 / 225 / 226 — Piste κ : Éclipses avec règle des maisons
  // Doctrine : une éclipse qui réactive un degré natal (planète transitant
  // un degré d'éclipse, orbe ≤ 2°) est un déclencheur de destin précis.
  //
  // Source v2 (Note 224) : `_mdseEclipseDegreeReactivations` exposé désormais
  // au top-level du payload par le super-noeud N8N. Données structurées :
  //   { planet, transitDate, eclipseDate, eclipseHouse, eclipseType, orb, house }
  //
  // Avant : on regexait `eventSignatures[i].eclipseReactivation` (string), on
  // n'avait que la maison de l'éclipse. Maintenant on a planète, orbe, type,
  // dates → exploitation fine possible.
  //
  // Note 226 — Filtre temporel (causalité)
  //   Une éclipse ne peut influer sur un événement qu'à partir du moment où
  //   elle se produit. Deux bornes successives :
  //     (a) fin de la période évaluée (`payload.periode`) — garde-fou global ;
  //     (b) fin de la `peakWindow` de la signature (ev.peakWindow.end) — filtre
  //         par signature, car une sig qui se calme avant la fin de l'année
  //         ne peut pas être déclenchée par une éclipse postérieure.
  //   Si une borne n'est pas parseable, on relâche le filtre (fail-open).
  //   Même règle appliquée à `transitDate` (le déclencheur doit avoir eu lieu).
  // ═══════════════════════════════════════════════════════════════════
  const _parseEndDate = (s) => {
    if (typeof s !== "string") return null;
    if (/^\d{4}-\d{2}-\d{2}$/.test(s)) {
      const t = Date.parse(s + "T23:59:59Z");
      return isNaN(t) ? null : t;
    }
    const months = { janvier:0, "février":1, fevrier:1, mars:2, avril:3, mai:4, juin:5, juillet:6, "août":7, aout:7, septembre:8, octobre:9, novembre:10, "décembre":11, decembre:11 };
    const m = s.match(/au\s+(\d{1,2})\s+([a-zéàâû]+)\s+(\d{4})/i);
    if (!m) return null;
    const mo = months[m[2].toLowerCase()];
    if (mo === undefined) return null;
    return Date.UTC(parseInt(m[3],10), mo, parseInt(m[1],10), 23, 59, 59);
  };
  const _evalEndTs = _parseEndDate(payload && payload.periode);

  // Borne supérieure d'effet d'une éclipse pour une signature donnée.
  // Ordre de préférence : peakWindow.end de la sig > _evalEndTs > Infinity.
  const _sigEvalEndTs = (sigCode) => {
    if (Array.isArray(payload.eventSignatures)) {
      const ev = payload.eventSignatures.find(e => e && e.code === sigCode);
      const pw = ev && ev.peakWindow;
      if (pw && pw.end) {
        const t = _parseEndDate(pw.end);
        if (t !== null) return t;
      }
    }
    return _evalEndTs !== null ? _evalEndTs : Infinity;
  };

  // Une date d'éclipse est valide pour une borne donnée si elle est antérieure
  // ou égale (la causalité doit être respectée).
  const _isPastFor = (dateStr, endTs) => {
    if (endTs === null || endTs === undefined || endTs === Infinity) return true;
    if (typeof dateStr !== "string") return true;
    const t = Date.parse(dateStr);
    if (isNaN(t)) return true;
    return t <= endTs;
  };

  const eclipseReactsRaw = Array.isArray(payload._mdseEclipseDegreeReactivations)
    ? payload._mdseEclipseDegreeReactivations
    : null;

  if (eclipseReactsRaw && eclipseReactsRaw.length > 0 && Array.isArray(payload.eventSignatures)) {
    // Note 224/225 — Hiérarchie hellénistique des types d'éclipses.
    // Calibration finale (Note 226) : on conserve l'écart Note 224 plutôt que
    // l'écart accentué 1.40/1.10 de la directive Gemini §1, car le test sur
    // 26 cas a montré qu'accentuer la Totale ET démoter la Partielle fait
    // chuter M3 (-1 sur anthony-weiner : la Partielle "06-01 M7" est le seul
    // signal qui plaçait SCANDALE en M3, et la passer de ×1.15 à ×1.10 la
    // fait perdre face à DEUIL boosté par une Totale). À reconsidérer avec
    // Gemini si on identifie des cas où la hiérarchie accentuée aide vraiment.
    const ECLIPSE_BOOST_BY_TYPE = {
      "Totale":    1.30,
      "Annulaire": 1.25,
      "Partielle": 1.15
    };

    // Note 225 — Planètes rapides : un transit Lune/Mercure/Vénus/Soleil sur
    // le degré d'une éclipse est trop éphémère pour faire foi (le luminaire
    // y passe chaque mois/année). On divise la "promesse de boost" par 2 sauf
    // si la planète rapide est elle-même un Maître Topique de la signature
    // (auquel cas elle réveille une promesse natale réelle).
    const FAST_PLANETS = new Set(["Soleil", "Lune", "Mercure", "Vénus"]);

    // ISO comportement v1 : on limite l'éligibilité aux signatures présentes
    // dans `eventSignatures` (top 12 de l'ancien moteur).
    const eligibleSigs = new Set(payload.eventSignatures.map(e => e.code).filter(Boolean));

    const ranked = Object.entries(finalScores)
      .filter(([, v]) => v > 0)
      .sort((a, b) => b[1] - a[1])
      .map(([k]) => k);
    const rankOf = (sig) => ranked.indexOf(sig);

    // Pré-filtre : on enlève les pénombrales et les éclipses postérieures à la
    // fin GLOBALE de la période évaluée (garde-fou). Le filtrage fin par sig
    // (peakWindow.end) est appliqué dans la boucle ci-dessous.
    const usefulReactsAll = eclipseReactsRaw.filter(r =>
      !/Pénombrale/i.test(r.eclipseType || "")
      && _isPastFor(r.eclipseDate, _evalEndTs)
      && _isPastFor(r.transitDate, _evalEndTs)
    );

    // Pour la pondération maîtres topiques : précalcul des house lords.
    const houseLords = getHouseLords(payload);

    for (const sig of eligibleSigs) {
      if (!finalScores[sig] || finalScores[sig] <= 0) continue;
      if (rankOf(sig) < 3) continue; // top3 ignoré (déjà détecté)
      const topiques = CODE_HOUSES[sig] || [];
      if (topiques.length === 0) continue;

      // Précalcul : maîtres topiques de la sig (planètes régissant les maisons clés).
      const lordsOfSig = new Set();
      if (houseLords) {
        for (const h of topiques) if (houseLords[h]) lordsOfSig.add(houseLords[h]);
      }

      // Filtre temporel par signature (Note 226) : on rejette les éclipses
      // postérieures au peakWindow.end de cette sig.
      const sigEnd = _sigEvalEndTs(sig);
      const reactsForSig = usefulReactsAll.filter(r =>
        _isPastFor(r.eclipseDate, sigEnd)
        && _isPastFor(r.transitDate, sigEnd)
      );

      // On cherche la meilleure éclipse pour cette signature (le boost le plus fort).
      let bestBoost = 0;
      for (const r of reactsForSig) {
        if (!topiques.includes(r.eclipseHouse)) continue;
        const baseBoost = ECLIPSE_BOOST_BY_TYPE[r.eclipseType] ?? 1.10;
        const promise = baseBoost - 1; // partie "boost" du multiplicateur (0.40, 0.25, 0.10)
        const isLord = lordsOfSig.has(r.planet);

        // Pondération planète rapide (Note 225 §2)
        let factor = 1;
        if (FAST_PLANETS.has(r.planet) && !isLord) factor = 0.5;

        // Bonus Maître Topique réactivé (Note 225 §3, ex-Piste B3)
        // Calibration finale (Note 226) : +0.10 au lieu de +0.15. À +0.15
        // certaines sigs concurrentes (ACCIDENT/JURIDIQUE_DOWN dont les
        // maîtres topiques sont fréquemment activés) montent trop et évincent
        // des sigs attendues plus discrètes (chanel-FINANCE_UP).
        let lordBonus = isLord ? 0.10 : 0;

        const b = 1 + promise * factor + lordBonus;
        if (b > bestBoost) bestBoost = b;
      }
      if (bestBoost === 0) continue;

      finalScores[sig] = Math.round(finalScores[sig] * bestBoost);
      breakdown[sig].final = finalScores[sig];
      breakdown[sig].eclipseHouseBoost = bestBoost;
    }

    // ─────────────────────────────────────────────────────────────────
    // Note 225 §4 — `_mdseEclipseNatalHits` : éclipses en conjonction
    // directe avec une planète natale. Marque toute l'année (voire 3 ans)
    // du sceau de cette planète. Boost massif sur les sigs dont la planète
    // touchée est Maître Topique — étendu aux Angles via la Note 227 §2.
    // Format hit : { planet, house, orb, date, eclType, eclAstre, eclHouse }
    // ─────────────────────────────────────────────────────────────────
    const NATAL_HIT_BOOST_BY_TYPE = {
      "Totale":    1.50,
      "Annulaire": 1.35,
      "Partielle": 1.20
    };
    const KNOWN_PLANETS = new Set([
      "Soleil", "Lune", "Mercure", "Vénus", "Mars",
      "Jupiter", "Saturne", "Uranus", "Neptune", "Pluton", "Chiron"
    ]);
    // Note 227 §2 — Extension Angles : un hit sur un angle équivaut à frapper
    // le Maître Direct de la maison correspondante. MC ↔ M10, AS ↔ M1, etc.
    // C'est plus puissant qu'une planète, car les angles sont les "portes" du
    // thème : ils n'ont pas besoin d'un maître intermédiaire, ils SONT
    // littéralement leur maison.
    const ANGLE_TO_HOUSE = {
      "Ascendant": 1, "AS": 1, "Asc": 1,
      "Fond du Ciel": 4, "FC": 4, "Imum Coeli": 4, "IC": 4,
      "Descendant": 7, "DS": 7, "Desc": 7,
      "Milieu du Ciel": 10, "MC": 10, "Médium Coeli": 10, "Medium Coeli": 10
    };
    // Filtre Pénombrales + causalité temporelle globale (Note 226).
    // Le filtre par sig (peakWindow.end) est appliqué dans la boucle.
    const natalHitsAll = Array.isArray(payload._mdseEclipseNatalHits)
      ? payload._mdseEclipseNatalHits.filter(h =>
          !/Pénombrale/i.test(h.eclType || "")
          && _isPastFor(h.date, _evalEndTs)
        )
      : [];

    if (natalHitsAll.length > 0) {
      for (const sig of eligibleSigs) {
        if (!finalScores[sig] || finalScores[sig] <= 0) continue;
        const topiques = CODE_HOUSES[sig] || [];
        if (topiques.length === 0) continue;

        // Maîtres topiques de la sig (utilisé pour hits sur planètes natales)
        const lordsOfSig = new Set();
        if (houseLords) {
          for (const h of topiques) if (houseLords[h]) lordsOfSig.add(houseLords[h]);
        }

        // Filtre temporel par sig (Note 226)
        const sigEnd = _sigEvalEndTs(sig);
        const natalHitsForSig = natalHitsAll.filter(h => _isPastFor(h.date, sigEnd));

        // Un hit qualifie pour cette sig si :
        //   (a) la planète touchée est un Maître Topique connu de la sig, OU
        //   (b) la planète touchée est un Angle (MC/AS/DS/FC) dont la maison
        //       équivalente fait partie des maisons topiques de la sig.
        // Note 228 Q2 : On relaxe la condition rank >= 3 pour les hits angulaires,
        // car ils sont des déclencheurs primaires qui doivent solidifier le top 1.
        let bestNatalBoost = 0;
        let bestNatalReason = null;
        for (const h of natalHitsForSig) {
          let qualifies = false;
          let reason = null;
          let isAngle = false;
          if (KNOWN_PLANETS.has(h.planet) && lordsOfSig.has(h.planet)) {
            if (rankOf(sig) < 3) continue; // Règle rank >= 3 maintenue pour planètes
            qualifies = true;
            reason = "lord=" + h.planet;
          } else {
            const angleHouse = ANGLE_TO_HOUSE[h.planet];
            if (angleHouse && topiques.includes(angleHouse)) {
              // Pas de filtre rank >= 3 pour les angles
              qualifies = true;
              isAngle = true;
              reason = "angle=" + h.planet + "→M" + angleHouse;
            }
          }
          if (!qualifies) continue;
          const b = NATAL_HIT_BOOST_BY_TYPE[h.eclType] ?? 0;
          if (b > bestNatalBoost) { bestNatalBoost = b; bestNatalReason = reason; }
        }
        if (bestNatalBoost === 0) continue;

      finalScores[sig] = Math.round(finalScores[sig] * bestNatalBoost);
      breakdown[sig].final = finalScores[sig];
      breakdown[sig].eclipseNatalHitBoost = bestNatalBoost;
      breakdown[sig].eclipseNatalHitReason = bestNatalReason;
      }
    }

    // ─────────────────────────────────────────────────────────────────
    // B3 (2026-06-02) — `_mdseEclipseHouseMap` polarité maison Brady L10258
    // Brady Ch.5 : « take greater notice of the natal houses in which
    // eclipses will occur over a given period of time … eclipses in any
    // one year will occur in a house polarity, e.g., 1st/7th or 2nd/8th »
    // V20 historique exploitait eclipseHouse SEULEMENT via les réactivations
    // (boost ×1.15-1.30 ci-dessus L5176-5202). Les éclipses NON réactivées
    // par transit ultérieur étaient ignorées alors que Brady en fait un
    // signifiant majeur INDÉPENDANT.
    // Patch ADDITIF PLAFONNÉ : +3 max par sig (single bonus, pas cumulé),
    // appliqué après les boosts multiplicatifs existants, sous flag dormant.
    // Format hit : { house, date, type, astre, degree, saros }
    // ─────────────────────────────────────────────────────────────────
    // B3 (2026-06-02) — Brady L10258 HouseMap polarité éclipses
    // LOCKED ON par défaut suite décision utilisateur 2026-06-02 après bench PREPROD
    // baseline 150 = +2.0 pp M5 BLOC A combiné (B3 + fenêtre éclipses 5y).
    // (cf. BILAN-B3-FENETRE5Y-PREPROD-GAIN-2026-06-02.md).
    // Override OFF possible via DTC_B3_HOUSEMAP=0 si rollback requis.
    // ⚠️ PRÉREQUIS DOCTRINAL : ce patch n'est efficace que si la fenêtre éclipses
    // 5 ans est en place en amont (cf. prev-deploy-download-eclipses-fenetre-5y-*).
    // Sans cette fenêtre, B3 ne dispose que de ~4 éclipses/cas et reste TIÈDE.
    const _DTC_B3_HOUSEMAP = (typeof process !== "undefined" && process.env && process.env.DTC_B3_HOUSEMAP === '0') ? false : true;
    if (_DTC_B3_HOUSEMAP) {
      const houseMapAll = Array.isArray(payload._mdseEclipseHouseMap)
        ? payload._mdseEclipseHouseMap.filter(e =>
            !/Pénombrale/i.test(e.type || "")
            && _isPastFor(e.date, _evalEndTs)
          )
        : [];
      if (houseMapAll.length > 0) {
        for (const sig of eligibleSigs) {
          if (!finalScores[sig] || finalScores[sig] <= 0) continue;
          const topiques = CODE_HOUSES[sig] || [];
          if (topiques.length === 0) continue;
          const sigEnd = _sigEvalEndTs(sig);
          // Polarité Brady L10258 : maison topique OU maison opposée (h ± 6)
          const polarSet = new Set();
          for (const h of topiques) { polarSet.add(h); polarSet.add(((h - 1 + 6) % 12) + 1); }
          let hasPolarityHit = false;
          let polarityReason = null;
          for (const e of houseMapAll) {
            if (!_isPastFor(e.date, sigEnd)) continue;
            if (polarSet.has(e.house)) {
              hasPolarityHit = true;
              polarityReason = "ecl=" + e.astre + "@H" + e.house + "(" + (e.type || "") + ")";
              break;
            }
          }
          if (hasPolarityHit) {
            finalScores[sig] = Math.min(99, finalScores[sig] + 3);
            if (breakdown[sig]) {
              breakdown[sig].final = finalScores[sig];
              breakdown[sig].b3HouseMapBonus = 3;
              breakdown[sig].b3HouseMapReason = polarityReason;
            }
          }
        }
      }
    }

    // ─────────────────────────────────────────────────────────────────
    // Note 227 §3 — `_eclipsesProgressees` : éclipses en progression
    // secondaire (1-2 fois par vie). Réveil de l'éclipse natale.
    // Doctrine Gemini : boost ×1.25 sur les sigs partageant la maison
    // de l'éclipse progressée.
    //
    // ⚠ Limitation actuelle : N8N expose `signe` mais pas toujours `degre`
    // ni la maison natale équivalente. Si manquant, on ne peut pas filtrer
    // par maison → on saute (fail-safe). À enrichir côté N8N pour exploitation
    // complète.
    // ─────────────────────────────────────────────────────────────────
    const PROG_ECLIPSE_BOOST = 1.25;
    const progAll = Array.isArray(payload._eclipsesProgressees)
      ? payload._eclipsesProgressees.filter(e =>
          !/Pénombrale/i.test(e.type || "")
          && _isPastFor(e.dateVie, _evalEndTs)
        )
      : [];

    // On retient uniquement les entrées qui ont une maison natale exploitable
    // (champ explicite `house` ou `maison`).
    const progWithHouse = progAll.filter(e => Number.isFinite(e.house) || Number.isFinite(e.maison));
    if (progWithHouse.length > 0) {
      for (const sig of eligibleSigs) {
        if (!finalScores[sig] || finalScores[sig] <= 0) continue;
        if (rankOf(sig) < 3) continue;
        const topiques = CODE_HOUSES[sig] || [];
        if (topiques.length === 0) continue;

        const sigEnd = _sigEvalEndTs(sig);
        const matched = progWithHouse.some(e => {
          const h = Number.isFinite(e.house) ? e.house : e.maison;
          return topiques.includes(h) && _isPastFor(e.dateVie, sigEnd);
        });
        if (!matched) continue;

        finalScores[sig] = Math.round(finalScores[sig] * PROG_ECLIPSE_BOOST);
        breakdown[sig].final = finalScores[sig];
        breakdown[sig].eclipseProgBoost = PROG_ECLIPSE_BOOST;
      }
    }
  } else if (Array.isArray(payload.eventSignatures)) {
    // Fallback (cache pré-Note 224) : regex sur les strings comme avant.
    // Note 226 : pas de filtre temporel ici car le string ne porte que MM-DD
    // (pas d'année). On compte sur le filtrage déjà fait en amont par N8N
    // (les eclipseReactivation d'une eventSignature sont relatives à l'année
    // évaluée). Code maintenu en sécurité pour caches obsolètes.
    const ranked = Object.entries(finalScores)
      .filter(([, v]) => v > 0)
      .sort((a, b) => b[1] - a[1])
      .map(([k]) => k);
    const rankOf = (sig) => ranked.indexOf(sig);
    for (const ev of payload.eventSignatures) {
      const sig = ev.code;
      if (!sig || !finalScores[sig] || finalScores[sig] <= 0) continue;
      const r = rankOf(sig);
