  // Note 229 — Stations (Rétrogrades et Directes)
  //   Une planète qui entre en station s'arrête sur un degré précis.
  //   Si ce degré est en aspect serré (≤ 2.0°) avec une planète natale,
  //   la thématique de la planète transitante se "fige" sur le point natal.
  //   C'est un déclencheur majeur (la planète y reste des semaines).
  //
  // Calibrage v2 :
  //   - Restriction aux PLANÈTES LENTES (Jupiter+). Mercure/Vénus stationnent
  //     ~3 fois/an, c'est du bruit. Mars aussi à plus petite échelle.
  //     Astéroïdes (Ceres, Junon, Pallas, Vesta) exclus aussi.
  //   - Boost calibré à ×1.20 (au lieu de 1.30) pour éviter la sur-domination.
  //   - Maître Topique requis (comme l'ancien moteur `station_on_natal`).
  //   - rank >= 3 maintenu (top3 déjà détecté, on solidifie le mid-top).
  //   Source : `_mdseStations` (exposé par N8N, Note 229 N8N).
  //   Format : { house, planete, date, fullDegree }
  // ═══════════════════════════════════════════════════════════════════
  const SLOW_STATION_PLANETS = new Set(["Jupiter", "Saturne", "Uranus", "Neptune", "Pluton", "Chiron"]);
  const STATION_BOOST = 1.20;
  const STATION_ORB = 2.0;
  const stationsRaw = Array.isArray(payload._mdseStations) ? payload._mdseStations : [];
  const slowStations = stationsRaw.filter(s => SLOW_STATION_PLANETS.has(s.planete));

  if (slowStations.length > 0 && payload._natalDict) {
    const ranked = Object.entries(finalScores)
      .filter(([, v]) => v > 0)
      .sort((a, b) => b[1] - a[1])
      .map(([k]) => k);
    const rankOf = (sig) => ranked.indexOf(sig);

    for (const sig of Object.keys(finalScores)) {
      if (!finalScores[sig] || finalScores[sig] <= 0) continue;
      if (rankOf(sig) < 3) continue; // top3 déjà détecté
      const topiques = CODE_HOUSES[sig] || [];
      if (topiques.length === 0) continue;

      // Maîtres topiques de la sig
      const lordsOfSig = new Set();
      const hLords = getHouseLords(payload);
      if (hLords) {
        for (const h of topiques) if (hLords[h]) lordsOfSig.add(hLords[h]);
      }
      if (lordsOfSig.size === 0) continue;

      // Filtre temporel par sig (Note 226 : causalité)
      const sigEnd = _sigEvalEndTs(sig);
      const stationsForSig = slowStations.filter(s => _isPastFor(s.date, sigEnd));

      let stationHit = false;
      let hitReason = null;
      for (const st of stationsForSig) {
        // On vérifie si la station touche une planète natale qui est Maître Topique
        for (const lord of lordsOfSig) {
          const nData = payload._natalDict[lord];
          if (nData && typeof nData.deg === "number") {
            const dist = Math.min(Math.abs(st.fullDegree - nData.deg), 360 - Math.abs(st.fullDegree - nData.deg));
            if (dist <= STATION_ORB) {
              stationHit = true;
              hitReason = `${st.planete}@${st.date} on ${lord} (${dist.toFixed(2)}°)`;
              break;
            }
          }
        }
        if (stationHit) break;
      }

      if (stationHit) {
        finalScores[sig] = Math.round(finalScores[sig] * STATION_BOOST);
        breakdown[sig].final = finalScores[sig];
        breakdown[sig].stationBoost = STATION_BOOST;
        breakdown[sig].stationReason = hitReason;
      }
    }
  }

