    let heavyContrib = 0;
    const hits = findTransitHits(payload, h => {
      if (h.isProg) return false;
      const tP = (h.transitP || "").replace(/^(ARC|PS|TP|fast_|slow_)\s*/, "");
      if (!HARD_ACC.has(h.aspectName)) return false;
      const pT = ACC_PLANETS_W[tP] || 0.1;
