function _phxParsePeriodeWindow(periode) {
  if (!periode || typeof periode !== "string") return null;
  const re = /(\d{1,2})\s+([a-zéèêàûôîïüç]+)\s+(20\d{2}|19\d{2})/gi;
  const parts = [];
  let m;
  while ((m = re.exec(periode)) !== null) {
    const mo = PHX_MOIS[m[2].toLowerCase()];
    if (!mo) continue;
    const dd = m[1].length < 2 ? "0" + m[1] : m[1];
    parts.push(m[3] + "-" + mo + "-" + dd);
  }
  if (parts.length >= 2) return { start: parts[0], end: parts[1] };
  if (parts.length === 1) return { start: parts[0], end: parts[0] };
  const y = periode.match(/\b(20\d{2}|19\d{2})\b/);
  if (y) return { start: y[1] + "-01-01", end: y[1] + "-12-31" };
  return null;
}

// PROD n8n : pas de _dtc_meta.event_date → ancre = pic le plus serré dans la période.
function _phxPickAnchorDate(payload) {
  if (!payload) return null;
  const meta = payload._dtc_meta;
  if (meta && meta.event_date) return meta.event_date;
  const win = _phxParsePeriodeWindow(payload.periode);
  if (!win) return null;
  let bestPk = null;
  let bestOrb = 99;
  const blocks = [payload._aspectsSuiviRap || {}, payload._aspectsSuiviLent || {}];
  for (let bi = 0; bi < blocks.length; bi++) {
    const block = blocks[bi];
    const keys = Object.keys(block);
    for (let i = 0; i < keys.length; i++) {
      // Patch C-2 anchor-safe (gated) : un lot dérivé (Lot d'Héritage, Vertex
      // Anti, etc.) ne doit jamais servir d'ancre temporelle GLOBALE pour le
      // payload, sinon un aspect ultra-serré sur un lot ajouté en C-2 décale
      // eventDate pour TOUTES les signatures et provoque des cascades
      // hors-doctrine (cf. JURIDIQUE_DOWN +85). Gate _phxPhaseC2Active() :
      // patch inactif tant que DTC_PHASEC2_LOTS_ENABLED n'est pas posé, donc
      // PROD/PREPROD restent strictement identiques (iso 150/150 préservé).
      if (_phxPhaseC2Active()) {
        const parts = keys[i].split("|||");
        const np = parts.length >= 3 ? parts[2] : null;
        if (np && _phxIsLot(np)) continue;
      }
      const val = block[keys[i]];
      if (!val || !val.waves) continue;
      for (let w = 0; w < val.waves.length; w++) {
        const pk = val.waves[w].peakDate || val.waves[w].start;
        if (!_phxInWindow(pk, win.start, win.end)) continue;
        const orb = parseFloat(val.waves[w].minOrb);
        if (!isFinite(orb) || orb >= bestOrb) continue;
        bestOrb = orb;
        bestPk = pk;
      }
    }
  }
  if (bestPk) return bestPk;
  return win.start.slice(0, 4) + "-07-01";
}

function _phxDaysFrom(eventDate, peakISO) {
  if (!eventDate || !peakISO) return null;
  return Math.round((new Date(peakISO) - new Date(eventDate)) / 86400000);
}

function _phxAddDays(eventDate, n) {
  if (!eventDate) return null;
  const d = new Date(eventDate + "T12:00:00Z");
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
}

function _phxInWindow(dateISO, start, end) {
  return dateISO && (!start || dateISO >= start) && (!end || dateISO <= end);
}

