    if (natalP === meta.ruler7 || natalP === meta.chartRuler) return ["maître"];
    if (["Vénus", "Lune", "Jupiter", "Mercure"].indexOf(natalP) >= 0) return ["planète_clé"];
    if ([4, 5, 6, 7, 11].indexOf(h) >= 0) return ["M" + h];
