  if (code === "SEPARATION") {
      if (PHX_ANGLES.has(natalP)) return ["angle"];
      if (natalP === meta.ruler7) return ["maître_M7"];
      if (["Uranus", "Pluton", "Junon"].indexOf(natalP) >= 0) return ["planète_clé"];
      if (["Vénus", "Lune", "Mars", "Mercure", "Jupiter", "Saturne"].indexOf(natalP) >= 0) return ["planète"];
      if ([2, 3, 5, 7, 8, 12].indexOf(h) >= 0) return ["M" + h];
      return null;
