    if (natalP === meta.ruler10 || natalP === meta.chartRuler) return ["maître"];
    if (["Soleil", "Jupiter", "Vénus"].indexOf(natalP) >= 0) return ["planète_clé"];
    if (code === "SCANDALE" && (natalP === "Lot d'Éros" || natalP === "Lot d'Eros")) return ["lot"];
    if ([1, 10, 11].indexOf(h) >= 0) return ["M" + h];
