    if (natalP === "Imum Coeli") return ["IC"];
    if (natalP === meta.ruler5) return ["maître_M5"];
    if ([4, 5].indexOf(h) >= 0) return ["M" + h];
    return null;
  }
  if (code === "RELOCATION") {
    if (natalP === "Imum Coeli") return ["IC"];
    if (natalP === "Lune" || PHX_ANGLES.has(natalP)) return ["angle/Lune"];
    if (natalP === meta.ruler4) return ["maître_M4"];
    if ([3, 4].indexOf(h) >= 0) return ["M" + h];
    return null;
  }
  if (code === "DEUIL") {
    if (natalP === "Imum Coeli") return ["IC"];
    if (PHX_ANGLES.has(natalP)) return ["angle"];
    if (natalP === meta.ruler8 || natalP === meta.ruler4) return ["maître"];
    if (["Lune", "Saturne", "Pluton"].indexOf(natalP) >= 0) return ["planète"];
    if (/^Nœud/.test(natalP)) return ["nœud"];
    if ([4, 8].indexOf(h) >= 0) return ["M" + h];
