  }
  if (code === "HÉRITAGE") {
    if (natalP === meta.ruler8) return ["maître_M8"];
    if (_phxMatchLot(natalP, "Héritage") || _phxMatchLot(natalP, "Heritage")) return ["lot"];
    if (h === 8) return ["M8"];
    if (PHX_ANGLES.has(natalP) || h === 4 || h === 10) return ["axe_famille"];
    if (["Pluton", "Saturne", "Jupiter", "Neptune"].indexOf(natalP) >= 0 && [4, 8, 10].indexOf(h) >= 0) {
      return ["planète_axe"];
    }
    if (["Lune", "Soleil"].indexOf(natalP) >= 0 && [4, 8].indexOf(h) >= 0) return ["luminaire_axe"];
    return null;
