    if (natalP === meta.ruler9 || natalP === meta.ruler12) return ["maître_juridique"];
    if (/^Nœud/.test(natalP)) return ["nœud"];
    if ([9, 12].indexOf(h) >= 0) return ["M" + h];
    return null;
  }
  return null;
}

