function _phxScorePermissionHit(code, layer, prom, asp, natalP, natalHouse, orb, unit, meta) {
  if (_phxAntiPattern(code, layer, prom, asp, natalP)) return null;
  if (!_phxPromissorOk(code, prom)) return null;
  if (!_phxAllowedAspects(code, prom).has(asp)) return null;
  const why = _phxSignificator(code, natalP, natalHouse, meta);
  if (!why && !(PHX_ANGLES.has(prom) && orb <= 0.3)) return null;
  const maxOrb = unit === "years" ? 1.0 : 1.0;
  if (orb > maxOrb) return null;
  const tight = unit === "years" ? orb <= 0.25 : orb <= 0.3;
  const quasiExact = layer === "ARC" && orb <= 0.1;
  return {
    layer: layer, pattern: prom + " " + asp + " " + natalP + (natalHouse ? " M" + natalHouse : ""),
    prom: prom, asp: asp, natalP: natalP, natalHouse: natalHouse,
    orb: orb, unit: unit, tight: tight, quasiExact: quasiExact,
    source: layer, why: why || ["angle_tight"],
