}

// Extraction permission DP + ARC.
function _phxExtractPermission(payload, meta, code) {
  const hits = [];
  const dps = payload._primaryDirections || [];
  for (let i = 0; i < dps.length; i++) {
    const dp = dps[i];
    const orbY = parseFloat(dp.orbYears);
    if (!isFinite(orbY)) continue;
    const r = _phxScorePermissionHit(code, "DP", dp.promissor, dp.aspect, dp.significator, dp.sigHouse, orbY, "years", meta);
    if (r) hits.push(r);
  }
  const lines = (payload.progressionsRaw && payload.progressionsRaw.aspects) || [];
  const text = lines.join("\n");
  const re = /ARC SOLAIRE\s*:\s*([\wœéèêàû]+(?:\s+[\wœéèêàû]+)?)\s+dirigé.+?en\s+(\w+)\s+avec\s+(\w+)\s+natal/gi;
  let m;
  while ((m = re.exec(text)) !== null) {
    const prom = m[1];
    const asp = m[2];
    const natalP = m[3];
    const line = text.slice(m.index, m.index + 200);
    const orbM = line.match(/orbe\s+([\d.]+)°/);
    const orb = orbM ? parseFloat(orbM[1]) : 9;
    const hM = line.match(/natal\s*\(M(\d+)/);
