    if (!info || !info.house) continue;
    if (info.house === 8) tierA.add(p);
    if (info.house === 6 || info.house === 12) tierB.add(p);
  }
  tierB.add("Lot de Maladie");
  const rap = payload._aspectsSuiviRap || {};
  const lent = payload._aspectsSuiviLent || {};
  const rapKeys = Object.keys(rap);
  let hasFast = false;
  for (let i = 0; i < rapKeys.length; i++) {
    if (rapKeys[i].indexOf("fast_Mars|||") === 0) { hasFast = true; break; }
  }
  const block = hasFast ? rap : lent;
  const prefix = hasFast ? "fast_Mars|||" : "slow_Mars|||";
  const hits = [];
  const blockKeys = Object.keys(block);
  for (let i = 0; i < blockKeys.length; i++) {
    const key = blockKeys[i];
    if (key.indexOf(prefix) !== 0) continue;
    const val = block[key];
    if (!val || !val.waves || !val.waves.length) continue;
    const parts = key.split("|||");
    const asp = parts[1];
    const np = parts[2];
    if (!PHX_HARD.has(asp)) continue;
    let tier = null;
    if (tierA.has(np) || PHX_ANGLES.has(np) || np === "Mars") tier = "A";
    else if (tierB.has(np)) tier = "B";
    if (!tier) continue;
    for (let j = 0; j < val.waves.length; j++) {
      const w = val.waves[j];
      const pk = w.peakDate || w.start;
      if (!_phxInWindow(pk, start, end)) continue;
      const orb = parseFloat(w.minOrb);
      const orbMax = tier === "A" ? 1.5 : 1.0;
      if (!isFinite(orb) || orb > orbMax) continue;
      if (tier === "B" && orb > 0.5) continue;
      const daysJ = _phxDaysFrom(eventDate, pk);
      hits.push({
        pattern: "Mars " + asp + " " + np,
        natalP: np, orb: orb, peak: pk, daysJ: daysJ, tier: tier,
        jourJ: Math.abs(daysJ) <= jourJMax,
      });
    }
  }
  hits.sort(function (a, b) {
    const jA = a.jourJ ? 0 : 1;
    const jB = b.jourJ ? 0 : 1;
    if (jA !== jB) return jA - jB;
    return Math.abs(a.daysJ) - Math.abs(b.daysJ);
  });
  const top = hits[0] || null;
  const jourJ = hits.find ? hits.find(function (h) { return h.jourJ; }) : null;
  return {
    present: hits.length > 0, top: top, jourJ: jourJ || null,
    strong: !!top && (top.jourJ || top.orb <= 0.5),
  };
}

// Signaux CORPS typés (Gemini 290 H1 — pas de regex sur chaînes).
function _phxScanCorpsHit(prom, asp, natalP, natalHouse, meta) {
  const flags = { acc: false, sd: false };
  if (!prom) return flags;
  const h = natalHouse || (meta.nd[natalP] && meta.nd[natalP].house);
  const accProm = prom === "Uranus" || prom === "Mars" || prom === "Pluton";
  const sdProm = prom === "Saturne" || prom === "Neptune" || prom === "Chiron" || prom === "Pluton";
  const hard = asp === "Conjonction" || asp === "Carré" || asp === "Opposition";
  const voyageLot = natalP && /Voyage/i.test(natalP);
  const chronicPlace = h === 6 || h === 12 || h === 1 || natalP === "Ascendant"
    || (natalP && /Maladie/i.test(natalP))
    || (prom === "Pluton" && (h === 12 || h === 1 || natalP === "Ascendant" || /Ceres|Cérès/.test(natalP)))
    || (prom === "Mars" && natalP === "Soleil" && h === 10);
  const accPlace = h === 1 || h === 8 || voyageLot
    || (accProm && hard && (natalP === "Lune" || natalP === meta.chartRuler))
    || (accProm && hard && natalP === "Soleil" && h !== 10);
  if (sdProm && (hard || asp === "Quinconce") && chronicPlace) flags.sd = true;
  if (accProm && hard && accPlace) flags.acc = true;
  if (sdProm && hard && voyageLot) flags.acc = true;
  if (asp === "Quinconce" && (prom === "Saturne" || prom === "Neptune" || prom === "Uranus")) flags.sd = true;
  return flags;
}

function _phxCollectCorpsSignals(permDpArc, transitTop, decl, lentRoof, mars, meta) {
  const out = { acc: false, sd: false, quinconce: false, jourJMars: false };
  function mergeHit(prom, asp, natalP, natalHouse) {
    const f = _phxScanCorpsHit(prom, asp, natalP, natalHouse, meta);
    if (f.acc) out.acc = true;
    if (f.sd) out.sd = true;
    if (asp === "Quinconce") out.quinconce = true;
  }
  for (let i = 0; i < permDpArc.length; i++) {
    mergeHit(permDpArc[i].prom, permDpArc[i].asp, permDpArc[i].natalP, permDpArc[i].natalHouse);
  }
  if (transitTop) mergeHit(transitTop.prom, transitTop.asp, transitTop.natalP, null);
  for (let d = 0; d < decl.length; d++) {
    mergeHit(decl[d].prom, decl[d].asp, decl[d].progP, decl[d].progHouse);
  }
  if (lentRoof) mergeHit(lentRoof.prom, lentRoof.asp, lentRoof.natalP, lentRoof.natalHouse);
  if (mars && mars.jourJ) out.jourJMars = true;
  return out;
}

function _phxRouteFacette(code, corpsSignals, mars, lentRoof) {
  if (code !== "ACCIDENT" && code !== "SANTE_DOWN") return code;
  if (!corpsSignals) return code;
  if (code === "ACCIDENT") {
    // Exception Athina: Toit M8/Vénus/Fortune sans Mars violent jour J = HÉRITAGE/FINANCE, pas ACCIDENT
    if (!corpsSignals.acc && lentRoof && /M8\b|Vénus|Venus|Part de Fortune/.test(lentRoof.pattern) && /Saturne|Pluton/.test(lentRoof.prom)) {
      if (!mars || !mars.jourJ) return null;
    }

    if (corpsSignals.acc) return "ACCIDENT";
    // Exception Diana: Neptune/Saturne/Pluton M1 + Mars/Pluton fort
    const fatalM1 = lentRoof && /M1\b|Ascendant/.test(lentRoof.pattern) && /Neptune|Saturne|Pluton/.test(lentRoof.prom);
    if (fatalM1 && mars && mars.present) return "ACCIDENT";

    if (!corpsSignals.sd && (corpsSignals.jourJMars || (mars && mars.strong))) return "ACCIDENT";
    return null;
  }
  if (corpsSignals.quinconce || corpsSignals.sd) return "SANTE_DOWN";
  if (corpsSignals.jourJMars && corpsSignals.acc) return "ACCIDENT";
  return "SANTE_DOWN";
}

function _phxIsScandaleMcLentS(code, lentRoof) {
  if (code !== "SCANDALE" || !lentRoof || lentRoof.tier !== "S") return false;
  return lentRoof.natalP === "Milieu du Ciel";
}

// Gemini 290 — SD ne plafonne DEUIL que si marqueurs chroniques probants (pas Neptune ambiant).
function _phxSdDominatesDeuil(sdEmp) {
  if (!sdEmp || !sdEmp.stackOk || !sdEmp.corpsSignals) return false;
