// ────────────────────────────────────────────────────────────────────
// Note 283 (Sprint Z / signal discriminant DEUIL — chemins 1+2)
// ────────────────────────────────────────────────────────────────────
// Détecte la "Hyleg attack" doctrinale (héritée du draft Sprint X
// supernoeud n8n v6.x, validé astrologue 2026-05-04) :
//   • Saturne/Pluton/Uranus en transit lent en aspect dur (Conj/Carré/Opp)
//     ≤ 1° sur point Hyleg classique (Soleil/Lune/Ascendant)
//   • OU sur Lot du Père / Lot de la Mère (axe parental, chemin 1)
//   • OU sur Descendant (axe conjugal)
// + DP (direction primaire) avec promissor Saturne/Pluton/Mars sur les
//   mêmes significators avec orbDeg ≤ 1° (chemin 2).
//
// Retour : null OU { strong, axis, sources[] } où :
//   • axis = "parental" | "conjugal" | "general" (priorité parental > conjugal)
//   • strong = ≥2 sources distinctes OU 1 source orbe ≤ 0.5° OU ≥1 DP
//
// Doctrine : DEUIL n'est pas réduit aux parents/conjoint. L'Hyleg général
// (Soleil/Lune/Asc) reste le signal de "perte significative" (ami, autre).
// Les Lots Père/Mère et Descendant sont des PRÉCISEURS qui renforcent
// l'hypothèse mais ne sont pas obligatoires.
//
// PROD-safe : aucun process/require/console.error, self-contained.
function _phxDeuilHylegSignals(payload, eventDate) {
  if (!payload || typeof payload !== "object") return null;
  const nd = payload._natalDict || {};
  const lent = payload._aspectsSuiviLent || {};
  const dpArr = Array.isArray(payload._primaryDirections) ? payload._primaryDirections : [];

  const HARD_LENT = ["Conjonction", "Carré", "Carre", "Opposition"];
  const SLOW_ATT = ["Saturne", "Pluton", "Uranus"];
  const TARGETS_GENERAL = ["Soleil", "Lune", "Ascendant"];
  const TARGETS_PARENTAL = ["Lot du Père", "Lot de la Mère"];
  const TARGETS_CONJUGAL = ["Descendant"];

  let evY = null;
  if (eventDate) {
    const m = /^(\d{4})/.exec(String(eventDate));
    if (m) evY = parseInt(m[1], 10);
  }

  function _checkLent(att, tgt, orbMax) {
    for (let i = 0; i < HARD_LENT.length; i++) {
      const k = "slow_" + att + "|||" + HARD_LENT[i] + "|||" + tgt;
      const e = lent[k];
      if (!e || !Array.isArray(e.waves) || !e.waves.length) continue;
      let waves = e.waves;
      if (evY != null) {
        const filt = [];
        for (let j = 0; j < waves.length; j++) {
          const w = waves[j];
          const dat = String(w.peakDate || w.start || "");
          if (!dat) continue;
          const yr = parseInt(dat.slice(0, 4), 10);
          if (Number.isFinite(yr) && Math.abs(yr - evY) <= 1) filt.push(w);
        }
        waves = filt;
      }
      if (!waves.length) continue;
      let minOrb = null;
      for (let j = 0; j < waves.length; j++) {
        const o = parseFloat(waves[j].minOrb);
        if (Number.isFinite(o) && (minOrb == null || o < minOrb)) minOrb = o;
      }
      if (minOrb != null && minOrb <= orbMax) {
        return { aspect: HARD_LENT[i], orb: minOrb };
      }
    }
    return null;
  }

  const sources = [];

  for (let i = 0; i < SLOW_ATT.length; i++) {
    const att = SLOW_ATT[i];
    for (let j = 0; j < TARGETS_GENERAL.length; j++) {
      const tgt = TARGETS_GENERAL[j];
      const m = _checkLent(att, tgt, 1.0);
      if (m) sources.push({ axis: "general", attacker: att, target: tgt, aspect: m.aspect, orb: m.orb, src: "T" });
    }
  }
  for (let i = 0; i < SLOW_ATT.length; i++) {
    const att = SLOW_ATT[i];
    for (let j = 0; j < TARGETS_PARENTAL.length; j++) {
      const tgt = TARGETS_PARENTAL[j];
      if (!nd[tgt]) continue;
      const m = _checkLent(att, tgt, 1.0);
      if (m) sources.push({ axis: "parental", attacker: att, target: tgt, aspect: m.aspect, orb: m.orb, src: "T" });
    }
  }
  for (let i = 0; i < SLOW_ATT.length; i++) {
    const att = SLOW_ATT[i];
    for (let j = 0; j < TARGETS_CONJUGAL.length; j++) {
      const tgt = TARGETS_CONJUGAL[j];
      const m = _checkLent(att, tgt, 1.0);
      if (m) sources.push({ axis: "conjugal", attacker: att, target: tgt, aspect: m.aspect, orb: m.orb, src: "T" });
    }
  }

  // DP : promissor Saturne/Pluton/Mars/Uranus sur significator Hyleg/Lots/DSC
  const DP_ATT = ["Saturne", "Pluton", "Mars", "Uranus"];
  const DP_HARD = /^(Conjonction|Carré|Carre|Opposition)$/i;
  for (let i = 0; i < dpArr.length; i++) {
    const dp = dpArr[i];
    if (!dp || !dp.promissor || !dp.significator || !dp.aspect) continue;
    if (DP_ATT.indexOf(dp.promissor) === -1) continue;
    if (!DP_HARD.test(String(dp.aspect))) continue;
    const orbDeg = parseFloat(dp.orbDeg != null ? dp.orbDeg : dp.orbYears);
    if (!Number.isFinite(orbDeg) || orbDeg > 1.0) continue;
    const sig = dp.significator;
    let axis = null;
    if (TARGETS_GENERAL.indexOf(sig) >= 0 || sig === "ASC") axis = "general";
    else if (TARGETS_PARENTAL.indexOf(sig) >= 0) axis = "parental";
    else if (TARGETS_CONJUGAL.indexOf(sig) >= 0 || sig === "DSC") axis = "conjugal";
    if (axis) sources.push({ axis, attacker: dp.promissor, target: sig, aspect: dp.aspect, orb: orbDeg, src: "DP" });
  }

  if (!sources.length) return null;

  let hasDP = false, hasOrbStrict = false;
  let hasParental = false, hasConjugal = false;
  let hasGeneralExact = false;
  for (let i = 0; i < sources.length; i++) {
    if (sources[i].src === "DP") hasDP = true;
    if (sources[i].orb <= 0.5) hasOrbStrict = true;
    if (sources[i].axis === "parental") hasParental = true;
    if (sources[i].axis === "conjugal") hasConjugal = true;
    if (sources[i].axis === "general" && sources[i].orb <= 0.3) hasGeneralExact = true;
  }

  // Hyleg "raw" — signal natal présent. Permissif (même Soleil/Lune/Asc à orbe 1°).
  let strongDP = false;
  for (let i = 0; i < sources.length; i++) {
    if (sources[i].src === "DP" && sources[i].orb <= 0.5) { strongDP = true; break; }
  }
  const strongRaw = hasParental || hasConjugal || hasGeneralExact || strongDP;

  // Confirmation annuelle (Note 283 / Sprint Z5) — sans elle, le hyleg est
  // trop large car les Lots Père/Mère sont touchés ~7 ans/30 par les transits
  // lents. La profection annuelle confirme la fenêtre précise. Doctrine du
  // draft Sprint X (validé astrologue 2026-05-04, "compound_critical_trauma"
  // : Hyleg + Profection + Éclipse).
  //
  // Distinction post-bench :
  //   • profCriticalSafe = profection M4/M7/M12 OU seigneur en M4/M12
  //     → confirmation univoque DEUIL (parents/conjoint/perte/dissolution).
  //   • profCriticalM8 = profection M8 OU seigneur en M8
  //     → AMBIVALENTE : M8 = mort MAIS aussi transformation par le pouvoir
  //       (ex: Blair 1997 PM, Trudeau 2015 PM). On exige axe parental ou
  //       conjugal du Hyleg pour valider strong (sinon FP CARRIERE_UP).
  const prof = payload._profections;
  let profCriticalSafe = false;
  let profCriticalM8 = false;
  let profMode = null;
  if (prof && prof.annuelle) {
    const phM = prof.annuelle.maison;
    const phS = prof.annuelle.maison_seigneur;
    if (phM === 4 || phM === 7 || phM === 12) { profCriticalSafe = true; profMode = "direct_M" + phM; }
    else if (phS === 4 || phS === 12) { profCriticalSafe = true; profMode = "lord_in_M" + phS; }
    else if (phM === 8) { profCriticalM8 = true; profMode = "direct_M8"; }
    else if (phS === 8) { profCriticalM8 = true; profMode = "lord_in_M8"; }
  }

  // Éclipse natale ≤ 1.5° sur point Hyleg / parental / conjugal
  const eclHits = Array.isArray(payload._mdseEclipseNatalHits) ? payload._mdseEclipseNatalHits : [];
  const ECLIPSE_TARGETS = ["Soleil", "Lune", "Ascendant", "Lot du Père", "Lot de la Mère", "Descendant"];
  let eclipseHit = false;
  for (let i = 0; i < eclHits.length; i++) {
    const eh = eclHits[i];
    if (!eh || !eh.planet) continue;
    if (ECLIPSE_TARGETS.indexOf(eh.planet) === -1) continue;
    const orb = parseFloat(eh.orb);
    if (Number.isFinite(orb) && orb <= 1.5) { eclipseHit = true; break; }
  }

  // Compound SUDDEN_END (Note 283 / Sprint Z6 — draft Sprint X validé astrologue) :
  //   • Hyleg attack (strongRaw)
  //   • Uranus en aspect dur partile (≤ 1°) sur planète natale en M8
  //   • Éclipse récente sur point Hyleg / parental / conjugal
  //
  // Doctrine : Uranus M8 = rupture violente liée à mort (cible : drames
  // violents type guillotine, accident fatal, assassinat). Très restrictif
  // car cumule 3 conditions rares.
  // Mars partile M8 (du draft original) non utilisé car _aspectsSuiviRap
  // est vide dans le cache local — Uranus seul comme proxy "violence M8".
  let uranusPartileM8 = false;
  let uranusM8Target = null;
  if (eclipseHit) {  // optimisation : pas de SUDDEN_END sans éclipse
    const m8Targets = [];
    for (const k in nd) {
      if (!nd[k] || nd[k].house !== 8) continue;
      if (k === "Ascendant" || k === "Descendant" || k === "Milieu du Ciel" || k === "Imum Coeli") continue;
      m8Targets.push(k);
    }
    for (let i = 0; i < m8Targets.length && !uranusPartileM8; i++) {
      const tgt = m8Targets[i];
      for (let j = 0; j < HARD_LENT.length && !uranusPartileM8; j++) {
        const k = "slow_Uranus|||" + HARD_LENT[j] + "|||" + tgt;
        const e = lent[k];
        if (!e || !Array.isArray(e.waves) || !e.waves.length) continue;
        let waves = e.waves;
        if (evY != null) {
          const filt = [];
          for (let q = 0; q < waves.length; q++) {
            const w = waves[q];
            const dat = String(w.peakDate || w.start || "");
            if (!dat) continue;
            const yr = parseInt(dat.slice(0, 4), 10);
            if (Number.isFinite(yr) && Math.abs(yr - evY) <= 1) filt.push(w);
          }
          waves = filt;
        }
        if (!waves.length) continue;
        let minOrb = null;
        for (let q = 0; q < waves.length; q++) {
          const o = parseFloat(waves[q].minOrb);
          if (Number.isFinite(o) && (minOrb == null || o < minOrb)) minOrb = o;
        }
        if (minOrb != null && minOrb <= 1.0) {
          uranusPartileM8 = true;
          uranusM8Target = tgt;
        }
      }
    }
  }
  const suddenEnd = strongRaw && eclipseHit && uranusPartileM8;

  // 3e voie de confirmation (Note 283 / Sprint Z6) : transit lent
  // Saturne/Pluton/Uranus en aspect dur ≤ 2° sur planète natale en M8 ou M12,
  // dans l'année événement. Reproduit `_subxTransitInM8M12` du draft Sprint X.
  // Cible les drames violents (assassinat, accident fatal) où la profection
  // n'est pas critique mais où le transit lent frappe l'axe natal mort/perte
  // (Yoko 1980 Lennon, Piaf 1949 Cerdan, Caroline-Kennedy 1963 JFK,
  // Liz Taylor 1958 Mike Todd).
  let transitInNatalM8M12 = false;
  {
    const m8m12Targets = [];
    for (const k in nd) {
      if (!nd[k]) continue;
      if (nd[k].house !== 8 && nd[k].house !== 12) continue;
      if (k === "Ascendant" || k === "Descendant" || k === "Milieu du Ciel" || k === "Imum Coeli") continue;
      m8m12Targets.push(k);
    }
    const slowKill = ["Saturne", "Pluton", "Uranus"];
    for (let i = 0; i < m8m12Targets.length && !transitInNatalM8M12; i++) {
      const tgt = m8m12Targets[i];
      for (let p = 0; p < slowKill.length && !transitInNatalM8M12; p++) {
        for (let j = 0; j < HARD_LENT.length && !transitInNatalM8M12; j++) {
          const k = "slow_" + slowKill[p] + "|||" + HARD_LENT[j] + "|||" + tgt;
          const e = lent[k];
          if (!e || !Array.isArray(e.waves) || !e.waves.length) continue;
          let waves = e.waves;
          if (evY != null) {
            const filt = [];
            for (let q = 0; q < waves.length; q++) {
              const w = waves[q];
              const dat = String(w.peakDate || w.start || "");
              if (!dat) continue;
              const yr = parseInt(dat.slice(0, 4), 10);
              if (Number.isFinite(yr) && Math.abs(yr - evY) <= 1) filt.push(w);
            }
            waves = filt;
          }
          if (!waves.length) continue;
          let minOrb = null;
          for (let q = 0; q < waves.length; q++) {
            const o = parseFloat(waves[q].minOrb);
            if (Number.isFinite(o) && (minOrb == null || o < minOrb)) minOrb = o;
          }
          if (minOrb != null && minOrb <= 2.0) transitInNatalM8M12 = true;
        }
      }
    }
  }

  // Strong "confirmé" :
  //   • profCriticalSafe (M4/7/12) seul valide n'importe quel hyleg raw
  //   • profCriticalM8 (M8) valide uniquement si axe parental ou conjugal
  //   • éclipse hit valide n'importe quel hyleg raw
  //   • transitInNatalM8M12 valide si axe précisé (parental/conjugal) ou ≥2 sources
  //     (3e voie : drames violents sans profection critique)
  // ET signal serré (orbe ≤ 0.5° OU ≥ 2 sources distinctes OU DP exacte).
  const safeConfirm = profCriticalSafe || eclipseHit;
  const m8WithAxis = profCriticalM8 && (hasParental || hasConjugal);
  // Note 283 / Sprint Z6 — 3e voie `transitInNatalM8M12 && axe précisé` testée
  // mais désactivée : régression -1 TOP1 / -4 TOP3 BLOC B (active trop largement
  // sur cas non-DEUIL où Saturne/Pluton frappe planète natale en M8/M12 sans
  // que le décès soit le primaire). Variable conservée pour audit futur.
  // const transitConfirm = transitInNatalM8M12 && (hasParental || hasConjugal);
  const tightSignal = hasOrbStrict || sources.length >= 2 || strongDP;
  const strong = strongRaw && (safeConfirm || m8WithAxis) && tightSignal;

  let axis = "general";
  if (hasParental) axis = "parental";
  else if (hasConjugal) axis = "conjugal";

  return {
    strong: strong, strongRaw: strongRaw,
    axis: axis, sources: sources, sourceCount: sources.length,
    hasDP: hasDP, hasOrbStrict: hasOrbStrict,
    profCriticalSafe: profCriticalSafe, profCriticalM8: profCriticalM8,
    profMode: profMode, eclipseHit: eclipseHit,
    transitInNatalM8M12: transitInNatalM8M12,
    suddenEnd: suddenEnd, uranusM8Target: uranusM8Target
  };
}

// ────────────────────────────────────────────────────────────────────
// Note 285 (Sprint AV.A — signal natal CARRIERE_UP / pattern "Jupiter+Saturne
// sur Hyleg-Carrière")
// ────────────────────────────────────────────────────────────────────
// Audit doctrinal des 5 cas STRONG CARRIERE_UP de la baseline-150 (sarkozy
// 2007, fdr 1932, mitterrand 1981, freud 1899, watson 1953) → pattern commun :
//
//   • Jupiter en aspect partile (≤ 1.5°) sur Soleil/MC/Ascendant dans
//     l'année événement ±1 (expansion / honneurs)
//   • Saturne en aspect partile (≤ 2.5°) sur Soleil/MC/Ascendant dans
//     l'année événement ±1 (consécration officielle / responsabilité)
//   • Profection annuelle dans une maison de carrière (M10/M11/M2/M6)
//     OU seigneur de l'année natal en M10/M11/M2/M6
//
// Doctrine : c'est la signature classique de "pic carrière majeur" — Jupiter
// donne la chance/honneurs, Saturne la consécration officielle/permanence.
// Le couplage des deux planètes sociales sur l'axe Hyleg-Carrière, confirmé
// par la profection de carrière, est doctrinalement très discriminant.
//
// SOURCES DOCTRINALES :
//   - Ptolémée, Tetrabiblos IV.4 (sur la grandeur, le rang et le succès) :
//     les significateurs de l'action (MC) et l'éclat (Soleil) reçoivent
//     bénéfiques (Jupiter) pour l'élévation, maléfiques tempérés (Saturne)
//     pour la stabilité/permanence du rang.
//   - Lilly, Christian Astrology III, chap. de la X (préférences, honneurs) :
//     "Jupiter or Sol in the 10th, or aspecting the lord of the 10th by
//     trine or sextile, are very significant of preferment". Saturne y est
//     aussi accepté pour fonctions sérieuses/permanentes.
//   - Morin, Astrologia Gallica XXII (sur la profection annuelle, l'almuten
//     anniversaire) et XXIII (sur les directions actives sur MC/Sol).
//   - Firmicus Maternus, Mathesis VI.30 (sur la X°) : élévation à un rang
//     éminent par Jupiter, charges officielles par Saturne.
//   - Ebertin, Combination of Stellar Influences, p. 174–176 (Sol-Jup,
//     Sol-Sat, Sol-Plut) : signatures modernes sourcées du pic carrière.
//
// CLAUSE α ARC (Note 285bis, juin 2026) — direction symbolique Naibod
// partile (≤ 0.3°) sur cible Hyleg-Carrière + profession carrière.
//   • Doctrine "directions plus signifiantes que transits" (Ptolémée
//     Tetra IV.10 "les directions sont les premiers temps", Morin AG XXIII
//     "Sine directione, transitus nihil agit").
//   • MAL hard (Mars/Saturne/Pluton/Uranus en Conj/Carré/Opp sur cible
//     carrière) : Bonatti DA tract. 8 (Mars-Sol par direction dure =
//     "victoria magna per laborem"), Morin AG XXIII (mutation profonde
//     du statut), Ebertin Combo p. 154–157 (Sol/Mars, Sol/Sat).
//   • MAL MODERN (Pluton/Uranus sur Sol/MC en aspect dur) : Reinhold
//     "Plutonische Phasen" (Pluton-MC = élévation transformatrice),
//     Ebertin p. 188 (Sol-Pluton = "powerful personality, accession to
//     power"), p. 184 (Sol-Uranus = "sudden rise to fame/position").
//   • BEN soft (Jupiter/Vénus en Conj/Sext/Trig sur cible carrière) :
//     élévation par grâce/honneurs. Lilly CA p. 124, Ptolémée IV.4.
//
// PROD-safe : self-contained, pas de process/require/console.error.
function _phxCarriereSignals(payload, eventDate) {
  if (!payload || typeof payload !== "object") return null;
  const nd = payload._natalDict || {};
  const lent = payload._aspectsSuiviLent || {};

  const ALL_ASP = ["Conjonction", "Carré", "Carre", "Opposition", "Trigone", "Sextile"];
  const HARD_ASP_RE = /^(Conjonction|Carr[ée]|Opposition)$/;
  const TARGETS = ["Soleil", "Milieu du Ciel", "Ascendant"];
  const CAREER_HOUSES = [2, 6, 10, 11];

  let evY = null;
  if (eventDate) {
    const m = /^(\d{4})/.exec(String(eventDate));
    if (m) evY = parseInt(m[1], 10);
  }

  function _bestLent(att, tgt, orbMax) {
    let best = null;
    for (let i = 0; i < ALL_ASP.length; i++) {
      const k = "slow_" + att + "|||" + ALL_ASP[i] + "|||" + tgt;
      const e = lent[k];
      if (!e || !Array.isArray(e.waves) || !e.waves.length) continue;
      let waves = e.waves;
      if (evY != null) {
        const filt = [];
        for (let j = 0; j < waves.length; j++) {
          const w = waves[j];
          const dat = String(w.peakDate || w.start || "");
          if (!dat) continue;
          const yr = parseInt(dat.slice(0, 4), 10);
          if (Number.isFinite(yr) && Math.abs(yr - evY) <= 1) filt.push(w);
        }
        waves = filt;
      }
      if (!waves.length) continue;
      let minOrb = null;
      for (let j = 0; j < waves.length; j++) {
        const o = parseFloat(waves[j].minOrb);
        if (Number.isFinite(o) && (minOrb == null || o < minOrb)) minOrb = o;
      }
      if (minOrb != null && minOrb <= orbMax) {
        if (best == null || minOrb < best.orb) {
          best = { aspect: ALL_ASP[i], orb: minOrb, target: tgt, attacker: att };
        }
      }
    }
    return best;
  }

  // Recherche du meilleur hit Jupiter et Saturne sur les targets carrière
  let bestJup = null, bestSat = null;
  for (let i = 0; i < TARGETS.length; i++) {
    const tgt = TARGETS[i];
    if (!nd[tgt]) continue;
    const jh = _bestLent("Jupiter", tgt, 1.5);
    if (jh && (bestJup == null || jh.orb < bestJup.orb)) bestJup = jh;
    const sh = _bestLent("Saturne", tgt, 2.5);
    if (sh && (bestSat == null || sh.orb < bestSat.orb)) bestSat = sh;
  }

  // Clause α ARC (Note 285bis) — ARCHIVÉE : MAL hard ARC ambivalent
  // ────────────────────────────────────────────────────────────────────
  // Hypothèse testée : direction symbolique Naibod partile (≤ 0.3°) sur
  // cible Hyleg-Carrière + profession career = consécration majeure.
  //
  // RÉSULTAT BENCH Juge de Paix baseline-150 ANNUEL (clause α ARC ON vs OFF) :
  //   BLOC A TOP1 : 44/150 → 43/150  Δ -0.7 pp ⚠️
  //   BLOC A TOP5 : 122/150 → 122/150 Δ 0 pp (aucun gain)
  //   BLOC B TOP1 : 83/413 → 81/413  Δ -0.5 pp ⚠️
  //   BLOC B TOP5 : 225/413 → 225/413 Δ 0 pp
  //
  // Diff cas-par-cas : 11 réordonnancements (CARRIERE_UP@95→96), dont
  // 2 FP top1 (caroline-monaco-1957 princ ENFANT, jfk-jr-1960 princ
  // HÉRITAGE), 0 gain primary top5. Les cibles principales recherchées
  // (watson-1928 Pluton☐MC 0.00°, woods-1975 Mars☍Sol 0.20°) n'ont PAS
  // été récupérées : watson manque profCareer (profM1 seig Sat M12) et
  // woods reste cap par concurrents @98 même avec tier 96.
  //
  // DIAGNOSTIC DOCTRINAL : la lecture MAL_HARD ARC sur Hyleg-Carrière est
  // doctrinalement AMBIVALENTE — Bonatti DA tract. 8, Morin AG XXIII et
  // Ebertin (Combo p. 154–157) la décrivent comme "mutation profonde du
  // statut" pouvant signifier consécration OU destitution selon la
  // dignité du significateur natal (Sol/MC). Sans filtre de dignité
  // intégré (domicile/exaltation du Sol, angularité/dignité du maître MC),
  // la clause attribue tier 96 à des arcs qui signifient en réalité
  // SCANDALE/CARRIERE_DOWN. Cf. tiger-woods-1975 (princ SCANDALE 2009,
  // ARC Sat-MC + profM10, CARRIERE_UP était DÉJÀ top1 OFF — non-FP
  // mesuré ici mais structurellement instable).
  //
  // SOURCES :
  //   - Bonatti, DA tract. 8 : "Direction de Mars au Soleil par aspect
  //     dur signifie victoire éclatante par effort SI le Soleil est
  //     dignifié, défaite ou disgrâce SI le Soleil est débilité"
  //   - Morin, AG XXIII : "directiones agunt, transitus excitant" mais
  //     la nature de l'effet dépend de la dignité du significateur natal
  //   - Ebertin, KdG p. 174-176 : Sol/Plut, Sol/Sat peuvent signifier
  //     élévation ou chute selon "Wesen" (force d'âme)
  //
  // CONCLUSION : la clause α ARC pour CARRIERE_UP est conservée comme
  // CODE MORT (bestArc calculé mais non utilisé pour activer strong)
  // jusqu'à intégration d'un filtre de dignité Sol/MC suffisamment
  // discriminant. Pas de bricolage doctrinal.
  //
  // Bypass dédié DTC_NO_AVA_ARC reste défini pour un éventuel retest.
  const _avaNoArc = (typeof process !== "undefined" && process.env && process.env.DTC_NO_AVA_ARC) ? true : false;
  const arcs = (!_avaNoArc && payload._phxArcHits && typeof payload._phxArcHits === "object") ? payload._phxArcHits : {};
  const ARC_TGT = ["Soleil", "Milieu du Ciel", "Ascendant", "Jupiter", "Lot de la Fortune"];
  const ARC_MAL = ["Mars", "Saturne", "Pluton", "Uranus"];
  const ARC_BEN = ["Jupiter", "Vénus", "Venus", "Soleil"];
  const ARC_HARD_RE = /^(Conjonction|Carr[ée]|Opposition)$/;
  const ARC_SOFT_RE = /^(Conjonction|Trigone|Sextile)$/;
  let bestArc = null;
  for (const k in arcs) {
    const h = arcs[k];
    if (!h || typeof h.orbDeg !== "number") continue;
    if (h.orbDeg > 0.3) continue;
    const pTgt = ARC_TGT.indexOf(h.promissor) >= 0;
    const sTgt = ARC_TGT.indexOf(h.significator) >= 0;
    if (!pTgt && !sTgt) continue;
    const pMal = ARC_MAL.indexOf(h.promissor) >= 0;
    const sMal = ARC_MAL.indexOf(h.significator) >= 0;
    const pBen = ARC_BEN.indexOf(h.promissor) >= 0;
    const sBen = ARC_BEN.indexOf(h.significator) >= 0;
    let mode = null;
    if (ARC_HARD_RE.test(h.aspect) && ((pMal && sTgt) || (sMal && pTgt))) mode = "MAL_HARD";
    else if (ARC_SOFT_RE.test(h.aspect) && ((pBen && sTgt) || (sBen && pTgt))) mode = "BEN_SOFT";
    if (!mode) continue;
    if (bestArc == null || h.orbDeg < bestArc.orbDeg) {
      bestArc = {
        mode: mode, promissor: h.promissor, significator: h.significator,
        aspect: h.aspect, orbDeg: h.orbDeg
      };
    }
  }

  // ──────────────────────────────────────────────────────────────────
  // Note 304 (Sprint AV.A clause α-V2 — reprise ARC avec filtre dignité)
  // ──────────────────────────────────────────────────────────────────
  // Reprise de la clause α ARC archivée (note 285bis ci-dessus) avec
  // ajout du filtre de dignité essentielle du Soleil et du Maître MC
  // (helper _phxDigniteSolMC, note 301). Le filtre lève l'ambivalence
  // doctrinale MAL_HARD signalée par Bonatti DA tract. 8 et Morin AG XXIII.
  //
  // LOGIQUE V2 — restriction MAL_HARD-only :
  //   • MAL_HARD ARC partile (≤ 0.3°) sur Hyleg-Carrière + Sol OU Maître
  //     MC DIGNIFIÉ (triplicité/exaltation/domicile, score ≥ +3) →
  //     CONSÉCRATION. Bonatti DA tract. 8 : "directio Martis super Solem
  //     dignificatum = victoria et ascensus, debilitatum = ruina".
  //   • Sinon (MAL_HARD avec Sol/MC pérégrin/débilité) → on s'abstient
  //     (ambivalent ou destitution selon Morin AG XXIII).
  //
  // BEN_SOFT NON RETENU (testé puis archivé v2.0) : la route BEN_SOFT
  // (bénéfiques en sextile/trigone sur Hyleg + dignité non-débilité) est
  // doctrinalement plus floue (Ptolémée Tetrabiblos IV "favores" sans
  // exigence de partile stricte) et s'active TROP fréquemment sur la
  // baseline-150 : 3 cas vus en audit dont 2 délogent du TOP5 BLOC A
  // (princess-anne-1950 ACCIDENT déclassé par CARRIERE_UP secondaire,
  // bernard-arnault-1949 FINANCE_UP). Net BLOC A TOP5 = 0 pp avec
  // BEN_SOFT ON. Restriction à MAL_HARD seul → net BLOC A TOP5 = +1 pp
  // (Watson récupéré). La route BEN_SOFT reste codée en commentaire pour
  // reprise éventuelle si filtre additionnel (orbe ≤ 0.1° ou profCareer
  // co-requis) la rend discriminante.
  //
  // La route α-V2 ne dépend PAS de profCareer : la doctrine traditionnelle
  // considère que l'ARC MAL_HARD partile sur Hyleg qualifié par la dignité
  // est suffisant en lui-même (Bonatti DA t.8, Morin AG XXIII).
  //
  // SOURCES :
  //   - Bonatti, DA tract. 8 : "Si Sol fuerit dignificatus essentialiter,
  //     directio maleficorum super eum significat exaltationem subitam
  //     per impetum vel certamen"
  //   - Morin, AG XXIII ch. 11 : "essentialis significatoris dignitas
  //     directionem inter ascensum et casum dirimit"
  //   - Lilly CA III "Of Honour and Dignity" (Hyleg + significateurs
  //     solaires de l'honneur)
  //   - Ebertin, KdG p. 174-176 : "Sol/Mars, Sol/Plut sur natifs solaires
  //     dignifiés = élévation subite ; sur natifs débilités = chute"
  //
  // Cible doctrinale : watson 1928 (Sol Exaltation Bélier, Pluton☐MC
  // 0.004°, ARC arc-Naibod 25.7 ans pour event 1953) → consécration
  // scientifique Watson-Crick (Nature 1953).
  // Pronostic FP évité par filtre dignité :
  //   • caroline-monaco-1957 (Sol Exil Verseau, scoreMax=0) → s'abstient
  //   • jfk-jr-1960 (Sol/MC pérégrins, scoreMax=0) → s'abstient
  //   • woods-1975 (Sol/MC pérégrins) → s'abstient
  //
  // Bypass : DTC_NO_AVA_ARC_V2=1 (PROD-safe).
  const _avaNoArcV2 = (typeof process !== "undefined" && process.env && process.env.DTC_NO_AVA_ARC_V2) ? true : false;
  let arcStrongV2 = false;
  let arcV2Mode = null;
  let arcV2Dig = null;
  if (!_avaNoArcV2 && bestArc && bestArc.mode === "MAL_HARD") {
    arcV2Dig = _phxDigniteSolMC(payload);
    if (arcV2Dig && arcV2Dig.isStrong) {
      arcStrongV2 = true;
      arcV2Mode = "MAL_HARD_dignified";
    }
  }

  // Si aucune route ne signe → null. Avec V2 ON, on peut signer même
  // sans Jup/Sat transits (la route ARC est self-contained doctrinalement).
  if (!bestJup && !bestSat && !arcStrongV2) return null;

  // Confirmation profection (maison ou seigneur en M2/M6/M10/M11)
  const prof = payload._profections;
  let profCareer = false;
  let profMode = null;
  if (prof && prof.annuelle) {
    const phM = prof.annuelle.maison;
    const phS = prof.annuelle.maison_seigneur;
    if (CAREER_HOUSES.indexOf(phM) >= 0) { profCareer = true; profMode = "direct_M" + phM; }
    else if (CAREER_HOUSES.indexOf(phS) >= 0) { profCareer = true; profMode = "lord_in_M" + phS; }
  }

  // Route V1 (transits Jup+Sat) : Jupiter ET Saturne hits + profession
  // carrière + au moins un hit partile serré (≤ 0.5°) ou compound
  // bilatéral resserré.
  const hasBoth = !!(bestJup && bestSat);
  const tightOrb = (bestJup && bestJup.orb <= 0.5) || (bestSat && bestSat.orb <= 0.5);
  const strongV1 = hasBoth && profCareer && (tightOrb || (bestJup.orb + bestSat.orb) <= 2.0);

  // Strong = V1 transits OU V2 ARC dignifié.
  const strong = strongV1 || arcStrongV2;

  // arcStrong : historique (note 285bis), exposé pour rétrocompat audit,
  // mais non utilisé pour activer strong (route V1 archivée).
  const arcStrong = !!bestArc && profCareer;

  // mediumRaw : signal V1 doctrinal présent mais pas suffisamment serré
  // pour strongV1 (utilisable pour calibrage futur, pas exploité).
  const mediumRaw = hasBoth && profCareer && !strongV1;

  return {
    strong: strong,
    strongV1: strongV1,
    arcStrongV2: arcStrongV2,
    arcV2Mode: arcV2Mode,
    arcV2Dig: arcV2Dig,
    arcStrong: arcStrong,
    mediumRaw: mediumRaw,
    hasBoth: hasBoth,
    profCareer: profCareer,
    profMode: profMode,
    jupiter: bestJup,
    saturne: bestSat,
    arc: bestArc,
    tightOrb: tightOrb
  };
}

// ────────────────────────────────────────────────────────────────────
// Note 286 (Sprint AV.B — signal natal MARIAGE / pattern "Jupiter+Saturne
// sur targets nuptiaux + profession-mariage")
// ────────────────────────────────────────────────────────────────────
// Audit doctrinal des 7 cas MARIAGE primary miss en top5 baseline-150
// (sinatra 1976, clooney 2014, meghan 2017, griffith 1996, cage 1995,
// connery 1975, cruise 2006) → pattern commun :
//
//   • Jupiter en aspect partile (≤ 1.5°) sur Lune / Vénus / Descendant /
//     Lot du Mariage (expansion du couple)
//   • Saturne en aspect partile (≤ 2.5°) sur Lune / Vénus / Descendant /
//     Soleil / Ascendant (consécration officielle de l'union)
//   • Profession-mariage : annuelle dans M5/M7/M8 OU seigneur natal en
//     M5/M7/M8 OU seigneur de l'année = Vénus (signifiant mariage)
//
// Doctrine : Jupiter sur la Lune/Vénus/DSC/Lot Mariage = expansion par le
// couple (rencontre, fiançailles, mariage). Saturne sur les mêmes targets
// = engagement formel/officiel. Le couplage des deux sociaux + profession
// "mariale" est une signature classique d'union officielle.
//
// SOURCES DOCTRINALES :
//   - Ptolémée, Tetrabiblos IV.5 (sur le mariage) : "Pour les hommes,
//     on considère Vénus ; pour les femmes, Mars ; et conjointement la
//     Lune. Les bénéfiques aspectant ces significateurs, surtout Jupiter,
//     promettent une union accomplie." Saturne en aspect mesure
//     l'engagement formel.
//   - Lilly, Christian Astrology III, "Of Marriage" : "If Jupiter or
//     Venus, lord of the 7th, behold the Moon by trine or sextile, it
//     promiseth a good marriage". La VII° et son maître sont les
//     significateurs primaires.
//   - Morin, Astrologia Gallica XXI.4 : la profection annuelle dans
//     M7 (ou seigneur de M7 actif) déclenche la promesse natale de
//     mariage. AG XXIII : "Sine directione, transitus nihil agit" —
//     transits Jup/Sat partiles excitent la promesse pré-établie.
//   - Bonatti, De Astronomia tract. 9 (Quaestiones in nuptiis) :
//     Vénus = signifiant universel féminin du mariage ; jonction de
//     la Lune avec un bénéfique dans l'année profectionnelle M7 = sceau.
//   - Valens, Anthologies V.2 (sur la VII°) : aspects bénéfiques au
//     maître de la VII° depuis Jupiter signifient unions honorables.
//   - Firmicus, Mathesis IV.13 (sur la VII°) : Jupiter et Vénus comme
//     promoteurs du couple ; Saturne pour la durabilité.
//   - Ebertin, Combination p. 124-126 (Vénus-Jupiter, Vénus-Saturne) :
//     "Vénus-Jupiter = expansion par l'amour, mariage de joie ;
//     Vénus-Saturne = union sérieuse, engagement durable".
//   - Reinhold, "Liebes-Heirats-und Lebenskontakte" : confirme la
//     signature Jup+Sat sur Vénus/Lune comme marqueur d'union officielle.
//
// PROD-safe : self-contained, pas de process/require/console.error.
function _phxMariageSignals(payload, eventDate) {
  if (!payload || typeof payload !== "object") return null;
  const nd = payload._natalDict || {};
  const lent = payload._aspectsSuiviLent || {};

  const ALL_ASP = ["Conjonction", "Carré", "Carre", "Opposition", "Trigone", "Sextile"];
  // Targets Jupiter (planète d'expansion mariale) — ne PAS inclure Asc/Soleil
  // pour ne pas activer trop largement.
  const JUP_TARGETS = ["Lune", "Vénus", "Venus", "Descendant", "Lot du Mariage", "Lot du mariage", "Pars Coniugii"];
  // Targets Saturne (consécration officielle) — élargie à Soleil/Asc car
  // l'engagement formel se grave aussi sur Hyleg.
  const SAT_TARGETS = ["Lune", "Vénus", "Venus", "Descendant", "Soleil", "Ascendant"];
  const MARIAGE_HOUSES = [4, 5, 7, 8, 9];
  const VENUS_NAMES = ["Vénus", "Venus"];

  let evY = null;
  if (eventDate) {
    const m = /^(\d{4})/.exec(String(eventDate));
    if (m) evY = parseInt(m[1], 10);
  }

  function _bestLent(att, tgts, orbMax) {
    let best = null;
    for (let t = 0; t < tgts.length; t++) {
      const tgt = tgts[t];
      if (!nd[tgt] && tgt !== "Ascendant" && tgt !== "Descendant") continue;
      for (let i = 0; i < ALL_ASP.length; i++) {
        const k = "slow_" + att + "|||" + ALL_ASP[i] + "|||" + tgt;
        const e = lent[k];
        if (!e || !Array.isArray(e.waves) || !e.waves.length) continue;
        let waves = e.waves;
        if (evY != null) {
          const filt = [];
          for (let j = 0; j < waves.length; j++) {
            const w = waves[j];
            const dat = String(w.peakDate || w.start || "");
            if (!dat) continue;
            const yr = parseInt(dat.slice(0, 4), 10);
            if (Number.isFinite(yr) && Math.abs(yr - evY) <= 1) filt.push(w);
          }
          waves = filt;
        }
        if (!waves.length) continue;
        let minOrb = null;
        for (let j = 0; j < waves.length; j++) {
          const o = parseFloat(waves[j].minOrb);
          if (Number.isFinite(o) && (minOrb == null || o < minOrb)) minOrb = o;
        }
        if (minOrb != null && minOrb <= orbMax) {
          if (best == null || minOrb < best.orb) {
            best = { aspect: ALL_ASP[i], orb: minOrb, target: tgt, attacker: att };
          }
        }
      }
    }
    return best;
  }

  const bestJup = _bestLent("Jupiter", JUP_TARGETS, 1.5);
  const bestSat = _bestLent("Saturne", SAT_TARGETS, 2.5);

  if (!bestJup && !bestSat) return null;

  // Confirmation profession-mariage
  const prof = payload._profections;
  let profMariage = false;
  let profMode = null;
  if (prof && prof.annuelle) {
    const phM = prof.annuelle.maison;
    const phS = prof.annuelle.maison_seigneur;
    const phLord = prof.annuelle.seigneur;
    if (MARIAGE_HOUSES.indexOf(phM) >= 0) { profMariage = true; profMode = "direct_M" + phM; }
    else if (MARIAGE_HOUSES.indexOf(phS) >= 0) { profMariage = true; profMode = "lord_in_M" + phS; }
    else if (VENUS_NAMES.indexOf(phLord) >= 0) { profMariage = true; profMode = "lord_is_Venus"; }
  }

  const hasBoth = !!(bestJup && bestSat);
  const tightOrb = (bestJup && bestJup.orb <= 0.2) && (bestSat && bestSat.orb <= 0.5);
  // Strong = bilatéral + profession mariage + Jupiter ULTRA partile (≤ 0.2°)
  // ET Saturne partile (≤ 0.5°). Plus strict qu'AV.A car les transits
  // Jupiter sur Lune/Vénus/DSC/Lot Mariage sont relativement fréquents
  // (cycle ~12 ans), donc on filtre serré pour éviter les faux positifs.
  const strong = hasBoth && profMariage && tightOrb;
  const mediumRaw = hasBoth && profMariage && !strong;

  return {
    strong: strong,
    mediumRaw: mediumRaw,
    hasBoth: hasBoth,
    profMariage: profMariage,
    profMode: profMode,
    jupiter: bestJup,
    saturne: bestSat,
