  // Audit V1 (calque MARIAGE) : régression -1.3 pp TOP5 BLOC A à cause
  // de 4 cas (baldwin/piaf/minnelli/tiger) où Jup+Sat partile sur Lune
  // déclenchait strong sur des années non-enfant. V2 exige une cible
  // parentale spécifique pour valider strong.
  const PARENT_SPECIFIC_TARGETS = ["Cérès", "Ceres", "Lot des Enfants", "Lot d'Enfant"];
  const PARENT_SPECIFIC_SET = new Set(PARENT_SPECIFIC_TARGETS);
  const ENFANT_LORDS = ["Vénus", "Venus", "Lune", "Jupiter"];

  let evY = null;
  if (eventDate) {
    const m = /^(\d{4})/.exec(String(eventDate));
    if (m) evY = parseInt(m[1], 10);
  }

  function _bestLent(att, tgts, orbMax) {
    let best = null;
    for (let t = 0; t < tgts.length; t++) {
      const tgt = tgts[t];
      if (!nd[tgt] && tgt !== "Ascendant" && tgt !== "Descendant") continue;
      for (let i = 0; i < ALL_ASP.length; i++) {
        const k = "slow_" + att + "|||" + ALL_ASP[i] + "|||" + tgt;
        const e = lent[k];
        if (!e || !Array.isArray(e.waves) || !e.waves.length) continue;
        let waves = e.waves;
        if (evY != null) {
          const filt = [];
          for (let j = 0; j < waves.length; j++) {
            const w = waves[j];
            const dat = String(w.peakDate || w.start || "");
            if (!dat) continue;
            const yr = parseInt(dat.slice(0, 4), 10);
