          if (Number.isFinite(o) && (minOrb == null || o < minOrb)) minOrb = o;
        }
        if (minOrb != null && minOrb <= orbMax) {
          if (best == null || minOrb < best.orb) {
            best = { aspect: ALL_ASP[i], orb: minOrb, target: tgt, attacker: att };
          }
        }
      }
    }
    return best;
  }

  const bestJup = _bestLent("Jupiter", JUP_TARGETS, 1.5);
  const bestSat = _bestLent("Saturne", SAT_TARGETS, 2.5);

  if (!bestJup && !bestSat) return null;

  // Profession-enfant restreinte (V2 calibration) : on retire les modes
