  // discrimine ENFANT vs un Jupiter+Saturne générique sur Lune/Vénus
  // (qui peut être mariage, séparation, deuil, etc.).
  const jupOnParent = !!(bestJup && PARENT_SPECIFIC_SET.has(bestJup.target));
  const satOnParent = !!(bestSat && PARENT_SPECIFIC_SET.has(bestSat.target));
  const hasBoth = !!(bestJup && bestSat);
  const tightOrb = (bestJup && bestJup.orb <= 0.2) && (bestSat && bestSat.orb <= 0.5);

