  //   • [Jup partile sur Cérès/Lot ≤ 0.2°] + [Sat ≤ 0.5° sur tout target]
  //   • [Sat partile sur Cérès/Lot ≤ 0.2°] + [Jup ≤ 1.5° sur tout target]
  //   • [Sat ULTRA-partile sur Cérès/Lot ≤ 0.1°] seul (sans Jupiter requis)
  //     — couvre kidman 2008 (Sat Carré Lot Enfants 0.02°, Jup à 2.33°
  //     hors orbe strict).
  const clauseA = jupOnParent && bestJup.orb <= 0.2 && bestSat && bestSat.orb <= 0.5;
  const clauseB = satOnParent && bestSat.orb <= 0.2 && bestJup && bestJup.orb <= 1.5;
  const clauseC = satOnParent && bestSat.orb <= 0.1;
  const strongPattern = clauseA || clauseB || clauseC;
  const strong = profEnfant && strongPattern;
  const mediumRaw = hasBoth && profEnfant && !strong;

  return {
    strong: strong,
    mediumRaw: mediumRaw,
    hasBoth: hasBoth,
    profEnfant: profEnfant,
    profMode: profMode,
    jupiter: bestJup,
    saturne: bestSat,
    tightOrb: tightOrb,
    parentSpecific: jupOnParent || satOnParent,
    clause: clauseA ? "A" : clauseB ? "B" : clauseC ? "C" : null
  };
}

