// Note 289 (Sprint AV.E — signal natal RELOCATION / pattern "axe IC ou
// Lot de Voyage activé + profession-mouvement + Mars/Mercure partile
// sur Asc/IC")
// ────────────────────────────────────────────────────────────────────
// Audit doctrinal des 2 cas RELOCATION primary miss en top5 baseline-150
// (kissinger 1938 émigration USA fuite Reich, julia-child 1948 relocation
// Paris) → pattern doctrinal triple cumulé :
//
//   1. Cible doctrinale activée (OU exclusif) :
//      (a) Transit lent partile (≤ 0.5°) Saturne/Pluton/Uranus en aspect
//          dur (Conj/Carré/Opp) sur **IC** natal — déracinement /
//          transformation radicale du foyer.
//      (b) Transit (≤ 1.0°) Jupiter/Saturne/Mars/Uranus tout aspect sur
//          **Lot de Voyage** natal — lot doctrinal explicite activé.
//   2. Profession-mouvement : annuelle dans M3 (voyage court) / M4
//      (foyer/déracinement) / M9 (étranger) OU seigneur natal de
//      l'année habite M3/M4/M9.
//   3. Confirmation Mars OU Mercure partile (≤ 0.5°) sur **Ascendant**
//      natal OU **IC** natal — action de déplacement physique active.
//
// Doctrine : RELOCATION = mouvement physique du natif. L'axe IC (racines)
// activé par transit lent indique transformation du foyer. Lot de Voyage
// activé = voyage doctrinal explicite. Profession M3/M4/M9 = thème
// dominant de l'année. Mars/Mercure sur Asc/IC = déplacement effectif.
//
// Couverture V1 :
//   • kissinger 1938 : Jup Carré Lot Voyage 0° + direct_M3 + Mars Conj
//     Asc 0.06° → strong via cible (b)
//   • julia-child 1948 : Sat Conj IC 0.01° + Pluton Conj IC 0.01° +
//     lord_in_M4 (Vénus seigneur en M4) + Mars Carré Asc 0.01° + Mars
//     Trig IC 0.02° → strong via cible (a)
//
// PROD-safe : self-contained, pas de process/require/console.error.
function _phxRelocationSignals(payload, eventDate) {
  if (!payload || typeof payload !== "object") return null;
  const nd = payload._natalDict || {};
  const lent = payload._aspectsSuiviLent || {};

  const ALL_ASP = ["Conjonction", "Carré", "Carre", "Opposition", "Trigone", "Sextile"];
  const HARD_ASP = ["Conjonction", "Carré", "Carre", "Opposition"];
  const RELOC_HOUSES = [3, 4, 9];

  let evY = null;
  if (eventDate) {
    const m = /^(\d{4})/.exec(String(eventDate));
    if (m) evY = parseInt(m[1], 10);
  }

  function _filterYear(waves) {
    if (evY == null) return waves;
    const out = [];
    for (let j = 0; j < waves.length; j++) {
      const w = waves[j];
      const dat = String(w.peakDate || w.start || "");
      if (!dat) continue;
      const yr = parseInt(dat.slice(0, 4), 10);
      if (Number.isFinite(yr) && Math.abs(yr - evY) <= 1) out.push(w);
    }
    return out;
  }

  // Best hit pour un (attacker, target) couple sur un set d'aspects donné.
  function _bestLent(att, tgt, aspects, orbMax) {
    let best = null;
    for (let i = 0; i < aspects.length; i++) {
      const k = "slow_" + att + "|||" + aspects[i] + "|||" + tgt;
      const e = lent[k];
      if (!e || !Array.isArray(e.waves) || !e.waves.length) continue;
      const waves = _filterYear(e.waves);
      if (!waves.length) continue;
      let minOrb = null;
      for (let j = 0; j < waves.length; j++) {
        const o = parseFloat(waves[j].minOrb);
        if (Number.isFinite(o) && (minOrb == null || o < minOrb)) minOrb = o;
      }
      if (minOrb != null && minOrb <= orbMax) {
        if (best == null || minOrb < best.orb) {
          best = { aspect: aspects[i], orb: minOrb, target: tgt, attacker: att };
        }
      }
    }
    return best;
  }

  // (a) Saturne/Pluton/Uranus en aspect dur partile sur IC.
  let bestAxe = null;
  const HEAVY = ["Saturne", "Pluton", "Uranus"];
  for (let i = 0; i < HEAVY.length; i++) {
    const h = _bestLent(HEAVY[i], "Imum Coeli", HARD_ASP, 0.5);
    if (h && (bestAxe == null || h.orb < bestAxe.orb)) bestAxe = h;
  }

  // (b) Jupiter/Saturne/Mars/Uranus sur Lot de Voyage (tout aspect, ≤ 1°)
  let bestLot = null;
  if (nd["Lot de Voyage"]) {
    const LOT_ATT = ["Jupiter", "Saturne", "Mars", "Uranus"];
    for (let i = 0; i < LOT_ATT.length; i++) {
      const h = _bestLent(LOT_ATT[i], "Lot de Voyage", ALL_ASP, 1.0);
      if (h && (bestLot == null || h.orb < bestLot.orb)) bestLot = h;
    }
  }

  // Profession-mouvement
  const prof = payload._profections;
  let profReloc = false;
  let profMode = null;
  if (prof && prof.annuelle) {
    const phM = prof.annuelle.maison;
    const phS = prof.annuelle.maison_seigneur;
    if (RELOC_HOUSES.indexOf(phM) >= 0) { profReloc = true; profMode = "direct_M" + phM; }
    else if (RELOC_HOUSES.indexOf(phS) >= 0) { profReloc = true; profMode = "lord_in_M" + phS; }
  }

  // Confirmation Mars OU Mercure partile sur Ascendant OU IC.
  let bestActor = null;
  const ACT_ATT = ["Mars", "Mercure"];
  const ACT_TGT = ["Ascendant", "Imum Coeli"];
  for (let i = 0; i < ACT_ATT.length; i++) {
    for (let j = 0; j < ACT_TGT.length; j++) {
      const h = _bestLent(ACT_ATT[i], ACT_TGT[j], ALL_ASP, 0.5);
      if (h && (bestActor == null || h.orb < bestActor.orb)) bestActor = h;
    }
  }

  const cibleOk = !!(bestAxe || bestLot);
  const strong = cibleOk && profReloc && !!bestActor;

  if (!cibleOk && !bestActor) return null;

  // Distinction de la source pour traçabilité
  let cibleSource = null;
  if (bestAxe) cibleSource = "axe_IC";
  else if (bestLot) cibleSource = "lot_voyage";

  const tightOrb = (bestAxe && bestAxe.orb <= 0.2) || (bestLot && bestLot.orb <= 0.2);

  return {
    strong: strong,
    cibleOk: cibleOk,
    cibleSource: cibleSource,
    profReloc: profReloc,
    profMode: profMode,
    axe: bestAxe,
    lot: bestLot,
    actor: bestActor,
    tightOrb: tightOrb
  };
}

