//     projeté sur Asc, méthode hellénistique) : lot afflictionné par
//     les maléfiques en partile = signature spécifique de morbidité.
//   - Firmicus, Mathesis IV.11 (sur la VI°) : ennemis intérieurs, mala-
//     dies. Astre maléfique en VI° natale dynamisé par profection M6
//     = activation.
//   - Ebertin, Combination p. 188-192 (Sun-Pluto, Moon-Pluto,
//     Ascendant-Pluto) : "tumeurs, cancers, profondes transformations
//     physiques par maladie". Sol-Uranus (p. 184) : "ruptures
//     nerveuses brutales, diagnostic soudain" (Parkinson, AVC).
//     Mars-Pluton (p. 186) : "blessures violentes, interventions
//     chirurgicales lourdes".
//   - Reinhold, "Krankheit und Heilung" : confirme Pluton/Asc comme
//     marqueur de cancer dans le pronostic moderne sourcé.
//
// PROD-safe : self-contained, pas de process/require/console.error.
function _phxSanteDownSignals(payload, eventDate) {
  if (!payload || typeof payload !== "object") return null;
  const lent = payload._aspectsSuiviLent || {};
  const lords = payload._houseLords || {};
  const prof = payload._profections || {};

  const HARD = ["Conjonction", "Carré", "Carre", "Opposition"];

  let evY = null;
  if (eventDate) {
    const m = /^(\d{4})/.exec(String(eventDate));
    if (m) evY = parseInt(m[1], 10);
  }

  function _filterYear(waves) {
    if (evY == null) return waves;
    const out = [];
    for (let j = 0; j < waves.length; j++) {
      const w = waves[j];
      const dat = String(w.peakDate || w.start || "");
      if (!dat) continue;
      const yr = parseInt(dat.slice(0, 4), 10);
      if (Number.isFinite(yr) && Math.abs(yr - evY) <= 1) out.push(w);
    }
    return out;
  }

  function _bestHard(att, tgt, orbMax) {
    if (!tgt) return null;
    let best = null;
    for (let i = 0; i < HARD.length; i++) {
      const k = "slow_" + att + "|||" + HARD[i] + "|||" + tgt;
      const e = lent[k];
      if (!e || !Array.isArray(e.waves) || !e.waves.length) continue;
      const waves = _filterYear(e.waves);
      if (!waves.length) continue;
      let minOrb = null;
      for (let j = 0; j < waves.length; j++) {
        const o = parseFloat(waves[j].minOrb);
        if (Number.isFinite(o) && (minOrb == null || o < minOrb)) minOrb = o;
      }
      if (minOrb != null && minOrb <= orbMax) {
        if (best == null || minOrb < best.orb) best = { aspect: HARD[i], orb: minOrb, target: tgt, attacker: att };
      }
    }
    return best;
  }

  function _bestAttSetOnTargets(attSet, targets, orbMax) {
    let best = null;
    for (let i = 0; i < attSet.length; i++) {
      for (let j = 0; j < targets.length; j++) {
        const h = _bestHard(attSet[i], targets[j], orbMax);
        if (h && (best == null || h.orb < best.orb)) best = h;
      }
    }
    return best;
  }

  const lordM1 = lords[1] && lords[1].maitre || null;
  const lordM6 = lords[6] && lords[6].maitre || null;
  const lordM8 = lords[8] && lords[8].maitre || null;
  const lordM12 = lords[12] && lords[12].maitre || null;

  const phMaison = prof && prof.annuelle ? prof.annuelle.maison : null;
  const phLordIn = prof && prof.annuelle ? prof.annuelle.maison_seigneur : null;
  const phLord = prof && prof.annuelle ? prof.annuelle.seigneur : null;

  // Profession SANTE V2 : restriction à M6 direct UNIQUEMENT (maison
  // spécifique des maladies courantes, Lilly III "Of the Sixth House").
  // M8 / M12 retirés car trop larges (M8 = mort autrui/héritage/sexe ;
  // M12 = exil/épreuves cachées). seigneur=Maître_vital retiré car
  // sémantiquement trop générique.
  let profMode = null;
  if (phMaison === 6) profMode = "direct_M6";
  else if (phLordIn === 6) profMode = "lord_in_M6";

  // Cibles vitales pour clause A
  const VITAL_TGTS = ["Soleil", "Lune", "Ascendant", "Lot de Maladie"];
  if (lordM1) VITAL_TGTS.push(lordM1);
  if (lordM6) VITAL_TGTS.push(lordM6);
  if (lordM8) VITAL_TGTS.push(lordM8);

  // Clause A — Profession M6 spécifique + Sat/Mars dur partile (≤ 0.5°) sur cibles vitales
  let hitA = null;
  if (profMode) {
    hitA = _bestAttSetOnTargets(["Saturne", "Mars"], VITAL_TGTS, 0.5);
  }

  // Clause B — Compound moderne AUTONOME (sans profession requise) :
  // Pluton OR Uranus dur partile (≤ 0.3°) sur Asc/Sol/Lun.
  // Source : Ebertin "Kombination der Gestirneinflüsse" (Pluton/Sol ou
  // Asc = cancer ; Uranus/Asc = diagnostic brutal).
  const hitB = _bestAttSetOnTargets(["Pluton", "Uranus"], ["Soleil", "Lune", "Ascendant"], 0.3);

  // Clause C — Compound Saturne+Mars ULTRA-partile (sans profession requise)
  // Saturne ≤ 0.1° sur Sol/Lun ET Mars ≤ 0.2° sur Asc/Maître M1/Lot Maladie
  let hitC = null;
  const cSat = _bestAttSetOnTargets(["Saturne"], ["Soleil", "Lune"], 0.1);
  if (cSat) {
    const corpsTgts = ["Ascendant", "Lot de Maladie"];
    if (lordM1) corpsTgts.push(lordM1);
    const cMars = _bestAttSetOnTargets(["Mars"], corpsTgts, 0.2);
    if (cMars) hitC = { sat: cSat, mars: cMars };
  }

  const strong = !!(hitA || hitB || hitC);
  if (!strong) return null;

  // Source dominante (priorité A > B > C)
  let source = null;
  if (hitA) source = "A_profession_" + profMode;
  else if (hitB) source = "B_compound_modern_" + profMode;
  else if (hitC) source = "C_compound_lum_corps";

  const main = hitA || hitB || (hitC && hitC.sat);
  const tightOrb = main && main.orb <= 0.1;

  return {
    strong: true,
    source: source,
    A: hitA, B: hitB, C: hitC,
    tightOrb: !!tightOrb
  };
}

// ────────────────────────────────────────────────────────────────────
// Note 293 (Pipeline AV — enrichissement payload avec arcs solaires
// Naibod pour usage helpers AV / sprints AV.D, AV.E, AV.H et suivants)
// ────────────────────────────────────────────────────────────────────
// Doctrine : les Arcs Solaires (méthode Naibod, 0°59'08" par jour ≈
// 0.9856°/an) sont la technique de prévision la plus standard pour
// extraire la « promesse natale active » à une année donnée. Ptolémée
// Tetrabiblos III.10 utilise les Directions Primaires (mouvement diurne)
// ; les Arcs Solaires en sont la version simplifiée et symétrique pour
// tous les corps célestes natals.
//
// Le pipeline n8n calcule déjà _primaryDirections (Placidus mundane)
// mais limité à ~4 hits par cas (principalement promissor planète vs
// significateur angle). Pour discriminer les codes intrinsèquement
// non-discriminants par transits seuls (FINANCE_UP AV.D, RELOCATION
// AV.E, CARRIERE_DOWN AV.H), il faut une couverture étendue à :
//   • Tous les promissors mobiles (10 planètes + Asc + MC)
//   • Tous les significateurs fixes (planètes + angles + Lots + Maîtres)
//
// Cet helper calcule en pur JS, PROD-safe, tous les arcs Naibod à
// l'âge événement (orbe ≤ 1.0° = ±1 an symbolique) et stocke le
// résultat sur payload._phxArcHits indexé par "arc_PROM|||ASPECT|||SIG".
//
// PROD-safe : Math seulement, pas de process/require/console.error.
function _phxComputeNatalArcHits(payload) {
  if (!payload || typeof payload !== "object") return {};
  const nd = payload._natalDict || {};
  const lords = payload._houseLords || {};

  const age = (payload.progressionsRaw && typeof payload.progressionsRaw.age === "number")
    ? payload.progressionsRaw.age
    : (payload._profections && typeof payload._profections.age === "number" ? payload._profections.age : null);
  if (age == null || age <= 0 || age > 120) return {};

  // Naibod : arc solaire moyen 360°/365.2422 jours ≈ 0.985647°/jour
  // (Naibod 1574, "Enarratio elementorum astrologiae"). En âge symbolique
  // = 1 jour de vie après naissance = 1 année d'âge. Donc arc(t) en
  // années = t × 0.985647° par année écoulée.
  const RATE = 360 / 365.2422;

  const ASPECTS = [
    { name: "Conjonction", deg: 0 },
    { name: "Sextile", deg: 60 },
    { name: "Carré", deg: 90 },
    { name: "Trigone", deg: 120 },
    { name: "Opposition", deg: 180 }
  ];

  const PROMISSORS = ["Soleil", "Lune", "Mercure", "Vénus", "Mars", "Jupiter",
                       "Saturne", "Uranus", "Neptune", "Pluton",
                       "Ascendant", "Milieu du Ciel"];

  const BASE_SIG = ["Soleil", "Lune", "Mercure", "Vénus", "Mars", "Jupiter",
                     "Saturne", "Uranus", "Neptune", "Pluton",
                     "Ascendant", "Milieu du Ciel", "Imum Coeli", "Descendant",
                     "Lot de la Fortune", "Lot de l'Esprit", "Lot de Basis",
                     "Lot du Père", "Lot de la Mère", "Lot du Mariage",
                     "Lot des Enfants", "Lot de Maladie", "Lot de Voyage"];

  // Ajouter Maîtres natals (déduplication)
  const SIG_SET = new Set(BASE_SIG);
  for (let h = 1; h <= 12; h++) {
    if (lords[h] && lords[h].maitre) SIG_SET.add(lords[h].maitre);
  }

  const ORB_YEARS_MAX = 1.0;
  const hits = {};

  for (let i = 0; i < PROMISSORS.length; i++) {
    const pName = PROMISSORS[i];
    const pEnt = nd[pName];
    if (!pEnt || typeof pEnt.deg !== "number") continue;
    const pDeg = pEnt.deg;

    for (const sName of SIG_SET) {
      if (sName === pName) continue;
      const sEnt = nd[sName];
      if (!sEnt || typeof sEnt.deg !== "number") continue;
      const sDeg = sEnt.deg;

      // baseDist = (sigDeg - promDeg) mod 360, distance que doit
      // parcourir le promissor (par arc symbolique direct) pour atteindre
      // la conjonction du significateur.
      let baseDist = ((sDeg - pDeg) % 360 + 360) % 360;

      for (let a = 0; a < ASPECTS.length; a++) {
        const aspect = ASPECTS[a];
        // Pour chaque aspect, 2 solutions possibles (sens + et −).
        for (let s = 0; s < 2; s++) {
          const sign = s === 0 ? 1 : -1;
          let arcNeeded = (baseDist + sign * aspect.deg) % 360;
          if (arcNeeded < 0) arcNeeded += 360;
          const agePerfect = arcNeeded / RATE;
          if (agePerfect > 120) continue;
          const orbYears = Math.abs(agePerfect - age);
          if (orbYears > ORB_YEARS_MAX) continue;
          const orbDeg = orbYears * RATE;

          const key = "arc_" + pName + "|||" + aspect.name + "|||" + sName;
          if (!hits[key] || hits[key].orbDeg > orbDeg) {
            hits[key] = {
              promissor: pName,
              significator: sName,
              aspect: aspect.name,
              agePerfect: Math.round(agePerfect * 100) / 100,
              orbYears: Math.round(orbYears * 1000) / 1000,
              orbDeg: Math.round(orbDeg * 1000) / 1000,
              direction: sign > 0 ? "directe" : "converse"
            };
            // Pour Conj (deg 0) et Opp (deg 180), les 2 directions
            // donnent le même résultat → on n'a pas à dédupliquer car
            // la condition orbDeg garde la meilleure.
          }
        }
      }
    }
  }

  return hits;
}

// Helper de lecture pour les helpers AV : trouve le meilleur hit ARC
// pour un (promissor, aspect, significator) donné, ou null si absent.
function _phxBestArcHit(payload, promissor, aspect, significator, orbDegMax) {
  if (!payload || !payload._phxArcHits) return null;
  const key = "arc_" + promissor + "|||" + aspect + "|||" + significator;
  const h = payload._phxArcHits[key];
  if (!h) return null;
  if (typeof orbDegMax === "number" && h.orbDeg > orbDegMax) return null;
  return h;
}

// ────────────────────────────────────────────────────────────────────
// Note 301 (Sprint B.1 — Helper utilitaire : score de dignité essentielle)
// ────────────────────────────────────────────────────────────────────
// Convertit l'étiquette de dignité majeure exposée par MDSE (string
// "Domicile" / "Exaltation" / "Triplicité" / "Pérégrin" / "Exil" / "Chute"
// stockée dans natalDict[planète].dignite, calculée par getDignite() côté
// FRA/PREV/N8N Prev) en SCORE NUMÉRIQUE pondéré selon la table classique
// Lilly CA III ch. 12 "Of Essential Dignities" :
//   • Domicile (Rulership)    : +5  → strong
//   • Exaltation              : +4  → strong
//   • Triplicité              : +3  → strong
//   • Terme (Bound)           : +2  [pas dispo via natalDict.dignite simple]
//   • Face (Decanate)         : +1  [pas dispo via natalDict.dignite simple]
//   • Pérégrin                :  0  → ambivalent (ni fort ni faible)
//   • Chute (Fall)            : -4  → weak
//   • Exil (Detriment)        : -5  → weak
//
// SOURCES :
//   - Lilly, Christian Astrology III ch. 12 "Of Essential Dignities" :
//     table classique +5/+4/+3/+2/+1/-4/-5 (anglo-saxon, post-Bonatti).
//   - Bonatti, De Astronomia tract. 3 ch. 5 "De fortitudinibus et
//     debilitatibus essentialibus" : même table en latin médiéval.
//   - Morin, Astrologia Gallica XVI (Determinatio) : "la dignité
//     essentielle du significateur qualifie l'effet" — dignifié = effet
//     en bien, débilité = effet en mal.
//   - Dykes (Bonatti tr., Cazimi Press 2007) : table normalisée
//     reprise dans toute l'astrologie traditionnelle moderne.
//   - Brennan, "Hellenistic Astrology" ch. 8 (sur les sect, dignités,
//     et leur fonction de modulation prédictive).
//
// USAGE DOCTRINAL : levée d'ambivalence MAL_HARD ARC sur Hyleg (cf.
// note 285bis archivée pour AV.A CARRIERE_UP route α). Bonatti DA
// tract. 8 et Morin AG XXIII : une direction MAL_HARD sur le Soleil
// ou MC signifie CONSÉCRATION si le Sol/MC est dignifié (score ≥ +3),
// DESTITUTION si débilité (score ≤ -4), ambivalent sinon (pérégrin).
//
// PROD-safe : self-contained, pas de process/require/console.error.
function _phxDigniteEssentielleScore(natalDict, planetName) {
  const NA = { score: 0, label: "indisponible", isStrong: false, isWeak: false, isAmbivalent: true };
  if (!natalDict || typeof natalDict !== "object") return NA;
  const ent = natalDict[planetName];
  if (!ent || typeof ent.dignite !== "string") return NA;
  const dig = ent.dignite.trim();
  if (/^domicile$/i.test(dig) || /^rulership$/i.test(dig))
    return { score: 5, label: "domicile", isStrong: true, isWeak: false, isAmbivalent: false };
  if (/^exaltation$/i.test(dig))
    return { score: 4, label: "exaltation", isStrong: true, isWeak: false, isAmbivalent: false };
  if (/^triplicit[ée]$/i.test(dig) || /^triplicity$/i.test(dig))
    return { score: 3, label: "triplicite", isStrong: true, isWeak: false, isAmbivalent: false };
  if (/^terme$/i.test(dig) || /^bound$/i.test(dig) || /^term$/i.test(dig))
    return { score: 2, label: "terme", isStrong: false, isWeak: false, isAmbivalent: false };
  if (/^face$/i.test(dig) || /^decanate$/i.test(dig) || /^d[ée]can/i.test(dig))
    return { score: 1, label: "face", isStrong: false, isWeak: false, isAmbivalent: false };
  if (/^p[ée]r[ée]grin$/i.test(dig) || /^peregrin/i.test(dig))
    return { score: 0, label: "peregrin", isStrong: false, isWeak: false, isAmbivalent: true };
  if (/^chute$/i.test(dig) || /^fall$/i.test(dig))
    return { score: -4, label: "chute", isStrong: false, isWeak: true, isAmbivalent: false };
  if (/^exil$/i.test(dig) || /^d[ée]triment$/i.test(dig) || /^detriment$/i.test(dig))
    return { score: -5, label: "exil", isStrong: false, isWeak: true, isAmbivalent: false };
  return { score: 0, label: "inconnu:" + dig, isStrong: false, isWeak: false, isAmbivalent: true };
}

// Helper composé : dignité combinée Soleil + Maître MC (significateurs
// solaires de la carrière selon Bonatti DA tract. 8 et Lilly CA III
// "Of the Tenth House"). Retourne le score MAX (effet bénéfique
// dominant si l'un OU l'autre est dignifié) et le score MIN (effet
// maléfique dominant uniquement si LES DEUX sont débilités).
function _phxDigniteSolMC(payload) {
  if (!payload || typeof payload !== "object") return null;
  const nd = payload._natalDict || {};
  const lords = payload._houseLords || {};
  const sol = _phxDigniteEssentielleScore(nd, "Soleil");
  const maitreM10 = (lords[10] && lords[10].maitre) ? lords[10].maitre : null;
  const mc = maitreM10 ? _phxDigniteEssentielleScore(nd, maitreM10) : null;
  const hasMC = !!(mc && mc.label !== "indisponible");
  const scoreMax = hasMC ? Math.max(sol.score, mc.score) : sol.score;
  const scoreMin = hasMC ? Math.min(sol.score, mc.score) : sol.score;
  return {
    soleil: sol,
    maitreM10: maitreM10,
    maitreM10Dignite: mc,
    scoreMax: scoreMax,
    scoreMin: scoreMin,
    // Doctrinalement "consécration" : au moins l'un des deux significateurs
    // solaires/carrière est en dignité majeure (triplicité+).
    isStrong: scoreMax >= 3,
    // "Destitution" claire : LES DEUX en débilité (chute/exil). Convention
    // prudente (Morin AG XVI : "ad significandum malum, debilitates
    // confirmatoriae requiruntur").
    isWeak: hasMC ? (sol.score <= -4 && mc.score <= -4) : (sol.score <= -4),
    // Ambivalent : ni fort ni clairement faible (Pérégrin, mixte, etc.).
    isAmbivalent: !(scoreMax >= 3) && !(hasMC ? (sol.score <= -4 && mc.score <= -4) : (sol.score <= -4))
  };
}

// ────────────────────────────────────────────────────────────────────
// Note 302 (Sprint B.2 — Helper utilitaire : DP actives pour event_date)
// ────────────────────────────────────────────────────────────────────
// Filtre les Directions Primaires (déjà calculées par MDSE bloc P42
// ligne ~5954, exposées via payload._mdsePrimaryDirections) actives au
// moment d'event_date. MDSE pré-calcule l'orbe en années (orbYears) et
// en degrés (orbDeg) à mi-période, en gardant uniquement les DP dont
// |exactAge - âgeEvent| ≤ 1 an.
//
// Système utilisé par MDSE : semi-arc équatorial avec clé Naibod
// (0.9856°/an), ascension droite (RA) pour MC/IC, ascension oblique
// (OA) pour Asc/Sol/Lune au pôle géographique du natal, descension
// oblique (OD) pour DSC. C'est doctrinalement proche du Régiomontanus
// (pôle géographique constant) — pas du Placidus mundane strict
// (qui utilise un pôle propre à chaque promissor) mais accepté par
// la tradition (Lilly CA III "Of Directions" utilise les directions
// équatoriales sous le pôle natal).
//
// SOURCES :
//   - Ptolémée, Tetrabiblos III.10-14 (athla / aphesis) : les
//     directions primaires comme mode prédictif majeur, mesurant
//     la durée jusqu'à la rencontre par mouvement diurne.
//   - Lilly, Christian Astrology III "Of Directions" : "Direction
//     is the bringing of the Promittor unto the Significator by the
//     motion of the Primum Mobile" (chap. dédié, ~p. 645).
//   - Morin, Astrologia Gallica XXIII : "directiones agunt, transitus
//     excitant" — les DP causent les événements, les transits les
//     déclenchent.
//   - Bonatti, De Astronomia tract. 8 (de directionibus) : MAL dur
//     en DP sur Hyleg = mutation profonde du statut.
//   - Naibod, Enarratio elementorum astrologiae (1574) : clé arc
//     solaire moyen 360°/365.2422 ≈ 0.9856°/an, retenue par la
//     tradition pour la conversion arc → temps.
//
// USAGE DOCTRINAL : AV.H CARRIERE_DOWN (DP partile Mars/Sat/Plut sur
// Maître M10 = chute professionnelle, cf. Lilly CA III "Of the Tenth
// House"). Filtre orbDegMax (typiquement 0.3° = ≈ 110 jours d'arc
// Naibod) pour ne retenir que les DP doctrinalement partiles à
// event_date, conformément au principe de Morin (orbes serrés pour
// les DP, larges pour les transits).
//
// PROD-safe : self-contained, pas de process/require/console.
function _phxDPActivesPourEvent(payload, eventDate, opts) {
  if (!payload || typeof payload !== "object") return [];
  const dps = payload._mdsePrimaryDirections;
  if (!Array.isArray(dps) || !dps.length) return [];
  const orbDegMax = (opts && typeof opts.orbDegMax === "number") ? opts.orbDegMax : 0.3;
  const orbYearsMax = (opts && typeof opts.orbYearsMax === "number") ? opts.orbYearsMax : 0.5;
  const out = [];
  for (let i = 0; i < dps.length; i++) {
    const dp = dps[i];
    if (!dp) continue;
    const od = (typeof dp.orbDeg === "number") ? dp.orbDeg : null;
    const oy = (typeof dp.orbYears === "number") ? dp.orbYears : null;
    if ((od !== null && od <= orbDegMax) || (oy !== null && oy <= orbYearsMax)) {
      out.push(dp);
    }
  }
  out.sort((a, b) => {
    const oa = (typeof a.orbDeg === "number") ? a.orbDeg : (typeof a.orbYears === "number" ? a.orbYears : 999);
    const ob = (typeof b.orbDeg === "number") ? b.orbDeg : (typeof b.orbYears === "number" ? b.orbYears : 999);
    return oa - ob;
  });
  return out;
}

// Recherche ciblée : meilleure DP partile (orbe minimal) où
// promissor ∈ promissorList, aspect ∈ aspectList, significator ∈ significatorList.
// Retourne null si aucune match. Les listes peuvent être string ou array.
// Note normalisation : Carré accepte aussi "Carre" (variante orthographique
// utilisée par certains nodes MDSE).
function _phxBestDPHit(payload, promissorList, aspectList, significatorList, opts) {
  const dps = _phxDPActivesPourEvent(payload, null, opts);
  if (!dps.length) return null;
  const proms = Array.isArray(promissorList) ? promissorList : [promissorList];
  const asps = Array.isArray(aspectList) ? aspectList : [aspectList];
  const sigs = Array.isArray(significatorList) ? significatorList : [significatorList];
  const normAsp = (a) => /^carr[eé]$/i.test(a) ? ["Carré", "Carre"] : [a];
  const aspsExp = [];
  for (let i = 0; i < asps.length; i++) {
    const variants = normAsp(asps[i]);
    for (let j = 0; j < variants.length; j++) aspsExp.push(variants[j]);
  }
  for (let i = 0; i < dps.length; i++) {
    const dp = dps[i];
    if (!dp) continue;
    if (proms.indexOf(dp.promissor) < 0) continue;
    if (aspsExp.indexOf(dp.aspect) < 0) continue;
    if (sigs.indexOf(dp.significator) < 0) continue;
    return dp;
  }
  return null;
}

// ────────────────────────────────────────────────────────────────────
// Note 303 (Sprint B-full — profection mensuelle à event_date)
// ────────────────────────────────────────────────────────────────────
// Calcule la maison profectée du MOIS de event_date (pas seulement le
// début de période MDSE dans profections.mensuelle). Requis pour AV.D
// FINANCE_UP (M2/M8 mensuelle) et AV.H V4 (M10/M12 mensuelle).
//
// Priorité : payload._profectionMensuelleEvent (cache post-build) si
// présent ; sinon calcul inline depuis _dateNaissance + _profections.
//
// Formule (cohérente MDSE P16 + L782-784 N8N Prev) :
//   decalage = (moisEvent - moisNaiss + 12) % 12
//   maisonMens = ((maisonAnn - 1) + decalage) % 12 + 1
//
// SOURCES : Valens Anthologies IV ; Paulus Alexandrinus ch. 29 ;
// Brennan "Hellenistic Astrology" ch. 9 (monthly profections).
//
// PROD-safe : self-contained, pas de process/require/fs.
function _phxParseDateFlex(s) {
  if (!s || typeof s !== "string") return null;
  const t = String(s).trim();
  const iso = /^(\d{4})-(\d{2})-(\d{2})/.exec(t);
  if (iso) {
    const d = new Date(parseInt(iso[1], 10), parseInt(iso[2], 10) - 1, parseInt(iso[3], 10));
    return isNaN(d.getTime()) ? null : d;
  }
  const fr = /^(\d{1,2})\/(\d{1,2})\/(\d{4})/.exec(t);
  if (fr) {
    const d = new Date(parseInt(fr[3], 10), parseInt(fr[2], 10) - 1, parseInt(fr[1], 10));
    return isNaN(d.getTime()) ? null : d;
  }
  const d = new Date(t);
  return isNaN(d.getTime()) ? null : d;
}

function _phxProfectionMensuelleAtEvent(payload, eventDate) {
  // V22 bypass — profections Brennan désactivées en mode V22 (cf. SPEC §1.4).
  // Couche temporelle reconstruite via Brady transits lents + Rushman cycles.
  if (DTC_V22_NO_PROFECTIONS) return null;
  if (!payload || typeof payload !== "object") return null;
  if (payload._profectionMensuelleEvent && typeof payload._profectionMensuelleEvent.maison === "number") {
    return payload._profectionMensuelleEvent;
  }
  const prof = payload._profections;
  const dateStr = payload._dateNaissance;
  if (!prof?.annuelle?.maison || !dateStr || !eventDate) return null;
  const dateNaiss = _phxParseDateFlex(dateStr);
  const evDate = _phxParseDateFlex(String(eventDate));
  if (!dateNaiss || !evDate) return null;
  const moisNaiss = dateNaiss.getMonth() + 1;
  const evMonth = evDate.getMonth() + 1;
  const maisonAnn = prof.annuelle.maison;
  const decalage = ((evMonth - moisNaiss + 12) % 12);
  const maisonMens = ((maisonAnn - 1 + decalage) % 12) + 1;
  const lords = payload._houseLords || {};
  const nd = payload._natalDict || {};
  const hl = lords[maisonMens];
  const seigneur = (hl && hl.maitre) ? hl.maitre : null;
  const ndSeig = seigneur ? nd[seigneur] : null;
  return {
    maison: maisonMens,
    signe_cuspide: (hl && hl.signe) ? hl.signe : null,
    seigneur: seigneur,
    maison_seigneur: (ndSeig && typeof ndSeig.house === "number") ? ndSeig.house : null,
    dignite: (ndSeig && ndSeig.dignite) ? ndSeig.dignite : null,
    mois_evenement: evMonth,
    decalage_mois: decalage
  };
}

