  if (!payload || typeof payload !== "object") return null;
  const lent = payload._aspectsSuiviLent || {};
  const lords = payload._houseLords || {};
  const prof = payload._profections || {};

  const HARD = ["Conjonction", "Carré", "Carre", "Opposition"];

  let evY = null;
  if (eventDate) {
    const m = /^(\d{4})/.exec(String(eventDate));
    if (m) evY = parseInt(m[1], 10);
  }

  function _filterYear(waves) {
    if (evY == null) return waves;
    const out = [];
    for (let j = 0; j < waves.length; j++) {
      const w = waves[j];
      const dat = String(w.peakDate || w.start || "");
      if (!dat) continue;
      const yr = parseInt(dat.slice(0, 4), 10);
      if (Number.isFinite(yr) && Math.abs(yr - evY) <= 1) out.push(w);
    }
    return out;
  }

  function _bestHard(att, tgt, orbMax) {
    if (!tgt) return null;
    let best = null;
    for (let i = 0; i < HARD.length; i++) {
      const k = "slow_" + att + "|||" + HARD[i] + "|||" + tgt;
      const e = lent[k];
      if (!e || !Array.isArray(e.waves) || !e.waves.length) continue;
      const waves = _filterYear(e.waves);
      if (!waves.length) continue;
      let minOrb = null;
      for (let j = 0; j < waves.length; j++) {
        const o = parseFloat(waves[j].minOrb);
        if (Number.isFinite(o) && (minOrb == null || o < minOrb)) minOrb = o;
      }
      if (minOrb != null && minOrb <= orbMax) {
        if (best == null || minOrb < best.orb) best = { aspect: HARD[i], orb: minOrb, target: tgt, attacker: att };
      }
    }
    return best;
  }

  function _bestAttSetOnTargets(attSet, targets, orbMax) {
    let best = null;
    for (let i = 0; i < attSet.length; i++) {
      for (let j = 0; j < targets.length; j++) {
        const h = _bestHard(attSet[i], targets[j], orbMax);
        if (h && (best == null || h.orb < best.orb)) best = h;
      }
    }
    return best;
  }

  const lordM10 = lords[10] && lords[10].maitre || null;
  const lordM12 = lords[12] && lords[12].maitre || null;

  const phMaison = prof && prof.annuelle ? prof.annuelle.maison : null;
  const phLordIn = prof && prof.annuelle ? prof.annuelle.maison_seigneur : null;
