  // honoris destructio Bonatti : Mars triple partile sur axe statut +
  // patronage natal = ruine d'honneur très spécifique (martha 2004).
  let hitA = null;
  const aMC = _bestHard("Mars", "Milieu du Ciel", 0.02);
  const aIC = _bestHard("Mars", "Imum Coeli", 0.02);
  const aJup = _bestHard("Mars", "Jupiter", 0.02);
  if (aMC && aIC && aJup) hitA = { mc: aMC, ic: aIC, jup: aJup };

  // Clause B — Compound saturnien/plutonien doctrinalement SPÉCIFIQUE :
  //   B1. Saturne dur partile (≤ 0.05°) sur Jupiter natal (Lilly :
  //       "perte de patronage durable" — winona 2002)
  //   B2. Pluton dur partile (≤ 0.05°) sur MC OU IC (Ebertin : axe
  //       carrière brisé par transformation forcée — gibson 2006)
  const b1 = _bestHard("Saturne", "Jupiter", 0.05);
  const b2 = _bestAttSetOnTargets(["Pluton"], ["Milieu du Ciel", "Imum Coeli"], 0.05);
  const hitB = b1 || b2;

  // Clause C — Profession carrière + signal classique (≤ 0.3°)
  let profMode = null;
  if (phMaison === 10) profMode = "direct_M10";
  else if (phMaison === 12) profMode = "direct_M12";
  else if (phLordIn === 10) profMode = "lord_in_M10";
  else if (phLordIn === 12) profMode = "lord_in_M12";
  else if (phLord && lordM10 && phLord === lordM10) profMode = "seigneur_eq_lordM10";

  let hitC = null;
  if (profMode) {
    const tgtC = ["Soleil", "Jupiter", "Milieu du Ciel", "Imum Coeli"];
    if (lordM10) tgtC.push(lordM10);
    hitC = _bestAttSetOnTargets(["Saturne", "Mars", "Pluton"], tgtC, 0.3);
  }

  const strong = !!(hitA || hitB || hitC);
  if (!strong) return null;

  let source = null;
  if (hitA) source = "A_mars_honoris";
  else if (hitB) source = "B_saturne_pluton_axe";
  else if (hitC) source = "C_profession_" + profMode;

  const main = (hitA && hitA.mc) || hitB || hitC;
  const tightOrb = main && main.orb <= 0.05;

  return {
    strong: true,
    source: source,
    A: hitA, B: hitB, C: hitC,
    tightOrb: !!tightOrb
  };
}

