    if (!e || !e.stackOk) continue;
    const fp = e.declencheurTop || e.marsJourJ || "";
    if (!fp) continue;
    if (!fpMap[fp]) fpMap[fp] = [];
    fpMap[fp].push(sig);
  }
  const keys = Object.keys(fpMap);
  for (let ki = 0; ki < keys.length; ki++) {
    const group = fpMap[keys[ki]];
    if (group.length < 4) continue;
    group.sort(function (a, b) {
      return stackQualityRank(b, stacks[b]) - stackQualityRank(a, stacks[a]);
    });
    for (let gi = 1; gi < group.length; gi++) {
      const sig = group[gi];
      const e = stacks[sig];
      if (sig === "SEPARATION" && /Mars (Conjonction|Carré|Opposition|Carre) Mars\b/i.test(e.marsJourJ || "")) continue;
      if ((sig === "JURIDIQUE_DOWN" || sig === "SCANDALE")
          && group.indexOf("JURIDIQUE_DOWN") >= 0 && group.indexOf("SCANDALE") >= 0) continue;
      if (sig === "SCANDALE" && e.scandaleMcLentS) continue;
      if (sig === "SCANDALE" && e.scandaleImpeachment) continue;
      if (sig === "SCANDALE" && e.scandaleMeltdown) continue;
      if (sig === "SEPARATION" && /Mars (Conjonction|Carré|Opposition|Carre).*?(Ascendant|Milieu du Ciel|Descendant|Vénus|Venus|Junon|Mars)/i.test((e.declencheurTop || "") + " " + (e.marsJourJ || ""))) continue;
