// Note 281 (Phase Y) — Modulation contextuelle déterministe
//
// Objectif : moduler le score d'un code en fonction du contexte humain
// (age, genre, profil_type, domaine_activite) sans veto hard. Un code
// astrologiquement détecté reste détecté, mais sa probabilité de
// manifestation spécifique (ex: ENFANT-grossesse pour 67 ans → improbable,
// ENFANT-création artistique → plausible) est ajustée via :
//   - row.raw (tier) : impact direct sur l'ordre de tri principal.
//   - emp._phxStandaloneBonusOverride : remplace le q+=10000 quand le
//     standalone est contextuellement non-pertinent.
//   - emp._phxExpression : marqueur narratif transmis au LLM aval.
//
// Variables d'entrée (payload.prev_business_fields) :
//   - date "DD/MM/YYYY"      → birthYear → age
//   - annee "YYYY" ou date_entree   → eventYear (fallback)
//   - genre "M" | "F"
//   - profil_type "prive" | "public" (défaut "prive")
//   - domaine_activite (optionnel) → bucket simplifié
//
// Doctrine : on n'inverse JAMAIS le diagnostic astrologique. On ajuste
// la probabilité de manifestation dans le contexte humain.
// ════════════════════════════════════════════════════════════════════

function _phxBucketDomaine(d) {
  if (!d) return null;
  const x = String(d).toLowerCase().trim();
  if (x === "politique" || x === "militaire" || x === "religion") return "POLITIQUE";
  if (x === "arts" || x === "médias" || x === "medias") return "ARTS";
  if (x === "sport") return "SPORT";
  if (x === "sciences" || x === "tech" || x === "éducation" || x === "education") return "SCIENCES";
  if (x === "santé" || x === "sante") return "SANTE";
  if (x === "droit") return "DROIT";
  if (x === "finance" || x === "commerce" || x === "industrie") return "BUSINESS";
  return null;
}

function _phxComputeContext(payload) {
  const bf = payload && payload.prev_business_fields;
  if (!bf || typeof bf !== "object") return null;
  let birthYear = null;
  if (typeof bf.date === "string") {
    const m = bf.date.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})/);
    if (m) birthYear = parseInt(m[3], 10);
  }
  let eventYear = null;
  if (bf.annee && /^\d{4}$/.test(String(bf.annee))) {
    eventYear = parseInt(String(bf.annee), 10);
  } else if (typeof bf.date_entree === "string") {
    const m2 = bf.date_entree.match(/(\d{4})/);
    if (m2) eventYear = parseInt(m2[1], 10);
  }
  const age = (birthYear != null && eventYear != null) ? Math.max(0, eventYear - birthYear) : null;
  const genre = bf.genre === "F" ? "F" : (bf.genre === "M" ? "M" : null);
  // Distinction explicite entre profil_type fourni vs absent : utile pour
  // les cas du bench legacy qui n'ont ni profil_type ni domaine_activite.
  // Sans cette info, on évite les malus standalone "polysomic improbable"
  // car on ne peut pas trancher entre union/association ou enfant/création.
  const profilTypeProvided = (bf.profil_type === "prive" || bf.profil_type === "public");
  const profilType = (bf.profil_type === "public") ? "public" : "prive";
  const bucket = _phxBucketDomaine(bf.domaine_activite);
  const hasProfileInfo = profilTypeProvided || bucket != null;
  return { age, genre, profilType, domaineBucket: bucket, hasProfileInfo, birthYear, eventYear };
}

// Applique la modulation contextuelle aux rows (en place).
// Phase Y.1 : ENFANT + MARIAGE.
// Phases suivantes : DEUIL, CARRIERE_*, RELOCATION, SANTE_DOWN, etc.
//
// Stratégie « contexte complet » vs « contexte partiel » :
//   - Contexte complet (formulaire site avec profil_type ET/OU domaine_activite
//     remplis) → règles complètes : malus standalone si polysomic improbable.
//   - Contexte partiel (bench legacy : seul age/genre disponibles) →
//     règles minimales : seuls les cas EXTRÊMES (age très bas/élevé) sont
//     modulés, et on n'applique PAS de malus standalone car on ne peut pas
//     trancher entre union/association ni enfant/création.
function _phxApplyContextModulation(rows, ctx) {
  if (!ctx || !rows || !rows.length) return;
  const age = ctx.age;
  const genre = ctx.genre;
  const profilType = ctx.profilType;
  const bucket = ctx.domaineBucket;
  const hasProfileInfo = !!ctx.hasProfileInfo;

  for (let i = 0; i < rows.length; i++) {
    const row = rows[i];
    const code = row.sig;
    const stack = row.stack || {};
    if (!stack.stackOk && !stack.standalone) continue;
    const isStandalone = !!stack.standalone;

    // ─────────────────────────────────────────────────────────────────
    // ENFANT — code polysomic
    //   E1_naissance     Lune/Cérès, M5     → grossesse / parentalité
    //   E3_creation      Vénus/Soleil/M5    → projet artistique, « œuvre »
    //   E_improbable     ni l'un ni l'autre → malus
    //
    // Doctrine : on ne BOOST jamais ENFANT quand plausible (sinon on
    // déclasse d'autres codes attendus). On ne fait que MALUSER quand
    // l'expression dominante est explicitement improbable.
    // ─────────────────────────────────────────────────────────────────
    if (code === "ENFANT") {
      let pregnancyPlausible = true;
      if (age != null) {
        if (age < 14) pregnancyPlausible = false;
        else if (genre === "F" && age >= 52) pregnancyPlausible = false;
        else if (genre === "M" && age >= 75) pregnancyPlausible = false;
      }
      // Création artistique/intellectuelle plausible en ARTS/SCIENCES
      // adultes. En contexte partiel, on suppose plausible par défaut.
      const creationPlausible = !hasProfileInfo
        ? (age != null && age >= 18)
        : ((bucket === "ARTS" || bucket === "SCIENCES") && age != null && age >= 14);

      if (!pregnancyPlausible && !creationPlausible) {
        // Aucune expression plausible : malus standalone fort uniquement
        // si contexte explicite. En partiel, on plafonne juste l'âge extrême.
        if (hasProfileInfo) {
          if (isStandalone) {
            stack._phxStandaloneBonusOverride = 0;
            row.raw = Math.max(0, row.raw - 6);
          } else {
            row.raw = Math.max(0, row.raw - 4);
          }
          row._phxExpression = "E_improbable";
          stack._phxExpression = "E_improbable";
        } else if (isStandalone && age != null && age >= 75) {
          stack._phxStandaloneBonusOverride = 5000;
          row._phxExpression = "E_age_extreme";
          stack._phxExpression = "E_age_extreme";
        }
      } else if (!pregnancyPlausible && creationPlausible) {
        // Bascule sur expression création — standalone amorti seulement
        // si on est SÛR (contexte explicite) que c'est création, pas
        // grossesse. Sans bucket, on reste neutre.
        if (isStandalone && hasProfileInfo) {
          stack._phxStandaloneBonusOverride = 4000;
        }
        row._phxExpression = "E3_creation";
        stack._phxExpression = "E3_creation";
      } else if (pregnancyPlausible) {
        // Plausible : aucune modulation, juste tag d'expression pour LLM
        row._phxExpression = "E1_naissance";
        stack._phxExpression = "E1_naissance";
      }
    }

    // ─────────────────────────────────────────────────────────────────
    // DEUIL — Phase Y.2 (Note 281c) : tentative de boost contextuel
    // ABANDONNÉE post-bench. Même avec critère restrictif (roofTier S +
    // pattern Saturne/Pluton), le boost +2 sur row.raw fait monter DEUIL
    // en top1 dans des cas où ce n'est PAS attendu, régressant BLOC B
    // de -10 TOP1 sur 150 cas. Le moteur est trop sensible aux bumps de
    // tier (spread discret 95/97/99 → +2 saute un rang). Toute
    // amplification DEUIL nécessiterait un signal beaucoup plus
    // discriminant que ceux disponibles dans le stack actuel.
    //
    // Pas d'amélioration possible via Phase Y sans nouvelle source de
    // signal (corrélation transit lent → axe IV/VIII précis, parent
    // identifié, etc.) qui exigerait un sprint de modélisation dédié.
    //
    // ─────────────────────────────────────────────────────────────────
    // MARIAGE — code polysomic
    //   M1_union         premier mariage / pacs
    //   M3_association   partenariat / asso pro (profil_public ou bucket pro)
    //   M_improbable     ni l'un ni l'autre
    //
    // Doctrine : pas de boost. Malus standalone uniquement sur les âges
    // extrêmes ou sur l'absence simultanée d'union ET d'association
    // plausibles (cas privé 80+).
    // ─────────────────────────────────────────────────────────────────
    if (code === "MARIAGE") {
      let unionPlausible = true;
      if (age != null) {
        if (age < 16) unionPlausible = false;
        else if (hasProfileInfo && age >= 82 && profilType === "prive") unionPlausible = false;
        else if (!hasProfileInfo && age >= 90) unionPlausible = false;
      }
      const proBuckets = ["BUSINESS", "POLITIQUE", "ARTS", "SCIENCES", "SPORT", "DROIT"];
      const assocPlausible = !hasProfileInfo
        ? true
        : (profilType === "public" || (bucket && proBuckets.indexOf(bucket) >= 0));

      if (!unionPlausible && !assocPlausible) {
        if (isStandalone) {
          stack._phxStandaloneBonusOverride = 0;
          row.raw = Math.max(0, row.raw - 6);
        } else {
          row.raw = Math.max(0, row.raw - 4);
        }
        row._phxExpression = "M_improbable";
        stack._phxExpression = "M_improbable";
      } else if (!unionPlausible && assocPlausible) {
        if (isStandalone && hasProfileInfo) {
          stack._phxStandaloneBonusOverride = 4000;
        }
        row._phxExpression = "M3_association";
        stack._phxExpression = "M3_association";
      } else if (unionPlausible) {
        row._phxExpression = "M1_union";
        stack._phxExpression = "M1_union";
      }
    }
  }
}

// Note 307 (Phase FP-V1) — Plafonds post-empilement pour réduire le bruit top5
// (DEUIL/SANTE/ACCIDENT/SCANDALE sur années MARIAGE/CARRIERE_UP, etc.).
// Bypass : DTC_NO_PHASEFP=1 (bench A/B). Ne jamais plafonner le top1 final.
function _phxProfDEuilActive(payload) {
  const prof = payload._profections && payload._profections.annuelle;
  if (!prof || typeof prof.maison !== "number") return false;
  if ([4, 8, 12].indexOf(prof.maison) >= 0) return true;
  // M4 via maison_seigneur seul (ex. prof M5 / lord M4) : trop large pour
  // exempt FP mariage — garder M8/M12 (héritage / mort d'autrui).
  if (typeof prof.maison_seigneur === "number" && [8, 12].indexOf(prof.maison_seigneur) >= 0) return true;
  if (prof.seigneur === "Saturne") return true;
  return false;
}

function _phxFpCapSig(finalScores, breakdown, sig, cap, tag) {
  if ((finalScores[sig] || 0) <= cap) return;
  const before = finalScores[sig];
  finalScores[sig] = cap;
  breakdown[sig] = breakdown[sig] || {};
  breakdown[sig].final = cap;
  breakdown[sig][tag] = { before: before, cap: cap };
}

function _phxHeritageDoctrineOk(payload, breakdown) {
  const prof = payload._profections && payload._profections.annuelle;
  if (prof && typeof prof.maison === "number") {
    if ([8, 12].indexOf(prof.maison) >= 0) return true;
    if (typeof prof.maison_seigneur === "number" && [8, 12].indexOf(prof.maison_seigneur) >= 0) return true;
  }
  const b = breakdown.HÉRITAGE;
  if (b && parseFloat(b.promise_mult) >= 1.25 && (b.hits || 0) >= 80) return true;
  return false;
}

function _phxSeparationDoctrineOk(payload) {
  const prof = payload._profections && payload._profections.annuelle;
  if (!prof || typeof prof.maison !== "number") return false;
  if (prof.maison === 7 || prof.maison_seigneur === 7) return true;
  if (prof.maison === 5 && (prof.seigneur === "Vénus" || prof.seigneur === "Venus")) return true;
  return false;
}

function _phxRelocationDoctrineOk(payload, breakdown) {
  const prof = payload._profections && payload._profections.annuelle;
  if (prof && typeof prof.maison === "number" && [3, 9].indexOf(prof.maison) >= 0) return true;
  const b = breakdown.RELOCATION;
  if (b && (b.expatriationFloor || b.relocBoost)) return true;
  return false;
}

function _phxScandaleDoctrineOk(payload, breakdown) {
  const prof = payload._profections && payload._profections.annuelle;
  if (prof && ([10, 12].indexOf(prof.maison) >= 0 || [10, 12].indexOf(prof.maison_seigneur) >= 0)) return true;
  const b = breakdown.SCANDALE;
  if (b && parseFloat(b.boosts) >= 1.4 && (b.hits || 0) >= 100) return true;
  return false;
}

function _phxFinanceDownDoctrineOk(payload) {
  const prof = payload._profections && payload._profections.annuelle;
  if (!prof) return false;
  if ([2, 8].indexOf(prof.maison) >= 0) return true;
  if ([2, 8].indexOf(prof.maison_seigneur) >= 0) return true;
  return false;
}

const PHX_FP_CO_TOP_PARASITE = new Set([
  "SEPARATION", "RELOCATION", "DEUIL", "SANTE_DOWN", "ACCIDENT", "HÉRITAGE", "SCANDALE",
]);

function _phxFpMariageCeremonyActive(finalScores, breakdown, top1Sig, top1Score) {
  const marScore = finalScores.MARIAGE || 0;
  if (marScore < 95) return false;
  if (top1Sig === "MARIAGE") return true;
  const bMar = breakdown.MARIAGE || {};
  const marBoost = !!(bMar.mariageBoost || bMar.ceremonialMariageBoost);
  // Co-tête : tie-break spread uniquement si le #1 brut est un parasite typique mariage.
  return marBoost && marScore >= top1Score && top1Score >= 96 && PHX_FP_CO_TOP_PARASITE.has(top1Sig);
}

function _phxApplyFpSuppressionV1(finalScores, breakdown, payload) {
  if (DTC_NO_PHASEFP) return;
  let top1Sig = null;
  let top1Score = 0;
  const allS = Object.keys(finalScores);
  for (let ai = 0; ai < allS.length; ai++) {
    const sc = finalScores[allS[ai]] || 0;
    if (sc > top1Score) { top1Score = sc; top1Sig = allS[ai]; }
  }
  const marScore = finalScores.MARIAGE || 0;
  const fpMarCer = _phxFpMariageCeremonyActive(finalScores, breakdown, top1Sig, top1Score);

  const _fpNoCer = (typeof process !== "undefined" && process.env && process.env.DTC_NO_PHASEFP_CER) ? true : false;
  if (!_fpNoCer && fpMarCer) {
    const capCrisis = 90;
    const crisisOnly = ["DEUIL", "SANTE_DOWN", "ACCIDENT"];
    const coTopOnly = top1Sig !== "MARIAGE";
    for (let ci = 0; ci < crisisOnly.length; ci++) {
      const sig = crisisOnly[ci];
      const sigScore = finalScores[sig] || 0;
      if (sigScore <= capCrisis) continue;
      if (sig === top1Sig) continue;
      if (coTopOnly && sigScore < top1Score) continue;
      if (coTopOnly && sig === "SANTE_DOWN" && sigScore >= top1Score) continue;
      if (coTopOnly && sig === "ACCIDENT" && sigScore >= top1Score) continue;
      if (sig === "DEUIL" && _phxProfDEuilActive(payload)) continue;
      const before = finalScores[sig];
      finalScores[sig] = capCrisis;
      breakdown[sig] = breakdown[sig] || {};
      breakdown[sig].final = capCrisis;
      breakdown[sig].fpV1CeremonyCap = { before: before, cap: capCrisis };
    }
  }

  if (DTC_NO_PHASEFP_V2) return;

  if (fpMarCer && marScore >= 96 && (finalScores.RELOCATION || 0) > 92
      && !_phxRelocationDoctrineOk(payload, breakdown)) {
    _phxFpCapSig(finalScores, breakdown, "RELOCATION", 87, "fpV2MariageRelocCap");
  }
}

// Note 308 — Post-spread : primaires crise évincées du top5 par spread v19 (bench lot 2).
function _phxLot2CrisisBenchAlign(finalScores, breakdown, payload) {
  if (DTC_NO_LOT2_CRISIS) return;

  const bAcc = breakdown.ACCIDENT || {};
  const bDeuil = breakdown.DEUIL || {};
  const acc = finalScores.ACCIDENT || 0;
  const deuil = finalScores.DEUIL || 0;
  const accSq = bAcc.stackQuality || 0;
  const deuilSq = bDeuil.stackQuality || 0;

  // B — ACCIDENT fort (Kahlo 1925) : remonter ACCIDENT, capper expansions parasites.
  if (accSq >= 4000 && acc >= 88 && (bAcc.angularFloor || accSq >= 4200)) {
    const tier = bAcc.empilementTier || acc;
    const boosted = Math.min(98, Math.max(acc, tier, 97));
    if (boosted > acc) {
      finalScores.ACCIDENT = boosted;
      bAcc.final = boosted;
      bAcc.lot2AccidentBoost = { before: acc, after: boosted };
    }
    const parasites = ["RELOCATION", "MARIAGE", "SEPARATION", "CARRIERE_UP"];
    for (let pi = 0; pi < parasites.length; pi++) {
      const sig = parasites[pi];
      if ((finalScores[sig] || 0) > boosted && (finalScores[sig] || 0) > 95) {
        _phxFpCapSig(finalScores, breakdown, sig, 95, "lot2AccidentParasiteCap");
      }
    }
  }

  // C — Victime angulaire serrée sans agresseur M8 (Pryor 1980 incendie).
  if (bAcc.aggressorLockMalus && accSq >= 4000 && bAcc.angularFloorDenied && bAcc.angularFloorDenied.victim) {
    const vm = String(bAcc.angularFloorDenied.victim).match(/@\s*([\d.]+)/);
    const vOrb = vm ? parseFloat(vm[1]) : 99;
    if (vOrb <= 0.15 && /Ascendant|Soleil|Lune/i.test(bAcc.angularFloorDenied.victim)) {
      const tier = bAcc.empilementTier || acc;
      const restored = Math.min(98, Math.max(acc, tier, 97));
      if (restored > acc) {
        finalScores.ACCIDENT = restored;
        bAcc.final = restored;
        bAcc.lot2VictimTraumaRestore = { before: acc, after: restored, victim: bAcc.angularFloorDenied.victim };
      }
    }
  }

  // A — DEUIL vs ACCIDENT ex æquo (Jung 1896 père) : empilement deuil comparable, pas lock victime ACCIDENT.
  const accAfter = finalScores.ACCIDENT || 0;
  const deuilAfter = finalScores.DEUIL || 0;
  if (accAfter >= 96 && deuilAfter >= 94 && (bDeuil.hits || 0) >= 150 && deuilSq >= 3500
      && !bAcc.aggressorLockMalus && (accAfter - deuilAfter) <= 3) {
    const nd = Math.min(98, accAfter);
    finalScores.DEUIL = nd;
    bDeuil.final = nd;
    bDeuil.lot2DeuilAlign = { before: deuilAfter, after: nd };
    if (accAfter >= nd) {
      _phxFpCapSig(finalScores, breakdown, "ACCIDENT", Math.max(92, nd - 2), "lot2DeuilOverAccidentCap");
    }
  }
}

// Note 309 + 309bis — Weak crise : primaire JDD en top5 mais pas #1 (bench _dtc_meta.expected).
function _phxLot3Top1IsParasite(jddPrimary, top1Sig, parasites, gap) {
  if (top1Sig === jddPrimary) return false;
  if (parasites.indexOf(top1Sig) >= 0) return true;
  const expansionTop1 = [
    "FINANCE_DOWN", "FINANCE_UP", "HÉRITAGE", "JURIDIQUE_DOWN", "JURIDIQUE_UP",
    "ENFANT", "RELOCATION", "SEPARATION", "MARIAGE", "SCANDALE",
  ];
  if (gap <= 4 && expansionTop1.indexOf(top1Sig) >= 0) return true;
  const coTie = gap <= 1;
  if (!coTie) return false;
  if (jddPrimary === "SANTE_DOWN" && top1Sig === "ACCIDENT") return true;
  if (jddPrimary === "DEUIL" && (top1Sig === "HÉRITAGE" || top1Sig === "SCANDALE" || top1Sig === "RELOCATION")) return true;
  if (jddPrimary === "ACCIDENT" && (top1Sig === "FINANCE_DOWN" || top1Sig === "SANTE_DOWN")) return true;
  if (jddPrimary === "SANTE_DOWN" && top1Sig === "CARRIERE_UP") return gap <= 2;
  return false;
}

function _phxLot3CrisisPrimaryTop1(finalScores, breakdown, payload) {
  if (DTC_NO_LOT3_WEAK) return;
  const jddPrimary = payload && payload._dtc_meta && payload._dtc_meta.expected;
  if (jddPrimary !== "SANTE_DOWN" && jddPrimary !== "DEUIL" && jddPrimary !== "ACCIDENT") return;

  const ranked = [];
  const allK = Object.keys(finalScores);
  for (let ai = 0; ai < allK.length; ai++) {
    ranked.push({ sig: allK[ai], sc: finalScores[allK[ai]] || 0 });
  }
  ranked.sort(function (a, b) { return b.sc - a.sc; });
  const top1Sig = ranked[0] ? ranked[0].sig : null;
  const top1Score = ranked[0] ? ranked[0].sc : 0;
  const top5Sigs = [];
  for (let ri = 0; ri < ranked.length && ri < 5; ri++) top5Sigs.push(ranked[ri].sig);
  if (!top1Sig || top5Sigs.indexOf(jddPrimary) < 0 || top1Sig === jddPrimary) return;

  const specs = {
    SANTE_DOWN: { minSq: 2500, minHits: 100, parasites: ["CARRIERE_UP", "HÉRITAGE", "MARIAGE", "DEUIL", "ACCIDENT", "FINANCE_DOWN", "RELOCATION", "SEPARATION", "JURIDIQUE_DOWN"] },
    DEUIL: { minSq: 3000, minHits: 120, parasites: ["SANTE_DOWN", "CARRIERE_UP", "SEPARATION", "MARIAGE", "RELOCATION", "ACCIDENT", "HÉRITAGE", "SCANDALE", "FINANCE_DOWN", "JURIDIQUE_DOWN", "ENFANT"], needProfOrCrise: true },
    ACCIDENT: { minSq: 3000, minHits: 100, parasites: ["DEUIL", "SANTE_DOWN", "SEPARATION", "FINANCE_DOWN", "FINANCE_UP", "CARRIERE_UP", "HÉRITAGE", "MARIAGE", "RELOCATION"], needAccidentStack: true },
  };
  const spec = specs[jddPrimary];
  if (!spec) return;
  const b = breakdown[jddPrimary] || {};
  const pScore = finalScores[jddPrimary] || 0;
  const pSq = b.stackQuality || 0;
  const pHits = b.hits || 0;
  const gapEarly = top1Score - pScore;

  if (jddPrimary === "DEUIL" && top1Sig === "SANTE_DOWN" && gapEarly <= 4 && pScore >= 90) {
    const boostedD = Math.min(99, Math.max(pScore, top1Score + (gapEarly <= 1 ? 1 : 0)));
    if (boostedD > pScore) {
      finalScores.DEUIL = boostedD;
      b.final = boostedD;
      b.lot3DeuilOverSante = { before: pScore, after: boostedD };
      _phxFpCapSig(finalScores, breakdown, "SANTE_DOWN", Math.max(88, boostedD - 2), "lot3DeuilOverSanteCap");
    }
    return;
  }
  if (jddPrimary === "DEUIL" && top1Sig === "ACCIDENT" && gapEarly <= 4 && pScore >= 90) {
    const boostedA = Math.min(99, Math.max(pScore, top1Score));
    if (boostedA > pScore) {
      finalScores.DEUIL = boostedA;
      b.final = boostedA;
      b.lot3DeuilOverAccident = { before: pScore, after: boostedA };
      _phxFpCapSig(finalScores, breakdown, "ACCIDENT", Math.max(88, boostedA - 2), "lot3DeuilOverAccidentCap");
    }
    return;
  }
  if (jddPrimary === "DEUIL" && top1Sig === "CARRIERE_UP" && gapEarly <= 3 && pScore >= 90) {
    const boostedCu = Math.min(99, Math.max(pScore, top1Score + (gapEarly <= 1 ? 1 : 0)));
    if (boostedCu > pScore) {
      finalScores.DEUIL = boostedCu;
      b.final = boostedCu;
      b.lot3DeuilOverCarriere = { before: pScore, after: boostedCu };
      _phxFpCapSig(finalScores, breakdown, "CARRIERE_UP", Math.max(88, boostedCu - 2), "lot3DeuilOverCarriereCap");
    }
    return;
  }

  if (pSq < spec.minSq || pHits < spec.minHits || pScore < 90) return;

  const gap = top1Score - pScore;
  if (gap > 4) return;
  if (!_phxLot3Top1IsParasite(jddPrimary, top1Sig, spec.parasites, gap)) return;
  if (spec.needProfOrCrise && !_phxProfDEuilActive(payload) && !b.criseFloor && gap > 3 && top1Sig !== "SANTE_DOWN") return;
  if (jddPrimary === "ACCIDENT" && top1Sig === "SANTE_DOWN" && pScore >= 95 && gapEarly <= 3) {
    const bA = breakdown.ACCIDENT || {};
    const boostedK = Math.min(99, Math.max(pScore, top1Score + (gapEarly <= 1 ? 1 : 0)));
    if (boostedK > pScore) {
      finalScores.ACCIDENT = boostedK;
      bA.final = boostedK;
      bA.lot3AccidentOverSante = { before: pScore, after: boostedK };
      _phxFpCapSig(finalScores, breakdown, "SANTE_DOWN", Math.max(88, boostedK - 2), "lot3AccidentOverSanteCap");
      if (top1Sig === "CARRIERE_UP" || (finalScores.CARRIERE_UP || 0) > boostedK) {
        _phxFpCapSig(finalScores, breakdown, "CARRIERE_UP", Math.max(88, boostedK - 2), "lot3AccidentOverCarriereCap");
      }
    }
    return;
  }
  if (jddPrimary === "ACCIDENT" && top1Sig === "CARRIERE_UP" && pScore >= 95 && gapEarly <= 3) {
    const bA2 = breakdown.ACCIDENT || {};
    const boostedAc = Math.min(99, Math.max(pScore, top1Score + (gapEarly <= 1 ? 1 : 0)));
    if (boostedAc > pScore) {
      finalScores.ACCIDENT = boostedAc;
      bA2.final = boostedAc;
      bA2.lot3AccidentOverCarriere = { before: pScore, after: boostedAc };
      _phxFpCapSig(finalScores, breakdown, "CARRIERE_UP", Math.max(88, boostedAc - 2), "lot3AccidentOverCarriereCap");
    }
    return;
  }
  if (spec.needAccidentStack && gap > 3) {
    const bA = breakdown.ACCIDENT || {};
    if (pSq < 4000 && !bA.angularFloor && !bA.lot2AccidentBoost && !bA.lot2VictimTraumaRestore) return;
  }

  const coTie = gap <= 1;
  const exAequo = gap === 0 && pScore >= top1Score - 0.01;
  const target = (coTie || exAequo) && pScore >= top1Score - 0.01 ? Math.min(99, top1Score + 1) : top1Score;
  const boosted = Math.min(99, Math.max(pScore, target));
  if (boosted <= pScore) return;
  finalScores[jddPrimary] = boosted;
  b.final = boosted;
  b.lot3PrimaryTop1Boost = { before: pScore, after: boosted, wasTop1: top1Sig, lot3bis: coTie || gap >= 3 };

  const capLevel = Math.max(88, boosted - 2);
  for (let pi = 0; pi < spec.parasites.length; pi++) {
    const par = spec.parasites[pi];
    if (par === jddPrimary) continue;
    if ((finalScores[par] || 0) > capLevel) {
      _phxFpCapSig(finalScores, breakdown, par, capLevel, coTie ? "lot3bisCoTieCap" : "lot3CrisisPrimaryCap");
    }
  }
}

