// Co-maîtres modernes (Brady ch.2). Brennan helléniste = traditionnel uniquement.
// Brady valide explicitement l'usage simultané selon empirie.
const V20_MODERN_CO_RULERS = Object.freeze({
  "Scorpion":  "Pluton",
  "Verseau":   "Uranus",
  "Poissons":  "Neptune",
});

// Mapping signe → maître traditionnel (réutilise TRAD_RULERS via lookup).
function _v20SignOfHouse(payload, houseNum) {
  if (!payload || typeof houseNum !== "number") return null;
  const hl = payload._houseLords || {};
  const entry = hl[houseNum] || hl[String(houseNum)];
  if (entry && entry.signe) return entry.signe;
  // Fallback whole-sign depuis Ascendant
  const ascSign = payload._natalDict && payload._natalDict["Ascendant"]
    && payload._natalDict["Ascendant"].sign;
  if (!ascSign) return null;
  const ascIdx = ZODIAC_ORDER.indexOf(ascSign);
  if (ascIdx < 0) return null;
  return ZODIAC_ORDER[(ascIdx + houseNum - 1) % 12];
}

function _v20CoRulerOfHouse(payload, houseNum) {
  const sign = _v20SignOfHouse(payload, houseNum);
  if (!sign) return null;
  return V20_MODERN_CO_RULERS[sign] || null;
}

function _v20EssentialDignityBonus(code, natalDict, payload, eventDate, emp) {
  // Brennan ch.8 l.12953-13013 + ch.8 l.13278-13305 + Rushman ch.7 l.1235 :
  //   condition essentielle natale du significateur principal modifie la
  //   qualité de manifestation. Stable, doctrinal, discriminant.
  // Réutilise _phxDigniteEssentielleScore (helper existant) sur le mainSig.
  // Mapping V20.6 (cf. doc § 11.2) :
  //   domicile        → +5
  //   exaltation      → +3
  //   triplicité/terme/face/peregrin → 0 (non-discriminant pour V20)
  //   chute (fall)    → -2
  //   exil (detriment)→ -3
  // V20.6c (2026-05-29) : bonus appliqué UNIQUEMENT si le mainSig est
  //   également ACTIVÉ (transit lent / DP/SA / déclencheur). Doctrine
  //   Brennan ch.16 : la dignité essentielle modifie la qualité d'une
  //   activation, elle ne crée pas l'activation. Sans activation du
  //   significateur, la dignité reste "latente" (Rushman ch.2 promesse
  //   non manifestée).
  const conf = _getRule3Conf(code);
  if (!conf) return 0;
  const mainSig = conf.planets && conf.planets[0];
  if (!mainSig) return 0;
  // Gate doctrinal : mainSig doit être actif pour que sa dignité compte
  if (!_v20MainSignificatorActive(payload, mainSig, eventDate, emp, conf.houses && conf.houses[0])) {
    return 0;
  }
  const dig = _phxDigniteEssentielleScore(natalDict, mainSig);
  if (!dig || dig.label === "indisponible" || dig.isAmbivalent) return 0;
  switch (dig.label) {
    case "domicile":   return 5;
    case "exaltation": return 3;
    case "chute":      return -2;
    case "exil":       return -3;
    default:           return 0;
  }
}

function _v20ApplyingBonusV6(emp) {
  // Brennan ch.9 l.16096-16143 : applying configurations « more powerful »,
