  if (!emp || emp.error) return 0;
  if (!emp.roofTier || (emp.roofTier !== "S" && emp.roofTier !== "A")) return 0;
  if (typeof emp.lentRoofPeakDaysJ !== "number") return 0;
  // Applying : peak après event = transit en cours de formation
  if (emp.lentRoofPeakDaysJ >= 0) return 2;
  return 0;
}

function _v20SectBonus(code, payload, natalDict) {
  // Brennan ch.10 l.10911-10920 : « the most positive planet in a day chart is
  //   Jupiter, while the most positive planet in a night chart is Venus.
  //   Conversely, the most negative planet in a night chart is Saturn, and the
  //   most negative planet in a day chart is Mars »
  // Bonus +3 si la planète sect benefic transite/active une topique d'un code
  //   "up" — bonus +3 si sect malefic active topique d'un code "down".
  if (!payload || typeof payload._isDayChart === "undefined") return 0;
  const isDay = payload._isDayChart;
  const sectBenefic = isDay ? "Jupiter" : "Vénus";
  const sectMalefic = isDay ? "Mars" : "Saturne";
  const conf = _getRule3Conf(code);
  if (!conf) return 0;
  const profAnn = payload._profections && payload._profections.annuelle;
  if (!profAnn) return 0;
  // Vérifie si sectBenefic est natal en signe profecté ou maître profecté
  const np_b = natalDict[sectBenefic];
  const np_m = natalDict[sectMalefic];
  const houseProf = profAnn.maison;
  const lordProf = profAnn.seigneur;
  const isSectBenInProfHouse = np_b && np_b.house === houseProf;
  const isSectMalInProfHouse = np_m && np_m.house === houseProf;
  const isSectBenLordProf = lordProf === sectBenefic;
  const isSectMalLordProf = lordProf === sectMalefic;
  const upCodes = ["CARRIERE_UP", "MARIAGE", "ENFANT", "FINANCE_UP", "HÉRITAGE"];
  const downCodes = ["DEUIL", "SEPARATION", "CARRIERE_DOWN", "FINANCE_DOWN", "SANTE_DOWN", "ACCIDENT", "JURIDIQUE_DOWN", "SCANDALE"];
  if (upCodes.indexOf(code) >= 0) {
    if (isSectBenInProfHouse || isSectBenLordProf) return 3;
    if (isSectMalInProfHouse || isSectMalLordProf) return -3;
  }
  if (downCodes.indexOf(code) >= 0) {
    if (isSectMalInProfHouse || isSectMalLordProf) return 3;
    if (isSectBenInProfHouse || isSectBenLordProf) return -3;
  }
  return 0;
}

function _v20PeakQualityBonus(code, payload, natalDict) {
  // V22 bypass — peak quality Brennan Ch.18 / ZR retiré en mode V22 (cf. SPEC §3.7).
  // Remplacé par _v22BradyPeakNarrowness (orbe étroite transit lent) dans c4 V22.
