  if (!payload || !payload._profections || !payload._profections.annuelle) return 0;
  const houseProfected = payload._profections.annuelle.maison;
  if (typeof houseProfected !== "number") return 0;
  const benefics = ["Jupiter", "Vénus", "Venus"];
  const malefics = ["Saturne", "Mars", "Pluton", "Uranus", "Pluto"];
  let hasBenefic = false;
  let hasMalefic = false;
  const keys = Object.keys(natalDict || {});
  for (let k = 0; k < keys.length; k++) {
    const pname = keys[k];
    const np = natalDict[pname];
    if (np && np.house === houseProfected) {
      if (benefics.indexOf(pname) >= 0) hasBenefic = true;
