    }
  }
  // Codes "up" et "down" — classification doctrinale Brennan ch.18 + Firmicus
  const upCodes = ["CARRIERE_UP", "MARIAGE", "ENFANT", "FINANCE_UP", "HÉRITAGE"];
  const downCodes = ["DEUIL", "SEPARATION", "CARRIERE_DOWN", "FINANCE_DOWN", "SANTE_DOWN", "ACCIDENT", "JURIDIQUE_DOWN", "SCANDALE"];
  if (upCodes.indexOf(code) >= 0) {
    if (hasBenefic && !hasMalefic) return 5;
    if (hasMalefic && !hasBenefic) return -5;
  }
  if (downCodes.indexOf(code) >= 0) {
    if (hasMalefic && !hasBenefic) return 5;
    if (hasBenefic && !hasMalefic) return -5;
  }
  return 0;
}

function _v20MainSignificatorActive(payload, planetName, eventDate, emp, mainHouseForCoRuler) {
  if (!planetName || !payload) return false;
