//
// Critère γ pour les 4 codes DOWN (SANTE/CARRIERE/FINANCE_DOWN + SCANDALE) :
//   - Transit lent partile (emp.lentNatalHouse) ∈ maisons topiques du code
//   - ET emp.lentRoofPattern contient au moins UNE planète signifiante
//     (planète naturelle OU maître Mx d'une maison topique du code)
//
// Plus restrictif que _v20MainHouseActive + _v20MainSignificatorActive
// (qui acceptent profections seules sans transit lent). Ici on exige la
// CONVERGENCE des deux dans emp.lentRoofPattern (= la planète lente
// transite une maison topique ET aspecte un signifiant natal).
//
// Choix γ validé Étape 0 (2026-05-31) : audit cats sur 35 cas absents a
// montré que cats>=2 simple est trop permissif (93% non-DOWN activeraient
// SANTE_DOWN). La convergence transit γ filtre les FP doctrinalement (les
// non-DOWN n'ont généralement PAS de transit lent partile dans M6/M8/M12
// sur Saturne/Pluton natal en année cible — sauf coïncidence).
// ─────────────────────────────────────────────────────────────────────
function _rot3DownTransitConvergenceOK(code, payload, emp) {
  const conf = _getRule3Conf(code);
  if (!conf || !emp || emp.error) return false;
  if (typeof emp.lentNatalHouse !== "number") return false;
  if (conf.houses.indexOf(emp.lentNatalHouse) < 0) return false;
  const pattern = emp.lentRoofPattern || "";
  if (!pattern) return false;
  // Vérifier qu'au moins UNE planète signifiante naturelle est dans le pattern
  for (let i = 0; i < conf.planets.length; i++) {
    if (pattern.indexOf(conf.planets[i]) >= 0) return true;
  }
  // OU le maître d'une maison topique du code est dans le pattern
  const lords = payload && payload._houseLords;
  if (lords) {
    for (let h = 0; h < conf.houses.length; h++) {
      const houseNum = conf.houses[h];
      const entry = lords[houseNum];
      const lord = entry && (typeof entry === "string" ? entry : entry.maitre);
      if (lord && pattern.indexOf(lord) >= 0) return true;
    }
  }
  return false;
}

// _ROT3_DOWN_3D_SET est défini en tête de fichier (juste après CODE_RULE_OF_THREE)
