function _v20ScoreContributions(code, payload, eventDate, emp, natalDict) {
  // C1 — Promesse natale (axes V3 doctrinal)
  const axes = _pnaAxesCount(natalDict, payload, code);
  let c1 = 0;
  if (axes >= 3) c1 = 25;
  else if (axes === 2) c1 = 16;
  else if (axes === 1) c1 = 8;

  // Phase B' 3-D : code ∈ _ROT3_DOWN_3D_SET ET flag DTC_PHASE_B_DOWN_3D actif
  //   pour ce code (single source of truth = _getRule3Conf, défini module-level).
  //   PROD-safe : _getRule3Conf retourne undefined sans flag → _isDown3DActive false.
  const _isDown3DActive = Boolean(_ROT3_DOWN_3D_SET[code] && _getRule3Conf(code));

  // ─── Phase C-1 Grappe 1 (2026-06-01) ─── Piste A : garde Rule of Three universelle
  //   (BUG-C1-01 + BUG-C1-02). Calcul `cats` en amont (au lieu d'après C2).
