 * Fix 2026-06-01 soir tardif : V20 stocke les Lots comme pseudo-planètes
 * directement dans payload._natalDict (cf. poc-dtc-local.mjs L3041-3043
 * `for (const lotName of conf.lots) { const nl = natalDict[lotName]; ... }`).
 * Le champ `payload._lots` n'existe PAS dans le contexte V20 amont.
 *
 * Mode WHOLE-SIGN (G6 ÉTAPE 3-BIS, flag DTC_V21_WHOLESIGN=1) : entry.house
 * est recalculé en whole-sign à partir de entry.longitude + ASC. Le .sign
 * reste le signe zodiacal du lot (system-indépendant). Fallback tolérant
 * si ASC ou longitude absents.
 */
function _v21LotPosition(payload, aliasGroup) {
  if (!aliasGroup || !aliasGroup.length) return null;
  const lots = (payload && payload._natalDict) || {};
  const ascIdx = _V21_WHOLESIGN_ENABLED ? _v21AscSignIndex(payload) : null;
  for (const alias of aliasGroup) {
    const entry = lots[alias];
    if (!entry || typeof entry.house !== "number") continue;
    let house = entry.house;
    if (_V21_WHOLESIGN_ENABLED && ascIdx !== null
        && typeof entry.longitude === "number") {
      const ws = _v21WSHouseFromLongitude(entry.longitude, ascIdx);
      if (ws !== null) house = ws;
    }
    return {
      house: house,
      sign: entry.sign || null,
      longitude: (typeof entry.longitude === "number") ? entry.longitude : null,
      alias: alias
    };
  }
  return null;
}

/**
 * Aspect ptolémaïque tight (orbe ≤ 3°) entre 2 corps natals.
 * Aspects considérés : conjonction (0°), sextile (60°), carré (90°),
 * trigone (120°), opposition (180°). LE QUINCONCE EST EXCLU
 * (RÈGLE-ZERO _INDEX-MASTER.md §4 : aversion/mineur, jamais en Rule of Three).
 *
 * Décision E.2 : accepte string OU objet { longitude }. Permet d'aspecter
 * directement un Lot (objet) sans le matérialiser comme pseudo-planète.
 */
function _v21AspectTight(natalDict, bodyA, bodyB) {
  function _resolveLon(body) {
    if (body == null) return null;
    if (typeof body === "string") {
      if (!natalDict || !natalDict[body]) return null;
      const lon = natalDict[body].longitude;
      return (typeof lon === "number") ? lon : null;
    }
    if (typeof body === "object" && typeof body.longitude === "number") {
      return body.longitude;
    }
    return null;
  }
  const lonA = _resolveLon(bodyA);
  const lonB = _resolveLon(bodyB);
  if (lonA === null || lonB === null) return false;
  let diff = Math.abs(lonA - lonB) % 360;
  if (diff > 180) diff = 360 - diff;
  for (const aspect of [0, 60, 90, 120, 180]) {
    if (Math.abs(diff - aspect) <= 3) return true;
  }
  return false;
}

