/**
 * §1.5.1 — Construit un verdict INACTIVE traçable quand le natal est mal formé.
 * Garantit que la cascade aval continue (14 codes INACTIVE) au lieu de crasher
 * le webhook PROD. Le champ _error est consommé par les logs upstream.
 */
function _v21Rule3DegradedResult(code, errorMsg) {
  const entry = _v21Rule3Matrix[code];
  return {
    code:       code,
    count:      0,
    level:      "INACTIVE",
    capLevel:   entry.capLevel,
    confidence: entry.confidence,
    witnesses:  { planet: null, place: null, lot: null },
    _error:     errorMsg
  };
}

/**
 * §1.5.2 — CAT 1 : planète signifiante.
 * Évalue (1.a) occupation topique, puis (1.b) aspect tight au maître d'une
 * topique. Retourne le PREMIER hit trouvé ou null.
 * Skip explicite planetName === lordName (aspect à soi-même, géré par CAT 2).
 */
function _v21Rule3CheckPlanet(natalDict, payload, entry) {

  // (1.a) Planète signifiante naturelle occupant une maison topique
  for (const planetName of entry.planets) {
    const ph = _v21HouseOf(natalDict, planetName);
    if (ph !== null && entry.houses.indexOf(ph) !== -1) {
      return {
        via:    "1.a",
        detail: planetName + " (signifiante) en M" + ph + " (topique)",
        source: "Brennan Ch.16 L27027"
      };
    }
  }

  // (1.b) Planète signifiante en aspect ptolémaïque tight au maître d'une topique
  for (const houseNum of entry.houses) {
    const lordName = _v21Lord(payload, houseNum);
    if (!lordName) continue;
    for (const planetName of entry.planets) {
      if (planetName === lordName) continue;
      if (!natalDict[planetName] || !natalDict[lordName]) continue;
      if (_v21AspectTight(natalDict, planetName, lordName)) {
        const ph = _v21HouseOf(natalDict, planetName);
        const lh = _v21HouseOf(natalDict, lordName);
        return {
          via:    "1.b",
          detail: planetName + " (M" + (ph || "?") + ", signifiante) aspect tight "
                + lordName + " (M" + (lh || "?") + ", maître M" + houseNum + ")",
          source: "Brennan Ch.16 L27027"
        };
      }
    }
  }

  return null;
}

/**
 * §1.5.3 — CAT 2 : maison topique et son maître.
 * Évalue par maison (extérieur), puis 2.a → 2.b → 2.c (intérieur).
 * Retourne le PREMIER hit trouvé ou null.
 */
function _v21Rule3CheckPlace(natalDict, payload, entry) {

  for (const houseNum of entry.houses) {

    // (2.a) Maison topique occupée par un astre quelconque (10 planètes)
    for (const planetName of _V21_ALL_PLANETS) {
      if (_v21HouseOf(natalDict, planetName) === houseNum) {
        return {
          via:    "2.a",
          detail: "M" + houseNum + " (topique) occupée par " + planetName,
          source: "Brennan Ch.16 L27029"
        };
      }
    }

    // (2.b) Maître de la topique placé dans une maison topique du code
    const lordName = _v21Lord(payload, houseNum);
    if (lordName) {
      const lh = _v21HouseOf(natalDict, lordName);
      if (lh !== null && entry.houses.indexOf(lh) !== -1) {
        return {
          via:    "2.b",
          detail: "maître M" + houseNum + " = " + lordName + " en M" + lh + " (topique)",
          source: "Brennan Ch.16 L27029"
        };
      }
    }

    // (2.c) Maître de la topique en aspect tight à une planète signifiante
    if (lordName && natalDict[lordName]) {
      for (const planetName of entry.planets) {
        if (planetName === lordName) continue;
        if (!natalDict[planetName]) continue;
        if (_v21AspectTight(natalDict, lordName, planetName)) {
          return {
            via:    "2.c",
            detail: "maître M" + houseNum + " = " + lordName
                  + " aspect tight " + planetName + " (signifiante)",
            source: "Brennan Ch.16 L27029-30"
          };
        }
      }
    }
  }

  return null;
}

/**
 * §1.5.4 — CAT 3 : lot topique et son maître.
 * Verrou décision B : si entry.lot === null, retour immédiat null.
 * Itération sur groupes d'alias (décision H.1-bis), puis 3.a → 3.b → 3.c.
 */
function _v21Rule3CheckLot(natalDict, payload, entry) {

  if (entry.lot === null) return null;

  for (const aliasGroup of entry.lot) {
    const lotPos = _v21LotPosition(payload, aliasGroup);
    if (!lotPos) continue;

    // (3.a) Lot dans une maison topique
    if (entry.houses.indexOf(lotPos.house) !== -1) {
      return {
        via:    "3.a",
        detail: lotPos.alias + " en M" + lotPos.house + " (topique)",
        source: "Brennan Ch.16 L27030"
      };
    }

    // (3.b) Maître du lot placé dans une maison topique
    const lordOfLot = _v21Lord(payload, lotPos.house);
    if (lordOfLot) {
      const lh = _v21HouseOf(natalDict, lordOfLot);
      if (lh !== null && entry.houses.indexOf(lh) !== -1) {
        return {
          via:    "3.b",
          detail: lotPos.alias + " en M" + lotPos.house
                + ", maître M" + lotPos.house + " = " + lordOfLot
                + " en M" + lh + " (topique)",
          source: "Brennan Ch.16 L27032-34"
        };
      }
    }

    // (3.c) Lot direct OU maître du lot en aspect tight à une planète signifiante
    for (const planetName of entry.planets) {
      // 3.c.i — Lot direct (décision E.2 — nécessite lotPos.longitude)
      if (lotPos.longitude !== null && natalDict[planetName]) {
        if (_v21AspectTight(natalDict, lotPos, planetName)) {
          return {
            via:    "3.c",
            detail: lotPos.alias + " aspect tight " + planetName + " (signifiante, via lot direct)",
            source: "Brennan Ch.16 L27032-34"
          };
        }
      }
      // 3.c.ii — Maître du lot
      if (lordOfLot && lordOfLot !== planetName
          && natalDict[lordOfLot] && natalDict[planetName]) {
        if (_v21AspectTight(natalDict, lordOfLot, planetName)) {
          return {
            via:    "3.c",
            detail: "maître M" + lotPos.house + " (" + lordOfLot
                  + ") aspect tight " + planetName + " (signifiante)",
            source: "Brennan Ch.16 L27032-34"
          };
        }
      }
    }
  }

  return null;
}

