/**
 * Extraction doctrinale autonome de la Rule of Three (Brennan Ch.16).
 * Compte symétrique sur 14 codes, sans convention asymétrique UP/DOWN.
 * Réimplémente proprement le comptage des 3 catégories Brennan
 * (planet / place / lot), strictement indépendantes.
 *
 * @param {Object} natalDict  positions natales planètes/angles/lots
 * @param {Object} payload    payload n8n complet (lords, _natalDict)
 * @param {string} code       parmi 14 codes DTC documentés
 * @returns {Object} verdict Z.1 (objet riche)
 *
 * Garanties :
 *   - Pure : aucun side-effect, lecture seule de natalDict + payload.
 *   - Symétrique : même logique pour les 14 codes (pas de UP/DOWN spécial).
 *   - Sourcée : chaque catégorie activée trace son verbatim Brennan.
 */
function _v21Rule3Strict(natalDict, payload, code) {

  // (a) Validation entrée — code dans matrice (5.3.A : exception explicite)
  if (!_v21Rule3Matrix[code]) {
    throw new Error('_v21Rule3Strict: code "' + code + '" absent de _v21Rule3Matrix (14 codes attendus)');
  }

  // (b) Validation entrée — natal valide (5.3.B : dégradation gracieuse)
  if (!natalDict || typeof natalDict !== "object") {
    return _v21Rule3DegradedResult(code, "natalDict absent ou invalide");
  }

  // (c) Récupération de l'entrée matrice
  const entry = _v21Rule3Matrix[code];

  // (d) Évaluation indépendante des 3 catégories
  const planetWitness = _v21Rule3CheckPlanet(natalDict, payload, entry);
  const placeWitness  = _v21Rule3CheckPlace (natalDict, payload, entry);
  const lotWitness    = _v21Rule3CheckLot   (natalDict, payload, entry);

  // (e) Comptage al-Khayyāt L27052-54 + mapping level
  const count = (planetWitness ? 1 : 0)
              + (placeWitness  ? 1 : 0)
              + (lotWitness    ? 1 : 0);
  const level = _V21_RULE3_LEVEL_MAP[count];

  // (f) Retour structuré (schéma Z.1 verrouillé)
  return {
    code:       code,
    count:      count,
    level:      level,
    capLevel:   entry.capLevel,
    confidence: entry.confidence,
    witnesses: {
      planet: planetWitness,
      place:  placeWitness,
      lot:    lotWitness
    }
  };
}

