/**
 * Décision J verrouillée — 6 codes violents éligibles à Mars trigger (§2.5.0 SPEC).
 * Liste justifiée par citations verbatim Rushman/Brennan dans la matrice §1.3
 * (ACCIDENT, SANTE_DOWN, SEPARATION, JURIDIQUE_DOWN, DEUIL, SCANDALE).
 */
const MARS_ELIGIBLE_CODES = Object.freeze([
  "ACCIDENT", "SANTE_DOWN", "SEPARATION",
  "JURIDIQUE_DOWN", "DEUIL", "SCANDALE"
]);

/** 5 aspects ptolémaïques canoniques pour transit (cohérence règle 1 §1.2.5) */
const _V21_ALLOWED_TRANSIT_ASPECTS = Object.freeze([
  "Conjonction", "Sextile", "Carré", "Trigone", "Opposition"
]);

/**
 * Mapping angle natal → maison équivalente (aligné sur ANGLE_TO_HOUSE V20
 * L5184-89, utilisé uniquement pour 2.2.d éclipses sur angles).
 */
const _V21_ANGLE_TO_HOUSE = Object.freeze({
  "Ascendant":      1,  "AS":  1,  "Asc": 1,
  "Fond du Ciel":   4,  "FC":  4,  "Imum Coeli": 4,  "IC": 4,
  "Descendant":     7,  "DS":  7,  "Desc": 7,
  "Milieu du Ciel": 10, "MC": 10,  "Médium Coeli": 10, "Medium Coeli": 10
});

