// G2.2 — Helpers stage-set (§2.3.0 SPEC)
// ─────────────────────────────────────────────────────────────────────────────

/** Lecture robuste du Lord of Year, retourne null si non calculé amont. */
function _v21LordOfYear(payload) {
  // V22 bypass — LoY est dérivé de la profection annuelle Brennan, désactivé en V22.
  if (DTC_V22_NO_PROFECTIONS) return null;
  if (!payload || !payload._profections) return null;
  const ann = payload._profections.annuelle;
  if (!ann || typeof ann.seigneur !== "string" || !ann.seigneur) return null;
  return ann.seigneur;
}

/** Lecture robuste de la maison annuelle activée par profection, null si non calculé. */
function _v21HouseProfected(payload) {
  if (!payload || !payload._profections) return null;
  const ann = payload._profections.annuelle;
  if (!ann || typeof ann.maison !== "number" || ann.maison < 1 || ann.maison > 12) {
    return null;
  }
  return ann.maison;
}

/**
 * Itère sur les progressions secondaires consignées par l'amont V20
 * (payload._progressedActivations[natalP] = [{ pProg, aspName, orbe }]).
 * Retourne le PREMIER hit tight (orbe ≤ maxOrb) ou null. Aspects acceptés :
 * 5 ptolémaïques (quinconce exclu, RÈGLE-ZERO §4).
 */
function _v21ProgressionTightHit(payload, natalP, maxOrb) {
  if (!payload || !payload._progressedActivations) return null;
  const acts = payload._progressedActivations[natalP];
  if (!Array.isArray(acts) || acts.length === 0) return null;
  const ALLOWED_ASPECTS = ["Conjonction", "Sextile", "Carré", "Trigone", "Opposition"];
  for (const act of acts) {
    if (!act || typeof act.orbe !== "number") continue;
    if (act.orbe > maxOrb) continue;
    if (typeof act.aspName !== "string") continue;
    if (ALLOWED_ASPECTS.indexOf(act.aspName) === -1) continue;
    return {
      pProg:   act.pProg,
      aspName: act.aspName,
      orbe:    act.orbe,
      natalP:  natalP
    };
  }
  return null;
}

