/**
 * Construit le Set des cibles natales pour un code donné :
 * signifiants naturels (entry.planets) ∪ maîtres des maisons topiques (entry.houses).
 * Filtre : ne garde que les noms présents dans natalDict (pas de cible fantôme).
 * Helper factorisé entre §2.3 (sous-règle 2.1.c) et §2.4 (sous-règles 2.2.a/b/c/d).
 */
function _v21BuildNatalTargets(natalDict, payload, entry) {
  const targets = new Set();
  for (const planet of entry.planets) {
    if (natalDict && natalDict[planet]) targets.add(planet);
  }
  for (const houseNum of entry.houses) {
    const lord = _v21Lord(payload, houseNum);
    if (lord && natalDict && natalDict[lord]) targets.add(lord);
  }
  return targets;
}

/**
 * Itère sur les transits consignés par l'amont V20
 * (payload._aspectsSuiviLent + payload._aspectsSuiviRap).
 * Format clé : "slow_TP|||AspName|||NatalP" ou "fast_TP|||AspName|||NatalP".
 * Format valeur : { waves: [{ minOrb }], natalHouse }.
 *
 * Parcourt "lents puis rapides" pour respecter Brady L4382-93 (slow > weight).
 * Retourne le PREMIER hit qui satisfait les filtres, ou null.
 */
function _v21TransitTightHit(payload, transitPlanetsAllowed, natalTargets, maxOrb) {
  if (!payload) return null;
  const allowedSet = new Set(transitPlanetsAllowed);
  const blocks = [
    payload._aspectsSuiviLent || {},
    payload._aspectsSuiviRap  || {}
  ];
  for (const block of blocks) {
    const keys = Object.keys(block);
    for (const key of keys) {
      const val = block[key];
      if (!val || !Array.isArray(val.waves) || val.waves.length === 0) continue;
      const parts = key.split("|||");
      if (parts.length !== 3) continue;
      const transitP = parts[0].replace(/^fast_|^slow_/, "");
      const aspName  = parts[1];
      const natalP   = parts[2];
      if (!allowedSet.has(transitP)) continue;
      if (!natalTargets.has(natalP)) continue;
      if (_V21_ALLOWED_TRANSIT_ASPECTS.indexOf(aspName) === -1) continue;
      let minOrb = Infinity;
      for (const wave of val.waves) {
        const o = parseFloat(wave.minOrb);
        if (isFinite(o) && o < minOrb) minOrb = o;
      }
      if (!isFinite(minOrb) || minOrb > maxOrb) continue;
      return {
        transitP:   transitP,
        natalP:     natalP,
        aspName:    aspName,
        orb:        minOrb,
        natalHouse: val.natalHouse || null
      };
    }
  }
  return null;
}

/**
 * Itère sur les éclipses consignées par l'amont V20
 * (payload._mdseEclipseNatalHits = [{ planet, eclType, date }]).
 * Filtre Pénombrales (V20 L5194). planet peut être planète/Lot/signifiant OU
 * un angle (AS/MC/DS/FC) → mapping via _V21_ANGLE_TO_HOUSE → vérifie maison
 * équivalente ∈ houseTargets.
 *
 * Retourne le PREMIER hit qui satisfait, ou null.
 */
function _v21EclipseTightHit(payload, planetTargets, houseTargets) {
  if (!payload || !Array.isArray(payload._mdseEclipseNatalHits)) return null;
  const planetSet = new Set(planetTargets);
  const houseSet  = new Set(houseTargets);
  for (const h of payload._mdseEclipseNatalHits) {
    if (!h || typeof h.planet !== "string") continue;
    if (typeof h.eclType === "string" && /Pénombrale/i.test(h.eclType)) continue;
    // (a) planet = planète/Lot/signifiant natal direct
    if (planetSet.has(h.planet)) {
      return {
        target:  h.planet,
        eclType: h.eclType || "Eclipse",
        date:    h.date || null,
        via:     "planet"
      };
    }
    // (b) planet = angle (AS/MC/DS/FC) → mapping vers maison
    const angleHouse = _V21_ANGLE_TO_HOUSE[h.planet];
    if (angleHouse && houseSet.has(angleHouse)) {
      return {
        target:  h.planet + " (M" + angleHouse + ")",
        eclType: h.eclType || "Eclipse",
        date:    h.date || null,
        via:     "angle"
      };
    }
  }
  return null;
}

// ─────────────────────────────────────────────────────────────────────────────
// G2.4 — Helpers internes règle 2 (§2.5.1 - §2.5.3 SPEC)
// ─────────────────────────────────────────────────────────────────────────────

/** §2.5.1 — Verdict { active: false } traçable quand natal/payload mal formé. */
function _v21StageSetDegradedResult(code, errorMsg) {
  return {
    code:      code,
    active:    false,
    witnesses: { stageSet: null, trigger: null },
    _error:    errorMsg
  };
}

/**
 * §2.5.2 — Évalue les 3 sous-règles stage-set 2.1.a → 2.1.b → 2.1.c.
 * Premier hit suffit. Retourne { via, detail, source } ou null.
 */
function _v21EvalStageSet(natalDict, payload, code, entry) {

  // (2.1.a) Profection annuelle active une maison topique du code
  const houseProfected = _v21HouseProfected(payload);
  if (houseProfected !== null && entry.houses.indexOf(houseProfected) !== -1) {
    return {
      via:    "2.1.a",
      detail: "profection annuelle active M" + houseProfected
            + " (topique " + code + ")",
      source: "Brennan Ch.17 L28098"
    };
  }

  // (2.1.b) Lord of Year — 2 sous-conditions séquentielles (i puis ii)
  const lordOfYear = _v21LordOfYear(payload);
  if (lordOfYear) {
    // (2.1.b.i) LotY EST un signifiant naturel
    if (entry.planets.indexOf(lordOfYear) !== -1) {
      return {
        via:    "2.1.b",
        detail: "Lord of Year = " + lordOfYear
              + " ∈ signifiants naturels " + code,
        source: "Brennan Ch.17 L28386"
      };
    }
    // (2.1.b.ii) LotY en aspect tight ≤ 3° à un signifiant
    if (natalDict[lordOfYear]) {
      for (const planet of entry.planets) {
        if (planet === lordOfYear) continue;
        if (!natalDict[planet]) continue;
        if (_v21AspectTight(natalDict, lordOfYear, planet)) {
          return {
            via:    "2.1.b",
            detail: "Lord of Year (" + lordOfYear
                  + ") aspect tight " + planet
                  + " (signifiante " + code + ")",
            source: "Brennan Ch.17 L28620"
          };
        }
      }
    }
  }

  // (2.1.c) Secondary progression tight ≤ 1° sur cible
  const targets = _v21BuildNatalTargets(natalDict, payload, entry);
  for (const natalP of targets) {
    const progHit = _v21ProgressionTightHit(payload, natalP, 1.0);
    if (progHit) {
      return {
        via:    "2.1.c",
        detail: progHit.pProg + " progressé " + progHit.aspName
              + " " + natalP + " (cible " + code
              + "), orbe " + progHit.orbe.toFixed(2) + "°",
        source: "Rushman L577"
      };
    }
  }

  return null;
}

/**
 * §2.5.3 — Évalue les 4 sous-règles trigger 2.2.a → 2.2.b → 2.2.c → 2.2.d.
 * Premier hit suffit. Retourne { via, detail, source } ou null.
 */
function _v21EvalTrigger(natalDict, payload, code, entry) {

  const targets = _v21BuildNatalTargets(natalDict, payload, entry);

  // (2.2.a) Transit lent S/U/N/P tight ≤ 3°
  const slowHit = _v21TransitTightHit(
    payload,
    ["Saturne", "Uranus", "Neptune", "Pluton"],
    targets,
    3.0
  );
  if (slowHit) {
    return {
      via:    "2.2.a",
      detail: slowHit.transitP + " transit " + slowHit.aspName
            + " " + slowHit.natalP + " (cible " + code
            + "), orbe " + slowHit.orb.toFixed(2) + "°",
      source: "Brady Ch.2 L4382-93"
    };
  }

  // (2.2.b) Transit Jupiter tight ≤ 3°
  const jupHit = _v21TransitTightHit(
    payload,
    ["Jupiter"],
    targets,
    3.0
  );
  if (jupHit) {
    return {
      via:    "2.2.b",
      detail: "Jupiter transit " + jupHit.aspName
            + " " + jupHit.natalP + " (cible " + code
            + "), orbe " + jupHit.orb.toFixed(2) + "°",
      source: "Rushman L612"
    };
  }

  // (2.2.c) Transit Mars tight ≤ 3°, UNIQUEMENT pour codes MARS_ELIGIBLE_CODES
  if (MARS_ELIGIBLE_CODES.indexOf(code) !== -1) {
    const marsHit = _v21TransitTightHit(
      payload,
      ["Mars"],
      targets,
      3.0
    );
    if (marsHit) {
      return {
        via:    "2.2.c",
        detail: "Mars transit " + marsHit.aspName
              + " " + marsHit.natalP + " (cible " + code
              + ", MARS_ELIGIBLE), orbe " + marsHit.orb.toFixed(2) + "°",
        source: "Rushman L586"
      };
    }
  }

  // (2.2.d) Éclipse tight sur cible (signifiant/maître) OU angle topique
  const eclHit = _v21EclipseTightHit(
    payload,
    Array.from(targets),
    entry.houses
  );
  if (eclHit) {
    return {
      via:    "2.2.d",
      detail: eclHit.eclType + " sur " + eclHit.target
            + " (" + eclHit.via + ", " + code + ")",
      source: "Rushman L577 + Brennan Ch.17 L28572"
    };
  }

  return null;
}

// ─────────────────────────────────────────────────────────────────────────────
// G2.5 — Fonction principale _v21StageSetRushman (§2.5.4 SPEC)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Extraction doctrinale autonome du Stage-Set Rushman (Ch.2 L577).
 * Architecture en 2 temps : STAGE SET par progressions (profections / LotY /
 * secondary progressions) + TRIGGER par transit (lents / Jupiter / Mars
 * paramétré / éclipse).
 *
 * Verdict binaire conjonctif (décision K) : active = stageSet AND trigger.
 *
 * @param {Object} natalDict   positions natales (= payload._natalDict)
 * @param {Object} payload     payload n8n complet (lords, profections, transits, éclipses)
 * @param {string} code        parmi 14 codes DTC
 * @param {Date}   eventDate   date pivot (informative, déjà filtrée amont V20)
 * @returns {Object} verdict schéma Z.2
 *
 * Garanties : pure, symétrique 14 codes, sourcée, PROD-safe inline n8n,
 * réutilise matrice §1.3 + helpers règle 1 §1.2.0.
 */
function _v21StageSetRushman(natalDict, payload, code, eventDate) {

  // (a) Validation entrée — code dans matrice (5.3.A : exception explicite)
  if (!_v21Rule3Matrix[code]) {
    throw new Error('_v21StageSetRushman: code "' + code
                  + '" absent de _v21Rule3Matrix (14 codes attendus)');
  }

  // (b) Validation entrée — natalDict valide (5.3.B : dégradation gracieuse)
  if (!natalDict || typeof natalDict !== "object") {
    return _v21StageSetDegradedResult(code, "natalDict absent ou invalide");
  }

  // (c) Validation entrée — payload valide (5.3.B : dégradation gracieuse)
  if (!payload || typeof payload !== "object") {
    return _v21StageSetDegradedResult(code, "payload absent ou invalide");
  }

  // (d) Récupération entrée matrice
  const entry = _v21Rule3Matrix[code];

  // (e) Évaluation indépendante stage-set + trigger (pas de short-circuit
  //     décision §2.2.4 : trigger évalué même si stageSet null pour traçabilité)
  const stageSet = _v21EvalStageSet(natalDict, payload, code, entry);
  const trigger  = _v21EvalTrigger (natalDict, payload, code, entry);

  // (f) Composition verdict binaire (décision K verrouillée)
  const active = (stageSet !== null) && (trigger !== null);

  // (g) Retour structuré (schéma Z.2 verrouillé)
  return {
    code:      code,
    active:    active,
    witnesses: {
      stageSet: stageSet,
      trigger:  trigger
    }
  };
}

