// Frequency Brady L4382-93 + L4395-4400 : "outer slower planets carry
//   greatest weight". Découpage en 4 catégories (synthèse fidèle) :
//   slow > jup > mars > fast.
// Ordre numérique : plus petit = plus fort (pour tri ascendant).
const _V21_BRADY_FREQ_RANK = Object.freeze({
  "Saturne":  0, "Uranus":   0, "Neptune": 0, "Pluton": 0,
  "Jupiter":  1,
  "Mars":     2,
  "Mercure":  3, "Vénus":    3, "Soleil":  3, "Lune":   3
});

// Movement Brady L4404-4413 : "personal planets + Cross of Matter
//   = greater effect when receiving".
// Ordre numérique : plus petit = plus fort.
const _V21_BRADY_MOV_RANK = Object.freeze({
  "Soleil":     0, "Lune":         0,
  "Vénus":      0, "Mercure":      0,
  "Ascendant":  0, "Descendant":   0,
  "Milieu du Ciel": 0, "Fond du Ciel": 0,
  "MC":         0, "IC":           0,
  "Asc":        0, "Desc":         0,
  "Mars":     1, "Jupiter": 1,
  "Saturne":  1, "Uranus":  1,
  "Neptune":  1, "Pluton":  1
});

// Aspecting Brady L4417 + L4461-4467 : smaller harmonic = stronger.
// Décision O.1 : 5 aspects ptolemaïques uniquement (exclure Quinconce,
//   Sesquicarré, Semi-carré). RÈGLE-ZERO _INDEX-MASTER.md point 4.
// Ordre numérique : plus petit = plus fort.
const _V21_BRADY_ASP_RANK = Object.freeze({
  "Conjonction": 0, "Opposition": 0,
  "Carré":       1, "Trigone":    1,
  "Sextile":     2
});

// Mapping bradyRank (1-5) → peakLevel cascade aval (briefing V21 ligne 66).
// Élargi à 4 → MODERATE pour cohérence Brady L4520 (secondary themes).
const _V21_BRADY_RANK_TO_LEVEL = Object.freeze({
  1: "PEAK",
  2: "STRONG",
  3: "MODERATE",
  4: "MODERATE",
  5: "WEAK"
});

// ─────────────────────────────────────────────────────────────────────────────
// Helpers internes règle 3 — § 3.3.1 → § 3.3.5
// 5 helpers self-contained PROD-safe inline n8n.
// ─────────────────────────────────────────────────────────────────────────────

/**
 * § 3.3.1 — Catégorie Frequency Brady d'une planète transitante.
 * "slow" | "jup" | "mars" | "fast" (cohérence avec _V21_BRADY_FREQ_RANK).
 * Retourne "fast" par défaut (downgrade gracieuse) si planète inconnue.
 */
function _v21BradyFreqCat(transitP) {
  const r = _V21_BRADY_FREQ_RANK[transitP];
  if (r === 0) return "slow";
  if (r === 1) return "jup";
  if (r === 2) return "mars";
  return "fast";
}

/**
 * § 3.3.2 — Catégorie Movement Brady d'une planète/angle natal recevant un transit.
 * "personal" | "outer" (cohérence avec _V21_BRADY_MOV_RANK).
 * Cas Lots / pseudo-planètes : non documenté Brady → "outer" par défaut
 * (downgrade conservateur, ne sur-pondère pas).
 */
function _v21BradyMovCat(natalP) {
  const r = _V21_BRADY_MOV_RANK[natalP];
  if (r === 0) return "personal";
  return "outer";
}

/**
 * § 3.3.3 — Catégorie Aspecting Brady d'un nom d'aspect.
 * "conj-opp" | "sqr-tri" | "sext-semi" (cohérence avec _V21_BRADY_ASP_RANK).
 * Retourne null pour aspects EXCLUS (Quinconce, Sesquicarré, Semi-carré, inconnus).
 *   → Le pipeline § 3.2 (c) filtre ces candidats AVANT _v21BradyCompareTransits.
 */
function _v21BradyAspCat(aspName) {
  const r = _V21_BRADY_ASP_RANK[aspName];
  if (r === 0) return "conj-opp";
  if (r === 1) return "sqr-tri";
  if (r === 2) return "sext-semi";
  return null;
}

/**
 * § 3.3.4 — Comparateur de 2 transitInfo enrichis pour Array.sort().
 * Retourne :
 *   < 0 si a est plus fort que b (a vient avant b)
 *   > 0 si b est plus fort que a
 *   = 0 si strictement identiques (cas pathologique, ne devrait pas arriver)
 *
 * Ordre hiérarchique STRICT (décision N.1) :
 *   1. Frequency  : _V21_BRADY_FREQ_RANK[transitP]  (plus petit = plus fort)
 *   2. Movement   : _V21_BRADY_MOV_RANK[natalP]
 *   3. Aspecting  : _V21_BRADY_ASP_RANK[aspName]
 *   4. Orb        : orb (plus petit = plus fort, Brady L4583-4623 "exact touch")
 *   5. Tie-break ultime : lexicographique sur (transitP|natalP|aspName)
 *      → garantit invariant I3-7 (déterminisme) cross-runtime.
 */
function _v21BradyCompareTransits(a, b) {
  // (1) Frequency — critère absolu
  const fA = _V21_BRADY_FREQ_RANK[a.transitP];
  const fB = _V21_BRADY_FREQ_RANK[b.transitP];
  const fAn = (fA !== undefined) ? fA : 3;
  const fBn = (fB !== undefined) ? fB : 3;
  if (fAn !== fBn) return fAn - fBn;

  // (2) Movement — premier tie-break
  const mA = _V21_BRADY_MOV_RANK[a.natalP];
  const mB = _V21_BRADY_MOV_RANK[b.natalP];
  const mAn = (mA !== undefined) ? mA : 1;
  const mBn = (mB !== undefined) ? mB : 1;
  if (mAn !== mBn) return mAn - mBn;

  // (3) Aspecting — deuxième tie-break
  const aA = _V21_BRADY_ASP_RANK[a.aspName];
  const aB = _V21_BRADY_ASP_RANK[b.aspName];
  const aAn = (aA !== undefined) ? aA : 2;
  const aBn = (aB !== undefined) ? aB : 2;
  if (aAn !== aBn) return aAn - aBn;

  // (4) Orb — troisième tie-break (tolérance 0.01° pour égalité réelle)
  const orbDelta = a.orb - b.orb;
  if (Math.abs(orbDelta) > 0.01) return orbDelta;

  // (5) Tie-break ultime lexicographique
  const keyA = (a.transitP || "") + "|" + (a.natalP || "") + "|" + (a.aspName || "");
  const keyB = (b.transitP || "") + "|" + (b.natalP || "") + "|" + (b.aspName || "");
  if (keyA < keyB) return -1;
  if (keyA > keyB) return  1;
  return 0;
}

/**
 * § 3.3.5 — Traduit un bradyRank ∈ {1,2,3,4,5} en peakLevel cascade aval.
 * Cas hors-borne (0, undefined, > 5) : downgrade à "WEAK".
 */
function _v21BradyRankToLevel(bradyRank) {
  const lvl = _V21_BRADY_RANK_TO_LEVEL[bradyRank];
  return lvl || "WEAK";
}

// ─────────────────────────────────────────────────────────────────────────────
// Sous-helpers règle 3 — § 3.4.0 → § 3.4.3
// ─────────────────────────────────────────────────────────────────────────────

/**
 * § 3.4.0 — Construit un verdict { bradyRank: 5, peakLevel: "WEAK" } traçable
 * quand le natal/payload est mal formé. Cohérence règles 1+2 (style _v21XxxDegradedResult).
 */
function _v21BradyDegradedResult(code, errorMsg) {
  return {
    code:       code,
    bradyRank:  5,
    peakLevel:  "WEAK",
    dominant1:  null,
    dominant2:  null,
    allRanked:  [],
    witnesses:  { freqRule: null, movRule: null, aspRule: null },
    _error:     errorMsg
  };
}

/**
 * § 3.4.1 — Parcourt _aspectsSuiviLent + _aspectsSuiviRap, filtre sur cibles
 * natales + orbe tight ≤ orbMax + aspect ptolémaïque, retourne la liste des
 * candidats enrichis Brady-3-règles.
 *
 * Format clé V20 : "slow_TP|||AspName|||NatalP" ou "fast_TP|||AspName|||NatalP".
 * Format valeur V20 : { waves: [{ minOrb, ... }], natalHouse, ... }.
 *
 * 5 aspects ptolemaïques retenus (O.1). Quinconce/Sesquicarré/Semi-carré IGNORÉS.
 */
function _v21BradyCollectCandidates(payload, targets, orbMax) {
  const candidates = [];
  const ORB_MAX = (typeof orbMax === "number") ? orbMax : 3.0;

  const _processMap = function(mapObj, prefix) {
    if (!mapObj || typeof mapObj !== "object") return;
    const keys = Object.keys(mapObj);
    for (const key of keys) {
      if (key.indexOf(prefix + "_") !== 0) continue;
      const rest  = key.substring(prefix.length + 1);
      const parts = rest.split("|||");
      if (parts.length !== 3) continue;
      const transitP = parts[0];
      const aspName  = parts[1];
      const natalP   = parts[2];

      const aspCat = _v21BradyAspCat(aspName);
      if (aspCat === null) continue;

      if (!targets.has(natalP)) continue;

      const entry = mapObj[key];
      if (!entry || !Array.isArray(entry.waves) || entry.waves.length === 0) continue;
      let minOrb = Infinity;
      for (const w of entry.waves) {
        const o = (typeof w.minOrb === "number") ? w.minOrb : parseFloat(w.minOrb);
        if (isFinite(o) && o < minOrb) minOrb = o;
      }
      if (!isFinite(minOrb) || minOrb > ORB_MAX) continue;

      candidates.push({
        transitP: transitP,
        natalP:   natalP,
        aspName:  aspName,
        orb:      minOrb,
        freqCat:  _v21BradyFreqCat(transitP),
        movCat:   _v21BradyMovCat(natalP),
        aspCat:   aspCat
      });
    }
  };

  _processMap(payload._aspectsSuiviLent, "slow");
  _processMap(payload._aspectsSuiviRap,  "fast");

  return candidates;
}

/**
 * § 3.4.2 — Attribue un rank 1-5 à chaque candidat trié.
 * Respect ex-aequo (Brady L4502 "rated equally") : si compare === 0, même rank.
 * Plafond à 5 (mapping _V21_BRADY_RANK_TO_LEVEL).
 * MUTATION en place sur le tableau (volontaire pour perf, scope local à _v21BradyRanking).
 */
function _v21BradyAttributeRanks(candidates) {
  if (candidates.length === 0) return;
  candidates[0].rank = 1;
  for (let i = 1; i < candidates.length; i++) {
    const cmp = _v21BradyCompareTransits(candidates[i], candidates[i - 1]);
    if (cmp === 0) {
      candidates[i].rank = candidates[i - 1].rank;
    } else {
      candidates[i].rank = Math.min(candidates[i - 1].rank + 1, 5);
    }
  }
}

/**
 * § 3.4.3 — Construit l'objet witnesses qui explique POURQUOI dominant1 a gagné.
 * Si dominant1 null, retourne 3 witnesses null (cohérence cas vide § 3.2.3).
 */
function _v21BradyBuildWitnesses(dominant1) {
  if (!dominant1) {
    return { freqRule: null, movRule: null, aspRule: null };
  }
  return {
    freqRule: {
      winner: dominant1.transitP,
      detail: dominant1.transitP + " (" + dominant1.freqCat + ")",
      source: "Brady Ch.2 L4382-93"
    },
    movRule: {
      winner: dominant1.natalP,
      detail: dominant1.natalP + " natal (" + dominant1.movCat + ")",
      source: "Brady Ch.2 L4404-13"
    },
    aspRule: {
      winner: dominant1.aspName,
      detail: dominant1.aspName + " (" + dominant1.aspCat
            + "), orbe " + dominant1.orb.toFixed(2) + "°",
      source: "Brady Ch.2 L4417 + L4461-67"
    }
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// Fonction principale règle 3 — § 3.4.4
// ─────────────────────────────────────────────────────────────────────────────

/**
 * § 3.4.4 — Ranking ordinal Brady Ch.2 d'un code DTC sur une date d'événement.
 *
 * Trie les transits actifs sur les signifiants natals du code selon les 3 règles
 * Brady (Frequency #1 > Movement #2 > Aspecting #3 > Orb #4 > lexico #5).
 * Retourne dominant1/dominant2 (S.1 Top-2 fixe) + bradyRank + peakLevel mappé.
 *
 * Indépendance R.1 : ne consulte JAMAIS le résultat de _v21StageSetRushman.
 * Indépendance V20 : aucune référence à _pna*, _phx*, _c2*, _v20*.
 *
 * @param {Object} natalDict  positions natales planètes/angles/lots
 * @param {Object} payload    payload n8n complet
 * @param {string} code       parmi 14 codes DTC (matrice § 1.3)
 * @param {Date}   eventDate  date événement (cohérence API règles 1+2,
 *                            non utilisée car amont V20 a déjà filtré)
 * @returns {Object} verdict Z.3 verrouillé (cf. SPEC § 3.0)
 *
 * Garanties : pure (immutabilité côté appelant), déterministe (5 niveaux tie-break),
 * Top-2 explicite, 5 aspects ptolemaïques uniquement, PROD-safe inline n8n.
 */
function _v21BradyRanking(natalDict, payload, code, eventDate) {

  // (a) Validation entrée — code dans matrice (5.3.A : exception explicite)
  if (!_v21Rule3Matrix[code]) {
    throw new Error('_v21BradyRanking: code "' + code
                  + '" absent de _v21Rule3Matrix (14 codes attendus)');
  }

  // (b) Validation entrée — natalDict valide (5.3.B : dégradation gracieuse)
  if (!natalDict || typeof natalDict !== "object") {
    return _v21BradyDegradedResult(code, "natalDict absent ou invalide");
  }

  // (c) Validation entrée — payload valide (5.3.B : dégradation gracieuse)
  if (!payload || typeof payload !== "object") {
    return _v21BradyDegradedResult(code, "payload absent ou invalide");
  }

  // (d) Récupération entrée matrice
  const entry = _v21Rule3Matrix[code];

  // (e) Cibles natales (réutilise helper règle 2 § 2.4.0, factorisation G2/G3)
  const targets = _v21BuildNatalTargets(natalDict, payload, entry);

  // (f) Collecte + enrichissement Brady-3-règles (§ 3.4.1)
  const candidates = _v21BradyCollectCandidates(payload, targets, 3.0);

  // (g) Cas "aucun candidat" — verdict WEAK par défaut (§ 3.2.3)
  if (candidates.length === 0) {
    return {
      code:       code,
      bradyRank:  5,
      peakLevel:  "WEAK",
      dominant1:  null,
      dominant2:  null,
      allRanked:  [],
      witnesses:  { freqRule: null, movRule: null, aspRule: null }
    };
  }

  // (h) Tri hiérarchique strict Freq>Mov>Asp>Orb>lexico (décision N.1)
  candidates.sort(_v21BradyCompareTransits);

  // (i) Attribution des ranks 1-5 avec gestion ex-aequo (§ 3.2.2 + § 3.4.2)
  _v21BradyAttributeRanks(candidates);

  // (j) Composition du verdict (décisions P.1 + S.1)
  const dominant1 = candidates[0];
  const dominant2 = (candidates.length >= 2) ? candidates[1] : null;
  const bradyRank = dominant1.rank;
  const peakLevel = _v21BradyRankToLevel(bradyRank);
  const witnesses = _v21BradyBuildWitnesses(dominant1);

  // (k) Retour structuré (schéma Z.3 verrouillé § 3.0)
  return {
    code:       code,
    bradyRank:  bradyRank,
    peakLevel:  peakLevel,
    dominant1:  dominant1,
    dominant2:  dominant2,
    allRanked:  candidates,
    witnesses:  witnesses
  };
}

// ═════════════════════════════════════════════════════════════════════════════
// SECTION G4 — CASCADE FINALE V21 : applyDoctrinalPipelineV21Categoriel
//
// Spec § C.0 → § C.5 (verrouillée 2026-06-01 soir).
// Décisions structurantes T/U/V/W/X/Y verrouillées en bloc :
//   T.B — Cap rule1.count dégressif : 3→PEAK / 2→STRONG / 1→MODERATE / 0→INACTIVE
//   U.C — Cascade + cap T.B + override DORMANT 3 cas tangents (6.a/6.b/6.c)
