// ─────────────────────────────────────────────────────────────────────────────
// Constantes cascade (§ C.2.2 + écart E2 _V21_PLANET_FALL_SIGN)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Table d'ordre des 6 niveaux peakLevel (§ C.2.2).
 * Ordre numérique : plus PETIT = pire (INACTIVE) ; plus GRAND = mieux (PEAK).
 * Permet : _v21OrderMin(a, b) (cap, choisit le pire),
 *          tri DESC par peakLevel (le meilleur en premier).
 */
const _V21_LEVEL_ORDER = Object.freeze({
  "INACTIVE": 0,
  "DORMANT":  1,
  "WEAK":     2,
  "MODERATE": 3,
  "STRONG":   4,
  "PEAK":     5
});

/**
 * Signes de chute des 7 planètes traditionnelles (doctrine hellénistique).
 * Utilisé par _v21LordOfYearInFall pour l'override 6.a (cf. écart E2).
 * Planètes modernes (Uranus, Neptune, Pluton) : pas de signe de chute classique,
 *   l'override 6.a ne s'applique donc pas à elles (conservateur).
 */
const _V21_PLANET_FALL_SIGN = Object.freeze({
  "Soleil":  "Balance",
  "Lune":    "Scorpion",
  "Mercure": "Poissons",
  "Vénus":   "Vierge",
  "Mars":    "Cancer",
  "Jupiter": "Capricorne",
  "Saturne": "Bélier"
});

// ─────────────────────────────────────────────────────────────────────────────
// Helpers cascade — § C.2.2 → § C.2.4 + § C.3.4
// ─────────────────────────────────────────────────────────────────────────────

/**
 * § C.2.2 — Renvoie le PIRE des 2 niveaux (cap).
 * orderMin("PEAK","STRONG")    = "STRONG"
 * orderMin("WEAK","MODERATE")  = "WEAK"
 * orderMin("DORMANT","PEAK")   = "DORMANT" (DORMANT bat tout)
 */
function _v21OrderMin(a, b) {
  const oa = _V21_LEVEL_ORDER[a];
  const ob = _V21_LEVEL_ORDER[b];
  if (oa === undefined) return b;
  if (ob === undefined) return a;
  return (oa <= ob) ? a : b;
}

/**
 * § C.2.3 — Mapping count → niveau max (cap T.B Brennan L27047 + al-Khayyāt L27052).
 *   count 3 → PEAK     (CERTAIN, "complete")
 *   count 2 → STRONG   (PROBABLE, "stronger")
 *   count 1 → MODERATE (POSSIBLE, "vulgare")
 *   count 0 → INACTIVE (filtré step 1, ne devrait pas atteindre step 4)
 */
function _v21LevelFromRule1Count(count) {
  if (count === 3) return "PEAK";
  if (count === 2) return "STRONG";
  if (count === 1) return "MODERATE";
  return "INACTIVE";
}

/**
 * § C.2.4 — Mapping peakLevel → score 0-99 (Y.A rétro-compat n8n).
 * 6 paliers nets (≥ 15 points entre paliers), PEAK=90 (laisse 10 pts marge MDSE),
 * DORMANT=15 (différencie cas tangent évalué vs INACTIVE non-évalué).
 */
function _v21LevelToLegacyScore(peakLevel) {
  if (peakLevel === "PEAK")     return 90;
  if (peakLevel === "STRONG")   return 70;
  if (peakLevel === "MODERATE") return 50;
  if (peakLevel === "WEAK")     return 30;
  if (peakLevel === "DORMANT")  return 15;
  if (peakLevel === "INACTIVE") return 0;
  return 0;
}

/**
 * Écart E2 — Détecteur Lord of Year en chute (override 6.a conservateur).
 * Retourne true ssi : LordOfYear présent dans natalDict ET son sign natal est
 *   le signe de chute classique de cette planète (mapping 7 planètes ancien).
 * Sinon false (par défaut, sécuritaire).
 */
function _v21LordOfYearInFall(natalDict, payload) {
  // V22 bypass — dépendance Brennan profections, désactivé en V22.
  if (DTC_V22_NO_PROFECTIONS) return false;
  if (!natalDict || !payload) return false;
  const loy = _v21LordOfYear(payload);
  if (!loy) return false;
  const fallSign = _V21_PLANET_FALL_SIGN[loy];
  if (!fallSign) return false;   // Uranus/Neptune/Pluton/inconnue : pas de chute classique
  const natalEntry = natalDict[loy];
  if (!natalEntry || typeof natalEntry.sign !== "string") return false;
  return natalEntry.sign === fallSign;
}

/**
 * § C.2.5 (avec correctif écart E1) — Assemblage VerdictEntry final.
 * Centralise la sérialisation pour garantir contrat § C.0 (zéro divergence entre
 * sorties Step 1/2/3/7).
 *
 * Correctif E1 : stageSetSources / triggerSources = [via] ou [] (la SPEC C.2.5
 * utilisait Object.keys mais notre règle 2 G2 retourne {via,detail,source} pas
 * un dict).
 */
function _v21BuildVerdictEntry(code, peakLevel, exitReason, rule1Full, rule2Full, rule3Full, cappedFromRule3) {
  // Synthèse compacte rule1
  const rule1Synth = rule1Full ? {
    count:                 rule1Full.count,
    level:                 rule1Full.level,
    capLevel:              rule1Full.capLevel,
    witnessesPlanetActive: Boolean(rule1Full.witnesses && rule1Full.witnesses.planet),
    witnessesPlaceActive:  Boolean(rule1Full.witnesses && rule1Full.witnesses.place),
    witnessesLotActive:    Boolean(rule1Full.witnesses && rule1Full.witnesses.lot)
  } : null;

  // Synthèse compacte rule2 (E1 : array de [via] ou [])
  const rule2Synth = rule2Full ? {
    active: Boolean(rule2Full.active),
    stageSetSources: (rule2Full.witnesses && rule2Full.witnesses.stageSet && rule2Full.witnesses.stageSet.via)
      ? [rule2Full.witnesses.stageSet.via]
      : [],
    triggerSources: (rule2Full.witnesses && rule2Full.witnesses.trigger && rule2Full.witnesses.trigger.via)
      ? [rule2Full.witnesses.trigger.via]
      : []
  } : null;

  // Synthèse compacte rule3
  const rule3Synth = rule3Full ? {
    bradyRank:       rule3Full.bradyRank,
    peakLevel:       rule3Full.peakLevel,
    dominant1Active: rule3Full.dominant1 !== null,
    dominant2Active: rule3Full.dominant2 !== null,
    dominantSummary: rule3Full.dominant1
      ? (rule3Full.dominant1.transitP + "-" + rule3Full.dominant1.aspName + "-" + rule3Full.dominant1.natalP)
      : null
  } : null;

  return {
    code:        code,
    peakLevel:   peakLevel,
    legacyScore: _v21LevelToLegacyScore(peakLevel),
    rule1:       rule1Synth,
    rule2:       rule2Synth,
    rule3:       rule3Synth,
    exitReason:  exitReason,
    _trace: {
      rule1Full:        rule1Full,
      rule2Full:        rule2Full,
      rule3Full:        rule3Full,
      cappedFromRule3:  cappedFromRule3 || null
    }
  };
}

/**
 * § C.3.2 — Comparator inter-codes (5 tie-breaks V.B).
 * Sort DESC sur peakLevel + 4 tie-breaks + alphabétique ultime.
 *
 * INACTIVE/DORMANT n'ont pas rule3.bradyRank / rule1.count : downgrade au pire
 * (rank=5, count=0) → ils tombent toujours derrière les codes actifs.
 */
function _v21CompareVerdicts(a, b) {
  // Tie-break 0 — peakLevel (ordre principal DESC)
  const orderA = _V21_LEVEL_ORDER[a.peakLevel];
  const orderB = _V21_LEVEL_ORDER[b.peakLevel];
  if (orderA !== orderB) return orderB - orderA;

  // Tie-break (a) — dominant2Active DESC (confluence Brady L4520)
  const dom2A = (a.rule3 && a.rule3.dominant2Active) ? 1 : 0;
  const dom2B = (b.rule3 && b.rule3.dominant2Active) ? 1 : 0;
  if (dom2A !== dom2B) return dom2B - dom2A;

  // Tie-break (b) — bradyRank ASC (Brady L4332 stronger/less strong)
  const rankA = (a.rule3 && typeof a.rule3.bradyRank === "number") ? a.rule3.bradyRank : 5;
  const rankB = (b.rule3 && typeof b.rule3.bradyRank === "number") ? b.rule3.bradyRank : 5;
  if (rankA !== rankB) return rankA - rankB;

  // Tie-break (c) — profection topique 2.1.a (Brennan Ch.17 stage set primaire)
  const profA = (a.rule2 && Array.isArray(a.rule2.stageSetSources)
                 && a.rule2.stageSetSources.indexOf("2.1.a") !== -1) ? 1 : 0;
  const profB = (b.rule2 && Array.isArray(b.rule2.stageSetSources)
                 && b.rule2.stageSetSources.indexOf("2.1.a") !== -1) ? 1 : 0;
  if (profA !== profB) return profB - profA;

  // Tie-break (d) — rule1.count DESC (Brennan L27047 gradient)
  const cntA = (a.rule1 && typeof a.rule1.count === "number") ? a.rule1.count : 0;
  const cntB = (b.rule1 && typeof b.rule1.count === "number") ? b.rule1.count : 0;
  if (cntA !== cntB) return cntB - cntA;

  // Tie-break (e) — alphabétique ASC (déterminisme cross-runtime ultime)
  if (a.code < b.code) return -1;
  if (a.code > b.code) return 1;
  return 0;
}

/**
 * § C.3.3 — Padding top-5 à 5 entrées (contrat W.C strict).
 * Cas pathologique : codes=[] ou < 5 codes évalués.
 * Codes pad préfixés "_PAD_" pour filtre MDSE/post-DTC trivial.
 */
function _v21PadTop5(verdictsSorted) {
  const top5 = verdictsSorted.slice(0, 5);
  while (top5.length < 5) {
    const padIdx = top5.length + 1;
    top5.push({
      code:        "_PAD_" + padIdx,
      peakLevel:   "INACTIVE",
      legacyScore: 0,
      rule1:       null,
      rule2:       null,
      rule3:       null,
      exitReason:  "padding",
      _trace: {
        rule1Full:       null,
        rule2Full:       null,
        rule3Full:       null,
        cappedFromRule3: null
