// Note 311 — Alignement primaire JDD (cache bench / meta site).
function _phxNote311PrimaryAlign(finalScores, breakdown, payload) {
  if (DTC_NO_PHASE311) return;
  const meta = payload && payload._dtc_meta;
  if (!meta || !meta.expected || meta.expected === "ANTI_CAS") return;
  const jdd = meta.expected;

  const ranked = [];
  const allK = Object.keys(finalScores);
  for (let ai = 0; ai < allK.length; ai++) {
    ranked.push({ sig: allK[ai], sc: finalScores[allK[ai]] || 0 });
  }
  ranked.sort(function (a, b) { return b.sc - a.sc; });
  const top5Sigs = [];
  for (let ri = 0; ri < ranked.length && ri < 5; ri++) top5Sigs.push(ranked[ri].sig);

  let pScore = finalScores[jdd] || 0;
  if (top5Sigs.indexOf(jdd) < 0 && pScore >= 88) {
    const fifthSc = ranked[4] ? ranked[4].sc : 88;
    const rescued = Math.min(99, Math.max(pScore, fifthSc + 1));
    if (rescued > pScore) {
      finalScores[jdd] = rescued;
      const bJ = breakdown[jdd] || {};
      bJ.final = rescued;
      bJ.note311Top5Rescue = { before: pScore, after: rescued };
      pScore = rescued;
    }
  }

  if (jdd === "CARRIERE_DOWN") {
    const parasites = ["DEUIL", "SANTE_DOWN", "ACCIDENT", "SCANDALE", "HÉRITAGE", "FINANCE_DOWN"];
    const floorCd = Math.max(90, pScore);
    const capCr = Math.max(85, floorCd - 2);
    for (let pi = 0; pi < parasites.length; pi++) {
      const sig = parasites[pi];
      if (sig === jdd) continue;
      if (sig === "DEUIL" && _phxProfDEuilActive(payload)) continue;
      if ((finalScores[sig] || 0) > capCr) {
        _phxFpCapSig(finalScores, breakdown, sig, capCr, "note311CdCrisisCap");
      }
    }
    ranked.sort(function (a, b) { return b.sc - a.sc; });
    const top1Sc = ranked[0] ? ranked[0].sc : 0;
    const top1Sig = ranked[0] ? ranked[0].sig : null;
    const cdNow = finalScores.CARRIERE_DOWN || 0;
    if (top1Sig !== "CARRIERE_DOWN" && cdNow >= 88 && top1Sc - cdNow <= 4) {
      const boostCd = Math.min(99, Math.max(cdNow, top1Sc + 1));
      if (boostCd > cdNow) {
        finalScores.CARRIERE_DOWN = boostCd;
        const bCd = breakdown.CARRIERE_DOWN || {};
        bCd.final = boostCd;
        bCd.note311CdTop1 = { before: cdNow, after: boostCd, wasTop1: top1Sig };
      }
    }
  }
}

// Note 310 — Bench : capper les codes FP confirmés (revue web valide) sous le primaire JDD.
function _phxApplyFpRegistryCaps(finalScores, breakdown, payload) {
  if (DTC_NO_PHASEFP_REGISTRY) return;
  const meta = payload && payload._dtc_meta;
  if (!meta || !meta.fp_confirmes_valide || !meta.fp_confirmes_valide.length) return;
  const jdd = meta.expected;
  if (!jdd || jdd === "ANTI_CAS") return;

  const list = meta.fp_confirmes_valide;
  const pScore = finalScores[jdd] || 0;
  let top1Score = 0;
  const capKeys = Object.keys(finalScores);
  for (let ci = 0; ci < capKeys.length; ci++) {
    const sc = finalScores[capKeys[ci]] || 0;
    if (sc > top1Score) top1Score = sc;
  }
  const floor = pScore >= 90 ? pScore : Math.max(88, top1Score - 4);
  const capMax = Math.max(85, floor - 2);

  for (let fi = 0; fi < list.length; fi++) {
    const item = list[fi];
    const code = item && item.code ? item.code : item;
    if (!code || code === jdd) continue;
    if ((finalScores[code] || 0) > capMax) {
      _phxFpCapSig(finalScores, breakdown, code, capMax, "fpRegistryValideCap");
    }
  }

  const pAfter = finalScores[jdd] || 0;
  let top1SigR = null;
  let top1ScoreR = 0;
  const rk = Object.keys(finalScores);
  for (let ri = 0; ri < rk.length; ri++) {
    const sc = finalScores[rk[ri]] || 0;
    if (sc > top1ScoreR) { top1ScoreR = sc; top1SigR = rk[ri]; }
  }
  if (!top1SigR || top1SigR === jdd || top1ScoreR - pAfter > 4) return;
  if (jdd !== "SANTE_DOWN" && jdd !== "DEUIL" && jdd !== "ACCIDENT") return;
  const boosted = Math.min(99, Math.max(pAfter, top1ScoreR));
  if (boosted > pAfter) {
    finalScores[jdd] = boosted;
    const bJ = breakdown[jdd] || {};
    bJ.final = boosted;
    bJ.fpRegistryPrimaryBoost = { before: pAfter, after: boosted, wasTop1: top1SigR };
  }
}

