      layerCount: couches.length,
      convergence: distinctTypes.size,
      hasTournant: couches.some((c) => c.nature === 'tournant'),
      phrase: _vulgAsp(isEN ? (t.phrasePreEcrite_EN || t.phrasePreEcrite_FR || null) : (t.phrasePreEcrite_FR || null)),
    };
  });

// Directions primaires : dédupe par (promissor+aspect+exactDate), garde les plus serrées.
const dpSeen = {};
const primaryDirections = [];
for (const d of arr(eng._primaryDirections)) {
  if (!d || !d.label) continue;
  const key = `${d.promissor}|${d.aspect}|${d.exactDate}`;
  if (dpSeen[key]) continue;
  dpSeen[key] = true;
  primaryDirections.push({
    label: d.label, exactDate: d.exactDate || null, aspect: d.aspect || null,
    promissor: d.promissor || null, significator: d.significator || null, orbYears: num(d.orbYears),
    promHouse: num(d.promHouse), sigHouse: num(d.sigHouse), house: num(d.house),
  });
  if (primaryDirections.length >= 10) break;
}

// E5 — repli « classement vide » : si AUCUN temps fort convergent n'existe cette
// année-là, on retire la DATE exacte des directions primaires. Sans point de
// pression à dater, le chat se rabat sinon sur ces dates et promeut une DP SEULE
// au rang de « tournant daté au jour » — ce que la doctrine interdit (DP seule =
// maturation de fond, jamais un événement daté). cf. build-prev-prompt.ts
// (règle « CLASSEMENT VIDE — ANNÉE CALME »). Le label/aspect/maisons restent.
if (!topTempsForts.length) {
  for (const d of primaryDirections) d.exactDate = null;
}

const stations = cap(eng._mdseStations, 16)
  .filter((s) => s && s.planete && s.date)
  .map((s) => ({
    planete: s.planete, date: s.date, signe: s.signe || null, house: num(s.house),
    isRetro: s.isRetro === true, natalTargets: arr(s.natalTargets), closestOrb: num(s.closestOrb),
  }));

// Maison NATALE (Placidus) frappée par chaque éclipse : calculée par le moteur
// (findNatalHouse) et exposée sur _mdseEclipseHouseMap. On la lit d'abord sur eng
// (finalOutput l'expose), repli sur le snapshot. Indexé par date(+astre).
const _eclHouseSrc = arr(eng._mdseEclipseHouseMap).length ? eng._mdseEclipseHouseMap : arr(snap._mdseEclipseHouseMap);
const _eclHouseByKey = {};
for (const e of arr(_eclHouseSrc)) {
  if (!e || !e.date) continue;
  const h = num(e.house);
  _eclHouseByKey[`${e.date}|${e.astre || ''}`] = h;
  if (_eclHouseByKey[e.date] == null) _eclHouseByKey[e.date] = h;
}

const eclipses = cap(eng._eclipsesData, 8).map((e) => ({
  astre: e.astre, type: e.type, date: e.date, signe: e.signe || null, degInSign: num(e.degre_dans_signe),
  // Maison Placidus frappée par CETTE éclipse — attachée directement pour empêcher le
  // LLM de ré-attribuer une maison depuis le signe/thème (anti-hallucination : en
  // Placidus, un signe n'est PAS une maison — ex. Poissons ≠ maison 8).
  natalHouse: (_eclHouseByKey[`${e.date}|${e.astre || ''}`] ?? _eclHouseByKey[e.date]) ?? null,
  sarosTheme: (isEN ? e.saros_themeEN : e.saros_theme) || e.saros_theme || null,
  sarosKeywords: (isEN ? e.saros_keywordsEN : e.saros_keywords) || e.saros_keywords || null,
}));

const eclipseNatalHits = cap(eng._mdseEclipseNatalHits, 8).map((h) => ({
  planet: h.planet, date: h.date, eclType: h.eclType, eclAstre: h.eclAstre, orb: num(h.orb),
}));
// NB : _mdseEclipseHouseMap couvre une fenêtre pluriannuelle (Brady, ~6 ans) → on ne
// l'expose PAS tel quel (risque d'éclipses hors période). La maison Placidus de chaque
// éclipse DE L'ANNÉE est déjà attachée inline sur `eclipses[].natalHouse` ci-dessus.

// Heatmap : mois les plus intenses (totaux mensuels) + libellés de colonnes.
const hm = obj(eng.heatmapData);
const colLabels = arr(hm.colLabels);
let peakMonths = [];
const totals = arr(hm.totals);
if (totals.length) {
  peakMonths = totals
    .map((v, i) => ({ month: colLabels[i] || String(i + 1), intensity: num(v) }))
    .filter((x) => x.intensity != null)
    .sort((a, b) => b.intensity - a.intensity)
    .slice(0, 4);
}
// Domaines (maisons) les plus sollicités de l'année : top3 cumulé du moteur (mêmes
// données que le rapport). On NE lit QUE `top3` (numéros de maison) — jamais
// `hm.eventSignatures` (couche signatures désactivée en prod, prev-signatures-desactivees).
const topHouses = arr(hm.top3).map((h) => num(h)).filter((h) => h != null && h >= 1 && h <= 12);
const heatmap = {
  title: hm.title || null,
  subtitle: hm.subtitle || null,
  colLabels,
  peakMonths,
  topHouses,
};

// WS_PLACIDUS_RETRAIT : on NE porte PAS `_prevSeigneur` (= seigneur de la profection
// annuelle whole-sign, `profections.annuelle.seigneur`). Lecture en signes entiers
// caduque en pipeline Placidus, retirée du rapport PREV → jamais dans le chatBrief.
const profil = {
  chartRuler: eng._prevChartRuler || null,
  almuten: eng._prevAlmutem || null,
  chartShape: obj(eng._prevChartShape),
};

const facts = {
  periode, year, typeRapport: eng.typeRapport || null,
  profil, firdaria, solarReturn, progressions,
  planetaryReturns, topTempsForts, primaryDirections, stations, eclipses, eclipseNatalHits, heatmap,
  // Socle "planète en maison + maîtrise de maison" (report-grade).
  natal, houseLords, rsHouses, progressedActivations,
};

const factWhitelist = [];
if (firdaria.major) factWhitelist.push(`Firdaria ${firdaria.major}/${firdaria.sub}`);
for (const hlEntry of houseLords) factWhitelist.push(`Maison ${hlEntry.house} maîtrisée par ${hlEntry.lord} (maison ${hlEntry.lordHouse})`);
for (const s of stations) factWhitelist.push(`Station ${s.planete} ${s.date}${s.house ? ` (maison ${s.house})` : ''}`);
for (const e of eclipses) factWhitelist.push(`Éclipse ${e.astre} ${e.type} ${e.date}`);
for (const r of planetaryReturns) if (r.label) factWhitelist.push(r.label);

const guardrails = {
  openBook: true,
  refuseOutOfScope: true,
  noAuthorNames: true,
  practicalActionable: true,
  vulgarized: true,
  addictiveTone: true,
  language: isEN ? 'en' : 'fr',
  subjectRelation: relation,
};

const brief = {
  schemaVersion: 1,
  theme: 'prev',
  generatedAt: new Date().toISOString(),
  clientProfileId: vars.clientProfileId || null,
  chatThreadId: vars.chatThreadId || null,
  person: { name, genre, relation },
  langue,
  facts,
  factWhitelist,
  digestedDoctrine: [],
  guardrails,
};

return [
  {
    json: {
      status: 'ready',
      mode: 'chatBrief',
      theme: 'prev',
      clientProfileId: vars.clientProfileId || null,
      chatThreadId: vars.chatThreadId || null,
      chatBrief: brief,
    },
  },
];
